#define NS_CSS_MAX_SELECTOR_NESTING 48
#define NS_CSS_MAX_AT_NESTING 32

static __thread gboolean g_sel_parse_error;
static __thread gboolean g_sel_ns_prefix;
static __thread gboolean g_sel_has_hover;
static __thread gboolean g_sel_has_active;
static __thread gboolean g_sel_strict;
static __thread int g_sel_has_depth;

static ns_css_selector *parse_one_selector_rel(const char **pp, const char *end,
                                               int depth, gboolean relative);
static ns_css_selector *parse_one_selector(const char **pp, const char *end,
                                           int depth);

static GPtrArray *
parse_selector_group_rel(const char *arg, gsize arg_n, int depth,
                         gboolean relative)
{
    GPtrArray *group = g_ptr_array_new_with_free_func(
        (GDestroyNotify)ns_css_selector_free);
    if (depth > NS_CSS_MAX_SELECTOR_NESTING)
        return group;
    const char *p = arg;
    const char *end = arg + arg_n;
    while (p < end) {
        const char *loop_start = p;
        p = css_skip_ws_comments(p, end);
        if (p >= end) break;
        ns_css_selector *sub = parse_one_selector_rel(&p, end, depth, relative);
        if (sub) g_ptr_array_add(group, sub);
        else if (g_sel_strict) g_sel_parse_error = TRUE;
        p = css_skip_ws_comments(p, end);
        if (p < end && *p == ',') { p++; continue; }
        if (p == loop_start) p++;
    }
    return group;
}

static GPtrArray *
parse_selector_group(const char *arg, gsize arg_n, int depth)
{
    return parse_selector_group_rel(arg, arg_n, depth, FALSE);
}

static const char *
css_find_nth_of(const char *s, const char *end)
{
    char quote = 0;
    int paren = 0, bracket = 0;
    const char *p = s;
    while (p < end) {
        char c = *p;
        if (quote) {
            if (c == '\\' && p + 1 < end) p += 2;
            else {
                if (c == quote) quote = 0;
                p++;
            }
            continue;
        }
        if (c == '/' && p + 1 < end && p[1] == '*') {
            p = css_skip_comment(p, end);
            continue;
        }
        if (c == '\\' && p + 1 < end) {
            p += 2;
            continue;
        }
        if (c == '"' || c == '\'') {
            quote = c;
            p++;
            continue;
        }
        if (c == '[') bracket++;
        else if (c == ']' && bracket > 0) bracket--;
        else if (c == '(') paren++;
        else if (c == ')' && paren > 0) paren--;
        if (paren == 0 && bracket == 0 &&
            p + 2 <= end &&
            g_ascii_strncasecmp(p, "of", 2) == 0 &&
            (p == s || is_ws(p[-1])) &&
            (p + 2 == end || is_ws(p[2])))
            return p;
        p++;
    }
    return NULL;
}

static gboolean
anb_int_strict(const char *str, int *out)
{
    const char *p = str;
    if (*p == '+' || *p == '-') p++;
    if (!g_ascii_isdigit(*p)) return FALSE;
    for (const char *q = p; *q; q++)
        if (!g_ascii_isdigit(*q)) return FALSE;
    *out = ns_parse_int(str, 0, -1000000, 1000000);
    return TRUE;
}

static gboolean
parse_anb(const char *arg, gsize alen, int *out_a, int *out_b)
{
    char *raw = g_strndup(arg, alen);
    char *trimmed = g_strstrip(raw);
    char *s = g_malloc(strlen(trimmed) + 1);
    char *w = s;
    for (const char *r = trimmed; *r; r++)
        if (!is_ws(*r)) *w++ = *r;
    *w = '\0';
    int a = 0, b = 0;
    gboolean ok = TRUE;
    if (g_ascii_strcasecmp(s, "odd") == 0) {
        a = 2;
        b = 1;
    } else if (g_ascii_strcasecmp(s, "even") == 0) {
        a = 2;
        b = 0;
    } else {
        char *n_pos = strchr(s, 'n');
        if (!n_pos) n_pos = strchr(s, 'N');
        if (n_pos) {
            *n_pos = '\0';
            const char *a_str = s;
            if (!*a_str || strcmp(a_str, "+") == 0) a = 1;
            else if (strcmp(a_str, "-") == 0) a = -1;
            else ok = anb_int_strict(a_str, &a);
            const char *b_str = n_pos + 1;
            if (*b_str) {
                if (*b_str != '+' && *b_str != '-') ok = FALSE;
                else ok = ok && anb_int_strict(b_str, &b);
            }
        } else {
            a = 0;
            ok = anb_int_strict(s, &b);
        }
    }
    g_free(s);
    g_free(raw);
    if (!ok) return FALSE;
    *out_a = a;
    *out_b = b;
    return TRUE;
}

static gboolean
css_pseudo_class_is_standard(const char *name, gsize n)
{
    static const char *known[] = {
        "default", "indeterminate", "in-range", "out-of-range",
        "fullscreen", "modal", "autofill", "blank",
        "user-valid", "user-invalid", "target-within", "focus-visible",
        "local-link", "current", "past", "future",
        "playing", "paused", "muted", "seeking", "buffering", "stalled",
        "picture-in-picture", "volume-locked",
        "host", "host-context", "nth-col", "nth-last-col", "state",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(known); i++)
        if (strlen(known[i]) == n && g_ascii_strncasecmp(name, known[i], n) == 0)
            return TRUE;
    return FALSE;
}

static gboolean
css_pseudo_element_is_standard(const char *name, gsize n)
{
    static const char *known[] = {
        "part", "slotted", "cue", "cue-region", "highlight",
        "target-text", "spelling-error", "grammar-error",
        "file-selector-button", "details-content",
        "view-transition", "view-transition-group",
        "view-transition-image-pair", "view-transition-old",
        "view-transition-new",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(known); i++)
        if (strlen(known[i]) == n && g_ascii_strncasecmp(name, known[i], n) == 0)
            return TRUE;
    return FALSE;
}

typedef enum {
    PEK_NONE, PEK_GENERIC, PEK_BEFORE_AFTER, PEK_PART, PEK_SLOTTED,
    PEK_VT_ROOT, PEK_VT_CHILD, PEK_VENDOR
} css_pe_kind;

static gboolean
css_name_is(const char *name, gsize n, const char *want)
{
    return strlen(want) == n && g_ascii_strncasecmp(name, want, n) == 0;
}

static css_pe_kind
css_pseudo_element_kind(const char *name, gsize n)
{
    if (n > 0 && name[0] == '-') return PEK_VENDOR;
    if (css_name_is(name, n, "before") || css_name_is(name, n, "after"))
        return PEK_BEFORE_AFTER;
    if (css_name_is(name, n, "part")) return PEK_PART;
    if (css_name_is(name, n, "slotted")) return PEK_SLOTTED;
    if (css_name_is(name, n, "view-transition")) return PEK_VT_ROOT;
    if (css_name_is(name, n, "view-transition-group") ||
        css_name_is(name, n, "view-transition-image-pair") ||
        css_name_is(name, n, "view-transition-old") ||
        css_name_is(name, n, "view-transition-new"))
        return PEK_VT_CHILD;
    return PEK_GENERIC;
}

static gboolean
css_pseudo_element_may_follow(css_pe_kind prev, const char *name, gsize n)
{
    css_pe_kind next = css_pseudo_element_kind(name, n);
    if (prev == PEK_VENDOR || next == PEK_VENDOR) return TRUE;
    switch (prev) {
    case PEK_BEFORE_AFTER:
        return css_name_is(name, n, "marker");
    case PEK_PART:
        return next != PEK_PART && next != PEK_SLOTTED &&
               next != PEK_VT_ROOT && next != PEK_VT_CHILD;
    case PEK_SLOTTED:
        return next == PEK_BEFORE_AFTER || css_name_is(name, n, "marker") ||
               css_name_is(name, n, "placeholder") ||
               css_name_is(name, n, "file-selector-button") ||
               css_name_is(name, n, "details-content");
    default:
        return FALSE;
    }
}

static gboolean
css_pseudo_class_may_follow(css_pe_kind prev, const char *pe_name, gsize pe_n,
                            const char *name, gsize n)
{
    static const char *const structural[] = {
        "first-child", "last-child", "only-child", "nth-child",
        "nth-last-child", "first-of-type", "last-of-type", "only-of-type",
        "nth-of-type", "nth-last-of-type", "empty", "root",
    };
    static const char *const user_action[] = {
        "hover", "active", "focus", "focus-visible", "focus-within",
        "not", "is", "where",
    };
    switch (prev) {
    case PEK_VENDOR:
        return TRUE;
    case PEK_PART:
        for (gsize i = 0; i < G_N_ELEMENTS(structural); i++)
            if (css_name_is(name, n, structural[i])) return FALSE;
        return TRUE;
    case PEK_VT_CHILD:
        return css_name_is(name, n, "only-child");
    case PEK_GENERIC:
    case PEK_BEFORE_AFTER:
        if (css_name_is(pe_name, pe_n, "selection") &&
            css_name_is(name, n, "window-inactive"))
            return TRUE;
        for (gsize i = 0; i < G_N_ELEMENTS(user_action); i++)
            if (css_name_is(name, n, user_action[i])) return TRUE;
        return FALSE;
    default:
        return FALSE;
    }
}

static gboolean
css_vt_ident_char(unsigned char c)
{
    return g_ascii_isalnum(c) || c == '-' || c == '_' || c >= 0x80;
}

static gboolean
css_vt_arg_valid(const char *s, gsize n)
{
    const char *p = s, *end = s + n;
    while (p < end && g_ascii_isspace(*p)) p++;
    while (end > p && g_ascii_isspace(end[-1])) end--;
    if (p >= end) return FALSE;
    if (*p == '*') {
        p++;
    } else if (*p != '.') {
        const char *start = p;
        while (p < end && (css_vt_ident_char((unsigned char)*p) || *p == '\\')) {
            if (*p == '\\' && p + 1 < end) p++;
            p++;
        }
        if (p == start) return FALSE;
        if ((gsize)(p - start) == 4 && g_ascii_strncasecmp(start, "none", 4) == 0)
            return FALSE;
    }
    while (p < end) {
        if (*p != '.') return FALSE;
        p++;
        const char *start = p;
        while (p < end && (css_vt_ident_char((unsigned char)*p) || *p == '\\')) {
            if (*p == '\\' && p + 1 < end) p++;
            p++;
        }
        if (p == start) return FALSE;
    }
    return TRUE;
}

static gboolean
parse_pseudo_keyword(const char *name, gsize n,
                     const char *arg, gsize alen,
                     ns_css_pseudo_pred *out, int depth)
{
    struct { const char *k; ns_css_pseudo v; } table[] = {
        { "first-child",   NS_CSS_PC_FIRST_CHILD },
        { "last-child",    NS_CSS_PC_LAST_CHILD },
        { "only-child",    NS_CSS_PC_ONLY_CHILD },
        { "first-of-type", NS_CSS_PC_FIRST_OF_TYPE },
        { "last-of-type",  NS_CSS_PC_LAST_OF_TYPE },
        { "only-of-type",  NS_CSS_PC_ONLY_OF_TYPE },
        { "empty",         NS_CSS_PC_EMPTY },
        { "root",          NS_CSS_PC_ROOT },
        { "checked",       NS_CSS_PC_CHECKED },
        { "disabled",      NS_CSS_PC_DISABLED },
        { "enabled",       NS_CSS_PC_ENABLED },
        { "required",      NS_CSS_PC_REQUIRED },
        { "optional",      NS_CSS_PC_OPTIONAL },
        { "valid",         NS_CSS_PC_VALID },
        { "invalid",       NS_CSS_PC_INVALID },
        { "in-range",      NS_CSS_PC_IN_RANGE },
        { "out-of-range",  NS_CSS_PC_OUT_OF_RANGE },
        { "default",       NS_CSS_PC_DEFAULT },
        { "indeterminate", NS_CSS_PC_INDETERMINATE },
        { "link",          NS_CSS_PC_LINK },
        { "visited",       NS_CSS_PC_VISITED },
        { "any-link",      NS_CSS_PC_ANY_LINK },
        { "hover",         NS_CSS_PC_HOVER },
        { "active",        NS_CSS_PC_ACTIVE },
        { "focus",         NS_CSS_PC_FOCUS },
        { "focus-visible", NS_CSS_PC_FOCUS_VISIBLE },
        { "focus-within",  NS_CSS_PC_FOCUS_WITHIN },
        { "target",        NS_CSS_PC_TARGET },
        { "target-within", NS_CSS_PC_TARGET_WITHIN },
        { "defined",       NS_CSS_PC_DEFINED },
        { "scope",         NS_CSS_PC_SCOPE },
        { "placeholder-shown", NS_CSS_PC_PLACEHOLDER_SHOWN },
        { "read-only",     NS_CSS_PC_READ_ONLY },
        { "read-write",    NS_CSS_PC_READ_WRITE },
        { "blank",         NS_CSS_PC_BLANK },
        { "open",          NS_CSS_PC_OPEN },
        { "popover-open",  NS_CSS_PC_POPOVER_OPEN },
        { "modal",         NS_CSS_PC_MODAL },
        { "fullscreen",    NS_CSS_PC_FULLSCREEN },
        { "user-valid",    NS_CSS_PC_USER_VALID },
        { "user-invalid",  NS_CSS_PC_USER_INVALID },
        { "autofill",      NS_CSS_PC_AUTOFILL },
        { "-webkit-autofill", NS_CSS_PC_AUTOFILL },
        { "playing",       NS_CSS_PC_PLAYING },
        { "paused",        NS_CSS_PC_PAUSED },
        { "muted",         NS_CSS_PC_MUTED },
        { "seeking",       NS_CSS_PC_SEEKING },
        { "buffering",     NS_CSS_PC_BUFFERING },
        { "stalled",       NS_CSS_PC_STALLED },
    };
    for (gsize i = 0; i < G_N_ELEMENTS(table); i++) {
        gsize klen = strlen(table[i].k);
        if (klen == n && g_ascii_strncasecmp(name, table[i].k, n) == 0) {
            out->kind = table[i].v;
            out->a = 0;
            out->b = 0;
            return TRUE;
        }
    }
    if (n == 7 && g_ascii_strncasecmp(name, "heading", 7) == 0) {
        out->kind = NS_CSS_PC_HEADING;
        out->a = 0;
        out->b = 0;
        if (!arg) {
            out->arg = NULL;
            return TRUE;
        }
        char *raw = g_strndup(arg, alen);
        char **items = g_strsplit(raw, ",", -1);
        gboolean ok = items[0] != NULL;
        for (int i = 0; ok && items[i]; i++) {
            int v = 0;
            if (!anb_int_strict(g_strstrip(items[i]), &v)) ok = FALSE;
        }
        g_strfreev(items);
        if (!ok) {
            g_free(raw);
            return FALSE;
        }
        out->arg = raw;
        return TRUE;
    }
    if (arg && ((n == 9 && g_ascii_strncasecmp(name, "nth-child", 9) == 0) ||
                (n == 14 && g_ascii_strncasecmp(name, "nth-last-child", 14) == 0) ||
                (n == 11 && g_ascii_strncasecmp(name, "nth-of-type", 11) == 0) ||
                (n == 16 && g_ascii_strncasecmp(name, "nth-last-of-type", 16) == 0))) {
        const char *as = arg;
        const char *ae = arg + alen;
        const char *of = (n == 9 || n == 14) ? css_find_nth_of(as, ae) : NULL;
        const char *anb_end = of ? of : ae;
        int a = 0, b = 0;
        if (!parse_anb(as, (gsize)(anb_end - as), &a, &b)) return FALSE;
        if (of) {
            const char *fs = css_skip_ws_comments(of + 2, ae);
            GPtrArray *group = parse_selector_group(fs, (gsize)(ae - fs),
                                                    depth + 1);
            if (!group || group->len == 0) {
                if (group) g_ptr_array_free(group, TRUE);
                return FALSE;
            }
            out->of_group = group;
        }
        if (n == 9) out->kind = NS_CSS_PC_NTH_CHILD;
        else if (n == 14) out->kind = NS_CSS_PC_NTH_LAST_CHILD;
        else if (n == 11) out->kind = NS_CSS_PC_NTH_OF_TYPE;
        else out->kind = NS_CSS_PC_NTH_LAST_OF_TYPE;
        out->a = a;
        out->b = b;
        return TRUE;
    }
    if (arg && n == 4 && g_ascii_strncasecmp(name, "lang", 4) == 0) {
        char *lang = css_trim_dup_range(arg, arg + alen);
        if (!lang || !*lang) {
            g_free(lang);
            return FALSE;
        }
        out->kind = NS_CSS_PC_LANG;
        out->arg = lang;
        return TRUE;
    }
    if (arg && n == 3 && g_ascii_strncasecmp(name, "dir", 3) == 0) {
        char *dir = css_trim_dup_range(arg, arg + alen);
        char *lo = g_ascii_strdown(dir ? dir : "", -1);
        g_free(dir);
        if (strcmp(lo, "ltr") != 0 && strcmp(lo, "rtl") != 0) {
            g_free(lo);
            return FALSE;
        }
        out->kind = NS_CSS_PC_DIR;
        out->arg = lo;
        return TRUE;
    }
    return FALSE;
}

static void
selector_group_max_specificity(const GPtrArray *group, int *a, int *b, int *c)
{
    for (guint i = 0; group && i < group->len; i++) {
        const ns_css_selector *sub = g_ptr_array_index(group, i);
        if (sub->spec_a > *a ||
            (sub->spec_a == *a && sub->spec_b > *b) ||
            (sub->spec_a == *a && sub->spec_b == *b && sub->spec_c > *c)) {
            *a = sub->spec_a;
            *b = sub->spec_b;
            *c = sub->spec_c;
        }
    }
}

static ns_css_selector *
parse_one_selector(const char **pp, const char *end, int depth)
{
    return parse_one_selector_rel(pp, end, depth, FALSE);
}

static guint32
css_identifier_hash(char kind, const char *name, gsize len)
{
    guint32 h = 2166136261u;
    h = (h ^ (guchar)kind) * 16777619u;
    for (gsize i = 0; i < len; i++)
        h = (h ^ (guchar)g_ascii_tolower(name[i])) * 16777619u;
    return h;
}

static void
css_selector_add_ancestor_hash(ns_css_selector *sel, guint32 hash)
{
    if (sel->n_ancestor_hashes < G_N_ELEMENTS(sel->ancestor_hashes))
        sel->ancestor_hashes[sel->n_ancestor_hashes++] = hash;
}

static gboolean g_css_attr_ancestor_hashes;

static guint32
css_attr_value_hash(const char *name, const char *value, gsize value_len)
{
    guint32 h = css_identifier_hash('[', name, strlen(name));
    h = (h ^ (guchar)'=') * 16777619u;
    for (gsize i = 0; i < value_len; i++)
        h = (h ^ (guchar)value[i]) * 16777619u;
    return h;
}

static gboolean
css_attr_pred_filterable(const ns_css_attr_pred *a)
{
    return a->op == NS_CSS_ATTR_EQ && a->name && a->value &&
           !a->case_insensitive && !a->html_ci && !strchr(a->name, '|');
}

static void
css_selector_collect_attr_ancestor_hashes(ns_css_selector *sel)
{
    for (int k = (int)sel->compounds->len - 2; k >= 0; k--) {
        ns_css_comb right = g_array_index(sel->combinators, ns_css_comb, k + 1);
        if (right != NS_CSS_COMB_DESCENDANT && right != NS_CSS_COMB_CHILD)
            continue;
        const ns_css_simple *c = g_ptr_array_index(sel->compounds, k);
        for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
            const ns_css_attr_pred *a =
                &g_array_index(c->attrs, ns_css_attr_pred, i);
            if (!css_attr_pred_filterable(a)) continue;
            css_selector_add_ancestor_hash(
                sel, css_attr_value_hash(a->name, a->value, strlen(a->value)));
            sel->n_ancestor_attr_hashes = sel->n_ancestor_hashes;
            if (!g_css_detached) g_css_attr_ancestor_hashes = TRUE;
        }
    }
}

static void
css_selector_collect_ancestor_hashes(ns_css_selector *sel)
{
    css_selector_collect_attr_ancestor_hashes(sel);
    for (int k = (int)sel->compounds->len - 2; k >= 0; k--) {
        ns_css_comb right = g_array_index(sel->combinators, ns_css_comb, k + 1);
        if (right != NS_CSS_COMB_DESCENDANT && right != NS_CSS_COMB_CHILD)
            continue;
        const ns_css_simple *c = g_ptr_array_index(sel->compounds, k);
        if (c->id)
            css_selector_add_ancestor_hash(
                sel, css_identifier_hash('#', c->id, strlen(c->id)));
        for (guint i = 0; i < c->classes->len; i++) {
            const char *cls = g_ptr_array_index(c->classes, i);
            css_selector_add_ancestor_hash(
                sel, css_identifier_hash('.', cls, strlen(cls)));
        }
        if (c->type && strcmp(c->type, "*") != 0)
            css_selector_add_ancestor_hash(
                sel, css_identifier_hash('%', c->type, strlen(c->type)));
    }
}

static gboolean ns_css_html_ci_attr(const char *name);

static ns_css_selector *
parse_one_selector_rel(const char **pp, const char *end, int depth,
                       gboolean relative)
{
    ns_css_selector *sel = g_new0(ns_css_selector, 1);
    sel->compounds   = g_ptr_array_new();
    sel->combinators = g_array_new(FALSE, FALSE, sizeof(ns_css_comb));

    ns_css_comb pending = NS_CSS_COMB_NONE;
    gboolean expect_compound = TRUE;
    gboolean leading_comb_used = FALSE;
    css_pe_kind pe_kind = PEK_NONE;
    const char *pe_name = "";
    gsize pe_name_n = 0;
    char *pe_name_buf = NULL;
    const char *p = *pp;

    while (p < end) {
        gboolean had_ws = FALSE;
        const char *before_ws = p;
        p = css_skip_ws_comments(p, end);
        had_ws = p > before_ws;
        if (p >= end) break;
        char c = *p;

        if (c == ',' || c == '{') break;

        if (c == '>' || c == '+' || c == '~') {
            if (relative && sel->compounds->len == 0 && !leading_comb_used)
                leading_comb_used = TRUE;
            else if (expect_compound || sel->compounds->len == 0)
                g_sel_parse_error = TRUE;
            pending = c == '>' ? NS_CSS_COMB_CHILD
                    : c == '+' ? NS_CSS_COMB_ADJACENT
                    : NS_CSS_COMB_SIBLING;
            expect_compound = TRUE;
            p++;
            continue;
        }

        if (had_ws && !expect_compound)
            pending = NS_CSS_COMB_DESCENDANT;

        if (pe_kind != PEK_NONE && pe_kind != PEK_VENDOR)
            g_sel_parse_error = TRUE;
        ns_css_simple *cmp = ns_css_simple_new();
        gboolean any = FALSE;
        while (p < end) {
            const char *tok_start = p;
            char cc = *p;
            if (pe_kind != PEK_NONE && pe_kind != PEK_VENDOR && cc != ':' &&
                (cc == '*' || cc == '|' || cc == '#' || cc == '.' || cc == '[' ||
                 is_ident_start(cc) || cc == '\\'))
                g_sel_parse_error = TRUE;
            if (cc == '*' || (cc == '|' && !(p + 1 < end && p[1] == '='))) {
                if (any) {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                }
                if (cc == '*') {
                    p++;
                }
                if (p < end && *p == '|' && !(p + 1 < end && p[1] == '=')) {
                    if (cc == '|')
                        cmp->ns_none = TRUE;
                    p++;
                    if (p < end && *p == '*') {
                        p++;
                        g_free(cmp->type);
                        cmp->type = g_strdup("*");
                    }
                    else {
                        char *type = read_css_ident(&p, end);
                        if (type && *type) {
                            if (!cmp->type) {
                                cmp->type = ascii_lower(type, strlen(type));
                                css_simple_keep_type_case(cmp, type);
                                sel->spec_c += 1;
                            }
                        }
                        else {
                            g_sel_parse_error = TRUE;
                        }
                        g_free(type);
                    }
                }
                else {
                    if (cmp->type) {
                        g_sel_parse_error = TRUE;
                        cmp->never_match = TRUE;
                    }
                    g_free(cmp->type);
                    cmp->type = g_strdup("*");
                }
                any = TRUE;
            } else if (cc == '#') {
                p++;
                char *id_str = read_css_ident(&p, end);
                if (id_str && *id_str) {
                    g_free(cmp->id);
                    cmp->id = id_str;
                    sel->spec_a += 1;
                } else {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                    g_free(id_str);
                }
                any = TRUE;
            } else if (cc == '.') {
                p++;
                gboolean bad_start = FALSE;
                if (p < end) {
                    unsigned char nc = (unsigned char)*p;
                    if (g_ascii_isdigit(nc))
                        bad_start = TRUE;
                    else if (nc == '-' && p + 1 < end &&
                             g_ascii_isdigit((unsigned char)p[1]))
                        bad_start = TRUE;
                }
                char *cls = read_css_ident(&p, end);
                if (!bad_start && cls && *cls) {
                    gsize cls_len = strlen(cls);
                    g_ptr_array_add(cmp->classes, cls);
                    g_array_append_val(cmp->class_lens, cls_len);
                    sel->spec_b += 1;
                } else {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                    g_free(cls);
                }
                any = TRUE;
            } else if (is_ident_start(cc) || cc == '\\') {
                if (any) {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                }
                char *type = read_css_ident(&p, end);
                if (p < end && *p == '|' && !(p + 1 < end && p[1] == '=')) {
                    g_sel_ns_prefix = TRUE;
                    cmp->never_match = TRUE;
                    p++;
                    if (p < end && *p == '*') {
                        p++;
                    }
                    else {
                        char *unused = read_css_ident(&p, end);
                        g_free(unused);
                    }
                }
                else if (!cmp->type) {
                    cmp->type = ascii_lower(type, strlen(type));
                    css_simple_keep_type_case(cmp, type);
                    sel->spec_c += 1;
                }
                else {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                }
                g_free(type);
                any = TRUE;
            } else if (cc == ':') {
                p++;
                gboolean is_element = (p < end && *p == ':');
                if (is_element) p++;
                char *pseudo_name = read_css_ident(&p, end);
                const char *name_s = pseudo_name;
                gsize name_n = strlen(pseudo_name);
                if (name_n == 0) {
                    g_sel_parse_error = TRUE;
                    cmp->never_match = TRUE;
                    g_free(pseudo_name);
                    any = TRUE;
                    continue;
                }
                const char *arg_s = NULL;
                gsize arg_n = 0;
                if (p < end && *p == '(') {
                    p++;
                    arg_s = p;
                    char term = 0;
                    const char *arg_end = css_scan_until(p, end, ")", &term);
                    arg_n = (gsize)(arg_end - arg_s);
                    p = term == ')' ? arg_end + 1 : arg_end;
                }
                gboolean names_element = is_element ||
                    css_name_is(name_s, name_n, "before") ||
                    css_name_is(name_s, name_n, "after") ||
                    css_name_is(name_s, name_n, "first-line") ||
                    css_name_is(name_s, name_n, "first-letter");
                if (names_element) {
                    css_pe_kind kind = css_pseudo_element_kind(name_s, name_n);
                    if (depth > 0 && kind != PEK_VENDOR)
                        g_sel_parse_error = TRUE;
                    if (pe_kind != PEK_NONE &&
                        !css_pseudo_element_may_follow(pe_kind, name_s, name_n))
                        g_sel_parse_error = TRUE;
                    if (kind == PEK_VT_ROOT && arg_s)
                        g_sel_parse_error = TRUE;
                    if (kind == PEK_VT_CHILD &&
                        (!arg_s || !css_vt_arg_valid(arg_s, arg_n)))
                        g_sel_parse_error = TRUE;
                    pe_kind = kind;
                    g_free(pe_name_buf);
                    pe_name_buf = g_strndup(name_s, name_n);
                    pe_name = pe_name_buf;
                    pe_name_n = name_n;
                } else if (pe_kind != PEK_NONE &&
                           !css_pseudo_class_may_follow(pe_kind, pe_name, pe_name_n,
                                                        name_s, name_n)) {
                    g_sel_parse_error = TRUE;
                }
                if (is_element ||
                    (name_n == 6 && g_ascii_strncasecmp(name_s, "before", 6) == 0) ||
                    (name_n == 5 && g_ascii_strncasecmp(name_s, "after",  5) == 0) ||
                    (name_n == 10 && g_ascii_strncasecmp(name_s, "first-line", 10) == 0) ||
                    (name_n == 12 && g_ascii_strncasecmp(name_s, "first-letter", 12) == 0)) {
                    if (name_n == 6 && g_ascii_strncasecmp(name_s, "before", 6) == 0) {
                        sel->pseudo_element = NS_CSS_PE_BEFORE;
                        sel->spec_c += 1;
                    } else if (name_n == 5 && g_ascii_strncasecmp(name_s, "after", 5) == 0) {
                        sel->pseudo_element = NS_CSS_PE_AFTER;
                        sel->spec_c += 1;
                    } else if (name_n == 12 && g_ascii_strncasecmp(name_s, "first-letter", 12) == 0) {
                        sel->pseudo_element = NS_CSS_PE_FIRST_LETTER;
                        sel->spec_c += 1;
                    } else if (name_n == 10 && g_ascii_strncasecmp(name_s, "first-line", 10) == 0) {
                        sel->pseudo_element = NS_CSS_PE_FIRST_LINE;
                        sel->spec_c += 1;
                    } else if (name_n == 9 && g_ascii_strncasecmp(name_s, "selection", 9) == 0) {
                        sel->pseudo_element = NS_CSS_PE_SELECTION;
                        sel->spec_c += 1;
                    } else if (name_n == 6 && g_ascii_strncasecmp(name_s, "marker", 6) == 0) {
                        sel->pseudo_element = NS_CSS_PE_MARKER;
                        sel->spec_c += 1;
                    } else if (name_n == 8 && g_ascii_strncasecmp(name_s, "backdrop", 8) == 0) {
                        sel->pseudo_element = NS_CSS_PE_BACKDROP;
                        sel->spec_c += 1;
                    } else if (name_n == 20 &&
                               g_ascii_strncasecmp(name_s,
                                                   "file-selector-button",
                                                   20) == 0) {
                        sel->pseudo_element = NS_CSS_PE_FILE_SELECTOR_BUTTON;
                        sel->spec_c += 1;
                    } else if ((name_n == 11 &&
                                g_ascii_strncasecmp(name_s, "placeholder", 11) == 0) ||
                               (name_n == 25 &&
                                g_ascii_strncasecmp(name_s, "-webkit-input-placeholder", 25) == 0) ||
                               (name_n == 21 &&
                                g_ascii_strncasecmp(name_s, "-ms-input-placeholder", 21) == 0) ||
                               (name_n == 16 &&
                                g_ascii_strncasecmp(name_s, "-moz-placeholder", 16) == 0)) {
                        sel->pseudo_element = NS_CSS_PE_PLACEHOLDER;
                        sel->spec_c += 1;
                    } else {
                        cmp->never_match = TRUE;
                        if (name_s[0] != '-'
                            && !css_pseudo_element_is_standard(name_s, name_n))
                            g_sel_parse_error = TRUE;
                        else if (name_s[0] != '-')
                            cmp->known_unmatched = TRUE;
                    }
                } else if (name_n == 3 && arg_s &&
                           g_ascii_strncasecmp(name_s, "has", 3) == 0 &&
                           g_sel_has_depth > 0) {
                    cmp->never_match = TRUE;
                    g_sel_parse_error = TRUE;
                } else if (name_n == 3 && arg_s &&
                           g_ascii_strncasecmp(name_s, "has", 3) == 0) {
                    g_sel_has_depth++;
                    GPtrArray *group = parse_selector_group_rel(arg_s, arg_n,
                                                                depth + 1, TRUE);
                    g_sel_has_depth--;
                    if (group->len == 0) {
                        g_ptr_array_free(group, TRUE);
                        cmp->never_match = TRUE;
                    } else {
                        if (!cmp->has_groups)
                            cmp->has_groups = g_ptr_array_new_with_free_func(
                                matches_any_group_free);
                        g_ptr_array_add(cmp->has_groups, group);
                        int ma = 0, mb = 0, mc = 0;
                        for (guint gi = 0; gi < group->len; gi++) {
                            const ns_css_selector *sub =
                                g_ptr_array_index(group, gi);
                            if (sub->spec_a > ma ||
                                (sub->spec_a == ma && sub->spec_b > mb) ||
                                (sub->spec_a == ma && sub->spec_b == mb &&
                                 sub->spec_c > mc)) {
                                ma = sub->spec_a;
                                mb = sub->spec_b;
                                mc = sub->spec_c;
                            }
                        }
                        sel->spec_a += ma;
                        sel->spec_b += mb;
                        sel->spec_c += mc;
                    }
                } else if (name_n > 0 && arg_s &&
                           ((name_n == 2 && g_ascii_strncasecmp(name_s, "is",    2) == 0) ||
                            (name_n == 5 && g_ascii_strncasecmp(name_s, "where", 5) == 0))) {
                    gboolean is_where = (name_n == 5);
                    gboolean saved_err = g_sel_parse_error;
                    gboolean saved_ns = g_sel_ns_prefix;
                    GPtrArray *group = parse_selector_group(arg_s, arg_n, depth + 1);
                    if (!g_sel_strict) g_sel_parse_error = saved_err;
                    g_sel_ns_prefix = saved_ns;
                    if (group->len == 0) {
                        g_ptr_array_free(group, TRUE);
                        cmp->never_match = TRUE;
                    } else {
                        if (!cmp->matches_any)
                            cmp->matches_any = g_ptr_array_new_with_free_func(
                                matches_any_group_free);
                        g_ptr_array_add(cmp->matches_any, group);
                        if (!is_where) {
                            int ma = 0, mb = 0, mc = 0;
                            for (guint gi = 0; gi < group->len; gi++) {
                                const ns_css_selector *sub =
                                    g_ptr_array_index(group, gi);
                                if (sub->spec_a > ma ||
                                    (sub->spec_a == ma && sub->spec_b > mb) ||
                                    (sub->spec_a == ma && sub->spec_b == mb &&
                                     sub->spec_c > mc)) {
                                    ma = sub->spec_a;
                                    mb = sub->spec_b;
                                    mc = sub->spec_c;
                                }
                            }
                            sel->spec_a += ma;
                            sel->spec_b += mb;
                            sel->spec_c += mc;
                        }
                    }
                } else if (name_n == 3 && arg_s &&
                           g_ascii_strncasecmp(name_s, "not", 3) == 0) {
                    GPtrArray *group = parse_selector_group(arg_s, arg_n, depth + 1);
                    if (group->len == 0) {
                        g_ptr_array_free(group, TRUE);
                    } else {
                        if (!cmp->matches_none)
                            cmp->matches_none = g_ptr_array_new_with_free_func(
                                matches_any_group_free);
                        g_ptr_array_add(cmp->matches_none, group);
                        int ma = 0, mb = 0, mc = 0;
                        for (guint gi = 0; gi < group->len; gi++) {
                            const ns_css_selector *sub =
                                g_ptr_array_index(group, gi);
                            if (sub->spec_a > ma ||
                                (sub->spec_a == ma && sub->spec_b > mb) ||
                                (sub->spec_a == ma && sub->spec_b == mb &&
                                 sub->spec_c > mc)) {
                                ma = sub->spec_a;
                                mb = sub->spec_b;
                                mc = sub->spec_c;
                            }
                        }
                        sel->spec_a += ma;
                        sel->spec_b += mb;
                        sel->spec_c += mc;
                    }
                } else if (name_n > 0) {
                    ns_css_pseudo_pred pc = {0};
                    if (parse_pseudo_keyword(name_s, name_n, arg_s, arg_n, &pc,
                                             depth)) {
                        g_array_append_val(cmp->pseudos, pc);
                        if (pc.kind == NS_CSS_PC_HOVER)
                            g_sel_has_hover = TRUE;
                        if (pc.kind == NS_CSS_PC_ACTIVE)
                            g_sel_has_active = TRUE;
                        sel->spec_b += 1;
                        int ma = 0, mb = 0, mc = 0;
                        selector_group_max_specificity(pc.of_group, &ma, &mb, &mc);
                        sel->spec_a += ma;
                        sel->spec_b += mb;
                        sel->spec_c += mc;
                    } else {
                        cmp->never_match = TRUE;
                        if (!css_pseudo_class_is_standard(name_s, name_n))
                            g_sel_parse_error = TRUE;
                    }
                } else {
                    cmp->never_match = TRUE;
                    g_sel_parse_error = TRUE;
                }
                g_free(pseudo_name);
                any = TRUE;
            } else if (cc == '[') {
                p++;
                p = css_skip_ws_comments(p, end);
                if (p + 1 < end && *p == '*' && p[1] == '|') {
                    p += 2;
                }
                else if (p < end && *p == '|' && !(p + 1 < end && p[1] == '=')) {
                    p++;
                }
                char *attr_name = read_css_ident(&p, end);
                if (attr_name && *attr_name && p < end && *p == '|'
                    && !(p + 1 < end && p[1] == '='))
                {
                    g_sel_ns_prefix = TRUE;
                    g_free(attr_name);
                    p++;
                    attr_name = read_css_ident(&p, end);
                    cmp->never_match = TRUE;
                }
                if (!attr_name || !*attr_name) {
                    g_free(attr_name);
                    char term = 0;
                    const char *close = css_scan_until(p, end, "]", &term);
                    p = term == ']' ? close + 1 : close;
                    continue;
                }
                ns_css_attr_pred ap = {0};
                ap.name = ascii_lower(attr_name, strlen(attr_name));
                ap.name_bit = ns_attr_name_bloom_bit(ap.name);
                ap.html_ci = ns_css_html_ci_attr(ap.name);
                g_free(attr_name);
                ap.op   = NS_CSS_ATTR_PRESENT;
                p = css_skip_ws_comments(p, end);
                if (p < end && (*p == '=' || *p == '^' || *p == '$' ||
                                *p == '*' || *p == '~' || *p == '|')) {
                    char op_c = *p;
                    if (op_c == '=')      ap.op = NS_CSS_ATTR_EQ;
                    else if (op_c == '^') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_PREFIX; }
                    else if (op_c == '$') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_SUFFIX; }
                    else if (op_c == '*') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_SUBSTR; }
                    else if (op_c == '~') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_WORD;   }
                    else if (op_c == '|') { p++; if (p < end && *p == '=') ap.op = NS_CSS_ATTR_HYPHEN; }
                    if (p < end && *p == '=') p++;
                    p = css_skip_ws_comments(p, end);
                    char q = (p < end) ? *p : 0;
                    if (q == '"' || q == '\'') {
                        ap.value = read_css_string(&p, end);
                    } else {
                        ap.value = read_css_ident(&p, end);
                    }
                }
                p = css_skip_ws_comments(p, end);
                if (p < end && *p != ']') {
                    const char *flag_start = p;
                    char *flag = read_css_ident(&p, end);
                    if (flag && g_ascii_strcasecmp(flag, "i") == 0) {
                        if (ap.op == NS_CSS_ATTR_PRESENT) g_sel_parse_error = TRUE;
                        ap.case_insensitive = TRUE;
                    } else if (flag && g_ascii_strcasecmp(flag, "s") == 0) {
                        if (ap.op == NS_CSS_ATTR_PRESENT) g_sel_parse_error = TRUE;
                        ap.case_sensitive = TRUE;
                    } else {
                        p = flag_start;
                        g_sel_parse_error = TRUE;
                    }
                    g_free(flag);
                }
                p = css_skip_ws_comments(p, end);
                if (p < end && *p != ']')
                    g_sel_parse_error = TRUE;
                char term = 0;
                const char *close = css_scan_until(p, end, "]", &term);
                p = term == ']' ? close + 1 : close;
                g_array_append_val(cmp->attrs, ap);
                sel->spec_b += 1;
                any = TRUE;
            } else {
                break;
            }
            if (p == tok_start) break;
        }
        if (!any) { ns_css_simple_free(cmp); break; }
        g_ptr_array_add(sel->compounds, cmp);
        g_array_append_val(sel->combinators, pending);
        pending = NS_CSS_COMB_NONE;
        expect_compound = FALSE;
    }
    *pp = p;
    g_free(pe_name_buf);
    if (pending != NS_CSS_COMB_NONE)
        g_sel_parse_error = TRUE;
    if (sel->compounds->len == 0) {
        ns_css_selector_free(sel);
        return NULL;
    }
    if (!relative) css_selector_collect_ancestor_hashes(sel);
    return sel;
}

static gboolean
parse_length(const char *text, double *out_v, ns_css_unit *out_unit)
{
    if (!text || !*text) return FALSE;
    const char *p = text;
    if (*p == '-' || *p == '+') p++;
    const char *num_start = p;
    while (*p && (g_ascii_isdigit(*p) || *p == '.')) p++;
    if (p == num_start) return FALSE;
    char *end = NULL;
    double v = g_ascii_strtod(text, &end);
    if (!end || end == text) return FALSE;
    *out_v = v;
    if (*end == '\0') { *out_unit = NS_CSS_UNIT_NUMBER; return TRUE; }
    if (g_ascii_strcasecmp(end, "px") == 0) { *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    if (g_ascii_strcasecmp(end, "em")  == 0) { *out_unit = NS_CSS_UNIT_EM;  return TRUE; }
    if (g_ascii_strcasecmp(end, "rem") == 0) { *out_unit = NS_CSS_UNIT_REM; return TRUE; }
    if (g_ascii_strcasecmp(end, "%")   == 0) { *out_unit = NS_CSS_UNIT_PERCENT; return TRUE; }
    if (g_ascii_strcasecmp(end, "vw") == 0) { *out_unit = NS_CSS_UNIT_VW; return TRUE; }
    if (g_ascii_strcasecmp(end, "vh") == 0) { *out_unit = NS_CSS_UNIT_VH; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvw") == 0 || g_ascii_strcasecmp(end, "svw") == 0 ||
        g_ascii_strcasecmp(end, "lvw") == 0) { *out_unit = NS_CSS_UNIT_VW; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvh") == 0 || g_ascii_strcasecmp(end, "svh") == 0 ||
        g_ascii_strcasecmp(end, "lvh") == 0) { *out_unit = NS_CSS_UNIT_VH; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqi") == 0 || g_ascii_strcasecmp(end, "cqw") == 0) {
        *out_unit = NS_CSS_UNIT_CQW;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "cqb") == 0 || g_ascii_strcasecmp(end, "cqh") == 0) {
        *out_unit = NS_CSS_UNIT_CQH;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "vi") == 0 || g_ascii_strcasecmp(end, "dvi") == 0 ||
        g_ascii_strcasecmp(end, "svi") == 0 || g_ascii_strcasecmp(end, "lvi") == 0) {
        *out_unit = NS_CSS_UNIT_VW;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "vb") == 0 || g_ascii_strcasecmp(end, "dvb") == 0 ||
        g_ascii_strcasecmp(end, "svb") == 0 || g_ascii_strcasecmp(end, "lvb") == 0) {
        *out_unit = NS_CSS_UNIT_VH;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "vmin") == 0) { *out_unit = NS_CSS_UNIT_VMIN; return TRUE; }
    if (g_ascii_strcasecmp(end, "vmax") == 0) { *out_unit = NS_CSS_UNIT_VMAX; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvmin") == 0 || g_ascii_strcasecmp(end, "svmin") == 0 ||
        g_ascii_strcasecmp(end, "lvmin") == 0) { *out_unit = NS_CSS_UNIT_VMIN; return TRUE; }
    if (g_ascii_strcasecmp(end, "dvmax") == 0 || g_ascii_strcasecmp(end, "svmax") == 0 ||
        g_ascii_strcasecmp(end, "lvmax") == 0) { *out_unit = NS_CSS_UNIT_VMAX; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqmin") == 0) { *out_unit = NS_CSS_UNIT_CQMIN; return TRUE; }
    if (g_ascii_strcasecmp(end, "cqmax") == 0) { *out_unit = NS_CSS_UNIT_CQMAX; return TRUE; }
    if (g_ascii_strcasecmp(end, "pt")  == 0) {
        *out_v = v * (96.0 / 72.0);
        *out_unit = NS_CSS_UNIT_PX;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "pc")  == 0) {
        *out_v = v * 16.0;
        *out_unit = NS_CSS_UNIT_PX;
        return TRUE;
    }
    if (g_ascii_strcasecmp(end, "ex")   == 0) { *out_unit = NS_CSS_UNIT_EX;   return TRUE; }
    if (g_ascii_strcasecmp(end, "ch")   == 0) { *out_unit = NS_CSS_UNIT_CH;   return TRUE; }
    if (g_ascii_strcasecmp(end, "cap")  == 0) { *out_unit = NS_CSS_UNIT_CAP;  return TRUE; }
    if (g_ascii_strcasecmp(end, "ic")   == 0) { *out_unit = NS_CSS_UNIT_IC;   return TRUE; }
    if (g_ascii_strcasecmp(end, "lh")   == 0) { *out_unit = NS_CSS_UNIT_LH;   return TRUE; }
    if (g_ascii_strcasecmp(end, "rlh")  == 0) { *out_unit = NS_CSS_UNIT_RLH;  return TRUE; }
    if (g_ascii_strcasecmp(end, "rex")  == 0) { *out_unit = NS_CSS_UNIT_REX;  return TRUE; }
    if (g_ascii_strcasecmp(end, "rch")  == 0) { *out_unit = NS_CSS_UNIT_RCH;  return TRUE; }
    if (g_ascii_strcasecmp(end, "rcap") == 0) { *out_unit = NS_CSS_UNIT_RCAP; return TRUE; }
    if (g_ascii_strcasecmp(end, "ric")  == 0) { *out_unit = NS_CSS_UNIT_RIC;  return TRUE; }
    if (g_ascii_strcasecmp(end, "cm")  == 0) { *out_v = v * (96.0 / 2.54); *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    if (g_ascii_strcasecmp(end, "mm")  == 0) { *out_v = v * (96.0 / 25.4); *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    if (g_ascii_strcasecmp(end, "q")   == 0) { *out_v = v * (96.0 / 101.6); *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    if (g_ascii_strcasecmp(end, "in")  == 0) { *out_v = v * 96.0;   *out_unit = NS_CSS_UNIT_PX; return TRUE; }
    return FALSE;
}

static double
font_size_keyword_px(const char *t)
{
    if (!t) return -1;
    if (g_ascii_strcasecmp(t, "xx-small")  == 0) return 9;
    if (g_ascii_strcasecmp(t, "x-small")   == 0) return 10;
    if (g_ascii_strcasecmp(t, "small")     == 0) return 13;
    if (g_ascii_strcasecmp(t, "medium")    == 0) return 16;
    if (g_ascii_strcasecmp(t, "large")     == 0) return 18;
    if (g_ascii_strcasecmp(t, "x-large")   == 0) return 24;
    if (g_ascii_strcasecmp(t, "xx-large")  == 0) return 32;
    if (g_ascii_strcasecmp(t, "xxx-large") == 0) return 48;
    return -1;
}

static ns_css_value *parse_calc(const char *text);
static ns_css_value *parse_calc_inner(const char *text);
static char *angle_expr_rewrite(const char *s, gboolean to_radians);

static void
font_unit_set(double *out_em, double *out_rem, ns_css_unit unit, double v,
              double *out_px)
{
    double *slot = unit == NS_CSS_UNIT_EM ? out_em : out_rem;
    if (slot) *slot = v;
    else *out_px = v * 16.0;
}

static gboolean
resolve_to_px_pct_font(const char *text, gsize len, double *out_px,
                       double *out_pct, double *out_em, double *out_rem)
{
    char *s = g_strndup(text, len);
    g_strstrip(s);
    *out_px = 0;
    *out_pct = 0;
    if (out_em) *out_em = 0;
    if (out_rem) *out_rem = 0;
    ns_css_value *v = parse_calc(s);
    if (!v) {
        char *wrapped = g_strdup_printf("calc(%s)", s);
        v = parse_calc(wrapped);
        g_free(wrapped);
    }
    if (v && v->kind == NS_CSS_V_CALC) {
        if (out_em && out_rem) {
            *out_em = v->u.calc.em;
            *out_rem = v->u.calc.rem;
            *out_px = v->u.calc.px;
        } else {
            double rel = v->u.calc.em * 16.0 + v->u.calc.rem * g_root_font_px;
            *out_px = rel == 0 ? v->u.calc.px : v->u.calc.px + rel;
        }
        *out_pct = v->u.calc.pct;
        ns_css_value_free(v);
        g_free(s);
        return TRUE;
    }
    if (v && v->kind == NS_CSS_V_LENGTH) {
        switch (v->u.length.unit) {
        case NS_CSS_UNIT_PERCENT:
            *out_pct = v->u.length.v;
            break;
        case NS_CSS_UNIT_EM:
        case NS_CSS_UNIT_REM:
            font_unit_set(out_em, out_rem, v->u.length.unit, v->u.length.v,
                          out_px);
            break;
        default:
            *out_px = v->u.length.v;
            break;
        }
        ns_css_value_free(v);
        g_free(s);
        return TRUE;
    }
    if (v) ns_css_value_free(v);
    double num;
    ns_css_unit u;
    if (parse_length(s, &num, &u)) {
        switch (u) {
        case NS_CSS_UNIT_PERCENT: *out_pct = num; break;
        case NS_CSS_UNIT_EM:
        case NS_CSS_UNIT_REM:
            font_unit_set(out_em, out_rem, u, num, out_px);
            break;
        case NS_CSS_UNIT_VW:      *out_px = num * g_viewport_w / 100.0; break;
        case NS_CSS_UNIT_VH:      *out_px = num * g_viewport_h / 100.0; break;
        case NS_CSS_UNIT_VMIN:
            *out_px = num * (g_viewport_w < g_viewport_h ?
                             g_viewport_w : g_viewport_h) / 100.0;
            break;
        case NS_CSS_UNIT_VMAX:
            *out_px = num * (g_viewport_w > g_viewport_h ?
                             g_viewport_w : g_viewport_h) / 100.0;
            break;
        case NS_CSS_UNIT_CQW:
        case NS_CSS_UNIT_CQH:
        case NS_CSS_UNIT_CQMIN:
        case NS_CSS_UNIT_CQMAX:
            *out_px = container_unit_resolve(num, u);
            break;
        default:                  *out_px = num; break;
        }
        g_free(s);
        return TRUE;
    }
    g_free(s);
    return FALSE;
}

static gboolean
resolve_to_px_pct(const char *text, gsize len, double *out_px, double *out_pct)
{
    return resolve_to_px_pct_font(text, len, out_px, out_pct, NULL, NULL);
}

static const char *
match_close_paren(const char *p, const char *end)
{
    int depth = 1;
    while (p < end && depth > 0) {
        if (*p == '(') depth++;
        else if (*p == ')') { depth--; if (depth == 0) return p; }
        p++;
    }
    return NULL;
}

typedef struct ns_calc_term {
    double px;
    double pct;
    double em;
    double rem;
    double vw, vh, vmin, vmax;
    double num;
    gboolean is_number;
    guint8 fn;
    guint8 n_args;
    guint8 arg_none;
    struct { double px, pct; } args[4];
} ns_calc_term;

static void
calc_skip_ws(const char **pp, const char *end)
{
    const char *p = *pp;
    while (p < end && is_ws(*p)) p++;
    *pp = p;
}

static void
calc_term_fn_scale(ns_calc_term *v, double m)
{
    if (!v->fn) return;
    if (!isfinite(m)) {
        v->fn = 0;
        return;
    }
    for (int i = 0; i < v->n_args; i++) {
        v->args[i].px *= m;
        v->args[i].pct *= m;
    }
    if (m >= 0) return;
    if (v->fn == 1 || v->fn == 2) {
        v->fn = v->fn == 1 ? 2 : 1;
        return;
    }
    double lo_px = v->args[0].px, lo_pct = v->args[0].pct;
    v->args[0] = v->args[2];
    v->args[2].px = lo_px;
    v->args[2].pct = lo_pct;
    guint8 none = v->arg_none;
    v->arg_none = (guint8)((none & 2u) | ((none & 1u) << 2) | ((none & 4u) >> 2));
}

static void
calc_term_fn_add(ns_calc_term *out, const ns_calc_term *rhs, double sign)
{
    if (!out->fn && !rhs->fn) return;
    if ((out->fn && rhs->fn) || out->em != 0 || out->rem != 0 ||
        rhs->em != 0 || rhs->rem != 0) {
        out->fn = 0;
        return;
    }
    if (out->fn) {
        for (int i = 0; i < out->n_args; i++) {
            out->args[i].px += sign * rhs->px;
            out->args[i].pct += sign * rhs->pct;
        }
        return;
    }
    ns_calc_term r = *rhs;
    calc_term_fn_scale(&r, sign);
    if (!r.fn) return;
    for (int i = 0; i < r.n_args; i++) {
        r.args[i].px += out->px;
        r.args[i].pct += out->pct;
    }
    out->fn = r.fn;
    out->n_args = r.n_args;
    out->arg_none = r.arg_none;
    memcpy(out->args, r.args, sizeof out->args);
}

static void
calc_term_scale(ns_calc_term *v, double m)
{
    calc_term_fn_scale(v, m);
    if (v->is_number) {
        v->num *= m;
    } else if (isfinite(m)) {
        v->px *= m;
        v->pct *= m;
        v->em *= m;
        v->rem *= m;
        v->vw *= m;
        v->vh *= m;
        v->vmin *= m;
        v->vmax *= m;
    } else {
        if (v->px  != 0) v->px  *= m;
        if (v->pct != 0) v->pct *= m;
        if (v->em  != 0) v->em  *= m;
        if (v->rem != 0) v->rem *= m;
        v->vw = 0;
        v->vh = 0;
        v->vmin = 0;
        v->vmax = 0;
    }
}

static void
calc_term_lengthify(ns_calc_term *v)
{
    if (!v->is_number) return;
    v->px = v->num;
    v->pct = 0;
    v->is_number = FALSE;
}

static gboolean calc_expr_parse(const char **pp, const char *end,
                                ns_calc_term *out, int depth);

static gboolean
calc_unit_value(const char *unit, double num, ns_calc_term *out)
{
    memset(out, 0, sizeof(*out));
    if (!isfinite(num) && (!unit || !*unit)) {
        out->num = num;
        out->is_number = TRUE;
        return TRUE;
    }
    char number[G_ASCII_DTOSTR_BUF_SIZE];
    g_ascii_dtostr(number, sizeof(number), num);
    char *text = g_strconcat(number, unit ? unit : "", NULL);
    double v = 0;
    ns_css_unit u = NS_CSS_UNIT_NUMBER;
    gboolean ok = parse_length(text, &v, &u);
    g_free(text);
    if (!ok) return FALSE;
    switch (u) {
    case NS_CSS_UNIT_NUMBER:
        out->num = v;
        out->is_number = TRUE;
        break;
    case NS_CSS_UNIT_PERCENT:
        out->pct = v;
        break;
    case NS_CSS_UNIT_EM:
        out->em = v;
        break;
    case NS_CSS_UNIT_EX:
    case NS_CSS_UNIT_CH:
        out->em = v * 0.5;
        break;
    case NS_CSS_UNIT_CAP:
        out->em = v * 0.7;
        break;
    case NS_CSS_UNIT_IC:
        out->em = v;
        break;
    case NS_CSS_UNIT_REM:
        out->rem = v;
        break;
    case NS_CSS_UNIT_VW:
    case NS_CSS_UNIT_VH:
    case NS_CSS_UNIT_VMIN:
    case NS_CSS_UNIT_VMAX:
        out->px = viewport_resolve(v, u);
        viewport_unit_coeff(u, v, &out->vw, &out->vh, &out->vmin, &out->vmax);
        break;
    case NS_CSS_UNIT_CQW:
    case NS_CSS_UNIT_CQH:
    case NS_CSS_UNIT_CQMIN:
    case NS_CSS_UNIT_CQMAX:
        out->px = container_unit_resolve(v, u);
        break;
    default:
        out->px = v;
        break;
    }
    return TRUE;
}

static gboolean
calc_primary_parse(const char **pp, const char *end, ns_calc_term *out,
                   int depth)
{
    if (depth > NS_CALC_MAX_DEPTH) return FALSE;
    const char *p = *pp;
    calc_skip_ws(&p, end);
    if (p >= end) return FALSE;
    if ((gsize)(end - p) > 4 && g_ascii_strncasecmp(p, "env(", 4) == 0) {
        const char *args = p + 4;
        const char *close = match_close_paren(args, end);
        if (!close) return FALSE;
        char *parts[2] = {0};
        int n = calc_split_args(args, close, parts, G_N_ELEMENTS(parts));
        memset(out, 0, sizeof(*out));
        if (n >= 2)
            resolve_to_px_pct(parts[1], strlen(parts[1]), &out->px, &out->pct);
        for (int i = 0; i < n; i++) g_free(parts[i]);
        *pp = close + 1;
        return TRUE;
    }
    if (*p == '(') {
        p++;
        if (!calc_expr_parse(&p, end, out, depth + 1)) return FALSE;
        calc_skip_ws(&p, end);
        if (p >= end || *p != ')') return FALSE;
        p++;
        *pp = p;
        return TRUE;
    }
    static const struct { const char *name; gsize len; } funcs[] = {
        { "calc", 4 }, { "min", 3 }, { "max", 3 }, { "clamp", 5 },
        { "round", 5 }, { "mod", 3 }, { "rem", 3 }, { "abs", 3 },
        { "hypot", 5 }, { "pow", 3 }, { "sqrt", 4 }, { "atan2", 5 },
        { "atan", 4 }, { "asin", 4 }, { "acos", 4 }, { "sign", 4 },
        { "sin", 3 }, { "cos", 3 }, { "tan", 3 }, { "exp", 3 },
        { "log", 3 }, { "progress", 8 },
    };
    for (gsize i = 0; i < G_N_ELEMENTS(funcs); i++) {
        if ((gsize)(end - p) <= funcs[i].len + 1 ||
            g_ascii_strncasecmp(p, funcs[i].name, funcs[i].len) != 0 ||
            p[funcs[i].len] != '(')
            continue;
        const char *args = p + funcs[i].len + 1;
        const char *close = match_close_paren(args, end);
        if (!close) return FALSE;
        char *frag = g_strndup(p, (gsize)(close + 1 - p));
        ns_css_value *v = parse_calc(frag);
        g_free(frag);
        if (!v) return FALSE;
        memset(out, 0, sizeof(*out));
        if (v->kind == NS_CSS_V_CALC) {
            out->px = v->u.calc.px;
            out->pct = v->u.calc.pct;
            out->em = v->u.calc.em;
            out->rem = v->u.calc.rem;
            out->vw = v->u.calc.vw;
            out->vh = v->u.calc.vh;
            out->vmin = v->u.calc.vmin;
            out->vmax = v->u.calc.vmax;
            if (v->u.calc.fn >= 1 && v->u.calc.fn <= 3 &&
                v->u.calc.n_args > 0 && v->u.calc.n_args <= 4) {
                out->fn = v->u.calc.fn;
                out->n_args = v->u.calc.n_args;
                out->arg_none = v->u.calc.arg_none;
                for (int k = 0; k < out->n_args; k++) {
                    out->args[k].px = v->u.calc.args[k].px +
                        v->u.calc.args[k].em * 16.0 +
                        v->u.calc.args[k].rem * g_root_font_px;
                    out->args[k].pct = v->u.calc.args[k].pct;
                }
            }
        } else if (v->kind == NS_CSS_V_LENGTH) {
            double num = v->u.length.v;
            switch (v->u.length.unit) {
            case NS_CSS_UNIT_PERCENT: out->pct = num; break;
            case NS_CSS_UNIT_EM:      out->em = num; break;
            case NS_CSS_UNIT_EX:      out->em = num * 0.5; break;
            case NS_CSS_UNIT_CH:      out->em = num * 0.5; break;
            case NS_CSS_UNIT_CAP:     out->em = num * 0.7; break;
            case NS_CSS_UNIT_IC:      out->em = num; break;
            case NS_CSS_UNIT_REM:     out->rem = num; break;
            case NS_CSS_UNIT_VW:
            case NS_CSS_UNIT_VH:
            case NS_CSS_UNIT_VMIN:
            case NS_CSS_UNIT_VMAX:
                out->px = viewport_resolve(num, v->u.length.unit);
                viewport_unit_coeff(v->u.length.unit, num, &out->vw, &out->vh,
                                    &out->vmin, &out->vmax);
                break;
            case NS_CSS_UNIT_CQW:
            case NS_CSS_UNIT_CQH:
            case NS_CSS_UNIT_CQMIN:
            case NS_CSS_UNIT_CQMAX:
                out->px = container_unit_resolve(num, v->u.length.unit);
                break;
            case NS_CSS_UNIT_NUMBER:
                out->num = num;
                out->is_number = TRUE;
                break;
            default:                  out->px = num; break;
            }
        } else {
            ns_css_value_free(v);
            return FALSE;
        }
        ns_css_value_free(v);
        *pp = close + 1;
        return TRUE;
    }
    {
        static const struct { const char *name; gsize len; double val; } consts[] = {
            { "infinity", 8, INFINITY }, { "pi", 2, G_PI }, { "e", 1, G_E },
            { "nan", 3, NAN },
        };
        for (gsize i = 0; i < G_N_ELEMENTS(consts); i++) {
            gsize L = consts[i].len;
            if ((gsize)(end - p) < L ||
                g_ascii_strncasecmp(p, consts[i].name, L) != 0)
                continue;
            const char *after = p + L;
            if (after < end && (g_ascii_isalnum(*after) || *after == '.' ||
                                *after == '%' || *after == '('))
                continue;
            memset(out, 0, sizeof(*out));
            out->num = consts[i].val;
            out->is_number = TRUE;
            *pp = after;
            return TRUE;
        }
    }
    char *num_end = NULL;
    double num = g_ascii_strtod(p, &num_end);
    if (!num_end || num_end == p) return FALSE;
    const char *u = num_end;
    while (u < end && (g_ascii_isalpha(*u) || *u == '%')) u++;
    char *unit = g_strndup(num_end, (gsize)(u - num_end));
    gboolean ok = calc_unit_value(unit, num, out);
    g_free(unit);
    if (!ok) return FALSE;
    *pp = u;
    return TRUE;
}

static gboolean
calc_product_parse(const char **pp, const char *end, ns_calc_term *out,
                   int depth)
{
    if (!calc_primary_parse(pp, end, out, depth)) return FALSE;
    while (1) {
        const char *p = *pp;
        calc_skip_ws(&p, end);
        if (p >= end || (*p != '*' && *p != '/')) {
            *pp = p;
            return TRUE;
        }
        char op = *p++;
        ns_calc_term rhs;
        if (!calc_primary_parse(&p, end, &rhs, depth)) return FALSE;
        if (op == '*') {
            if (out->is_number && rhs.is_number) {
                out->num *= rhs.num;
            } else if (out->is_number) {
                double m = out->num;
                *out = rhs;
                calc_term_scale(out, m);
            } else if (rhs.is_number) {
                calc_term_scale(out, rhs.num);
            } else {
                return FALSE;
            }
        } else {
            if (!rhs.is_number) return FALSE;
            calc_term_scale(out, 1.0 / rhs.num);
        }
        *pp = p;
    }
}

static gboolean
calc_expr_parse(const char **pp, const char *end, ns_calc_term *out,
                int depth)
{
    if (!calc_product_parse(pp, end, out, depth)) return FALSE;
    while (1) {
        const char *p = *pp;
        calc_skip_ws(&p, end);
        if (p >= end || (*p != '+' && *p != '-')) {
            *pp = p;
            return TRUE;
        }
        char op = *p++;
        ns_calc_term rhs;
        if (!calc_product_parse(&p, end, &rhs, depth)) return FALSE;
        if (out->is_number != rhs.is_number) return FALSE;
        if (out->is_number) {
            if (op == '+') out->num += rhs.num;
            else           out->num -= rhs.num;
            *pp = p;
            continue;
        }
        calc_term_fn_add(out, &rhs, op == '+' ? 1.0 : -1.0);
        if (op == '+') {
            out->px += rhs.px;
            out->pct += rhs.pct;
            out->em += rhs.em;
            out->rem += rhs.rem;
            out->vw += rhs.vw;
            out->vh += rhs.vh;
            out->vmin += rhs.vmin;
            out->vmax += rhs.vmax;
        } else {
            out->px -= rhs.px;
            out->pct -= rhs.pct;
            out->em -= rhs.em;
            out->rem -= rhs.rem;
            out->vw -= rhs.vw;
            out->vh -= rhs.vh;
            out->vmin -= rhs.vmin;
            out->vmax -= rhs.vmax;
        }
        *pp = p;
    }
}

static int
calc_split_args(const char *args, const char *body_end, char *out[], int max)
{
    int n = 0;
    const char *seg = args;
    while (seg < body_end && n < max) {
        char term = 0;
        const char *next = css_scan_until(seg, body_end, ",", &term);
        out[n++] = css_trim_dup_range(seg, next);
        seg = term == ',' ? next + 1 : next;
        if (term != ',') break;
    }
    return n;
}

static gboolean
calc_arg_key(const char *text, double *out)
{
    double px = 0, pct = 0;
    if (!resolve_to_px_pct(text, strlen(text), &px, &pct)) {
        char *w = g_strdup_printf("calc(%s)", text);
        gboolean ok = resolve_to_px_pct(w, strlen(w), &px, &pct);
        g_free(w);
        if (!ok) return FALSE;
    }
    double add = pct * 0.01 * g_viewport_w;
    *out = add == 0 ? px : px + add;
    return TRUE;
}

static gboolean
calc_token_sign(const char *text, double *out)
{
    static const char *const units[] = {
        "s", "ms", "deg", "grad", "rad", "turn", "hz", "khz",
        "dpi", "dpcm", "dppx", "x", "fr",
    };
    char *s = g_strdup(text);
    g_strstrip(s);
    const char *p = s;
    gboolean ok = FALSE;
    char *end = NULL;
    double num = g_ascii_strtod(p, &end);
    if (end && end != p) {
        const char *u = end;
        while (*u && g_ascii_isalpha((guchar)*u)) u++;
        gsize ulen = (gsize)(u - end);
        const char *rest = u;
        while (*rest && is_ws(*rest)) rest++;
        if (*rest == '\0' && ulen > 0) {
            for (gsize i = 0; i < G_N_ELEMENTS(units); i++)
                if (strlen(units[i]) == ulen &&
                    g_ascii_strncasecmp(end, units[i], ulen) == 0) {
                    *out = isnan(num) ? NAN : num > 0 ? 1 : num < 0 ? -1 : num;
                    ok = TRUE;
                    break;
                }
        }
    }
    g_free(s);
    return ok;
}

typedef enum {
    PT_INVALID, PT_NUMBER, PT_LENGTHPCT, PT_ANGLE
} ns_prog_type;

static ns_prog_type
progress_operand(const char *text, double *out)
{
    char *w = g_strdup_printf("calc(%s)", text);
    ns_css_value *v = parse_calc(w);
    g_free(w);
    ns_prog_type ty = PT_INVALID;
    if (v) {
        if (v->kind == NS_CSS_V_LENGTH) {
            if (v->u.length.unit == NS_CSS_UNIT_NUMBER) {
                ty = PT_NUMBER;
                *out = v->u.length.v;
            } else if (v->u.length.unit == NS_CSS_UNIT_PERCENT) {
                ty = PT_LENGTHPCT;
                *out = v->u.length.v * 0.01 * g_viewport_w;
            } else {
                ty = PT_LENGTHPCT;
                *out = v->u.length.v;
            }
        } else if (v->kind == NS_CSS_V_CALC) {
            ty = PT_LENGTHPCT;
            *out = v->u.calc.px + v->u.calc.em * 16.0 +
                   v->u.calc.rem * g_root_font_px +
                   v->u.calc.pct * 0.01 * g_viewport_w;
        }
        ns_css_value_free(v);
        return ty;
    }
    static const struct { const char *u; double to_deg; } angs[] = {
        { "deg", 1.0 }, { "grad", 0.9 }, { "rad", 180.0 / G_PI },
        { "turn", 360.0 },
    };
    char *s = g_strdup(text);
    g_strstrip(s);
    char *end = NULL;
    double num = g_ascii_strtod(s, &end);
    ns_prog_type ty2 = PT_INVALID;
    if (end && end != s) {
        const char *u = end;
        while (*u && g_ascii_isalpha((guchar)*u)) u++;
        gsize ulen = (gsize)(u - end);
        if (*u == '\0' && ulen > 0)
            for (gsize i = 0; i < G_N_ELEMENTS(angs); i++)
                if (strlen(angs[i].u) == ulen &&
                    g_ascii_strncasecmp(end, angs[i].u, ulen) == 0) {
                    *out = num * angs[i].to_deg;
                    ty2 = PT_ANGLE;
                    break;
                }
    }
    g_free(s);
    return ty2;
}

static gboolean
calc_arg_is_number(const char *text)
{
    char *s = g_strdup(text);
    g_strstrip(s);
    char *endp = NULL;
    g_ascii_strtod(s, &endp);
    gboolean num = endp && endp != s && *endp == '\0';
    if (!num) {
        ns_css_value *v = parse_calc(s);
        if (!v) {
            char *wrapped = g_strdup_printf("calc(%s)", s);
            v = parse_calc(wrapped);
            g_free(wrapped);
        }
        num = v && v->kind == NS_CSS_V_LENGTH &&
              v->u.length.unit == NS_CSS_UNIT_NUMBER;
        if (v) ns_css_value_free(v);
    }
    g_free(s);
    return num;
}

static ns_css_value *
calc_px_value(double px)
{
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_LENGTH;
    v->u.length.v = px;
    v->u.length.unit = NS_CSS_UNIT_PX;
    return v;
}

static ns_css_value *
calc_num_value(double n)
{
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_LENGTH;
    v->u.length.v = n;
    v->u.length.unit = NS_CSS_UNIT_NUMBER;
    return v;
}

static double
css_round_step(int strategy, double a, double b)
{
    if (isnan(a) || isnan(b) || b == 0) return NAN;
    if (isinf(a)) return isinf(b) ? NAN : a;
    if (isinf(b)) {
        if (strategy == 1) return a > 0 ? INFINITY : 0.0;
        if (strategy == 2) return a < 0 ? -INFINITY : 0.0;
        return 0.0;
    }
    double q = a / fabs(b);
    double rq = strategy == 1 ? ceil(q) :
                strategy == 2 ? floor(q) :
                strategy == 3 ? trunc(q) : round(q);
    return rq * fabs(b);
}

static double
css_mod_rem(gboolean is_mod, double a, double b)
{
    if (isnan(a) || isnan(b) || b == 0 || isinf(a)) return NAN;
    if (isinf(b)) {
        if (!is_mod) return a;
        return signbit(a) == signbit(b) ? a : NAN;
    }
    double q = a / b;
    return is_mod ? a - b * floor(q) : a - b * trunc(q);
}

static ns_css_value *
parse_calc(const char *text)
{
    static __thread int depth;
    if (depth > NS_CALC_MAX_DEPTH) return NULL;
    depth++;
    ns_css_value *v = parse_calc_inner(text);
    depth--;
    return v;
}

static const char *
ns_css_unit_suffix(int unit)
{
    switch (unit) {
    case NS_CSS_UNIT_PX:      return "px";
    case NS_CSS_UNIT_EM:      return "em";
    case NS_CSS_UNIT_REM:     return "rem";
    case NS_CSS_UNIT_PERCENT: return "%";
    case NS_CSS_UNIT_NUMBER:  return "";
    case NS_CSS_UNIT_VW:      return "vw";
    case NS_CSS_UNIT_VH:      return "vh";
    case NS_CSS_UNIT_VMIN:    return "vmin";
    case NS_CSS_UNIT_VMAX:    return "vmax";
    case NS_CSS_UNIT_EX:      return "ex";
    case NS_CSS_UNIT_CH:      return "ch";
    case NS_CSS_UNIT_CAP:     return "cap";
    case NS_CSS_UNIT_IC:      return "ic";
    case NS_CSS_UNIT_LH:      return "lh";
    case NS_CSS_UNIT_RLH:     return "rlh";
    case NS_CSS_UNIT_REX:     return "rex";
    case NS_CSS_UNIT_RCH:     return "rch";
    case NS_CSS_UNIT_RCAP:    return "rcap";
    case NS_CSS_UNIT_RIC:     return "ric";
    default:                  return "px";
    }
}

static char *
ns_css_number_str(double n)
{
    if (isnan(n)) return g_strdup("NaN");
    if (isinf(n)) return g_strdup(n < 0 ? "-infinity" : "infinity");
    return g_strdup_printf("%g", n);
}

static gboolean
ns_value_has_relative_unit(const char *s)
{
    static const char *const rel[] = {
        "em", "rem", "ex", "rex", "ch", "rch", "cap", "rcap", "ic", "ric",
        "lh", "rlh", "vw", "vh", "vi", "vb", "vmin", "vmax",
        "svw", "svh", "svmin", "svmax", "lvw", "lvh", "lvmin", "lvmax",
        "dvw", "dvh", "dvmin", "dvmax",
        "cqw", "cqh", "cqi", "cqb", "cqmin", "cqmax",
    };
    while (*s) {
        if (g_ascii_isalpha(*s)) {
            const char *start = s;
            while (g_ascii_isalpha(*s) || *s == '-') s++;
            gsize len = (gsize)(s - start);
            if (*s == '(') continue;
            for (gsize i = 0; i < G_N_ELEMENTS(rel); i++)
                if (strlen(rel[i]) == len &&
                    g_ascii_strncasecmp(start, rel[i], len) == 0)
                    return TRUE;
        } else {
            s++;
        }
    }
    return FALSE;
}

static char *
serialize_nonfinite_length(double v, const char *unit)
{
    const char *nf = isnan(v) ? "NaN" : v < 0 ? "-infinity" : "infinity";
    if (!unit || !*unit)
        return g_strdup_printf("calc(%s)", nf);
    return g_strdup_printf("calc(%s * 1%s)", nf, unit);
}

#define NS_MATH_SUM_MAX 16

typedef struct ns_math_sum {
    double   number;
    gboolean has_number;
    double   percent;
    gboolean has_percent;
    char     unit[NS_MATH_SUM_MAX][8];
    double   coeff[NS_MATH_SUM_MAX];
    int      n;
} ns_math_sum;

static const char *
math_unit_canonical(const char *unit, gsize len, double *factor)
{
    static const struct { const char *name; const char *canonical; double f; }
        convertible[] = {
        { "px",   "px",   1.0 },
        { "cm",   "px",   96.0 / 2.54 },
        { "mm",   "px",   96.0 / 25.4 },
        { "q",    "px",   96.0 / 101.6 },
        { "in",   "px",   96.0 },
        { "pt",   "px",   96.0 / 72.0 },
        { "pc",   "px",   16.0 },
        { "deg",  "deg",  1.0 },
        { "grad", "deg",  0.9 },
        { "rad",  "deg",  180.0 / G_PI },
        { "turn", "deg",  360.0 },
        { "s",    "s",    1.0 },
        { "ms",   "s",    0.001 },
        { "hz",   "hz",   1.0 },
        { "khz",  "hz",   1000.0 },
        { "dppx", "dppx", 1.0 },
        { "x",    "dppx", 1.0 },
        { "dpi",  "dppx", 1.0 / 96.0 },
        { "dpcm", "dppx", 2.54 / 96.0 },
    };
    static const char *const relative[] = {
        "em", "rem", "ex", "rex", "ch", "rch", "cap", "rcap", "ic", "ric",
        "lh", "rlh", "vw", "vh", "vi", "vb", "vmin", "vmax",
        "svw", "svh", "svi", "svb", "svmin", "svmax",
        "lvw", "lvh", "lvi", "lvb", "lvmin", "lvmax",
        "dvw", "dvh", "dvi", "dvb", "dvmin", "dvmax",
        "cqw", "cqh", "cqi", "cqb", "cqmin", "cqmax", "fr",
    };
    if (len == 0 || len >= 8) return NULL;
    for (gsize i = 0; i < G_N_ELEMENTS(convertible); i++)
        if (strlen(convertible[i].name) == len &&
            g_ascii_strncasecmp(unit, convertible[i].name, len) == 0) {
            *factor = convertible[i].f;
            return convertible[i].canonical;
        }
    for (gsize i = 0; i < G_N_ELEMENTS(relative); i++)
        if (strlen(relative[i]) == len &&
            g_ascii_strncasecmp(unit, relative[i], len) == 0) {
            *factor = 1.0;
            return relative[i];
        }
    return NULL;
}

static gboolean
math_sum_add_dim(ns_math_sum *s, const char *unit, double v)
{
    for (int i = 0; i < s->n; i++)
        if (strcmp(s->unit[i], unit) == 0) {
            s->coeff[i] += v;
            return TRUE;
        }
    if (s->n >= NS_MATH_SUM_MAX) return FALSE;
    g_strlcpy(s->unit[s->n], unit, sizeof s->unit[0]);
    s->coeff[s->n] = v;
    s->n++;
    return TRUE;
}

static gboolean
math_sum_add(ns_math_sum *dst, const ns_math_sum *src, double sign)
{
    if (src->has_number) {
        dst->number += sign * src->number;
        dst->has_number = TRUE;
    }
    if (src->has_percent) {
        dst->percent += sign * src->percent;
        dst->has_percent = TRUE;
    }
    for (int i = 0; i < src->n; i++)
        if (!math_sum_add_dim(dst, src->unit[i], sign * src->coeff[i]))
            return FALSE;
    return TRUE;
}

static void
math_sum_scale(ns_math_sum *s, double m)
{
    s->number *= m;
    s->percent *= m;
    for (int i = 0; i < s->n; i++) s->coeff[i] *= m;
}

static gboolean
math_sum_is_number(const ns_math_sum *s)
{
    return s->has_number && !s->has_percent && s->n == 0;
}

static gboolean math_sum_parse(const char **pp, const char *end,
                               ns_math_sum *out, int depth);

static gboolean
math_number_token(const char **pp, const char *end, ns_math_sum *out)
{
    const char *p = *pp;
    const char *start = p;
    if (p < end && (*p == '+' || *p == '-')) p++;
    const char *digits = p;
    while (p < end && (g_ascii_isdigit(*p) || *p == '.')) p++;
    if (p == digits) return FALSE;
    if (p < end && (*p == 'e' || *p == 'E')) {
        const char *exponent = p + 1;
        if (exponent < end && (*exponent == '+' || *exponent == '-'))
            exponent++;
        const char *exp_digits = exponent;
        while (exponent < end && g_ascii_isdigit(*exponent)) exponent++;
        if (exponent != exp_digits) p = exponent;
    }
    char *text = g_strndup(start, (gsize)(p - start));
    char *tail = NULL;
    double v = g_ascii_strtod(text, &tail);
    gboolean numeric = tail && *tail == '\0' && isfinite(v);
    g_free(text);
    if (!numeric) return FALSE;
    memset(out, 0, sizeof *out);
    if (p < end && *p == '%') {
        out->has_percent = TRUE;
        out->percent = v;
        p++;
    } else {
        const char *unit = p;
        while (p < end && g_ascii_isalpha(*p)) p++;
        if (p == unit) {
            out->has_number = TRUE;
            out->number = v;
        } else {
            double factor = 1.0;
            const char *canonical =
                math_unit_canonical(unit, (gsize)(p - unit), &factor);
            if (!canonical) return FALSE;
            math_sum_add_dim(out, canonical, v * factor);
        }
    }
    *pp = p;
    return TRUE;
}

static gboolean
math_primary_parse(const char **pp, const char *end, ns_math_sum *out,
                   int depth)
{
    if (depth > NS_CALC_MAX_DEPTH) return FALSE;
    const char *p = *pp;
    calc_skip_ws(&p, end);
    if (p >= end) return FALSE;
    if ((gsize)(end - p) > 5 && g_ascii_strncasecmp(p, "calc(", 5) == 0)
        p += 5;
    else if (*p == '(')
        p++;
    else {
        if (!math_number_token(&p, end, out)) return FALSE;
        *pp = p;
        return TRUE;
    }
    if (!math_sum_parse(&p, end, out, depth + 1)) return FALSE;
    calc_skip_ws(&p, end);
    if (p >= end || *p != ')') return FALSE;
    *pp = p + 1;
    return TRUE;
}

static gboolean
math_product_parse(const char **pp, const char *end, ns_math_sum *out,
                   int depth)
{
    if (!math_primary_parse(pp, end, out, depth)) return FALSE;
    for (;;) {
        const char *p = *pp;
        calc_skip_ws(&p, end);
        if (p >= end || (*p != '*' && *p != '/')) return TRUE;
        char op = *p++;
        ns_math_sum rhs;
        if (!math_primary_parse(&p, end, &rhs, depth)) return FALSE;
        if (op == '/') {
            if (!math_sum_is_number(&rhs) || rhs.number == 0) return FALSE;
            math_sum_scale(out, 1.0 / rhs.number);
        } else if (math_sum_is_number(&rhs)) {
            math_sum_scale(out, rhs.number);
        } else if (math_sum_is_number(out)) {
            double scale = out->number;
            *out = rhs;
            math_sum_scale(out, scale);
        } else {
            return FALSE;
        }
        *pp = p;
    }
}

static gboolean
math_sum_parse(const char **pp, const char *end, ns_math_sum *out, int depth)
{
    if (depth > NS_CALC_MAX_DEPTH) return FALSE;
    if (!math_product_parse(pp, end, out, depth)) return FALSE;
    for (;;) {
        const char *p = *pp;
        calc_skip_ws(&p, end);
        if (p == *pp) return TRUE;
        if (p >= end || (*p != '+' && *p != '-')) return TRUE;
        char op = *p++;
        if (p >= end || !is_ws(*p)) return FALSE;
        ns_math_sum rhs;
        if (!math_product_parse(&p, end, &rhs, depth)) return FALSE;
        if (!math_sum_add(out, &rhs, op == '+' ? 1.0 : -1.0)) return FALSE;
        *pp = p;
    }
}

static char *
math_sum_serialize(const ns_math_sum *s)
{
    struct { const char *unit; double v; } term[NS_MATH_SUM_MAX + 2];
    int n = 0;
    if (s->has_number) { term[n].unit = ""; term[n].v = s->number; n++; }
    if (s->has_percent) { term[n].unit = "%"; term[n].v = s->percent; n++; }
    int first_dim = n;
    for (int i = 0; i < s->n; i++) {
        term[n].unit = s->unit[i];
        term[n].v = s->coeff[i];
        n++;
    }
    for (int i = first_dim; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if (g_ascii_strcasecmp(term[j].unit, term[i].unit) < 0) {
                typeof(term[0]) swap = term[i];
                term[i] = term[j];
                term[j] = swap;
            }
    if (n == 0) return NULL;
    GString *out = g_string_new("calc(");
    for (int i = 0; i < n; i++) {
        if (i > 0) g_string_append(out, term[i].v < 0 ? " - " : " + ");
        char *digits = ns_css_number_str(i > 0 ? fabs(term[i].v) : term[i].v);
        g_string_append(out, digits);
        g_free(digits);
        g_string_append(out, term[i].unit);
    }
    g_string_append_c(out, ')');
    return g_string_free(out, FALSE);
}

static char *
math_sum_canonical(const char *value)
{
    const char *p = value;
    while (*p && is_ws(*p)) p++;
    const char *body = NULL;
    if (g_ascii_strncasecmp(p, "calc(", 5) == 0)     body = p + 5;
    else if (g_ascii_strncasecmp(p, "min(", 4) == 0) body = p + 4;
    else if (g_ascii_strncasecmp(p, "max(", 4) == 0) body = p + 4;
    if (!body) return NULL;
    const char *end = value + strlen(value);
    while (end > body && is_ws(end[-1])) end--;
    if (end <= body || end[-1] != ')') return NULL;
    end--;
    ns_math_sum sum;
    memset(&sum, 0, sizeof sum);
    const char *cursor = body;
    if (!math_sum_parse(&cursor, end, &sum, 0)) return NULL;
    calc_skip_ws(&cursor, end);
    if (cursor != end) return NULL;
    return math_sum_serialize(&sum);
}

char *
ns_css_math_canonical(const char *value)
{
    if (!value) return NULL;
    while (*value && is_ws(*value)) value++;
    char *sum = math_sum_canonical(value);
    if (sum) return sum;
    if (ns_value_has_relative_unit(value)) return NULL;
    static const char *const fns[] = {
        "calc(", "min(", "max(", "clamp(", "round(", "mod(", "rem(",
        "abs(", "hypot(", "pow(", "sqrt(", "sin(", "cos(", "tan(",
        "sign(", "exp(", "log(", "progress(",
    };
    gboolean is_math = FALSE;
    for (gsize i = 0; i < G_N_ELEMENTS(fns); i++)
        if (g_ascii_strncasecmp(value, fns[i], strlen(fns[i])) == 0) {
            is_math = TRUE;
            break;
        }
    if (!is_math) return NULL;
    gboolean has_pct = strchr(value, '%') != NULL;
    ns_css_value *v = parse_calc(value);
    if (!v) return NULL;
    char *out = NULL;
    gboolean nonfinite = FALSE;
    gboolean number_result = v->kind == NS_CSS_V_LENGTH &&
                             v->u.length.unit == NS_CSS_UNIT_NUMBER &&
                             g_ascii_strncasecmp(value, "progress(", 9) == 0;
    if (v->kind == NS_CSS_V_LENGTH) {
        double lv = v->u.length.v;
        const char *suf = ns_css_unit_suffix(v->u.length.unit);
        if (!isfinite(lv)) {
            out = serialize_nonfinite_length(lv, suf);
            nonfinite = TRUE;
        } else {
            char *num = ns_css_number_str(lv);
            out = g_strdup_printf("calc(%s%s)", num, suf);
            g_free(num);
        }
    } else if (v->kind == NS_CSS_V_CALC) {
        int nonzero = 0;
        double val = 0;
        const char *unit = "px";
        if (v->u.calc.px != 0)  { nonzero++; val = v->u.calc.px;  unit = "px"; }
        if (v->u.calc.pct != 0) { nonzero++; val = v->u.calc.pct; unit = "%"; }
        if (v->u.calc.em != 0)  { nonzero++; val = v->u.calc.em;  unit = "em"; }
        if (v->u.calc.rem != 0) { nonzero++; val = v->u.calc.rem; unit = "rem"; }
        if (nonzero == 0) {
            out = g_strdup("calc(0px)");
        } else if (nonzero == 1) {
            if (!isfinite(val)) {
                out = serialize_nonfinite_length(val, unit);
                nonfinite = TRUE;
            } else {
                char *num = ns_css_number_str(val);
                out = g_strdup_printf("calc(%s%s)", num, unit);
                g_free(num);
            }
        }
    }
    ns_css_value_free(v);
    if (has_pct && !nonfinite && !number_result) {
        g_free(out);
        out = NULL;
    }
    return out;
}

typedef struct {
    double px, pct;
    gboolean number;
} calc_arg;

static gboolean
calc_arg_parse(const char *text, calc_arg *out)
{
    out->px = out->pct = 0;
    if (!resolve_to_px_pct(text, strlen(text), &out->px, &out->pct)) {
        char *w = g_strdup_printf("calc(%s)", text);
        gboolean ok = resolve_to_px_pct(w, strlen(w), &out->px, &out->pct);
        g_free(w);
        if (!ok) return FALSE;
    }
    out->number = calc_arg_is_number(text);
    return TRUE;
}

static ns_css_value *
calc_stepped_result(guint8 fn, const calc_arg *a, double r)
{
    int n = fn == NS_CALC_FN_ABS ? 1 : 2;
    int numbers = 0;
    gboolean basis = FALSE;
    for (int i = 0; i < n; i++) {
        if (a[i].number) numbers++;
        if (a[i].pct != 0) basis = TRUE;
    }
    if (numbers == n) return calc_num_value(r);
    if (numbers > 0) return NULL;
    if (!basis) return calc_px_value(r);
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_CALC;
    v->u.calc.px = r;
    v->u.calc.fn = fn;
    v->u.calc.n_args = (guint8)n;
    for (int i = 0; i < n; i++) {
        v->u.calc.args[i].px = a[i].px;
        v->u.calc.args[i].pct = a[i].pct;
    }
    return v;
}

static ns_css_value *
calc_stepped_fn_value(guint8 fn, char **parts, int n)
{
    calc_arg a[2] = { { 0, 0, FALSE }, { 1, 0, TRUE } };
    double k[2];
    for (int i = 0; i < n; i++)
        if (!calc_arg_parse(parts[i], &a[i])) return NULL;
    for (int i = 0; i < 2; i++)
        k[i] = a[i].px + a[i].pct * 0.01 * g_viewport_w;
    return calc_stepped_result(fn, a, calc_stepped_eval(fn, k));
}

static ns_css_value *
calc_round_fn_parse(char **parts, int n)
{
    static const char *const names[] = { "nearest", "up", "down", "to-zero" };
    int strategy = 0, vi = 0;
    for (int i = 0; n > 0 && i < 4; i++)
        if (g_ascii_strcasecmp(parts[0], names[i]) == 0) {
            strategy = i;
            vi = 1;
        }
    if (n - vi < 1 || n - vi > 2) return NULL;
    return calc_stepped_fn_value((guint8)(NS_CALC_FN_ROUND + strategy),
                                 parts + vi, n - vi);
}

static ns_css_value *
calc_stepped_fn_parse(int fn, char **parts, int n)
{
    if (fn == 4) return calc_round_fn_parse(parts, n);
    if (fn == 7)
        return n == 1 ? calc_stepped_fn_value(NS_CALC_FN_ABS, parts, 1) : NULL;
    if (n != 2) return NULL;
    return calc_stepped_fn_value(fn == 5 ? NS_CALC_FN_MOD : NS_CALC_FN_REM,
                                 parts, 2);
}

static ns_css_value *
parse_calc_inner(const char *text)
{
    while (*text && is_ws(*text)) text++;
    int fn = -1;
    const char *args = NULL;
    if      (g_ascii_strncasecmp(text, "calc(",  5) == 0) { fn = 0; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "clamp(", 6) == 0) { fn = 3; args = text + 6; }
    else if (g_ascii_strncasecmp(text, "min(",   4) == 0) { fn = 1; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "max(",   4) == 0) { fn = 2; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "round(", 6) == 0) { fn = 4; args = text + 6; }
    else if (g_ascii_strncasecmp(text, "mod(",   4) == 0) { fn = 5; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "rem(",   4) == 0) { fn = 6; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "abs(",   4) == 0) { fn = 7; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "hypot(", 6) == 0) { fn = 8; args = text + 6; }
    else if (g_ascii_strncasecmp(text, "pow(",   4) == 0) { fn = 9; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "sqrt(",  5) == 0) { fn = 10; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "sin(",   4) == 0) { fn = 11; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "cos(",   4) == 0) { fn = 12; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "tan(",   4) == 0) { fn = 13; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "atan2(", 6) == 0) { fn = 14; args = text + 6; }
    else if (g_ascii_strncasecmp(text, "atan(",  5) == 0) { fn = 15; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "asin(",  5) == 0) { fn = 16; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "acos(",  5) == 0) { fn = 17; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "sign(",  5) == 0) { fn = 18; args = text + 5; }
    else if (g_ascii_strncasecmp(text, "exp(",   4) == 0) { fn = 19; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "log(",   4) == 0) { fn = 20; args = text + 4; }
    else if (g_ascii_strncasecmp(text, "progress(", 9) == 0) { fn = 21; args = text + 9; }
    else return NULL;
    const char *body_end = match_close_paren(args, args + strlen(args));
    if (!body_end) return NULL;
    for (const char *tail = body_end + 1; *tail; tail++)
        if (!is_ws(*tail)) return NULL;
    if (fn >= 4) {
        char *parts[4] = {0};
        int n = calc_split_args(args, body_end, parts, G_N_ELEMENTS(parts));
        ns_css_value *out = NULL;
        if (fn <= 7) {
            out = calc_stepped_fn_parse(fn, parts, n);
        } else if (fn == 8 && n >= 1) {
            double sum = 0;
            gboolean ok = TRUE;
            for (int i = 0; i < n && ok; i++) {
                double x = 0;
                ok = calc_arg_key(parts[i], &x);
                sum += x * x;
            }
            if (ok) out = calc_num_value(sqrt(sum));
        } else if (fn == 9 && n == 2) {
            double x = 0, y = 0;
            if (calc_arg_key(parts[0], &x) && calc_arg_key(parts[1], &y))
                out = calc_num_value(pow(x, y));
        } else if (fn == 10 && n == 1) {
            double x = 0;
            if (calc_arg_key(parts[0], &x))
                out = calc_num_value(sqrt(x));
        } else if (fn >= 11 && fn <= 13 && n == 1) {
            char *rad = angle_expr_rewrite(parts[0], TRUE);
            double x = 0;
            gboolean ok = calc_arg_key(rad, &x);
            g_free(rad);
            if (ok)
                out = calc_num_value(fn == 11 ? sin(x)
                                  : fn == 12 ? cos(x) : tan(x));
        } else if (fn == 14 && n == 2) {
            double y = 0, x = 0;
            if (calc_arg_key(parts[0], &y) && calc_arg_key(parts[1], &x))
                out = calc_num_value(atan2(y, x));
        } else if (fn >= 15 && fn <= 17 && n == 1) {
            double x = 0;
            if (calc_arg_key(parts[0], &x))
                out = calc_num_value(fn == 15 ? atan(x)
                                  : fn == 16 ? asin(x) : acos(x));
        } else if (fn == 18 && n == 1) {
            double x = 0;
            if (calc_arg_key(parts[0], &x))
                out = calc_num_value(isnan(x) ? NAN : x > 0 ? 1 : x < 0 ? -1 : x);
            else if (calc_token_sign(parts[0], &x))
                out = calc_num_value(x);
        } else if (fn == 19 && n == 1) {
            double x = 0;
            if (calc_arg_key(parts[0], &x))
                out = calc_num_value(exp(x));
        } else if (fn == 20 && n >= 1) {
            double x = 0, base = 0;
            if (calc_arg_key(parts[0], &x)) {
                if (n >= 2 && calc_arg_key(parts[1], &base))
                    out = calc_num_value(log(x) / log(base));
                else if (n == 1)
                    out = calc_num_value(log(x));
            }
        } else if (fn == 21 && n == 3) {
            const char *a = parts[0];
            while (*a && is_ws(*a)) a++;
            gboolean no_clamp = FALSE;
            if (g_ascii_strncasecmp(a, "no-clamp", 8) == 0 &&
                (a[8] == '\0' || is_ws(a[8]))) {
                no_clamp = TRUE;
                a += 8;
                while (*a && is_ws(*a)) a++;
            }
            double A = 0, B = 0, C = 0;
            ns_prog_type ta = progress_operand(a, &A);
            ns_prog_type tb = progress_operand(parts[1], &B);
            ns_prog_type tc = progress_operand(parts[2], &C);
            if (ta != PT_INVALID && ta == tb && tb == tc) {
                double den = C - B;
                double num = A - B;
                double p;
                if (den == 0) {
                    p = !no_clamp ? 0.0
                      : num > 0 ? INFINITY : num < 0 ? -INFINITY : NAN;
                } else {
                    p = num / den;
                    if (!no_clamp)
                        p = isnan(p) ? 0.0 : p < 0 ? 0.0 : p > 1 ? 1.0 : p;
                }
                out = calc_num_value(p);
            }
        }
        for (int i = 0; i < n; i++) g_free(parts[i]);
        return out;
    }
    if (fn != 0) {
        double values_px[8] = {0};
        double values_pct[8] = {0};
        double values_em[8] = {0};
        double values_rem[8] = {0};
        gboolean is_none[8] = {0};
        int num_count = 0;
        int none_count = 0;
        gboolean ok = TRUE;
        int n = 0;
        const char *seg = args;
        int depth = 0;
        for (const char *q = args; q <= body_end; q++) {
            if (q < body_end && *q == '(') depth++;
            else if (q < body_end && *q == ')') depth--;
            if (q == body_end || (*q == ',' && depth == 0)) {
                int slot = n < 8 ? n : 7;
                char *part = g_strndup(seg, (gsize)(q - seg));
                g_strstrip(part);
                if (g_ascii_strcasecmp(part, "none") == 0) {
                    is_none[slot] = TRUE;
                    none_count++;
                    if (fn != 3) ok = FALSE;
                } else if (!resolve_to_px_pct_font(part, strlen(part),
                                                   &values_px[slot],
                                                   &values_pct[slot],
                                                   &values_em[slot],
                                                   &values_rem[slot])) {
                    ok = FALSE;
                } else if (calc_arg_is_number(part)) {
                    num_count++;
                }
                g_free(part);
                n++;
                seg = q + 1;
            }
        }
        if (n == 0 || !ok) return NULL;
        int non_none = n - none_count;
        if (num_count != 0 && num_count != non_none) return NULL;
        if (fn == 3 && (n != 3 || is_none[1])) return NULL;
        gboolean all_numbers = non_none > 0 && num_count == non_none;
        if (n > 8) n = 8;
        double keys[8] = {0};
        gboolean font_relative = FALSE;
        for (int i = 0; i < n; i++) {
            keys[i] = values_px[i] + values_em[i] * 16.0 +
                      values_rem[i] * g_root_font_px +
                      values_pct[i] * 0.01 * g_viewport_w;
            if (values_em[i] != 0 || values_rem[i] != 0) font_relative = TRUE;
        }
        double out_px;
        if (fn == 3) {
            double min_v = is_none[0] ? -HUGE_VAL : keys[0];
            double val_v = keys[1];
            double max_v = is_none[2] ? HUGE_VAL : keys[2];
            if (isnan(min_v) || isnan(val_v) || isnan(max_v)) {
                out_px = NAN;
            } else {
                out_px = val_v;
                if (out_px > max_v) out_px = max_v;
                if (out_px < min_v) out_px = min_v;
            }
        } else {
            out_px = keys[0];
            gboolean any_nan = isnan(keys[0]);
            for (int i = 1; i < n; i++) {
                if (isnan(keys[i])) any_nan = TRUE;
                if (fn == 1 && keys[i] < out_px) out_px = keys[i];
                if (fn == 2 && keys[i] > out_px) out_px = keys[i];
            }
            if (any_nan) out_px = NAN;
        }
        if (all_numbers) return calc_num_value(out_px);
        gboolean basis_dependent = n <= 4;
        if (basis_dependent) {
            basis_dependent = font_relative;
            for (int i = 0; i < n; i++)
                if (values_pct[i] != 0) basis_dependent = TRUE;
        }
        if (!basis_dependent) return calc_px_value(out_px);
        ns_css_value *mv = g_new0(ns_css_value, 1);
        mv->kind = NS_CSS_V_CALC;
        mv->u.calc.px = out_px;
        mv->u.calc.fn = (guint8)fn;
        mv->u.calc.n_args = (guint8)n;
        for (int i = 0; i < n; i++) {
            mv->u.calc.args[i].px  = values_px[i];
            mv->u.calc.args[i].pct = values_pct[i];
            mv->u.calc.args[i].em  = values_em[i];
            mv->u.calc.args[i].rem = values_rem[i];
            if (is_none[i]) mv->u.calc.arg_none |= (guint8)(1u << i);
        }
        return mv;
    }
    text = args;
    const char *end = body_end;
    double pct = 0;
    double px  = 0;
    double em  = 0;
    double rem = 0;
    const char *p = text;
    ns_calc_term term;
    gboolean parsed = FALSE;
    if (calc_expr_parse(&p, end, &term, 0)) {
        calc_skip_ws(&p, end);
        if (p == end) {
            if (term.is_number) return calc_num_value(term.num);
            calc_term_lengthify(&term);
            px = term.px;
            pct = term.pct;
            em = term.em;
            rem = term.rem;
            parsed = TRUE;
        }
    }
    if (!parsed) return NULL;
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_CALC;
    if (term.fn) {
        v->u.calc.px = px + em * 16.0 + rem * g_root_font_px +
                       pct * 0.01 * g_viewport_w;
        v->u.calc.fn = term.fn;
        v->u.calc.n_args = term.n_args;
        v->u.calc.arg_none = term.arg_none;
        for (int k = 0; k < term.n_args; k++) {
            v->u.calc.args[k].px = term.args[k].px;
            v->u.calc.args[k].pct = term.args[k].pct;
        }
        return v;
    }
    v->u.calc.pct = pct;
    v->u.calc.px  = px;
    v->u.calc.em  = em;
    v->u.calc.rem = rem;
    v->u.calc.vw = term.vw;
    v->u.calc.vh = term.vh;
    v->u.calc.vmin = term.vmin;
    v->u.calc.vmax = term.vmax;
    v->u.calc.parsed_vw = g_viewport_w;
    v->u.calc.parsed_vh = g_viewport_h;
    return v;
}

static int split_ws(const char *s, char *out[4]);

static gboolean
parse_bg_size_component(const char *tok, double *out_v, ns_css_unit *out_unit)
{
    if (parse_length(tok, out_v, out_unit)) return TRUE;
    ns_css_value *cv = parse_calc(tok);
    if (!cv) return FALSE;
    gboolean ok = TRUE;
    if (cv->kind == NS_CSS_V_LENGTH) {
        *out_v = cv->u.length.v;
        *out_unit = cv->u.length.unit;
    } else if (cv->kind == NS_CSS_V_CALC) {
        if (cv->u.calc.pct != 0 && cv->u.calc.px == 0 &&
            cv->u.calc.em == 0 && cv->u.calc.rem == 0) {
            *out_v = cv->u.calc.pct;
            *out_unit = NS_CSS_UNIT_PERCENT;
        } else {
            *out_v = cv->u.calc.px + cv->u.calc.em * 16.0 +
                     cv->u.calc.rem * g_root_font_px;
            *out_unit = NS_CSS_UNIT_PX;
        }
    } else {
        ok = FALSE;
    }
    ns_css_value_free(cv);
    return ok;
}

static gboolean
parse_track_token(const char *tok, ns_css_track *out)
{
    if (!tok || !*tok) return FALSE;
    if (g_ascii_strcasecmp(tok, "auto") == 0) {
        out->kind = NS_CSS_TRACK_AUTO;
        out->v = 0;
        return TRUE;
    }
    if (g_ascii_strcasecmp(tok, "min-content") == 0) {
        out->kind = NS_CSS_TRACK_MIN_CONTENT;
        out->v = 0;
        return TRUE;
    }
    if (g_ascii_strcasecmp(tok, "max-content") == 0) {
        out->kind = NS_CSS_TRACK_MAX_CONTENT;
        out->v = 0;
        return TRUE;
    }
    char *endp = NULL;
    double v = g_ascii_strtod(tok, &endp);
    if (!endp || endp == tok) return FALSE;
    if (g_ascii_strcasecmp(endp, "fr") == 0) {
        if (v < 0) return FALSE;
        out->kind = NS_CSS_TRACK_FR; out->v = v; return TRUE;
    }
    ns_css_unit unit = NS_CSS_UNIT_NUMBER;
    if (!parse_length(tok, &v, &unit)) return FALSE;
    if (v < 0) return FALSE;
    switch (unit) {
    case NS_CSS_UNIT_PERCENT:
        out->kind = NS_CSS_TRACK_PERCENT; out->v = v; return TRUE;
    case NS_CSS_UNIT_NUMBER:
    case NS_CSS_UNIT_PX:
        out->kind = NS_CSS_TRACK_PX; out->v = v; return TRUE;
    case NS_CSS_UNIT_EM:
    case NS_CSS_UNIT_IC:
        out->kind = NS_CSS_TRACK_PX; out->v = 0; out->em = v; return TRUE;
    case NS_CSS_UNIT_REM:
        out->kind = NS_CSS_TRACK_PX; out->v = 0; out->rem = v; return TRUE;
    case NS_CSS_UNIT_LH:
    case NS_CSS_UNIT_RLH:
        out->kind = NS_CSS_TRACK_PX; out->v = v * 19.2; return TRUE;
    case NS_CSS_UNIT_EX:
    case NS_CSS_UNIT_CH:
        out->kind = NS_CSS_TRACK_PX; out->v = v * 8; return TRUE;
    case NS_CSS_UNIT_CAP:
        out->kind = NS_CSS_TRACK_PX; out->v = v * 11.2; return TRUE;
    case NS_CSS_UNIT_CQW:
    case NS_CSS_UNIT_CQH:
    case NS_CSS_UNIT_CQMIN:
    case NS_CSS_UNIT_CQMAX:
        out->kind = NS_CSS_TRACK_PX;
        out->v = container_unit_resolve(v, unit);
        return TRUE;
    default:
        out->kind = NS_CSS_TRACK_PX;
        out->v = viewport_resolve(v, unit);
        return TRUE;
    }
}

#define NS_CSS_TRACK_MAX_DEPTH 32

static gboolean parse_one_track(const char *start, gsize len,
                                ns_css_track *out);
static gboolean parse_one_track_depth(const char *start, gsize len,
                                      ns_css_track *out, int depth);

static gboolean
parse_math_track(const char *start, gsize len, ns_css_track *out)
{
    char *tok = g_strndup(start, len);
    ns_css_value *cv = parse_calc(tok);
    g_free(tok);
    if (!cv) return FALSE;
    gboolean ok = FALSE;
    if (cv->kind == NS_CSS_V_LENGTH &&
        (cv->u.length.unit == NS_CSS_UNIT_PX ||
         cv->u.length.unit == NS_CSS_UNIT_NUMBER)) {
        out->kind = NS_CSS_TRACK_PX;
        out->v = cv->u.length.v;
        ok = TRUE;
    } else if (cv->kind == NS_CSS_V_CALC) {
        if (cv->u.calc.pct != 0 && cv->u.calc.px == 0 &&
            cv->u.calc.em == 0 && cv->u.calc.rem == 0) {
            out->kind = NS_CSS_TRACK_PERCENT;
            out->v = cv->u.calc.pct;
        } else {
            out->kind = NS_CSS_TRACK_PX;
            out->v = cv->u.calc.px;
            out->em = cv->u.calc.em;
            out->rem = cv->u.calc.rem;
            out->pct = cv->u.calc.pct;
        }
        ok = TRUE;
    }
    ns_css_value_free(cv);
    return ok;
}

static gboolean
parse_minmax_token(const char *body, gsize len, ns_css_track *out, int depth)
{
    const char *p = body;
    const char *end = body + len;
    while (p < end && is_ws(*p)) p++;
    const char *as = p;
    char term = 0;
    const char *comma = css_scan_until(p, end, ",", &term);
    if (term != ',') return FALSE;
    p = comma;
    gsize alen = (gsize)(p - as);
    while (alen > 0 && is_ws(as[alen - 1])) alen--;
    p++;
    while (p < end && is_ws(*p)) p++;
    const char *bs = p;
    gsize blen = (gsize)(end - p);
    while (blen > 0 && is_ws(bs[blen - 1])) blen--;
    ns_css_track mn = {0}, mx = {0};
    gboolean ok = parse_one_track_depth(as, alen, &mn, depth) &&
                  parse_one_track_depth(bs, blen, &mx, depth);
    if (!ok) return FALSE;
    if (mn.kind == NS_CSS_TRACK_FR) {
        if (mx.kind != NS_CSS_TRACK_FR) return FALSE;
        *out = mx;
        return TRUE;
    }
    *out = mx;
    out->min_kind = mn.kind;
    out->min_v    = mn.v;
    out->min_em   = mn.em;
    out->min_rem  = mn.rem;
    out->min_pct  = mn.pct;
    out->has_min  = TRUE;
    return TRUE;
}

static gboolean
parse_one_track_depth(const char *start, gsize len, ns_css_track *out, int depth)
{
    if (depth >= NS_CSS_TRACK_MAX_DEPTH) return FALSE;
    while (len > 0 && is_ws(*start)) { start++; len--; }
    while (len > 0 && is_ws(start[len - 1])) len--;
    if (len == 0) return FALSE;
    if (len > 7 && g_ascii_strncasecmp(start, "minmax(", 7) == 0 &&
        start[len - 1] == ')') {
        return parse_minmax_token(start + 7, len - 8, out, depth + 1);
    }
    if (len > 12 && g_ascii_strncasecmp(start, "fit-content(", 12) == 0 &&
        start[len - 1] == ')') {
        ns_css_track inner = {0};
        if (!parse_one_track_depth(start + 12, len - 13, &inner, depth + 1))
            return FALSE;
        *out = inner;
        out->min_kind = NS_CSS_TRACK_AUTO;
        out->min_v    = 0;
        out->has_min  = TRUE;
        out->fit_content = TRUE;
        return TRUE;
    }
    if (start[len - 1] == ')' &&
        (g_ascii_strncasecmp(start, "min(", 4) == 0 ||
         g_ascii_strncasecmp(start, "max(", 4) == 0 ||
         g_ascii_strncasecmp(start, "clamp(", 6) == 0 ||
         g_ascii_strncasecmp(start, "calc(", 5) == 0))
        return parse_math_track(start, len, out);
    char *tok = g_strndup(start, len);
    gboolean ok = parse_track_token(tok, out);
    g_free(tok);
    return ok;
}

static gboolean
parse_one_track(const char *start, gsize len, ns_css_track *out)
{
    return parse_one_track_depth(start, len, out, 0);
}

static int
split_tracks_top(const char *text, gsize len, const char **starts, gsize *lens, int max)
{
    int n = 0;
    const char *p = text;
    const char *end = text + len;
    while (p < end && n < max) {
        while (p < end && is_ws(*p)) p++;
        if (p >= end) break;
        const char *tok_start = p;
        char term = 0;
        p = css_scan_until(p, end, " \t\n\r\f,", &term);
        starts[n] = tok_start;
        lens[n]   = (gsize)(p - tok_start);
        n++;
        if (p < end && *p == ',') p++;
    }
    return n;
}

static gboolean
font_family_ident_valid(const char *tok, gsize len)
{
    if (len == 0) return FALSE;
    gsize i = 0;
    if (tok[0] == '-') {
        i = 1;
        if (len == 1) return FALSE;
        if (tok[1] == '-') i = 2;
    }
    if (i >= len) return FALSE;
    unsigned char first = (unsigned char)tok[i];
    if (!(g_ascii_isalpha(first) || first == '_' || first >= 0x80 || first == '\\'))
        return FALSE;
    for (gsize k = i; k < len; k++) {
        unsigned char c = (unsigned char)tok[k];
        if (c == '\\') { k++; continue; }
        if (!(g_ascii_isalnum(c) || c == '-' || c == '_' || c >= 0x80))
            return FALSE;
    }
    return TRUE;
}

static gboolean
font_family_is_generic(const char *tok, gsize len)
{
    static const char *const generic[] = {
        "serif", "sans-serif", "cursive", "fantasy", "monospace",
        "system-ui", "ui-serif", "ui-sans-serif", "ui-monospace",
        "ui-rounded", "math", "emoji", "fangsong", "inherit", "initial",
        "unset", "revert", "revert-layer", "default",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(generic); i++)
        if (strlen(generic[i]) == len &&
            g_ascii_strncasecmp(tok, generic[i], len) == 0)
            return TRUE;
    return FALSE;
}

static gboolean is_font_stretch_keyword(const char *s);
static ns_css_value *parse_value_for(ns_css_prop prop, const char *text);

static int
split_ws_paren(const char *text, char **out, int max)
{
    int n = 0;
    const char *p = text, *end = text + strlen(text);
    while (p < end && n < max) {
        while (p < end && is_ws(*p)) p++;
        if (p >= end) break;
        const char *start = p;
        int depth = 0;
        char quote = 0;
        while (p < end) {
            char c = *p;
            if (quote) { if (c == quote) quote = 0; p++; continue; }
            if (c == '\\' && p + 1 < end) { p += 2; continue; }
            if (c == '"' || c == '\'') { quote = c; p++; continue; }
            if (c == '(') depth++;
            else if (c == ')') { if (depth) depth--; }
            else if (is_ws(c) && depth == 0) break;
            p++;
        }
        out[n++] = g_strndup(start, (gsize)(p - start));
    }
    return n;
}

static gboolean
font_size_token_valid(const char *tok)
{
    if (font_size_keyword_px(tok) > 0) return TRUE;
    if (g_ascii_strcasecmp(tok, "larger") == 0 ||
        g_ascii_strcasecmp(tok, "smaller") == 0)
        return TRUE;
    if (g_ascii_strncasecmp(tok, "calc(", 5) == 0 ||
        g_ascii_strncasecmp(tok, "min(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "max(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "clamp(", 6) == 0) {
        ns_css_value *cv = parse_calc(tok);
        if (!cv) return FALSE;
        ns_css_value_free(cv);
        return TRUE;
    }
    double v; ns_css_unit u;
    return parse_length(tok, &v, &u) && u != NS_CSS_UNIT_NUMBER && v >= 0;
}

static gboolean
font_line_height_token_valid(const char *tok)
{
    if (g_ascii_strcasecmp(tok, "normal") == 0) return TRUE;
    if (g_ascii_strncasecmp(tok, "calc(", 5) == 0 ||
        g_ascii_strncasecmp(tok, "min(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "max(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "clamp(", 6) == 0) {
        ns_css_value *cv = parse_calc(tok);
        if (!cv) return FALSE;
        ns_css_value_free(cv);
        return TRUE;
    }
    double v; ns_css_unit u;
    return parse_length(tok, &v, &u) && v >= 0;
}

static char *
font_shorthand_slash(char *tok)
{
    int depth = 0;
    for (char *q = tok; *q; q++) {
        if (*q == '(') depth++;
        else if (*q == ')') { if (depth) depth--; }
        else if (*q == '/' && depth == 0) return q;
    }
    return NULL;
}

static gboolean
font_shorthand_is_size_token(const char *tok)
{
    char *copy = g_strdup(tok);
    char *slash = font_shorthand_slash(copy);
    if (slash) *slash = '\0';
    gboolean ok = *copy && font_size_token_valid(copy) &&
                  !(g_ascii_isdigit((guchar)copy[0]) &&
                    strspn(copy, "0123456789.") == strlen(copy));
    g_free(copy);
    return ok;
}

static ns_css_value *
font_shorthand_size_value(const char *size_only)
{
    double kw = font_size_keyword_px(size_only);
    ns_css_value *v = NULL;
    if (kw > 0 || g_ascii_strcasecmp(size_only, "larger") == 0 ||
        g_ascii_strcasecmp(size_only, "smaller") == 0) {
        v = g_new0(ns_css_value, 1);
        v->kind = NS_CSS_V_LENGTH;
        if (kw > 0) {
            v->u.length.v = kw;
            v->u.length.unit = NS_CSS_UNIT_PX;
        } else {
            v->u.length.v = g_ascii_strcasecmp(size_only, "larger") == 0
                ? 1.2 : 0.833333333333;
            v->u.length.unit = NS_CSS_UNIT_EM;
        }
        return v;
    }
    return parse_value_for(NS_CSS_FONT_SIZE, size_only);
}

char *
ns_css_font_shorthand_canonical(const char *text)
{
    if (!text) return NULL;
    char *tokens[24] = {0};
    int n = split_ws_paren(text, tokens, 24);
    char *result = NULL;
    const char *style = NULL, *variant = NULL, *weight = NULL, *stretch = NULL;
    int prefix = 0;
    int i = 0;
    for (; i < n && prefix < 4; i++) {
        const char *t = tokens[i];
        if (g_ascii_strcasecmp(t, "normal") == 0) { prefix++; continue; }
        if (g_ascii_strcasecmp(t, "italic") == 0 ||
            g_ascii_strcasecmp(t, "oblique") == 0) {
            if (style) goto done;
            style = t; prefix++; continue;
        }
        if (g_ascii_strcasecmp(t, "small-caps") == 0) {
            if (variant) goto done;
            variant = t; prefix++; continue;
        }
        if (g_ascii_strcasecmp(t, "bold") == 0 ||
            g_ascii_strcasecmp(t, "bolder") == 0 ||
            g_ascii_strcasecmp(t, "lighter") == 0) {
            if (weight) goto done;
            weight = t; prefix++; continue;
        }
        if (g_ascii_isdigit((guchar)t[0])) {
            char *endp = NULL;
            double w = g_ascii_strtod(t, &endp);
            if (endp && *endp == '\0' && w >= 1 && w <= 1000 &&
                !(i + 1 < n && FALSE)) {
                if (weight) goto done;
                weight = t; prefix++; continue;
            }
        }
        if (is_font_stretch_keyword(t)) {
            if (stretch) goto done;
            stretch = t; prefix++; continue;
        }
        break;
    }
    if (i >= n) goto done;
    char *size_tok = tokens[i];
    char *lh_tok = NULL;
    char *slash = NULL;
    {
        int depth = 0;
        for (char *q = size_tok; *q; q++) {
            if (*q == '(') depth++;
            else if (*q == ')') { if (depth) depth--; }
            else if (*q == '/' && depth == 0) { slash = q; break; }
        }
    }
    char *size_only = slash ? g_strndup(size_tok, (gsize)(slash - size_tok))
                            : g_strdup(size_tok);
    int fam_start = i + 1;
    if (slash) {
        if (slash[1]) lh_tok = g_strdup(slash + 1);
        else if (fam_start < n) lh_tok = g_strdup(tokens[fam_start++]);
        else { g_free(size_only); goto done; }
    } else if (fam_start < n && tokens[fam_start][0] == '/') {
        if (tokens[fam_start][1]) lh_tok = g_strdup(tokens[fam_start] + 1);
        else if (fam_start + 1 < n) { lh_tok = g_strdup(tokens[fam_start + 1]); fam_start++; }
        fam_start++;
    }
    if (!*size_only || !font_size_token_valid(size_only) ||
        (lh_tok && !font_line_height_token_valid(lh_tok)) || fam_start >= n) {
        g_free(size_only);
        g_free(lh_tok);
        goto done;
    }
    GString *fam = g_string_new(NULL);
    for (int j = fam_start; j < n; j++) {
        if (j > fam_start) g_string_append_c(fam, ' ');
        g_string_append(fam, tokens[j]);
    }
    char *family = ns_css_font_family_canonical(fam->str);
    g_string_free(fam, TRUE);
    if (!family) {
        g_free(size_only);
        g_free(lh_tok);
        goto done;
    }
    GString *out = g_string_new(NULL);
    if (style) { g_string_append(out, g_ascii_strcasecmp(style, "italic") == 0 ? "italic" : "oblique"); }
    if (variant) { if (out->len) g_string_append_c(out, ' '); g_string_append(out, "small-caps"); }
    if (weight) {
        if (out->len) g_string_append_c(out, ' ');
        char *lw = g_ascii_strdown(weight, -1);
        g_string_append(out, lw);
        g_free(lw);
    }
    if (stretch) {
        if (out->len) g_string_append_c(out, ' ');
        char *ls = g_ascii_strdown(stretch, -1);
        g_string_append(out, ls);
        g_free(ls);
    }
    if (out->len) g_string_append_c(out, ' ');
    {
        char *ls = font_size_keyword_px(size_only) > 0 ||
                   g_ascii_strcasecmp(size_only, "larger") == 0 ||
                   g_ascii_strcasecmp(size_only, "smaller") == 0
            ? g_ascii_strdown(size_only, -1) : g_strdup(size_only);
        g_string_append(out, ls);
        g_free(ls);
    }
    if (lh_tok && g_ascii_strcasecmp(lh_tok, "normal") != 0) {
        g_string_append(out, " / ");
        g_string_append(out, lh_tok);
    }
    g_string_append_c(out, ' ');
    g_string_append(out, family);
    g_free(family);
    g_free(size_only);
    g_free(lh_tok);
    result = g_string_free(out, FALSE);
done:
    for (int k = 0; k < n; k++) g_free(tokens[k]);
    return result;
}

#define NS_CSS_RANDOM_ITEM_MAX_DEPTH 16

static gboolean
font_family_random_item_valid(const char *item, gsize ilen)
{
    static __thread int nesting;
    if (nesting >= NS_CSS_RANDOM_ITEM_MAX_DEPTH) return FALSE;
    const char *open = memchr(item, '(', ilen);
    if (!open || item[ilen - 1] != ')') return FALSE;
    char *body = g_strndup(open + 1, (gsize)(item + ilen - 1 - (open + 1)));
    GPtrArray *args = g_ptr_array_new_with_free_func(g_free);
    const char *seg = body;
    int depth = 0;
    for (const char *q = body; ; q++) {
        if (*q == '(' || *q == '{' || *q == '[') depth++;
        else if ((*q == ')' || *q == '}' || *q == ']') && depth > 0) depth--;
        if ((*q == ',' && depth == 0) || !*q) {
            char *piece = g_strndup(seg, (gsize)(q - seg));
            g_strstrip(piece);
            g_ptr_array_add(args, piece);
            if (!*q) break;
            seg = q + 1;
        }
    }
    g_free(body);
    gboolean ok = args->len >= 2;
    if (ok) {
        const char *first = args->pdata[0];
        char *tok[3] = {0};
        int n = split_ws_limit(first, tok, 3);
        ok = n >= 1 && n <= 2;
        for (int i = 0; i < n && ok; i++) {
            const char *t = tok[i];
            if (i == 1 && g_ascii_strcasecmp(tok[0], "fixed") == 0) {
                char *endp = NULL;
                g_ascii_strtod(t, &endp);
                ok = endp && *endp == '\0';
            } else {
                ok = font_family_ident_valid(t, strlen(t)) ||
                     (g_str_has_prefix(t, "--") && t[2]);
            }
        }
        for (int i = 0; i < n; i++) g_free(tok[i]);
    }
    for (guint i = 1; i < args->len && ok; i++) {
        const char *a = args->pdata[i];
        gsize alen = strlen(a);
        if (!alen) continue;
        char *inner = NULL;
        if (a[0] == '{') {
            if (a[alen - 1] != '}') { ok = FALSE; break; }
            inner = g_strndup(a + 1, alen - 2);
        } else if (memchr(a, '{', alen) || memchr(a, '}', alen)) {
            ok = FALSE;
            break;
        } else {
            inner = g_strdup(a);
        }
        nesting++;
        char *canon = ns_css_font_family_canonical(inner);
        nesting--;
        ok = canon != NULL;
        g_free(canon);
        g_free(inner);
    }
    g_ptr_array_free(args, TRUE);
    return ok;
}

char *
ns_css_font_family_canonical(const char *text)
{
    if (!text) return NULL;
    GString *out = g_string_new(NULL);
    const char *p = text;
    const char *end = text + strlen(text);
    gboolean any = FALSE;
    while (p <= end) {
        while (p < end && is_ws(*p)) p++;
        const char *item_start = p;
        char term = 0;
        const char *item_end = css_scan_until(p, end, ",", &term);
        gsize ilen = (gsize)(item_end - item_start);
        while (ilen > 0 && is_ws(item_start[ilen - 1])) ilen--;
        if (ilen == 0) { g_string_free(out, TRUE); return NULL; }
        if (any) g_string_append(out, ", ");
        any = TRUE;
        if (item_start[0] == '"' || item_start[0] == '\'') {
            char q = item_start[0];
            if (ilen < 2 || item_start[ilen - 1] != q) {
                g_string_free(out, TRUE);
                return NULL;
            }
            const char *body = item_start + 1;
            gsize blen = ilen - 2;
            gboolean ident_like = blen > 0 && !is_ws(body[0]) &&
                                  !is_ws(body[blen - 1]) &&
                                  !memchr(body, '\\', blen);
            if (ident_like) {
                const char *w = body, *wend = body + blen;
                while (w < wend && ident_like) {
                    const char *tok = w;
                    while (w < wend && !is_ws(*w)) w++;
                    gsize tlen = (gsize)(w - tok);
                    if (!font_family_ident_valid(tok, tlen) ||
                        font_family_is_generic(tok, tlen))
                        ident_like = FALSE;
                    if (w < wend && (w + 1 >= wend || is_ws(w[1])))
                        ident_like = FALSE;
                    w++;
                }
            }
            if (ident_like) {
                g_string_append_len(out, body, (gssize)blen);
            } else {
                g_string_append_c(out, '"');
                for (gsize k = 0; k < blen; k++) {
                    char c = body[k];
                    if (c == '\\' && k + 1 < blen) {
                        g_string_append_c(out, c);
                        g_string_append_c(out, body[++k]);
                        continue;
                    }
                    if (c == '"') g_string_append_c(out, '\\');
                    g_string_append_c(out, c);
                }
                g_string_append_c(out, '"');
            }
        } else if (item_start[ilen - 1] == ')' &&
                   (g_ascii_strncasecmp(item_start, "random-item(", 12) == 0 ||
                    g_ascii_strncasecmp(item_start, "-webkit-generic(", 16) == 0)) {
            if (g_ascii_strncasecmp(item_start, "random-item(", 12) == 0 &&
                !font_family_random_item_valid(item_start, ilen)) {
                g_string_free(out, TRUE);
                return NULL;
            }
            g_string_append_len(out, item_start, (gssize)ilen);
        } else {
            const char *q = item_start, *qend = item_start + ilen;
            gboolean first = TRUE;
            {
                static const char *const reserved[] = {
                    "inherit", "initial", "unset", "revert", "revert-layer",
                    "default",
                };
                for (gsize k = 0; k < G_N_ELEMENTS(reserved); k++)
                    if (strlen(reserved[k]) == ilen &&
                        g_ascii_strncasecmp(item_start, reserved[k], ilen) == 0) {
                        g_string_free(out, TRUE);
                        return NULL;
                    }
            }
            while (q < qend) {
                while (q < qend && is_ws(*q)) q++;
                const char *tok = q;
                while (q < qend && !is_ws(*q)) q++;
                gsize tlen = (gsize)(q - tok);
                if (tlen == 0) break;
                static const char *const leading_generic[] = {
                    "serif", "sans-serif", "cursive", "fantasy", "monospace",
                    "system-ui", "math", "-webkit-body",
                };
                gboolean generic_head = FALSE;
                for (gsize k = 0; first && q < qend &&
                                  k < G_N_ELEMENTS(leading_generic); k++)
                    if (strlen(leading_generic[k]) == tlen &&
                        g_ascii_strncasecmp(tok, leading_generic[k], tlen) == 0)
                        generic_head = TRUE;
                if (!font_family_ident_valid(tok, tlen) || generic_head) {
                    g_string_free(out, TRUE);
                    return NULL;
                }
                if (!first) g_string_append_c(out, ' ');
                if (first && q >= qend && font_family_is_generic(tok, tlen)) {
                    char *lower = g_ascii_strdown(tok, (gssize)tlen);
                    g_string_append(out, lower);
                    g_free(lower);
                } else {
                    g_string_append_len(out, tok, (gssize)tlen);
                }
                first = FALSE;
            }
        }
        if (term != ',') break;
        p = item_end + 1;
        if (p >= end) { g_string_free(out, TRUE); return NULL; }
    }
    if (!any) { g_string_free(out, TRUE); return NULL; }
    return g_string_free(out, FALSE);
}

static gboolean
line_name_is_custom_ident(const char *ns, gsize nlen)
{
    if (nlen == 0) return FALSE;
    gsize i = 0;
    if (ns[0] == '-') {
        i = 1;
        if (nlen == 1) return FALSE;
    }
    if (g_ascii_isdigit(ns[i])) return FALSE;
    for (gsize k = i; k < nlen; k++) {
        char c = ns[k];
        if (!(g_ascii_isalnum(c) || c == '-' || c == '_' || (unsigned char)c >= 0x80))
            return FALSE;
    }
    static const char *const reserved[] = {
        "span", "auto", "initial", "inherit", "unset", "revert",
        "revert-layer", "default",
    };
    for (gsize k = 0; k < G_N_ELEMENTS(reserved); k++)
        if (strlen(reserved[k]) == nlen &&
            g_ascii_strncasecmp(ns, reserved[k], nlen) == 0)
            return FALSE;
    return TRUE;
}

static gboolean
tracks_add_names(ns_css_tracks *tk, const char *names, gsize names_len, int line)
{
    if (memchr(names, ',', names_len)) return FALSE;
    const char *q = names, *qend = names + names_len;
    while (q < qend) {
        while (q < qend && is_ws(*q)) q++;
        const char *ns = q;
        while (q < qend && !is_ws(*q)) q++;
        gsize nlen = (gsize)(q - ns);
        if (nlen > 0 && !line_name_is_custom_ident(ns, nlen)) return FALSE;
        if (nlen > 0 && tk->n_line_names < NS_CSS_LINE_NAMES_MAX) {
            char *name = g_strndup(ns, nlen);
            ns_css_line_name *ln = &tk->line_names[tk->n_line_names++];
            ln->name = g_intern_string(name);
            ln->line = line;
            g_free(name);
        }
    }
    return TRUE;
}

static gboolean
track_is_fixed_size(const ns_css_track *t)
{
    gboolean main_fixed = t->kind == NS_CSS_TRACK_PX || t->kind == NS_CSS_TRACK_PERCENT;
    if (!t->has_min) return main_fixed;
    gboolean min_fixed = t->min_kind == NS_CSS_TRACK_PX ||
                         t->min_kind == NS_CSS_TRACK_PERCENT;
    return main_fixed || min_fixed;
}

static gboolean
tracks_append_repeat_body(ns_css_tracks *tk, const char *body, gsize body_len,
                          long repeats, int *out_tracks_per_repeat)
{
    const char *tstarts[32];
    gsize tlens[32];
    int nb = 0;
    const char *p = body, *end = body + body_len;
    while (p < end && nb < 32) {
        while (p < end && is_ws(*p)) p++;
        if (p >= end) break;
        const char *tok_start = p;
        if (*p == '[') {
            while (p < end && *p != ']') p++;
            if (p < end) p++;
        } else {
            char term = 0;
            p = css_scan_until(p, end, " \t\n\r\f,[", &term);
        }
        tstarts[nb] = tok_start;
        tlens[nb] = (gsize)(p - tok_start);
        nb++;
        if (p < end && *p == ',') p++;
    }
    int per = 0;
    for (int i = 0; i < nb; i++)
        if (tstarts[i][0] != '[') per++;
    if (per == 0) return FALSE;
    if (out_tracks_per_repeat) *out_tracks_per_repeat = per;
    for (long r = 0; r < repeats; r++) {
        gboolean last_names = FALSE;
        for (int i = 0; i < nb; i++) {
            if (tstarts[i][0] == '[') {
                if (last_names || tlens[i] < 2) return FALSE;
                if (!tracks_add_names(tk, tstarts[i] + 1, tlens[i] - 2, tk->n + 1))
                    return FALSE;
                last_names = TRUE;
                continue;
            }
            last_names = FALSE;
            if (tk->n >= NS_CSS_TRACKS_MAX) return TRUE;
            ns_css_track t = {0};
            if (!parse_one_track(tstarts[i], tlens[i], &t)) return FALSE;
            tk->tracks[tk->n++] = t;
        }
    }
    return TRUE;
}

static ns_css_value *
parse_tracks(const char *text)
{
    if (!text || !*text) return NULL;
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_TRACKS;
    const char *p = text;
    const char *full_end = text + strlen(text);
    while (p < full_end && is_ws(*p)) p++;
    if (g_ascii_strncasecmp(p, "subgrid", 7) == 0 &&
        (p + 7 >= full_end || is_ws(p[7]) || p[7] == '[')) {
        v->u.tracks.subgrid = TRUE;
        return v;
    }
    gboolean last_was_names = FALSE;
    while (p < full_end && v->u.tracks.n < NS_CSS_TRACKS_MAX) {
        while (p < full_end && is_ws(*p)) p++;
        if (p >= full_end) break;
        if (*p == '[') {
            const char *names = ++p;
            while (p < full_end && *p != ']') p++;
            gsize names_len = (gsize)(p - names);
            if (p >= full_end || last_was_names ||
                memchr(names, ',', names_len)) {
                g_free(v);
                return NULL;
            }
            last_was_names = TRUE;
            p++;
            if (!tracks_add_names(&v->u.tracks, names, names_len,
                                  v->u.tracks.n + 1)) {
                g_free(v);
                return NULL;
            }
            continue;
        }
        last_was_names = FALSE;
        if (g_ascii_strncasecmp(p, "repeat(", 7) == 0) {
            p += 7;
            while (p < full_end && is_ws(*p)) p++;
            const char *count_s = p;
            while (p < full_end && *p != ',' && *p != ')') p++;
            gsize count_len = (gsize)(p - count_s);
            while (count_len > 0 && is_ws(count_s[count_len - 1])) count_len--;
            if (p < full_end && *p == ',') p++;
            const char *body = p;
            int depth = 1;
            while (p < full_end && depth > 0) {
                if (*p == '(') depth++;
                else if (*p == ')') { depth--; if (depth == 0) break; }
                p++;
            }
            gsize body_len = (gsize)(p - body);
            if (p < full_end && *p == ')') p++;
            ns_css_auto_repeat ar = NS_CSS_AUTO_REPEAT_NONE;
            long n = 0;
            if (count_len == 8 && g_ascii_strncasecmp(count_s, "auto-fit", 8) == 0)
                ar = NS_CSS_AUTO_REPEAT_FIT;
            else if (count_len == 9 && g_ascii_strncasecmp(count_s, "auto-fill", 9) == 0)
                ar = NS_CSS_AUTO_REPEAT_FILL;
            else {
                char *cstr = g_strndup(count_s, count_len);
                n = strtol(cstr, NULL, 10);
                g_free(cstr);
                if (n <= 0) continue;
                if (n > NS_CSS_TRACKS_MAX) n = NS_CSS_TRACKS_MAX;
            }
            if (ar != NS_CSS_AUTO_REPEAT_NONE) {
                if (v->u.tracks.auto_repeat != NS_CSS_AUTO_REPEAT_NONE) {
                    g_free(v);
                    return NULL;
                }
                v->u.tracks.auto_repeat = ar;
                v->u.tracks.auto_repeat_start = v->u.tracks.n;
                v->u.tracks.auto_repeat_names_start = v->u.tracks.n_line_names;
                int cnt = 0;
                if (!tracks_append_repeat_body(&v->u.tracks, body, body_len,
                                               1, &cnt)) {
                    g_free(v);
                    return NULL;
                }
                v->u.tracks.auto_repeat_names_end = v->u.tracks.n_line_names;
                for (int k = v->u.tracks.auto_repeat_start; k < v->u.tracks.n; k++)
                    if (!track_is_fixed_size(&v->u.tracks.tracks[k])) {
                        g_free(v);
                        return NULL;
                    }
                if (cnt > v->u.tracks.n - v->u.tracks.auto_repeat_start)
                    cnt = v->u.tracks.n - v->u.tracks.auto_repeat_start;
                v->u.tracks.auto_repeat_count = cnt;
                continue;
            }
            if (!tracks_append_repeat_body(&v->u.tracks, body, body_len, n, NULL)) {
                g_free(v);
                return NULL;
            }
            continue;
        }
        const char *tstarts[1];
        gsize tlens[1];
        int n = split_tracks_top(p, (gsize)(full_end - p), tstarts, tlens, 1);
        if (n == 0) break;
        {
            const char *after = tstarts[0] + tlens[0];
            while (after < full_end && is_ws(*after)) after++;
            if (after < full_end && *after == ',') {
                g_free(v);
                return NULL;
            }
        }
        last_was_names = FALSE;
        ns_css_track t = {0};
        if (!parse_one_track(tstarts[0], tlens[0], &t)) {
            g_free(v);
            return NULL;
        }
        v->u.tracks.tracks[v->u.tracks.n++] = t;
        const char *next = tstarts[0] + tlens[0];
        while (next < full_end && is_ws(*next)) next++;
        if (next < full_end && *next == ',') next++;
        if (next <= p) next = p + 1;
        p = next;
    }
    if (v->u.tracks.n == 0) { g_free(v); return NULL; }
    if (v->u.tracks.n == 0 && v->u.tracks.n_line_names > 0) {
        g_free(v);
        return NULL;
    }
    if (v->u.tracks.auto_repeat != NS_CSS_AUTO_REPEAT_NONE) {
        for (int k = 0; k < v->u.tracks.n; k++) {
            if (k >= v->u.tracks.auto_repeat_start &&
                k < v->u.tracks.auto_repeat_start + v->u.tracks.auto_repeat_count)
                continue;
            if (!track_is_fixed_size(&v->u.tracks.tracks[k])) {
                g_free(v);
                return NULL;
            }
        }
    }
    return v;
}

static ns_css_value *
parse_areas(const char *text)
{
    if (!text || !*text) return NULL;
    char *grid[NS_CSS_TRACKS_MAX][NS_CSS_TRACKS_MAX] = {{0}};
    int rows = 0;
    int cols = -1;
    const char *p = text;
    while (*p && rows < NS_CSS_TRACKS_MAX) {
        while (*p && is_ws(*p)) p++;
        if (!*p) break;
        if (*p != '"' && *p != '\'') {
            for (int r = 0; r < rows; r++)
                for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
                    g_free(grid[r][k]);
            return NULL;
        }
        const char *row_start = p;
        char *row = read_css_string(&p, p + strlen(p));
        if (p == row_start) {
            g_free(row);
            for (int r = 0; r < rows; r++)
                for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
                    g_free(grid[r][k]);
            return NULL;
        }
        char **toks = g_strsplit_set(row, " \t\r\n", -1);
        int c = 0;
        for (int i = 0; toks[i]; i++) {
            if (!*toks[i]) continue;
            if (c >= NS_CSS_TRACKS_MAX) break;
            grid[rows][c++] = g_strdup(toks[i]);
        }
        g_strfreev(toks);
        g_free(row);
        if (cols < 0) cols = c;
        else if (c != cols) {
            for (int r = 0; r <= rows; r++)
                for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
                    g_free(grid[r][k]);
            return NULL;
        }
        rows++;
    }
    if (rows == 0 || cols <= 0) {
        for (int r = 0; r < rows; r++)
            for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
                g_free(grid[r][k]);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_AREAS;
    v->u.areas.n_rows = rows;
    v->u.areas.n_cols = cols;
    gboolean used[NS_CSS_TRACKS_MAX][NS_CSS_TRACKS_MAX] = {{0}};
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (used[r][c]) continue;
            const char *name = grid[r][c];
            if (!name || strcmp(name, ".") == 0) { used[r][c] = TRUE; continue; }
            int c1 = c;
            while (c1 + 1 < cols && grid[r][c1 + 1] &&
                   strcmp(grid[r][c1 + 1], name) == 0) c1++;
            int r1 = r;
            while (r1 + 1 < rows) {
                gboolean ok = TRUE;
                for (int k = c; k <= c1; k++) {
                    if (!grid[r1 + 1][k] || strcmp(grid[r1 + 1][k], name) != 0) {
                        ok = FALSE; break;
                    }
                }
                if (!ok) break;
                r1++;
            }
            if (v->u.areas.n_rects < NS_CSS_AREAS_MAX) {
                ns_css_area_rect *rect = &v->u.areas.rects[v->u.areas.n_rects++];
                rect->name = g_strdup(name);
                rect->r0 = r; rect->r1 = r1;
                rect->c0 = c; rect->c1 = c1;
            }
            for (int rr = r; rr <= r1; rr++)
                for (int cc = c; cc <= c1; cc++)
                    used[rr][cc] = TRUE;
        }
    }
    for (int r = 0; r < rows; r++)
        for (int k = 0; k < NS_CSS_TRACKS_MAX; k++)
            g_free(grid[r][k]);
    return v;
}

static gboolean text_is_ident(const char *t);
static gboolean bg_repeat_token(const char *tok, gboolean allow_axis);
static char *bg_repeat_canonical(const char *a, const char *b);
static char *bg_position_zip(const char *xs, const char *ys);
static gboolean bg_token_is_box(const char *tok);
static char *position_from_edge(const char *edge, const char *offset);
static int css_ws_token_count(const char *s);
static char *transform_list_canonical(const char *value);
static char *individual_transform_canonical(const char *value, ns_css_prop prop);
static char *transform_origin_canonical(const char *value, gboolean two_only);
static gboolean inline_css_wide_value(const char *value);
static char *bg_clip_canonical(const char *text);
static char *css_add_leading_zeros(char *v);
static char *css_normalize_negative_zero(char *value);
static void ns_css_append_color(GString *s, guint8 r, guint8 g, guint8 b, guint8 a);

static gboolean
shadow_length_token(const char *tok, gboolean allow_negative, GString *out)
{
    double num;
    ns_css_unit unit;
    if (parse_length(tok, &num, &unit)) {
        if (unit == NS_CSS_UNIT_PERCENT) return FALSE;
        if (unit == NS_CSS_UNIT_NUMBER && num != 0) return FALSE;
        if (!allow_negative && num < 0) return FALSE;
        if (num == 0) {
            g_string_append(out, "0px");
            return TRUE;
        }
        char *canon = css_normalize_negative_zero(
            css_add_leading_zeros(g_strdup(tok)));
        char *suffix = canon + strlen(canon);
        while (suffix > canon && g_ascii_isalpha((guchar)suffix[-1]))
            suffix--;
        for (char *c = suffix; *c; c++) *c = g_ascii_tolower((guchar)*c);
        g_string_append(out, canon);
        g_free(canon);
        return TRUE;
    }
    ns_css_value *calc = parse_calc(tok);
    if (!calc) return FALSE;
    gboolean ok = (calc->kind == NS_CSS_V_CALC && calc->u.calc.pct == 0) ||
                  (calc->kind == NS_CSS_V_LENGTH &&
                   calc->u.length.unit != NS_CSS_UNIT_PERCENT &&
                   calc->u.length.unit != NS_CSS_UNIT_NUMBER);
    ns_css_value_free(calc);
    if (!ok) return FALSE;
    char *canon = ns_css_math_canonical(tok);
    if (!canon) canon = css_add_leading_zeros(g_strdup(tok));
    g_string_append(out, canon);
    g_free(canon);
    return TRUE;
}

static gboolean
shadow_specified_one(const char *text, gboolean is_text, GString *out)
{
    char *tokens[8] = {0};
    int n = split_ws_limit(text, tokens, G_N_ELEMENTS(tokens));
    GString *color = NULL;
    GString *lengths = g_string_new(NULL);
    int n_lengths = 0;
    gboolean lengths_closed = FALSE;
    gboolean inset = FALSE, ok = n > 0;
    for (int i = 0; ok && i < n; i++) {
        const char *tok = tokens[i];
        guint8 r, g, b, a;
        if (g_ascii_strcasecmp(tok, "inset") == 0) {
            if (is_text || inset) ok = FALSE;
            inset = TRUE;
            if (n_lengths) lengths_closed = TRUE;
            continue;
        }
        if (parse_color(tok, &r, &g, &b, &a) ||
            g_ascii_strcasecmp(tok, "currentcolor") == 0) {
            if (color) {
                ok = FALSE;
                continue;
            }
            color = g_string_new(NULL);
            if (text_is_ident(tok)) {
                char *lower = g_ascii_strdown(tok, -1);
                g_string_append(color, lower);
                g_free(lower);
            } else {
                ns_css_append_color(color, r, g, b, a);
            }
            if (n_lengths) lengths_closed = TRUE;
            continue;
        }
        if (lengths_closed || n_lengths >= (is_text ? 3 : 4)) {
            ok = FALSE;
            continue;
        }
        if (lengths->len) g_string_append_c(lengths, ' ');
        if (!shadow_length_token(tok, n_lengths != 2, lengths)) ok = FALSE;
        n_lengths++;
    }
    if (n_lengths < 2) ok = FALSE;
    if (ok) {
        if (color) {
            g_string_append(out, color->str);
            g_string_append_c(out, ' ');
        }
        g_string_append(out, lengths->str);
        if (inset) g_string_append(out, " inset");
    }
    if (color) g_string_free(color, TRUE);
    g_string_free(lengths, TRUE);
    for (int i = 0; i < n; i++) g_free(tokens[i]);
    return ok;
}

static char *
shadow_specified_canonical(const char *value, gboolean is_text)
{
    if (!value) return NULL;
    while (*value && is_ws(*value)) value++;
    if (!*value || strstr(value, "var(")) return NULL;
    if (g_ascii_strcasecmp(value, "none") == 0) return g_strdup("none");
    GString *out = g_string_new(NULL);
    const char *end = value + strlen(value);
    const char *p = value;
    gboolean ok = TRUE;
    while (ok && p < end) {
        char term = 0;
        const char *seg_end = css_scan_until(p, end, ",", &term);
        char *layer = css_trim_dup_range(p, seg_end);
        if (out->len) g_string_append(out, ", ");
        ok = shadow_specified_one(layer, is_text, out);
        g_free(layer);
        p = term == ',' ? seg_end + 1 : seg_end;
        if (term == ',' && p >= end) ok = FALSE;
    }
    if (!ok) {
        g_string_free(out, TRUE);
        return NULL;
    }
    return g_string_free(out, FALSE);
}

static gboolean
parse_one_shadow(const char *text, ns_css_shadow *out)
{
    char *tokens[8] = {0};
    int n = split_ws_limit(text, tokens, G_N_ELEMENTS(tokens));
    gboolean inset = FALSE;
    guint8 cr = 0, cg = 0, cb = 0, ca = 255;
    gboolean has_color = FALSE;
    double lens[4] = {0}, ems[4] = {0}, rems[4] = {0};
    int n_lens = 0;
    for (int i = 0; i < n; i++) {
        const char *tok = tokens[i];
        guint8 r, g, b, a;
        double num;
        ns_css_unit u;
        if (parse_color(tok, &r, &g, &b, &a)) {
            cr = r; cg = g; cb = b; ca = a; has_color = TRUE;
        } else if (n_lens < 4 && parse_length(tok, &num, &u)) {
            if (u == NS_CSS_UNIT_EM) { ems[n_lens] = num; num = 0; }
            else if (u == NS_CSS_UNIT_REM) { rems[n_lens] = num; num = 0; }
            else if (u == NS_CSS_UNIT_EX || u == NS_CSS_UNIT_CH) num *= 8;
            else if (u == NS_CSS_UNIT_CAP) num *= 11.2;
            else if (u == NS_CSS_UNIT_IC) num *= 16;
            lens[n_lens++] = num;
        } else if (n_lens < 4 && g_ascii_strncasecmp(tok, "calc(", 5) == 0) {
            ns_css_value *cv = parse_calc(tok);
            if (cv && cv->kind == NS_CSS_V_CALC) {
                lens[n_lens] = cv->u.calc.px;
                ems[n_lens] = cv->u.calc.em;
                rems[n_lens] = cv->u.calc.rem;
                n_lens++;
            }
            ns_css_value_free(cv);
        } else if (g_ascii_strcasecmp(tok, "inset") == 0) {
            inset = TRUE;
        }
    }
    for (int i = 0; i < n; i++) g_free(tokens[i]);
    if (n_lens < 2) return FALSE;
    memset(out, 0, sizeof *out);
    out->x = lens[0];
    out->y = lens[1];
    out->blur   = n_lens >= 3 ? CLAMP(lens[2], 0.0, 1000.0) : 0;
    out->spread = n_lens >= 4 ? CLAMP(lens[3], -1000.0, 1000.0) : 0;
    for (int k = 0; k < 4; k++) {
        out->em[k] = ems[k];
        out->rem[k] = rems[k];
    }
    out->r = cr; out->g = cg; out->b = cb;
    out->a = ca;
    out->currentcolor = !has_color;
    out->inset = inset;
    return TRUE;
}

static ns_css_value *
parse_box_shadow(const char *text)
{
    while (*text && is_ws(*text)) text++;
    if (!*text) return NULL;
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_SHADOW;
    char *copy = g_strdup(text);
    int depth = 0;
    char *seg = copy;
    for (char *q = copy; ; q++) {
        if (*q == '(') depth++;
        else if (*q == ')') { if (depth > 0) depth--; }
        gboolean at_end = (*q == '\0');
        if ((*q == ',' && depth == 0) || at_end) {
            char saved = *q;
            *q = '\0';
            if (v->u.shadow.n < NS_CSS_SHADOWS_MAX) {
                if (parse_one_shadow(seg, &v->u.shadow.s[v->u.shadow.n]))
                    v->u.shadow.n++;
            }
            if (at_end) break;
            *q = saved;
            seg = q + 1;
        }
    }
    g_free(copy);
    if (v->u.shadow.n == 0) { g_free(v); return NULL; }
    return v;
}

static gboolean position_is_h_edge(const char *t);
static gboolean position_is_v_edge(const char *t);
static gboolean math_text_mixes_angle_and_length(const char *t);
static void position_split(const char *text, char **out_x, char **out_y);
static double parse_angle_deg(const char *s);

typedef struct ns_gradient_parse {
    ns_css_gradient gr;
    char *angle_text;
    char *size_text;
    char *position_text;
    gboolean interp_explicit;
    gboolean all_legacy;
    GPtrArray *stop_texts;
    GPtrArray *stop_colors;
} ns_gradient_parse;

static void
gradient_parse_clear(ns_gradient_parse *gp)
{
    g_free(gp->angle_text);
    g_free(gp->size_text);
    g_free(gp->position_text);
    if (gp->stop_texts) g_ptr_array_free(gp->stop_texts, TRUE);
    if (gp->stop_colors) g_ptr_array_free(gp->stop_colors, TRUE);
    memset(gp, 0, sizeof *gp);
}

static gboolean
token_eq(const char *t, const char *kw)
{
    return g_ascii_strcasecmp(t, kw) == 0;
}

static gboolean
token_is_math_fn(const char *t)
{
    return g_ascii_strncasecmp(t, "calc(", 5) == 0 ||
           g_ascii_strncasecmp(t, "min(", 4) == 0 ||
           g_ascii_strncasecmp(t, "max(", 4) == 0 ||
           g_ascii_strncasecmp(t, "clamp(", 6) == 0;
}

static gboolean
token_is_length_pct(const char *t)
{
    if (token_is_math_fn(t)) {
        ns_css_value *cv = parse_calc(t);
        if (!cv) return FALSE;
        gboolean ok = cv->kind == NS_CSS_V_CALC || cv->kind == NS_CSS_V_LENGTH;
        ns_css_value_free(cv);
        return ok;
    }
    double v; ns_css_unit u;
    if (!parse_length(t, &v, &u)) return FALSE;
    return u != NS_CSS_UNIT_NUMBER || v == 0;
}

static gboolean
token_is_angle(const char *t)
{
    if (token_is_math_fn(t)) {
        char *lower = g_ascii_strdown(t, -1);
        gboolean ok = strstr(lower, "deg") || strstr(lower, "rad") ||
                      strstr(lower, "turn") || strstr(lower, "grad");
        g_free(lower);
        return ok;
    }
    if (strcmp(t, "0") == 0) return TRUE;
    char *end = NULL;
    double v = g_ascii_strtod(t, &end);
    (void)v;
    if (!end || end == t) return FALSE;
    return token_eq(end, "deg") || token_eq(end, "grad") ||
           token_eq(end, "rad") || token_eq(end, "turn");
}

static char *
gradient_stop_color_specified(const char *tok)
{
    char *canon = ns_css_color_specified(tok);
    if (canon) return canon;
    guint8 r, g, b, a;
    gboolean legacy_syntax = tok[0] == '#' ||
        g_ascii_strncasecmp(tok, "rgb(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "rgba(", 5) == 0 ||
        g_ascii_strncasecmp(tok, "hsl(", 4) == 0 ||
        g_ascii_strncasecmp(tok, "hsla(", 5) == 0;
    if (legacy_syntax && parse_color(tok, &r, &g, &b, &a)) {
        ns_css_value cv = { .kind = NS_CSS_V_COLOR };
        cv.u.color.r = r;
        cv.u.color.g = g;
        cv.u.color.b = b;
        cv.u.color.a = a;
        return ns_css_value_serialize(&cv);
    }
    if (strchr(tok, '(')) return g_strdup(tok);
    return g_ascii_strdown(tok, -1);
}

static gboolean
color_text_is_legacy(const char *t)
{
    if (t[0] == '#') return TRUE;
    if (!strchr(t, '(')) return TRUE;
    return g_ascii_strncasecmp(t, "rgb(", 4) == 0 ||
           g_ascii_strncasecmp(t, "rgba(", 5) == 0 ||
           g_ascii_strncasecmp(t, "hsl(", 4) == 0 ||
           g_ascii_strncasecmp(t, "hsla(", 5) == 0;
}

static int
gradient_interp_parse(char **tok, int n, char out[NS_CSS_GRADIENT_INTERP_MAX])
{
    if (n < 1) return 0;
    static const char *rect[] = {
        "srgb", "srgb-linear", "display-p3", "a98-rgb", "prophoto-rgb",
        "rec2020", "lab", "oklab", "xyz", "xyz-d50", "xyz-d65",
    };
    static const char *polar[] = { "hsl", "hwb", "lch", "oklch" };
    char *space = g_ascii_strdown(tok[0], -1);
    gboolean is_rect = FALSE, is_polar = FALSE;
    for (gsize i = 0; i < G_N_ELEMENTS(rect); i++)
        if (strcmp(space, rect[i]) == 0) is_rect = TRUE;
    for (gsize i = 0; i < G_N_ELEMENTS(polar); i++)
        if (strcmp(space, polar[i]) == 0) is_polar = TRUE;
    if (!is_rect && !is_polar) { g_free(space); return 0; }
    if (strcmp(space, "xyz") == 0) { g_free(space); space = g_strdup("xyz-d65"); }
    int used = 1;
    const char *hue = NULL;
    if (is_polar && n >= 3 && token_eq(tok[2], "hue")) {
        if (token_eq(tok[1], "shorter")) hue = NULL;
        else if (token_eq(tok[1], "longer")) hue = "longer";
        else if (token_eq(tok[1], "increasing")) hue = "increasing";
        else if (token_eq(tok[1], "decreasing")) hue = "decreasing";
        else { g_free(space); return 0; }
        used = 3;
    } else if (n >= 2 && (token_eq(tok[1], "hue") || token_eq(tok[1], "shorter") ||
                          token_eq(tok[1], "longer") || token_eq(tok[1], "increasing") ||
                          token_eq(tok[1], "decreasing"))) {
        g_free(space);
        return 0;
    }
    if (hue) g_snprintf(out, NS_CSS_GRADIENT_INTERP_MAX, "%s %s hue", space, hue);
    else g_strlcpy(out, space, NS_CSS_GRADIENT_INTERP_MAX);
    g_free(space);
    return used;
}

static char *
position_canonical_ex(const char *text, gboolean expand_single,
                      gboolean allow_three)
{
    char *tok[8] = {0};
    int m = split_ws_paren(text, tok, 8);
    char *spec = NULL;
    if (m == 0 || m > 4 || (m == 3 && !allow_three)) goto done;
    gboolean h0 = position_is_h_edge(tok[0]), v0 = position_is_v_edge(tok[0]);
    gboolean c0 = token_eq(tok[0], "center");
    if (m == 1) {
        if (!(h0 || v0 || c0 || token_is_length_pct(tok[0]))) goto done;
        if (!expand_single) spec = g_strdup(tok[0]);
        else if (v0) spec = g_strdup_printf("center %s", tok[0]);
        else spec = g_strdup_printf("%s center", tok[0]);
    } else if (m == 3) {
        gboolean off_after_first = token_is_length_pct(tok[1]);
        const char *ek = off_after_first ? tok[0] : tok[1];
        const char *off = off_after_first ? tok[1] : tok[2];
        const char *other = off_after_first ? tok[2] : tok[0];
        gboolean eh = position_is_h_edge(ek), ev = position_is_v_edge(ek);
        gboolean oh = position_is_h_edge(other), ov = position_is_v_edge(other);
        gboolean oc = token_eq(other, "center");
        if (!(eh || ev) || !token_is_length_pct(off) || !(oh || ov || oc))
            goto done;
        if ((eh && oh) || (ev && ov)) goto done;
        if (eh) spec = g_strdup_printf("%s %s %s", ek, off, other);
        else spec = g_strdup_printf("%s %s %s", other, ek, off);
    } else if (m == 2) {
        gboolean h1 = position_is_h_edge(tok[1]), v1 = position_is_v_edge(tok[1]);
        gboolean c1 = token_eq(tok[1], "center");
        gboolean k0 = h0 || v0 || c0, k1 = h1 || v1 || c1;
        if (k0 && k1) {
            if ((h0 && h1) || (v0 && v1)) goto done;
            if ((v0 && (h1 || c1) && !(c0 && c1)) || (c0 && h1))
                spec = g_strdup_printf("%s %s", tok[1], tok[0]);
            else
                spec = g_strdup_printf("%s %s", tok[0], tok[1]);
        } else if (k0 && !k1) {
            if (!v0 && token_is_length_pct(tok[1]))
                spec = g_strdup_printf("%s %s", tok[0], tok[1]);
        } else if (!k0 && k1) {
            if (!h1 && token_is_length_pct(tok[0]))
                spec = g_strdup_printf("%s %s", tok[0], tok[1]);
        } else if (token_is_length_pct(tok[0]) && token_is_length_pct(tok[1])) {
            spec = g_strdup_printf("%s %s", tok[0], tok[1]);
        }
    } else {
        gboolean h2 = position_is_h_edge(tok[2]), v2 = position_is_v_edge(tok[2]);
        if (!token_is_length_pct(tok[1]) || !token_is_length_pct(tok[3]))
            goto done;
        if (h0 && v2)
            spec = g_strdup_printf("%s %s %s %s", tok[0], tok[1], tok[2], tok[3]);
        else if (v0 && h2)
            spec = g_strdup_printf("%s %s %s %s", tok[2], tok[3], tok[0], tok[1]);
    }
done:
    for (int k = 0; k < m; k++) g_free(tok[k]);
    return spec;
}

static char *
position_canonical(const char *text)
{
    return position_canonical_ex(text, FALSE, FALSE);
}

static int
gradient_position_parse(char **tok, int n, ns_gradient_parse *gp)
{
    int m = 0;
    while (m < n && m < 4 && !token_eq(tok[m], "in")) m++;
    if (m == 0) return 0;
    GString *joined = g_string_new(NULL);
    for (int k = 0; k < m; k++) {
        if (k) g_string_append_c(joined, ' ');
        g_string_append(joined, tok[k]);
    }
    char *spec = position_canonical(joined->str);
    g_string_free(joined, TRUE);
    if (!spec) return 0;
    char *xs = NULL, *ys = NULL;
    position_split(spec, &xs, &ys);
    double px = 0, pct = 0;
    if (resolve_to_px_pct(xs, strlen(xs), &px, &pct)) {
        gp->gr.center_x = pct / 100.0;
        gp->gr.center_x_px = px;
    }
    if (resolve_to_px_pct(ys, strlen(ys), &px, &pct)) {
        gp->gr.center_y = pct / 100.0;
        gp->gr.center_y_px = px;
    }
    g_free(xs);
    g_free(ys);
    gp->gr.has_center = !(gp->gr.center_x == 0.5 && gp->gr.center_x_px == 0 &&
                          gp->gr.center_y == 0.5 && gp->gr.center_y_px == 0);
    g_free(gp->position_text);
    gp->position_text = spec;
    return m;
}

static gboolean
gradient_parse_prelude(ns_gradient_parse *gp, char **tok, int n)
{
    ns_css_gradient *gr = &gp->gr;
    gboolean seen_dir = FALSE, seen_shape = FALSE, seen_size = FALSE;
    gboolean seen_at = FALSE, seen_in = FALSE, seen_from = FALSE;
    int explicit_lengths = 0;
    int i = 0;
    while (i < n) {
        const char *t = tok[i];
        if (token_eq(t, "in")) {
            if (seen_in) return FALSE;
            int used = gradient_interp_parse(tok + i + 1, n - i - 1, gr->interp);
            if (!used) return FALSE;
            seen_in = TRUE;
            gp->interp_explicit = TRUE;
            i += 1 + used;
            continue;
        }
        if (!gr->radial && !gr->conic) {
            if (token_eq(t, "to")) {
                if (seen_dir) return FALSE;
                int sides = 0;
                for (int k = i + 1; k < n && k <= i + 2; k++) {
                    int bit = 0;
                    if (token_eq(tok[k], "top")) bit = NS_CSS_GRADIENT_TO_TOP;
                    else if (token_eq(tok[k], "bottom")) bit = NS_CSS_GRADIENT_TO_BOTTOM;
                    else if (token_eq(tok[k], "left")) bit = NS_CSS_GRADIENT_TO_LEFT;
                    else if (token_eq(tok[k], "right")) bit = NS_CSS_GRADIENT_TO_RIGHT;
                    if (!bit) break;
                    if (gr->to_side & bit) return FALSE;
                    gr->to_side |= bit;
                    sides++;
                }
                if (!sides) return FALSE;
                if ((gr->to_side & (NS_CSS_GRADIENT_TO_TOP | NS_CSS_GRADIENT_TO_BOTTOM)) ==
                    (NS_CSS_GRADIENT_TO_TOP | NS_CSS_GRADIENT_TO_BOTTOM))
                    return FALSE;
                if ((gr->to_side & (NS_CSS_GRADIENT_TO_LEFT | NS_CSS_GRADIENT_TO_RIGHT)) ==
                    (NS_CSS_GRADIENT_TO_LEFT | NS_CSS_GRADIENT_TO_RIGHT))
                    return FALSE;
                seen_dir = TRUE;
                i += 1 + sides;
                continue;
            }
            if (token_is_angle(t)) {
                if (seen_dir) return FALSE;
                gr->has_angle = TRUE;
                gr->angle_deg = parse_angle_deg(t);
                g_free(gp->angle_text);
                gp->angle_text = g_ascii_strdown(t, -1);
                seen_dir = TRUE;
                i++;
                continue;
            }
            return FALSE;
        }
        if (token_eq(t, "at")) {
            if (seen_at) return FALSE;
            int used = gradient_position_parse(tok + i + 1, n - i - 1, gp);
            if (!used) return FALSE;
            seen_at = TRUE;
            i += 1 + used;
            continue;
        }
        if (gr->conic) {
            if (token_eq(t, "from")) {
                if (seen_from || i + 1 >= n || !token_is_angle(tok[i + 1]) ||
                    strchr(tok[i + 1], '%') ||
                    math_text_mixes_angle_and_length(tok[i + 1]))
                    return FALSE;
                gr->has_from = TRUE;
                gr->from_deg = parse_angle_deg(tok[i + 1]);
                g_free(gp->angle_text);
                gp->angle_text = g_ascii_strdown(tok[i + 1], -1);
                seen_from = TRUE;
                i += 2;
                continue;
            }
            return FALSE;
        }
        if (token_eq(t, "circle") || token_eq(t, "ellipse")) {
            if (seen_shape) return FALSE;
            gr->circle = token_eq(t, "circle");
            seen_shape = TRUE;
            i++;
            continue;
        }
        static const struct { const char *kw; ns_css_gradient_size size; } sizes[] = {
            { "closest-side", NS_CSS_GRADIENT_CLOSEST_SIDE },
            { "farthest-side", NS_CSS_GRADIENT_FARTHEST_SIDE },
            { "closest-corner", NS_CSS_GRADIENT_CLOSEST_CORNER },
            { "farthest-corner", NS_CSS_GRADIENT_FARTHEST_CORNER },
        };
        gboolean size_kw = FALSE;
        for (gsize k = 0; k < G_N_ELEMENTS(sizes); k++) {
            if (!token_eq(t, sizes[k].kw)) continue;
            if (seen_size) return FALSE;
            gr->size = sizes[k].size;
            seen_size = TRUE;
            size_kw = TRUE;
        }
        if (size_kw) { i++; continue; }
        if (token_is_length_pct(t)) {
            if (seen_size) return FALSE;
            int j = 0;
            double px[2] = { 0, 0 }, pct[2] = { 0, 0 };
            while (i + j < n && j < 2 && token_is_length_pct(tok[i + j])) {
                resolve_to_px_pct(tok[i + j], strlen(tok[i + j]), &px[j], &pct[j]);
                if (px[j] < 0 || pct[j] < 0) return FALSE;
                j++;
            }
            if (i + j < n && token_is_length_pct(tok[i + j])) return FALSE;
            gr->size = NS_CSS_GRADIENT_EXPLICIT_SIZE;
            gr->size_x = px[0];
            gr->size_x_pct = pct[0];
            gr->size_y = j == 2 ? px[1] : px[0];
            gr->size_y_pct = j == 2 ? pct[1] : pct[0];
            explicit_lengths = j;
            if (j == 1 && strchr(tok[i], '%')) return FALSE;
            g_free(gp->size_text);
            gp->size_text = j == 2 ? g_strdup_printf("%s %s", tok[i], tok[i + 1])
                                   : g_strdup(tok[i]);
            seen_size = TRUE;
            i += j;
            continue;
        }
        return FALSE;
    }
    if (explicit_lengths) {
        if (seen_shape && gr->circle != (explicit_lengths == 1)) return FALSE;
        gr->circle = explicit_lengths == 1;
    }
    return TRUE;
}

static gboolean
math_text_has_unit(const char *t, const char *const *units, gsize n_units)
{
    char *lower = g_ascii_strdown(t, -1);
    gboolean found = FALSE;
    for (const char *p = lower; *p && !found; p++) {
        if (!g_ascii_isdigit((guchar)*p) && *p != '.') continue;
        while (g_ascii_isdigit((guchar)*p) || *p == '.') p++;
        for (gsize k = 0; k < n_units && !found; k++) {
            gsize len = strlen(units[k]);
            if (g_ascii_strncasecmp(p, units[k], len) == 0 &&
                !g_ascii_isalpha((guchar)p[len]))
                found = TRUE;
        }
        if (!*p) break;
    }
    g_free(lower);
    return found;
}

static gboolean
math_text_mixes_angle_and_length(const char *t)
{
    static const char *const angles[] = { "deg", "grad", "rad", "turn" };
    static const char *const lengths[] = { "px", "em", "rem", "vw", "vh",
                                           "vmin", "vmax", "ch", "ex", "cm",
                                           "mm", "in", "pt", "pc", "lh" };
    return math_text_has_unit(t, angles, G_N_ELEMENTS(angles)) &&
           math_text_has_unit(t, lengths, G_N_ELEMENTS(lengths));
}

static char *
conic_calc_canonical(const char *t)
{
    if (g_ascii_strncasecmp(t, "calc(", 5) != 0) return g_strdup(t);
    gsize len = strlen(t);
    if (len < 7 || t[len - 1] != ')') return g_strdup(t);
    char *inner = g_strndup(t + 5, len - 6);
    char *plus = strstr(inner, " + ");
    char *out = NULL;
    if (plus && !strchr(inner, '(')) {
        *plus = '\0';
        char *a = g_strstrip(inner), *b = g_strstrip(plus + 3);
        gboolean a_angle = !strchr(a, '%'), b_pct = strchr(b, '%') != NULL;
        if (a_angle && b_pct) out = g_strdup_printf("calc(%s + %s)", b, a);
    }
    g_free(inner);
    return out ? out : g_strdup(t);
}

static gboolean
gradient_stop_pos_parse(const char *t, gboolean conic, ns_css_gradient_stop *st)
{
    st->pos = 0;
    st->pos_px = 0;
    st->pos_is_angle = FALSE;
    if (token_is_math_fn(t)) {
        static const char *const angles[] = { "deg", "grad", "rad", "turn" };
        static const char *const lengths[] = { "px", "em", "rem", "vw", "vh",
                                               "vmin", "vmax", "ch", "ex",
                                               "cm", "mm", "in", "pt", "pc",
                                               "lh" };
        gboolean has_angle = math_text_has_unit(t, angles, G_N_ELEMENTS(angles));
        gboolean has_len = math_text_has_unit(t, lengths, G_N_ELEMENTS(lengths));
        if (conic ? has_len : has_angle) return FALSE;
        if (conic && !has_angle && !strchr(t, '%')) return FALSE;
    }
    if (conic) {
        if (token_is_angle(t)) {
            st->pos = parse_angle_deg(t) / 360.0;
            st->pos_is_angle = TRUE;
            st->has_pos = TRUE;
            return TRUE;
        }
        if (token_is_math_fn(t)) {
            double px = 0, pct = 0;
            if (!resolve_to_px_pct(t, strlen(t), &px, &pct)) return FALSE;
            st->pos = pct / 100.0;
            st->has_pos = TRUE;
            return TRUE;
        }
        double v; ns_css_unit u;
        if (parse_length(t, &v, &u) && u == NS_CSS_UNIT_PERCENT) {
            st->pos = v / 100.0;
            st->has_pos = TRUE;
            return TRUE;
        }
        return FALSE;
    }
    if (!token_is_length_pct(t)) return FALSE;
    double px = 0, pct = 0;
    resolve_to_px_pct(t, strlen(t), &px, &pct);
    st->pos = pct / 100.0;
    st->pos_px = px;
    st->has_pos = TRUE;
    return TRUE;
}

static gboolean
gradient_stop_parse(ns_gradient_parse *gp, const char *seg, gboolean *is_hint)
{
    char *tok[8] = {0};
    int n = split_ws_paren(seg, tok, 8);
    gboolean ok = FALSE;
    gboolean conic = gp->gr.conic;
    ns_css_gradient *gr = &gp->gr;
    *is_hint = FALSE;
    if (n < 1) goto done;
    guint8 r, g, b, a;
    if (parse_color(tok[0], &r, &g, &b, &a)) {
        if (n > 3) goto done;
        ns_css_gradient_stop first = { .r = r, .g = g, .b = b, .a = a };
        ns_css_gradient_stop second = first;
        if (n >= 2 && !gradient_stop_pos_parse(tok[1], conic, &first)) goto done;
        if (n == 3 && !gradient_stop_pos_parse(tok[2], conic, &second)) goto done;
        if (!color_text_is_legacy(tok[0])) gp->all_legacy = FALSE;
        if (gr->n_stops < NS_CSS_GRADIENT_STOPS_MAX) {
            gr->stops[gr->n_stops++] = first;
            if (gp->stop_colors) g_ptr_array_add(gp->stop_colors, g_strdup(tok[0]));
        }
        if (n == 3 && gr->n_stops < NS_CSS_GRADIENT_STOPS_MAX) {
            second.pair_with_prev = TRUE;
            gr->stops[gr->n_stops++] = second;
            if (gp->stop_colors) g_ptr_array_add(gp->stop_colors, NULL);
        }
        if (gp->stop_texts) {
            GString *s = g_string_new(NULL);
            char *color_text = gradient_stop_color_specified(tok[0]);
            g_string_append(s, color_text);
            g_free(color_text);
            for (int k = 1; k < n; k++) {
                g_string_append_c(s, ' ');
                char *pos_text = conic ? conic_calc_canonical(tok[k]) : g_strdup(tok[k]);
                g_string_append(s, pos_text);
                g_free(pos_text);
            }
            g_ptr_array_add(gp->stop_texts, g_string_free(s, FALSE));
        }
        ok = TRUE;
        goto done;
    }
    if (n != 1) goto done;
    ns_css_gradient_stop hint = { .is_hint = TRUE };
    if (!gradient_stop_pos_parse(tok[0], conic, &hint)) goto done;
    if (gr->n_stops < NS_CSS_GRADIENT_STOPS_MAX) {
        gr->stops[gr->n_stops++] = hint;
        if (gp->stop_colors) g_ptr_array_add(gp->stop_colors, NULL);
    }
    if (gp->stop_texts)
        g_ptr_array_add(gp->stop_texts,
                        conic ? conic_calc_canonical(tok[0]) : g_strdup(tok[0]));
    *is_hint = TRUE;
    ok = TRUE;
done:
    for (int k = 0; k < n; k++) g_free(tok[k]);
    return ok;
}

static void
gradient_hint_color(ns_css_gradient_stop *hint, const ns_css_gradient_stop *prev,
                    const ns_css_gradient_stop *next)
{
    double a = (prev->a + next->a) / 2.0;
    double p[3] = { prev->r, prev->g, prev->b };
    double n[3] = { next->r, next->g, next->b };
    guint8 *out[3] = { &hint->r, &hint->g, &hint->b };
    for (int k = 0; k < 3; k++) {
        double pm = (p[k] * prev->a + n[k] * next->a) / 2.0;
        *out[k] = (guint8)(a > 0 ? pm / a + 0.5 : (p[k] + n[k]) / 2.0);
    }
    hint->a = (guint8)(a + 0.5);
}

static void
gradient_finish_stops(ns_css_gradient *gr)
{
    int n = MIN(gr->n_stops, NS_CSS_GRADIENT_STOPS_MAX);
    if (n == 0) return;
    ns_css_gradient_stop *st = gr->stops;
    gboolean fixed[NS_CSS_GRADIENT_STOPS_MAX] = { FALSE };
    for (int i = 0; i < n; i++) fixed[i] = st[i].has_pos;
    if (!fixed[0]) { st[0].pos = 0; st[0].pos_px = 0; fixed[0] = TRUE; }
    if (!fixed[n - 1]) { st[n - 1].pos = 1; st[n - 1].pos_px = 0; fixed[n - 1] = TRUE; }
    for (int i = 1; i < n; i++)
        if (fixed[i] && fixed[i - 1] && st[i].pos_px == 0 &&
            st[i - 1].pos_px == 0 && st[i].pos < st[i - 1].pos)
            st[i].pos = st[i - 1].pos;
    for (int i = 0; i < n; ) {
        if (fixed[i]) { i++; continue; }
        int j = i;
        while (j < n && !fixed[j]) j++;
        double lo = st[i - 1].pos, hi = st[j].pos;
        for (int k = i; k < j; k++) {
            st[k].pos = lo + (hi - lo) * (double)(k - i + 1) / (double)(j - i + 1);
            st[k].pos_px = 0;
        }
        i = j;
    }
    for (int i = 1; i + 1 < n; i++)
        if (st[i].is_hint) gradient_hint_color(&st[i], &st[i - 1], &st[i + 1]);
}

static const char *
gradient_skip_vendor_prefix(const char *p, gboolean *legacy)
{
    if (g_ascii_strncasecmp(p, "-webkit-", 8) != 0) return p;
    if (legacy) *legacy = TRUE;
    return p + 8;
}

static const char *
legacy_side_opposite(const char *t)
{
    if (token_eq(t, "left")) return "right";
    if (token_eq(t, "right")) return "left";
    if (token_eq(t, "top")) return "bottom";
    if (token_eq(t, "bottom")) return "top";
    return NULL;
}

static gboolean
legacy_position_token(const char *t)
{
    return legacy_side_opposite(t) || token_eq(t, "center") ||
           g_ascii_isdigit(t[0]) || t[0] == '.' || t[0] == '-' || t[0] == '+';
}

static const char *
legacy_radial_shape_token(const char *t)
{
    if (token_eq(t, "cover")) return "farthest-corner";
    if (token_eq(t, "contain")) return "closest-side";
    static const char *const kept[] = {
        "circle", "ellipse", "closest-side", "closest-corner",
        "farthest-side", "farthest-corner",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(kept); i++)
        if (token_eq(t, kept[i])) return kept[i];
    return NULL;
}

static char *
legacy_linear_prelude(char **tok, int n)
{
    if (n == 1 && token_is_angle(tok[0])) {
        char deg[G_ASCII_DTOSTR_BUF_SIZE];
        g_ascii_formatd(deg, sizeof deg, "%g", 90.0 - parse_angle_deg(tok[0]));
        return g_strconcat(deg, "deg", NULL);
    }
    if (n < 1 || n > 2) return NULL;
    GString *out = g_string_new("to");
    for (int k = 0; k < n; k++) {
        const char *opposite = legacy_side_opposite(tok[k]);
        if (!opposite) return g_string_free(out, TRUE);
        g_string_append_printf(out, " %s", opposite);
    }
    return g_string_free(out, FALSE);
}

static char *
legacy_radial_shape(const char *part)
{
    char *tok[4] = {0};
    int n = split_ws_paren(part, tok, 4);
    GString *out = g_string_new(NULL);
    gboolean ok = n > 0;
    for (int k = 0; k < n && ok; k++) {
        const char *word = legacy_radial_shape_token(tok[k]);
        if (!word) ok = FALSE;
        else g_string_append_printf(out, "%s%s", out->len ? " " : "", word);
    }
    for (int k = 0; k < n; k++) g_free(tok[k]);
    return g_string_free(out, !ok);
}

static void
gradient_legacy_prelude(GPtrArray *parts, gboolean radial)
{
    if (parts->len == 0) return;
    char *tok[4] = {0};
    int n = split_ws_paren(parts->pdata[0], tok, 4);
    char *prelude = NULL;
    if (!radial) {
        prelude = legacy_linear_prelude(tok, n);
    } else {
        gboolean position = n > 0 && n <= 2;
        for (int k = 0; k < n && position; k++)
            position = legacy_position_token(tok[k]);
        char *shape = parts->len > 1 ? legacy_radial_shape(parts->pdata[1]) : NULL;
        if (position) {
            prelude = shape ? g_strdup_printf("%s at %s", shape,
                                              (char *)parts->pdata[0])
                            : g_strconcat("at ", parts->pdata[0], NULL);
            if (shape) g_ptr_array_remove_index(parts, 1);
        } else {
            prelude = legacy_radial_shape(parts->pdata[0]);
        }
        g_free(shape);
    }
    for (int k = 0; k < n; k++) g_free(tok[k]);
    if (!prelude) return;
    g_free(parts->pdata[0]);
    parts->pdata[0] = prelude;
}

static gboolean
gradient_parse(const char *text, ns_gradient_parse *gp, const char **out_end,
               gboolean keep_texts)
{
    memset(gp, 0, sizeof *gp);
    const char *p = text;
    while (*p && is_ws(*p)) p++;
    gboolean legacy = FALSE;
    p = gradient_skip_vendor_prefix(p, &legacy);
    if (g_ascii_strncasecmp(p, "repeating-", 10) == 0) {
        gp->gr.repeating = TRUE;
        p += 10;
    }
    if (g_ascii_strncasecmp(p, "linear-gradient", 15) == 0) p += 15;
    else if (g_ascii_strncasecmp(p, "radial-gradient", 15) == 0) { gp->gr.radial = TRUE; p += 15; }
    else if (g_ascii_strncasecmp(p, "conic-gradient", 14) == 0) { gp->gr.conic = TRUE; p += 14; }
    else return FALSE;
    while (*p && is_ws(*p)) p++;
    if (*p != '(') return FALSE;
    p++;
    const char *body_start = p;
    int depth = 0;
    const char *end = NULL;
    for (const char *q = p; *q; q++) {
        if (*q == '(') depth++;
        else if (*q == ')') {
            if (depth == 0) { end = q; break; }
            depth--;
        }
    }
    if (!end) return FALSE;
    if (out_end) *out_end = end + 1;
    gp->gr.center_x = 0.5;
    gp->gr.center_y = 0.5;
    gp->all_legacy = TRUE;
    if (keep_texts) {
        gp->stop_texts = g_ptr_array_new_with_free_func(g_free);
        gp->stop_colors = g_ptr_array_new_with_free_func(g_free);
    }

    GPtrArray *parts = g_ptr_array_new_with_free_func(g_free);
    const char *seg = body_start;
    depth = 0;
    for (const char *q = body_start; ; q++) {
        if (*q == '(') depth++;
        else if (*q == ')' && depth > 0) depth--;
        if ((*q == ',' && depth == 0) || q == end) {
            char *piece = g_strndup(seg, (gsize)(q - seg));
            g_strstrip(piece);
            g_ptr_array_add(parts, piece);
            if (q == end) break;
            seg = q + 1;
        }
    }
    gboolean ok = TRUE;
    for (guint i = 0; i < parts->len && ok; i++)
        if (!*(char *)parts->pdata[i]) ok = FALSE;
    if (ok && legacy && !gp->gr.conic) gradient_legacy_prelude(parts, gp->gr.radial);
    guint start = 0;
    if (ok && parts->len > 0) {
        char *tok[24] = {0};
        int n = split_ws_paren(parts->pdata[0], tok, 24);
        ns_css_gradient saved = gp->gr;
        gboolean saved_explicit = gp->interp_explicit;
        if (n > 0 && gradient_parse_prelude(gp, tok, n)) {
            start = 1;
        } else {
            gp->gr = saved;
            gp->interp_explicit = saved_explicit;
            g_free(gp->angle_text); gp->angle_text = NULL;
            g_free(gp->size_text); gp->size_text = NULL;
            g_free(gp->position_text); gp->position_text = NULL;
        }
        for (int k = 0; k < n; k++) g_free(tok[k]);
    }
    if (ok && start >= parts->len) ok = FALSE;
    gboolean prev_hint = TRUE;
    int color_stops = 0;
    for (guint i = start; i < parts->len && ok; i++) {
        gboolean hint = FALSE;
        if (!gradient_stop_parse(gp, parts->pdata[i], &hint)) { ok = FALSE; break; }
        if (hint && prev_hint) { ok = FALSE; break; }
        if (!hint) color_stops++;
        prev_hint = hint;
    }
    if (ok && (prev_hint || color_stops < 1)) ok = FALSE;
    g_ptr_array_free(parts, TRUE);
    if (!ok) {
        gradient_parse_clear(gp);
        return FALSE;
    }
    if (gp->interp_explicit) {
        const char *def = gp->all_legacy ? "srgb" : "oklab";
        if (strcmp(gp->gr.interp, def) == 0) gp->gr.interp[0] = '\0';
    }
    gradient_finish_stops(&gp->gr);
    return TRUE;
}

static void
gradient_append_stop_pos(GString *s, const ns_css_gradient_stop *st)
{
    if (st->pos_is_angle) {
        g_string_append_printf(s, "%gdeg", st->pos * 360.0);
    } else if (st->pos_px == 0) {
        g_string_append_printf(s, "%g%%", st->pos * 100.0);
    } else if (st->pos == 0) {
        g_string_append_printf(s, "%gpx", st->pos_px);
    } else {
        g_string_append_printf(s, "calc(%g%% %c %gpx)", st->pos * 100.0,
                               st->pos_px < 0 ? '-' : '+', fabs(st->pos_px));
    }
}

static void
gradient_append_center_coord(GString *s, double frac, double px)
{
    if (px == 0) g_string_append_printf(s, "%g%%", frac * 100.0);
    else if (frac == 0) g_string_append_printf(s, "%gpx", px);
    else g_string_append_printf(s, "calc(%g%% %c %gpx)", frac * 100.0,
                                px < 0 ? '-' : '+', fabs(px));
}

static void
gradient_append_to_side(GString *s, int to_side)
{
    g_string_append(s, "to");
    if (to_side & NS_CSS_GRADIENT_TO_LEFT) g_string_append(s, " left");
    if (to_side & NS_CSS_GRADIENT_TO_RIGHT) g_string_append(s, " right");
    if (to_side & NS_CSS_GRADIENT_TO_TOP) g_string_append(s, " top");
    if (to_side & NS_CSS_GRADIENT_TO_BOTTOM) g_string_append(s, " bottom");
}

static void
gradient_append_name(GString *s, const ns_css_gradient *gr)
{
    if (gr->repeating) g_string_append(s, "repeating-");
    g_string_append(s, gr->conic ? "conic-gradient(" :
                       gr->radial ? "radial-gradient(" : "linear-gradient(");
}

static void
gradient_append_prelude_part(GString *prelude, const char *part)
{
    if (prelude->len) g_string_append_c(prelude, ' ');
    g_string_append(prelude, part);
}

static void
gradient_serialize_computed(GString *s, const ns_css_gradient *gr,
                            const GPtrArray *stop_colors)
{
    gradient_append_name(s, gr);
    GString *pre = g_string_new(NULL);
    if (gr->conic) {
        if (gr->has_from) {
            char *t = g_strdup_printf("from %gdeg", gr->from_deg);
            gradient_append_prelude_part(pre, t);
            g_free(t);
        }
    } else if (gr->radial) {
        if (gr->size == NS_CSS_GRADIENT_EXPLICIT_SIZE) {
            GString *sz = g_string_new(NULL);
            gradient_append_center_coord(sz, gr->size_x_pct / 100.0, gr->size_x);
            if (!gr->circle) {
                g_string_append_c(sz, ' ');
                gradient_append_center_coord(sz, gr->size_y_pct / 100.0, gr->size_y);
            }
            gradient_append_prelude_part(pre, sz->str);
            g_string_free(sz, TRUE);
        } else {
            if (gr->circle) gradient_append_prelude_part(pre, "circle");
            static const char *kws[] = { NULL, "closest-side", "farthest-side",
                                         "closest-corner", NULL };
            if (kws[gr->size]) gradient_append_prelude_part(pre, kws[gr->size]);
        }
    } else {
        if (gr->has_angle) {
            char *t = g_strdup_printf("%gdeg", gr->angle_deg);
            gradient_append_prelude_part(pre, t);
            g_free(t);
        } else if (gr->to_side && gr->to_side != NS_CSS_GRADIENT_TO_BOTTOM) {
            GString *t = g_string_new(NULL);
            gradient_append_to_side(t, gr->to_side);
            gradient_append_prelude_part(pre, t->str);
            g_string_free(t, TRUE);
        }
    }
    if ((gr->radial || gr->conic) && gr->has_center) {
        GString *at = g_string_new("at ");
        gradient_append_center_coord(at, gr->center_x, gr->center_x_px);
        g_string_append_c(at, ' ');
        gradient_append_center_coord(at, gr->center_y, gr->center_y_px);
        gradient_append_prelude_part(pre, at->str);
        g_string_free(at, TRUE);
    }
    if (gr->interp[0]) {
        char *t = g_strdup_printf("in %s", gr->interp);
        gradient_append_prelude_part(pre, t);
        g_free(t);
    }
    if (pre->len) {
        g_string_append(s, pre->str);
        g_string_append(s, ", ");
    }
    g_string_free(pre, TRUE);
    for (int i = 0; i < gr->n_stops; i++) {
        const ns_css_gradient_stop *st = &gr->stops[i];
        if (st->pair_with_prev) {
            g_string_append_c(s, ' ');
            gradient_append_stop_pos(s, st);
            continue;
        }
        if (i > 0) g_string_append(s, ", ");
        if (st->is_hint) {
            gradient_append_stop_pos(s, st);
            continue;
        }
        const char *color_text = stop_colors && (guint)i < stop_colors->len
            ? g_ptr_array_index(stop_colors, i) : NULL;
        char *computed = color_text ? ns_css_color_computed(color_text, NULL) : NULL;
        if (computed) g_string_append(s, computed);
        else ns_css_append_color(s, st->r, st->g, st->b, st->a);
        g_free(computed);
        if (st->has_pos) {
            g_string_append_c(s, ' ');
            gradient_append_stop_pos(s, st);
        }
    }
    g_string_append_c(s, ')');
}

static char *
gradient_serialize_specified(const ns_gradient_parse *gp)
{
    const ns_css_gradient *gr = &gp->gr;
    GString *s = g_string_new(NULL);
    gradient_append_name(s, gr);
    GString *pre = g_string_new(NULL);
    if (gr->conic) {
        if (gr->has_from) {
            char *t = g_strdup_printf("from %s", gp->angle_text);
            gradient_append_prelude_part(pre, t);
            g_free(t);
        }
    } else if (gr->radial) {
        if (gr->size == NS_CSS_GRADIENT_EXPLICIT_SIZE) {
            gradient_append_prelude_part(pre, gp->size_text);
        } else {
            if (gr->circle) gradient_append_prelude_part(pre, "circle");
            static const char *kws[] = { NULL, "closest-side", "farthest-side",
                                         "closest-corner", NULL };
            if (kws[gr->size]) gradient_append_prelude_part(pre, kws[gr->size]);
        }
    } else {
        if (gr->has_angle) {
            gradient_append_prelude_part(pre, gp->angle_text);
        } else if (gr->to_side && gr->to_side != NS_CSS_GRADIENT_TO_BOTTOM) {
            GString *t = g_string_new(NULL);
            gradient_append_to_side(t, gr->to_side);
            gradient_append_prelude_part(pre, t->str);
            g_string_free(t, TRUE);
        }
    }
    if ((gr->radial || gr->conic) && gp->position_text &&
        g_ascii_strcasecmp(gp->position_text, "center") != 0 &&
        g_ascii_strcasecmp(gp->position_text, "center center") != 0) {
        char *t = g_strdup_printf("at %s", gp->position_text);
        gradient_append_prelude_part(pre, t);
        g_free(t);
    }
    if (gr->interp[0]) {
        char *t = g_strdup_printf("in %s", gr->interp);
        gradient_append_prelude_part(pre, t);
        g_free(t);
    }
    if (pre->len) {
        g_string_append(s, pre->str);
        g_string_append(s, ", ");
    }
    g_string_free(pre, TRUE);
    for (guint i = 0; gp->stop_texts && i < gp->stop_texts->len; i++) {
        if (i > 0) g_string_append(s, ", ");
        g_string_append(s, gp->stop_texts->pdata[i]);
    }
    g_string_append_c(s, ')');
    return g_string_free(s, FALSE);
}

static gboolean
text_starts_gradient(const char *p)
{
    while (*p && is_ws(*p)) p++;
    p = gradient_skip_vendor_prefix(p, NULL);
    if (g_ascii_strncasecmp(p, "repeating-", 10) == 0) p += 10;
    return g_ascii_strncasecmp(p, "linear-gradient", 15) == 0 ||
           g_ascii_strncasecmp(p, "radial-gradient", 15) == 0 ||
           g_ascii_strncasecmp(p, "conic-gradient", 14) == 0;
}

static char *image_set_canonical(const char *text, gboolean computed);
static gboolean text_starts_image_set(const char *p);
static const char *cq_match_paren(const char *p, const char *end);

char *
ns_css_image_value_canonical(const char *text)
{
    if (!text) return NULL;
    GString *out = g_string_new(NULL);
    const char *p = text;
    const char *end = text + strlen(text);
    gboolean first = TRUE;
    while (p < end) {
        char term = 0;
        const char *seg_end = css_scan_until(p, end, ",", &term);
        char *layer = css_trim_dup_range(p, seg_end);
        char *canon = NULL;
        if (text_starts_gradient(layer)) {
            ns_gradient_parse gp;
            const char *gend = NULL;
            if (gradient_parse(layer, &gp, &gend, TRUE)) {
                while (gend && *gend && is_ws(*gend)) gend++;
                if (!gend || !*gend) canon = gradient_serialize_specified(&gp);
                gradient_parse_clear(&gp);
            }
            if (!canon) {
                g_free(layer);
                g_string_free(out, TRUE);
                return NULL;
            }
        } else if (text_starts_image_set(layer)) {
            canon = image_set_canonical(layer, FALSE);
            if (!canon) {
                g_free(layer);
                g_string_free(out, TRUE);
                return NULL;
            }
        }
        if (!first) g_string_append(out, ", ");
        first = FALSE;
        g_string_append(out, canon ? canon : layer);
        g_free(canon);
        g_free(layer);
        p = term == ',' ? seg_end + 1 : seg_end;
    }
    return g_string_free(out, FALSE);
}

double
ns_css_gradient_angle(const ns_css_gradient *gr, double w, double h)
{
    if (gr->has_angle) return gr->angle_deg;
    int side = gr->to_side ? gr->to_side : NS_CSS_GRADIENT_TO_BOTTOM;
    gboolean horiz = side & (NS_CSS_GRADIENT_TO_LEFT | NS_CSS_GRADIENT_TO_RIGHT);
    gboolean vert = side & (NS_CSS_GRADIENT_TO_TOP | NS_CSS_GRADIENT_TO_BOTTOM);
    if (!horiz) return side & NS_CSS_GRADIENT_TO_TOP ? 0 : 180;
    if (!vert) return side & NS_CSS_GRADIENT_TO_LEFT ? 270 : 90;
    double corner = w > 0 && h > 0 ? atan2(w, h) * 180.0 / G_PI : 45.0;
    gboolean right = side & NS_CSS_GRADIENT_TO_RIGHT;
    gboolean top = side & NS_CSS_GRADIENT_TO_TOP;
    if (right && top) return corner;
    if (right) return 180.0 - corner;
    if (top) return 360.0 - corner;
    return 180.0 + corner;
}

void
ns_css_gradient_radii(const ns_css_gradient *gr, double w, double h,
                      double cx, double cy, double *rx, double *ry)
{
    double dl = fabs(cx), dr = fabs(w - cx), dt = fabs(cy), db = fabs(h - cy);
    switch (gr->size) {
    case NS_CSS_GRADIENT_EXPLICIT_SIZE:
        *rx = gr->size_x + gr->size_x_pct / 100.0 * w;
        *ry = gr->circle ? *rx : gr->size_y + gr->size_y_pct / 100.0 * h;
        break;
    case NS_CSS_GRADIENT_CLOSEST_SIDE:
        *rx = MIN(dl, dr);
        *ry = MIN(dt, db);
        if (gr->circle) *rx = *ry = MIN(*rx, *ry);
        break;
    case NS_CSS_GRADIENT_FARTHEST_SIDE:
        *rx = MAX(dl, dr);
        *ry = MAX(dt, db);
        if (gr->circle) *rx = *ry = MAX(*rx, *ry);
        break;
    case NS_CSS_GRADIENT_CLOSEST_CORNER:
        if (gr->circle) {
            *rx = *ry = sqrt(MIN(dl, dr) * MIN(dl, dr) + MIN(dt, db) * MIN(dt, db));
        } else {
            *rx = MIN(dl, dr) * G_SQRT2;
            *ry = MIN(dt, db) * G_SQRT2;
        }
        break;
    case NS_CSS_GRADIENT_FARTHEST_CORNER:
    default:
        if (gr->circle) {
            *rx = *ry = sqrt(MAX(dl, dr) * MAX(dl, dr) + MAX(dt, db) * MAX(dt, db));
        } else {
            *rx = MAX(dl, dr) * G_SQRT2;
            *ry = MAX(dt, db) * G_SQRT2;
        }
        break;
    }
    if (*rx <= 0) *rx = 1;
    if (*ry <= 0) *ry = 1;
}

typedef enum {
    CONTENT_TOK_STRING,
    CONTENT_TOK_IDENT,
    CONTENT_TOK_FUNC,
    CONTENT_TOK_SLASH,
} content_tok_kind;

typedef struct {
    content_tok_kind kind;
    char *text;
    char *args;
} content_tok;

static void
content_tok_clear(gpointer data)
{
    content_tok *t = data;
    g_free(t->text);
    g_free(t->args);
}

static char *
content_string_canonical(const char *raw, gsize len)
{
    GString *decoded = g_string_new(NULL);
    char *inner = g_strndup(raw, len);
    for (const char *p = inner; *p; )
        ns_css_append_unescaped(decoded, &p);
    g_free(inner);
    GString *out = g_string_new("\"");
    for (const char *p = decoded->str; *p; p++) {
        if (*p == '"' || *p == '\\') g_string_append_c(out, '\\');
        g_string_append_c(out, *p);
    }
    g_string_append_c(out, '"');
    g_string_free(decoded, TRUE);
    return g_string_free(out, FALSE);
}

static const char *
content_scan_string_end(const char *p)
{
    char q = *p++;
    while (*p) {
        if (*p == '\\' && p[1]) { p += 2; continue; }
        if (*p == q) return p;
        p++;
    }
    return NULL;
}

static GArray *
content_tokenize(const char *text)
{
    GArray *toks = g_array_new(FALSE, TRUE, sizeof(content_tok));
    g_array_set_clear_func(toks, content_tok_clear);
    const char *p = text;
    while (*p) {
        if (is_ws(*p)) { p++; continue; }
        content_tok t = { 0 };
        if (*p == '"' || *p == '\'') {
            const char *e = content_scan_string_end(p);
            if (!e) goto fail;
            t.kind = CONTENT_TOK_STRING;
            t.text = content_string_canonical(p + 1, (gsize)(e - p - 1));
            p = e + 1;
        } else if (*p == '/') {
            t.kind = CONTENT_TOK_SLASH;
            t.text = g_strdup("/");
            p++;
        } else if (g_ascii_isalpha((guchar)*p) || *p == '-' || *p == '_' ||
                   *p == '\\' || (guchar)*p >= 0x80) {
            const char *s = p;
            while (*p && (g_ascii_isalnum((guchar)*p) || *p == '-' ||
                          *p == '_' || (guchar)*p >= 0x80 || *p == '\\')) {
                if (*p == '\\' && p[1]) p += 2;
                else p++;
            }
            t.text = g_strndup(s, (gsize)(p - s));
            if (*p == '(') {
                int depth = 0;
                const char *a = p + 1;
                const char *q = p;
                for (; *q; q++) {
                    if (*q == '"' || *q == '\'') {
                        q = content_scan_string_end(q);
                        if (!q) break;
                        continue;
                    }
                    if (*q == '(') depth++;
                    else if (*q == ')' && --depth == 0) break;
                }
                if (!q || *q != ')') { g_free(t.text); goto fail; }
                t.kind = CONTENT_TOK_FUNC;
                t.args = g_strndup(a, (gsize)(q - a));
                g_strstrip(t.args);
                char *lower = g_ascii_strdown(t.text, -1);
                g_free(t.text);
                t.text = lower;
                p = q + 1;
            } else {
                t.kind = CONTENT_TOK_IDENT;
            }
        } else {
            goto fail;
        }
        g_array_append_val(toks, t);
    }
    return toks;
fail:
    g_array_free(toks, TRUE);
    return NULL;
}

static GPtrArray *
content_split_args(const char *args)
{
    GPtrArray *out = g_ptr_array_new_with_free_func(g_free);
    const char *seg = args;
    int depth = 0;
    for (const char *q = args; ; q++) {
        if (*q == '"' || *q == '\'') {
            const char *e = content_scan_string_end(q);
            if (!e) { g_ptr_array_free(out, TRUE); return NULL; }
            q = e;
            continue;
        }
        if (*q == '(') depth++;
        else if (*q == ')' && depth > 0) depth--;
        if ((*q == ',' && depth == 0) || !*q) {
            char *piece = g_strndup(seg, (gsize)(q - seg));
            g_strstrip(piece);
            g_ptr_array_add(out, piece);
            if (!*q) break;
            seg = q + 1;
        }
    }
    return out;
}

static gboolean css_wide_keyword_or_default(const char *item);
static gboolean attr_functions_syntax_valid(const char *text);

static gboolean
content_ident_valid(const char *s)
{
    if (!s || !*s) return FALSE;
    if (g_ascii_isdigit((guchar)s[0])) return FALSE;
    for (const char *p = s; *p; p++) {
        if (*p == '\\') { if (!p[1]) return FALSE; p++; continue; }
        if (!(g_ascii_isalnum((guchar)*p) || *p == '-' || *p == '_' ||
              (guchar)*p >= 0x80))
            return FALSE;
    }
    return TRUE;
}

static gboolean
content_is_string_token(const char *s)
{
    if (!s || (s[0] != '"' && s[0] != '\'')) return FALSE;
    const char *e = content_scan_string_end(s);
    return e && e[1] == '\0';
}

static char *
content_symbols_canonical(const char *args)
{
    GArray *toks = content_tokenize(args);
    if (!toks) return NULL;
    const char *system = NULL;
    guint i = 0;
    if (toks->len > 0) {
        content_tok *t = &g_array_index(toks, content_tok, 0);
        if (t->kind == CONTENT_TOK_IDENT) {
            static const char *systems[] = { "cyclic", "numeric", "alphabetic",
                                             "symbolic", "additive", "fixed" };
            for (gsize k = 0; k < G_N_ELEMENTS(systems); k++)
                if (g_ascii_strcasecmp(t->text, systems[k]) == 0)
                    system = systems[k];
            if (!system) { g_array_free(toks, TRUE); return NULL; }
            i = 1;
        }
    }
    GString *out = g_string_new(NULL);
    if (system && strcmp(system, "symbolic") != 0) g_string_append(out, system);
    int n_symbols = 0;
    for (; i < toks->len; i++) {
        content_tok *t = &g_array_index(toks, content_tok, i);
        gboolean image = t->kind == CONTENT_TOK_FUNC &&
                         (strcmp(t->text, "url") == 0 ||
                          strcmp(t->text, "image") == 0 ||
                          strstr(t->text, "gradient"));
        if (t->kind != CONTENT_TOK_STRING && !image) {
            g_string_free(out, TRUE);
            g_array_free(toks, TRUE);
            return NULL;
        }
        if (out->len) g_string_append_c(out, ' ');
        if (image) g_string_append_printf(out, "%s(%s)", t->text, t->args);
        else g_string_append(out, t->text);
        n_symbols++;
    }
    g_array_free(toks, TRUE);
    gboolean ok = n_symbols >= 1;
    if (system && (strcmp(system, "numeric") == 0 ||
                   strcmp(system, "alphabetic") == 0) && n_symbols < 2)
        ok = FALSE;
    if (system && strcmp(system, "additive") == 0) ok = FALSE;
    if (!ok) { g_string_free(out, TRUE); return NULL; }
    return g_string_free(out, FALSE);
}

static char *
content_counter_style_canonical(const char *style)
{
    if (g_ascii_strncasecmp(style, "symbols(", 8) == 0 &&
        style[strlen(style) - 1] == ')') {
        char *inner = g_strndup(style + 8, strlen(style) - 9);
        char *canon = content_symbols_canonical(inner);
        g_free(inner);
        if (!canon) return NULL;
        char *res = g_strdup_printf("symbols(%s)", canon);
        g_free(canon);
        return res;
    }
    if (!content_ident_valid(style) || css_wide_keyword_or_default(style) ||
        g_ascii_strcasecmp(style, "none") == 0) return NULL;
    if (g_ascii_strcasecmp(style, "decimal") == 0) return g_strdup("");
    return g_strdup(style);
}

static char *
content_counter_canonical(const content_tok *t)
{
    gboolean counters = strcmp(t->text, "counters") == 0;
    GPtrArray *args = content_split_args(t->args);
    if (!args) return NULL;
    guint min_args = counters ? 2 : 1, max_args = counters ? 3 : 2;
    char *res = NULL;
    if (args->len < min_args || args->len > max_args) goto done;
    const char *name = args->pdata[0];
    if (!content_ident_valid(name) || g_ascii_strcasecmp(name, "none") == 0)
        goto done;
    char *sep = NULL;
    if (counters) {
        const char *s = args->pdata[1];
        if (!content_is_string_token(s)) goto done;
        sep = content_string_canonical(s + 1, strlen(s) - 2);
    }
    char *style = NULL;
    if (args->len == max_args) {
        style = content_counter_style_canonical(args->pdata[max_args - 1]);
        if (!style) { g_free(sep); goto done; }
    }
    GString *out = g_string_new(t->text);
    g_string_append_c(out, '(');
    g_string_append(out, name);
    if (sep) { g_string_append(out, ", "); g_string_append(out, sep); }
    if (style && *style) { g_string_append(out, ", "); g_string_append(out, style); }
    g_string_append_c(out, ')');
    g_free(sep);
    g_free(style);
    res = g_string_free(out, FALSE);
done:
    g_ptr_array_free(args, TRUE);
    return res;
}

static gboolean
content_func_is_image(const content_tok *t)
{
    return strcmp(t->text, "url") == 0 || strcmp(t->text, "image") == 0 ||
           strcmp(t->text, "image-set") == 0 ||
           strcmp(t->text, "cross-fade") == 0 ||
           strcmp(t->text, "element") == 0 ||
           g_str_has_suffix(t->text, "-gradient");
}

static char *
content_item_canonical(const content_tok *t, gboolean alt)
{
    if (t->kind == CONTENT_TOK_STRING) return g_strdup(t->text);
    if (t->kind == CONTENT_TOK_IDENT) {
        if (alt) return NULL;
        static const char *kws[] = { "open-quote", "close-quote",
                                     "no-open-quote", "no-close-quote",
                                     "contents" };
        for (gsize k = 0; k < G_N_ELEMENTS(kws); k++)
            if (g_ascii_strcasecmp(t->text, kws[k]) == 0)
                return g_strdup(kws[k]);
        return NULL;
    }
    if (t->kind != CONTENT_TOK_FUNC) return NULL;
    if (strcmp(t->text, "counter") == 0 || strcmp(t->text, "counters") == 0)
        return content_counter_canonical(t);
    if (strcmp(t->text, "attr") == 0) {
        GPtrArray *args = content_split_args(t->args);
        gboolean ok = args && args->len >= 1 && args->len <= 2 &&
                      *(char *)args->pdata[0];
        if (ok) {
            char *first = g_strdup(args->pdata[0]);
            char *sp = strpbrk(first, " \t");
            if (sp) *sp = '\0';
            ok = content_ident_valid(first);
            g_free(first);
        }
        if (args) g_ptr_array_free(args, TRUE);
        return ok ? g_strdup_printf("attr(%s)", t->args) : NULL;
    }
    if (alt) return NULL;
    if (strcmp(t->text, "image-set") == 0 || strcmp(t->text, "-webkit-image-set") == 0) {
        char *raw = g_strdup_printf("%s(%s)", t->text, t->args);
        char *canon = image_set_canonical(raw, FALSE);
        g_free(raw);
        return canon;
    }
    if (content_func_is_image(t) || strcmp(t->text, "leader") == 0 ||
        g_str_has_prefix(t->text, "target-") || strcmp(t->text, "var") == 0 ||
        strcmp(t->text, "string") == 0 || strcmp(t->text, "content") == 0)
        return g_strdup_printf("%s(%s)", t->text, t->args);
    return NULL;
}

char *
ns_css_content_canonical(const char *text)
{
    if (!text) return NULL;
    GArray *toks = content_tokenize(text);
    if (!toks || toks->len == 0) {
        if (toks) g_array_free(toks, TRUE);
        return NULL;
    }
    if (toks->len == 1) {
        content_tok *t = &g_array_index(toks, content_tok, 0);
        if (t->kind == CONTENT_TOK_IDENT &&
            (g_ascii_strcasecmp(t->text, "normal") == 0 ||
             g_ascii_strcasecmp(t->text, "none") == 0)) {
            char *r = g_ascii_strdown(t->text, -1);
            g_array_free(toks, TRUE);
            return r;
        }
    }
    GString *out = g_string_new(NULL);
    gboolean alt = FALSE, ok = TRUE;
    int main_items = 0, alt_items = 0;
    for (guint i = 0; i < toks->len && ok; i++) {
        content_tok *t = &g_array_index(toks, content_tok, i);
        if (t->kind == CONTENT_TOK_SLASH) {
            if (alt || main_items == 0) { ok = FALSE; break; }
            alt = TRUE;
            g_string_append(out, " /");
            continue;
        }
        char *item = content_item_canonical(t, alt);
        if (!item) { ok = FALSE; break; }
        if (out->len) g_string_append_c(out, ' ');
        g_string_append(out, item);
        g_free(item);
        if (alt) alt_items++; else main_items++;
    }
    g_array_free(toks, TRUE);
    if (!ok || main_items == 0 || (alt && alt_items == 0)) {
        g_string_free(out, TRUE);
        return NULL;
    }
    return g_string_free(out, FALSE);
}

static int
image_set_split_ws(const char *text, char **out, int max)
{
    int n = 0;
    const char *p = text;
    while (*p && n < max) {
        while (*p && is_ws(*p)) p++;
        if (!*p) break;
        const char *start = p;
        int depth = 0;
        while (*p) {
            if (*p == '"' || *p == '\'') {
                const char *e = content_scan_string_end(p);
                if (!e) return -1;
                p = e + 1;
                continue;
            }
            if (*p == '(') depth++;
            else if (*p == ')') { if (depth) depth--; }
            else if (is_ws(*p) && depth == 0) break;
            p++;
        }
        out[n++] = g_strndup(start, (gsize)(p - start));
    }
    return n;
}

typedef struct {
    double value;
    gboolean resolution;
    gboolean known;
} res_term;

static gboolean
res_unit_factor(const char *unit, double *factor)
{
    if (g_ascii_strcasecmp(unit, "x") == 0 || g_ascii_strcasecmp(unit, "dppx") == 0)
        *factor = 1.0;
    else if (g_ascii_strcasecmp(unit, "dpi") == 0)
        *factor = 1.0 / 96.0;
    else if (g_ascii_strcasecmp(unit, "dpcm") == 0)
        *factor = 2.54 / 96.0;
    else
        return FALSE;
    return TRUE;
}

static gboolean res_eval_sum(const char **pp, const char *end, res_term *out,
                             int depth);

static gboolean
res_eval_atom(const char **pp, const char *end, res_term *out, int depth)
{
    if (depth > NS_CALC_MAX_DEPTH) return FALSE;
    const char *p = *pp;
    while (p < end && is_ws(*p)) p++;
    if (p >= end) return FALSE;
    if (*p == '(') {
        p++;
        if (!res_eval_sum(&p, end, out, depth + 1)) return FALSE;
        while (p < end && is_ws(*p)) p++;
        if (p >= end || *p != ')') return FALSE;
        *pp = p + 1;
        return TRUE;
    }
    if (g_ascii_isalpha((guchar)*p) || *p == '-') {
        const char *s = p;
        while (p < end && (g_ascii_isalnum((guchar)*p) || *p == '-')) p++;
        if (p < end && *p == '(') {
            const char *close = cq_match_paren(p, end);
            if (!close) return FALSE;
            char *name = g_strndup(s, (gsize)(p - s));
            gboolean ok = g_ascii_strcasecmp(name, "calc") == 0 ||
                          g_ascii_strcasecmp(name, "sign") == 0 ||
                          g_ascii_strcasecmp(name, "sibling-index") == 0 ||
                          g_ascii_strcasecmp(name, "sibling-count") == 0 ||
                          g_ascii_strcasecmp(name, "min") == 0 ||
                          g_ascii_strcasecmp(name, "max") == 0 ||
                          g_ascii_strcasecmp(name, "clamp") == 0 ||
                          g_ascii_strcasecmp(name, "abs") == 0;
            if (g_ascii_strcasecmp(name, "calc") == 0) {
                const char *inner = p + 1;
                ok = res_eval_sum(&inner, close, out, depth + 1);
            } else if (g_ascii_strcasecmp(name, "sign") == 0) {
                char *arg = g_strndup(p + 1, (gsize)(close - p - 1));
                double px = 0, pct = 0;
                gboolean rel = ns_value_has_relative_unit(arg);
                gboolean parsed = !rel && resolve_to_px_pct(arg, strlen(arg), &px, &pct);
                out->resolution = FALSE;
                out->known = parsed && pct == 0;
                out->value = px > 0 ? 1 : px < 0 ? -1 : 0;
                g_free(arg);
            } else if (ok) {
                out->resolution = FALSE;
                out->known = FALSE;
                out->value = 0;
            }
            g_free(name);
            if (!ok) return FALSE;
            *pp = close + 1;
            return TRUE;
        }
        return FALSE;
    }
    char *endp = NULL;
    double v = g_ascii_strtod(p, &endp);
    if (!endp || endp == p) return FALSE;
    p = endp;
    const char *us = p;
    while (p < end && g_ascii_isalpha((guchar)*p)) p++;
    out->value = v;
    out->known = TRUE;
    out->resolution = FALSE;
    if (p > us) {
        char *unit = g_strndup(us, (gsize)(p - us));
        double factor = 1;
        gboolean ok = res_unit_factor(unit, &factor);
        g_free(unit);
        if (!ok) return FALSE;
        out->value = v * factor;
        out->resolution = TRUE;
    }
    *pp = p;
    return TRUE;
}

static gboolean
res_eval_product(const char **pp, const char *end, res_term *out, int depth)
{
    if (!res_eval_atom(pp, end, out, depth)) return FALSE;
    while (TRUE) {
        const char *p = *pp;
        while (p < end && is_ws(*p)) p++;
        if (p >= end || (*p != '*' && *p != '/')) break;
        char op = *p++;
        res_term rhs;
        if (!res_eval_atom(&p, end, &rhs, depth)) return FALSE;
        if (op == '*') {
            if (out->resolution && rhs.resolution) return FALSE;
            out->resolution = out->resolution || rhs.resolution;
            out->value *= rhs.value;
        } else {
            if (rhs.resolution) return FALSE;
            if (rhs.known && rhs.value == 0) return FALSE;
            out->value = rhs.value != 0 ? out->value / rhs.value : 0;
        }
        out->known = out->known && rhs.known;
        *pp = p;
    }
    return TRUE;
}

static gboolean
res_eval_sum(const char **pp, const char *end, res_term *out, int depth)
{
    if (!res_eval_product(pp, end, out, depth)) return FALSE;
    while (TRUE) {
        const char *p = *pp;
        while (p < end && is_ws(*p)) p++;
        if (p >= end || (*p != '+' && *p != '-')) break;
        char op = *p;
        if (!(p + 1 < end && is_ws(p[1]))) return FALSE;
        p++;
        res_term rhs;
        if (!res_eval_product(&p, end, &rhs, depth)) return FALSE;
        if (out->resolution != rhs.resolution) return FALSE;
        out->value = op == '+' ? out->value + rhs.value : out->value - rhs.value;
        out->known = out->known && rhs.known;
        *pp = p;
    }
    return TRUE;
}

static char *
image_set_resolution_canonical(const char *tok, gboolean computed)
{
    if (token_is_math_fn(tok)) {
        const char *p = tok;
        const char *end = tok + strlen(tok);
        res_term t = { 0 };
        if (!res_eval_atom(&p, end, &t, 0) || !t.resolution) return NULL;
        while (p < end && is_ws(*p)) p++;
        if (p < end) return NULL;
        if (!t.known) return g_strdup(tok);
        return computed ? g_strdup_printf("%gdppx", t.value)
                        : g_strdup_printf("calc(%gdppx)", t.value);
    }
    char *endp = NULL;
    double v = g_ascii_strtod(tok, &endp);
    if (!endp || endp == tok || !*endp) return NULL;
    double factor = 1;
    if (!res_unit_factor(endp, &factor) || v < 0) return NULL;
    if (computed) return g_strdup_printf("%gdppx", v * factor);
    char *unit = g_ascii_strdown(endp, -1);
    char *res = g_strdup_printf("%g%s", v, unit);
    g_free(unit);
    return res;
}

static char *
image_set_canonical(const char *text, gboolean computed)
{
    const char *p = text;
    while (*p && is_ws(*p)) p++;
    if (g_ascii_strncasecmp(p, "-webkit-image-set(", 18) == 0) p += 18;
    else if (g_ascii_strncasecmp(p, "image-set(", 10) == 0) p += 10;
    else return NULL;
    const char *end = p + strlen(p);
    const char *close = cq_match_paren(p - 1, end);
    if (!close) return NULL;
    const char *after = close + 1;
    while (*after && is_ws(*after)) after++;
    if (*after) return NULL;
    char *body = g_strndup(p, (gsize)(close - p));
    GPtrArray *options = content_split_args(body);
    g_free(body);
    if (!options) return NULL;
    GString *out = g_string_new("image-set(");
    gboolean ok = options->len > 0;
    for (guint i = 0; i < options->len && ok; i++) {
        char *tok[6] = {0};
        int n = image_set_split_ws(options->pdata[i], tok, 6);
        char *image = NULL, *res = NULL, *type = NULL;
        if (n < 1) ok = FALSE;
        for (int k = 0; k < n && ok; k++) {
            const char *t = tok[k];
            if (k == 0) {
                if (content_is_string_token(t)) {
                    char *inner = content_string_canonical(t + 1, strlen(t) - 2);
                    image = g_strdup_printf("url(%s)", inner);
                    g_free(inner);
                } else if (g_ascii_strncasecmp(t, "url(", 4) == 0 ||
                           g_ascii_strncasecmp(t, "src(", 4) == 0 ||
                           g_ascii_strncasecmp(t, "image(", 6) == 0 ||
                           g_ascii_strncasecmp(t, "cross-fade(", 11) == 0) {
                    image = g_strdup(t);
                } else if (text_starts_gradient(t)) {
                    ns_gradient_parse gp;
                    const char *gend = NULL;
                    if (gradient_parse(t, &gp, &gend, TRUE)) {
                        image = gradient_serialize_specified(&gp);
                        gradient_parse_clear(&gp);
                    }
                    if (!image) ok = FALSE;
                } else {
                    ok = FALSE;
                }
            } else if (g_ascii_strncasecmp(t, "type(", 5) == 0) {
                if (type) ok = FALSE;
                else type = g_strdup(t);
            } else {
                if (res) ok = FALSE;
                else res = image_set_resolution_canonical(t, computed);
                if (!res) ok = FALSE;
            }
        }
        if (ok) {
            if (i) g_string_append(out, ", ");
            g_string_append(out, image);
            g_string_append_c(out, ' ');
            g_string_append(out, res ? res : computed ? "1dppx" : "1x");
            if (type) { g_string_append_c(out, ' '); g_string_append(out, type); }
        }
        g_free(image);
        g_free(res);
        g_free(type);
        for (int k = 0; k < n; k++) g_free(tok[k]);
    }
    g_ptr_array_free(options, TRUE);
    if (!ok) { g_string_free(out, TRUE); return NULL; }
    g_string_append_c(out, ')');
    return g_string_free(out, FALSE);
}

static gboolean
text_starts_image_set(const char *p)
{
    while (*p && is_ws(*p)) p++;
    return g_ascii_strncasecmp(p, "image-set(", 10) == 0 ||
           g_ascii_strncasecmp(p, "-webkit-image-set(", 18) == 0;
}

char *
ns_css_unicode_range_canonical(const char *text)
{
    if (!text) return NULL;
    GString *clean = g_string_new(NULL);
    for (const char *p = text; *p; ) {
        if (p[0] == '/' && p[1] == '*') {
            const char *e = strstr(p + 2, "*/");
            if (!e) { g_string_free(clean, TRUE); return NULL; }
            p = e + 2;
            continue;
        }
        g_string_append_c(clean, *p++);
    }
    GString *out = g_string_new(NULL);
    gboolean ok = TRUE;
    char **parts = g_strsplit(clean->str, ",", -1);
    for (int i = 0; parts[i] && ok; i++) {
        char *r = g_strstrip(parts[i]);
        if (!*r || (r[0] != 'u' && r[0] != 'U') || r[1] != '+') { ok = FALSE; break; }
        const char *q = r + 2;
        guint32 start = 0, endv = 0;
        int hex = 0, wild = 0;
        while (g_ascii_isxdigit((guchar)*q) && hex < 7) {
            start = start * 16 + g_ascii_xdigit_value(*q);
            hex++; q++;
        }
        while (*q == '?' && wild < 7) { wild++; q++; }
        if (hex + wild == 0 || hex + wild > 6) { ok = FALSE; break; }
        if (wild) {
            if (*q) { ok = FALSE; break; }
            endv = start;
            for (int k = 0; k < wild; k++) { start *= 16; endv = endv * 16 + 15; }
        } else if (*q == '-') {
            q++;
            int hex2 = 0;
            while (g_ascii_isxdigit((guchar)*q) && hex2 < 7) {
                endv = endv * 16 + g_ascii_xdigit_value(*q);
                hex2++; q++;
            }
            if (hex2 == 0 || hex2 > 6 || *q) { ok = FALSE; break; }
        } else if (*q) {
            ok = FALSE;
            break;
        } else {
            endv = start;
        }
        if (start > endv || endv > 0x10FFFF) { ok = FALSE; break; }
        if (out->len) g_string_append(out, ", ");
        if (start == endv) g_string_append_printf(out, "U+%X", start);
        else g_string_append_printf(out, "U+%X-%X", start, endv);
    }
    g_strfreev(parts);
    g_string_free(clean, TRUE);
    if (!ok || out->len == 0) { g_string_free(out, TRUE); return NULL; }
    return g_string_free(out, FALSE);
}

static const char *
css_quoted_end(const char *u, char quote)
{
    const char *p = u;
    while (*p) {
        if (*p == '\\' && p[1]) { p += 2; continue; }
        if (*p == quote) return p;
        p++;
    }
    return NULL;
}

static char *
css_unescape_url(const char *u, gsize len)
{
    GString *out = g_string_sized_new(len);
    for (gsize i = 0; i < len; i++) {
        if (u[i] == '\\' && i + 1 < len) i++;
        g_string_append_c(out, u[i]);
    }
    return g_string_free(out, FALSE);
}

static char *
pick_image_set_url(const char *t)
{
    const char *p = t;
    while (*p && is_ws(*p)) p++;
    if (g_ascii_strncasecmp(p, "-webkit-image-set(", 18) == 0)
        p += 18;
    else if (g_ascii_strncasecmp(p, "image-set(", 10) == 0)
        p += 10;
    else
        return NULL;

    const double target = 1.0;
    char *best = NULL;
    double best_res = 0;
    while (*p && *p != ')') {
        while (*p && (is_ws(*p) || *p == ',')) p++;
        if (!*p || *p == ')') break;
        char *url = NULL;
        if (g_ascii_strncasecmp(p, "url(", 4) == 0) {
            const char *u = p + 4;
            while (*u && is_ws(*u)) u++;
            char q = 0;
            if (*u == '"' || *u == '\'') { q = *u; u++; }
            const char *end;
            if (q) end = css_quoted_end(u, q);
            else { end = u; while (*end && *end != ')' && !is_ws(*end)) end++; }
            if (end && end > u) url = css_unescape_url(u, (gsize)(end - u));
            p = end ? end : p + 4;
            while (*p && *p != ')') p++;
            if (*p == ')') p++;
        }
        double res = 1.0;
        while (*p && is_ws(*p)) p++;
        if (*p && *p != ',' && *p != ')') {
            res = g_ascii_strtod(p, NULL);
            while (*p && *p != ',' && *p != ')') p++;
        }
        if (url) {
            if (!best || fabs(res - target) < fabs(best_res - target)) {
                g_free(best);
                best = url;
                best_res = res;
            } else {
                g_free(url);
            }
        } else {
            while (*p && *p != ',' && *p != ')') p++;
        }
    }
    return best;
}

static ns_css_value *
parse_gradient_text(const char *t, gboolean allow_trailing)
{
    ns_gradient_parse gp;
    const char *gend = NULL;
    if (!gradient_parse(t, &gp, &gend, FALSE)) return NULL;
    while (gend && *gend && is_ws(*gend)) gend++;
    if (!allow_trailing && gend && *gend) {
        gradient_parse_clear(&gp);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_GRADIENT;
    v->u.gradient = gp.gr;
    if (!gp.all_legacy && !allow_trailing) v->specified = g_strdup(t);
    gradient_parse_clear(&gp);
    return v;
}

static ns_css_value *
parse_any_gradient(const char *t)
{
    return parse_gradient_text(t, FALSE);
}

static double
parse_angle_deg(const char *s)
{
    if (!s) return 0;
    char *end = NULL;
    double v = g_ascii_strtod(s, &end);
    if (!end || end == s) return 0;
    while (*end && is_ws(*end)) end++;
    if (g_ascii_strncasecmp(end, "rad", 3) == 0) return v * 180.0 / G_PI;
    if (g_ascii_strncasecmp(end, "turn", 4) == 0) return v * 360.0;
    if (g_ascii_strncasecmp(end, "grad", 4) == 0) return v * 0.9;
    return v;
}

static gboolean
parse_transform_len(const char *s, double *out, gboolean *is_percent)
{
    if (!s) return FALSE;
    double px = 0, pct = 0;
    if (resolve_to_px_pct(s, strlen(s), &px, &pct)) {
        if (pct != 0 && px == 0) {
            *out = pct;
            *is_percent = TRUE;
        } else {
            *out = px;
            *is_percent = FALSE;
        }
        return TRUE;
    }
    char *end = NULL;
    double v = g_ascii_strtod(s, &end);
    if (!end || end == s) return FALSE;
    while (*end && is_ws(*end)) end++;
    *out = v;
    *is_percent = (*end == '%');
    return TRUE;
}

static char *
angle_expr_rewrite(const char *s, gboolean to_radians)
{
    GString *out = g_string_new(NULL);
    const char *p = s;
    while (*p) {
        gboolean num_start = g_ascii_isdigit(*p) ||
            (*p == '.' && g_ascii_isdigit(p[1]));
        if (num_start) {
            char *end = NULL;
            double v = g_ascii_strtod(p, &end);
            const char *u = end;
            while (*u && g_ascii_isalpha(*u)) u++;
            gsize ul = (gsize)(u - end);
            double deg = v;
            gboolean is_angle = TRUE;
            if      (ul == 3 && g_ascii_strncasecmp(end, "deg",  3) == 0) deg = v;
            else if (ul == 4 && g_ascii_strncasecmp(end, "grad", 4) == 0) deg = v * 0.9;
            else if (ul == 3 && g_ascii_strncasecmp(end, "rad",  3) == 0) deg = v * 180.0 / G_PI;
            else if (ul == 4 && g_ascii_strncasecmp(end, "turn", 4) == 0) deg = v * 360.0;
            else is_angle = FALSE;
            if (is_angle) {
                g_string_append_printf(out, "%.17g",
                                       to_radians ? deg * G_PI / 180.0 : deg);
                p = u;
            } else {
                g_string_append_len(out, p, (gssize)(u - p));
                p = u;
            }
            continue;
        }
        g_string_append_c(out, *p++);
    }
    return g_string_free(out, FALSE);
}

static gboolean
parse_translate_len(const char *s, ns_css_transform_op *op, int axis)
{
    if (!s) return FALSE;
    double *field = axis == 0 ? &op->a : axis == 1 ? &op->b : &op->c;
    gboolean *is_percent = axis == 0 ? &op->a_is_percent
                         : axis == 1 ? &op->b_is_percent : NULL;
    double px = 0, pct = 0, em = 0, rem = 0;
    if (!resolve_to_px_pct_font(s, strlen(s), &px, &pct, &em, &rem)) {
        gboolean fallback_pct = FALSE;
        if (!parse_transform_len(s, field, &fallback_pct)) return FALSE;
        if (is_percent) *is_percent = fallback_pct;
        return is_percent || !fallback_pct;
    }
    op->em[axis] = em;
    op->rem[axis] = rem;
    if (!is_percent) {
        *field = px;
        return pct == 0;
    }
    if (pct != 0 && px == 0 && em == 0 && rem == 0) {
        *field = pct;
        *is_percent = TRUE;
        return TRUE;
    }
    *field = px;
    *is_percent = FALSE;
    if (axis == 0) op->a_pct = pct;
    else op->b_pct = pct;
    return TRUE;
}

static gboolean
parse_angle_any(const char *s, double *deg_out)
{
    if (!s) return FALSE;
    while (*s && is_ws(*s)) s++;
    if (!*s) return FALSE;
    if (g_ascii_strncasecmp(s, "atan2(", 6) == 0 ||
        g_ascii_strncasecmp(s, "atan(", 5) == 0 ||
        g_ascii_strncasecmp(s, "asin(", 5) == 0 ||
        g_ascii_strncasecmp(s, "acos(", 5) == 0) {
        double px = 0, pct = 0;
        if (!resolve_to_px_pct(s, strlen(s), &px, &pct)) return FALSE;
        *deg_out = px * 180.0 / G_PI;
        return TRUE;
    }
    {
        static const char *const fns[] = {
            "calc(", "min(", "max(", "clamp(", "round(", "mod(", "rem(",
            "abs(", "sign(", "hypot(", "pow(", "sqrt(", "sin(", "cos(",
            "tan(", "exp(", "log(",
        };
        for (gsize i = 0; i < G_N_ELEMENTS(fns); i++) {
            if (g_ascii_strncasecmp(s, fns[i], strlen(fns[i])) != 0) continue;
            char *rw = angle_expr_rewrite(s, FALSE);
            double px = 0, pct = 0;
            gboolean ok = resolve_to_px_pct(rw, strlen(rw), &px, &pct);
            g_free(rw);
            if (!ok) return FALSE;
            *deg_out = px;
            return TRUE;
        }
    }
    char *end = NULL;
    g_ascii_strtod(s, &end);
    if (!end || end == s) return FALSE;
    *deg_out = parse_angle_deg(s);
    return TRUE;
}

static gboolean parse_scale_number(const char *s, double *out);

static ns_css_value *
parse_transform(const char *text)
{
    while (*text && is_ws(*text)) text++;
    if (!*text) return NULL;
    if (g_ascii_strncasecmp(text, "none", 4) == 0) return NULL;
    ns_css_transform tf = {0};
    const char *p = text;
    while (*p && tf.n_ops < NS_CSS_TRANSFORM_OPS_MAX) {
        while (*p && (is_ws(*p) || *p == ',')) p++;
        if (!*p) break;
        const char *name_start = p;
        while (*p && *p != '(') p++;
        if (*p != '(') break;
        gsize name_len = (gsize)(p - name_start);
        char *fn = g_strndup(name_start, name_len);
        g_strstrip(fn);
        char *fn_lc = g_ascii_strdown(fn, -1);
        g_free(fn);
        p++;
        const char *args_start = p;
        int depth = 1;
        while (*p && depth > 0) {
            if (*p == '(') depth++;
            else if (*p == ')') depth--;
            if (depth > 0) p++;
        }
        if (depth != 0) { g_free(fn_lc); break; }
        gsize args_len = (gsize)(p - args_start);
        char *args = g_strndup(args_start, args_len);
        if (*p == ')') p++;

        char *targs[16] = {0};
        int nt = 0;
        char *seg = args;
        int adepth = 0;
        for (char *q = args; ; q++) {
            if (*q == '(') adepth++;
            else if (*q == ')') adepth--;
            if ((*q == ',' && adepth == 0) || *q == '\0') {
                int saved = *q;
                *q = '\0';
                if (nt < 16) {
                    char *piece = g_strdup(seg);
                    g_strstrip(piece);
                    targs[nt++] = piece;
                }
                if (saved == '\0') break;
                seg = q + 1;
            }
        }

        ns_css_transform_op *op = &tf.ops[tf.n_ops];
        gboolean accept = FALSE;
        gboolean dummy_pct = FALSE;
        if (strcmp(fn_lc, "translate") == 0 ||
            strcmp(fn_lc, "translatex") == 0 ||
            strcmp(fn_lc, "translatey") == 0 ||
            strcmp(fn_lc, "translatez") == 0) {
            op->kind = NS_CSS_TFN_TRANSLATE;
            op->a = 0; op->b = 0; op->c = 0;
            op->a_is_percent = FALSE; op->b_is_percent = FALSE;
            if (strcmp(fn_lc, "translatey") == 0) {
                if (nt >= 1) parse_translate_len(targs[0], op, 1);
            } else if (strcmp(fn_lc, "translatez") == 0) {
                if (nt >= 1) parse_translate_len(targs[0], op, 2);
            } else {
                if (nt >= 1) parse_translate_len(targs[0], op, 0);
                if (nt >= 2) parse_translate_len(targs[1], op, 1);
            }
            accept = TRUE;
        } else if (strcmp(fn_lc, "rotate") == 0 ||
                   strcmp(fn_lc, "rotatez") == 0) {
            op->kind = NS_CSS_TFN_ROTATE;
            op->a = 0;
            op->b = 0;
            accept = nt == 1 && parse_angle_any(targs[0], &op->a);
        } else if (strcmp(fn_lc, "rotatex") == 0 ||
                   strcmp(fn_lc, "rotatey") == 0) {
            op->kind = NS_CSS_TFN_ROTATE3D;
            op->a = strcmp(fn_lc, "rotatex") == 0 ? 1 : 0;
            op->b = strcmp(fn_lc, "rotatey") == 0 ? 1 : 0;
            op->c = 0;
            op->d = 0;
            accept = nt == 1 && parse_angle_any(targs[0], &op->d);
        } else if (strcmp(fn_lc, "rotate3d") == 0 && nt == 4) {
            op->kind = NS_CSS_TFN_ROTATE3D;
            op->a = g_ascii_strtod(targs[0], NULL);
            op->b = g_ascii_strtod(targs[1], NULL);
            op->c = g_ascii_strtod(targs[2], NULL);
            op->d = 0;
            accept = parse_angle_any(targs[3], &op->d);
        } else if (strcmp(fn_lc, "perspective") == 0 && nt >= 1) {
            op->kind = NS_CSS_TFN_PERSPECTIVE;
            op->a = 0;
            parse_transform_len(targs[0], &op->a, &dummy_pct);
            accept = TRUE;
        } else if (strcmp(fn_lc, "scale") == 0 ||
                   strcmp(fn_lc, "scalex") == 0 ||
                   strcmp(fn_lc, "scaley") == 0 ||
                   strcmp(fn_lc, "scalez") == 0) {
            op->kind = NS_CSS_TFN_SCALE;
            double sa = 1, sb;
            if (nt >= 1 && !parse_scale_number(targs[0], &sa)) sa = 0;
            sb = sa;
            if (nt >= 2 && !parse_scale_number(targs[1], &sb)) sb = 0;
            op->c = 1;
            if (strcmp(fn_lc, "scalex") == 0) { op->a = sa; op->b = 1; }
            else if (strcmp(fn_lc, "scaley") == 0) { op->a = 1; op->b = sa; }
            else if (strcmp(fn_lc, "scalez") == 0) { op->a = 1; op->b = 1; op->c = sa; }
            else { op->a = sa; op->b = sb; }
            accept = TRUE;
        } else if (strcmp(fn_lc, "skew") == 0 ||
                   strcmp(fn_lc, "skewx") == 0 ||
                   strcmp(fn_lc, "skewy") == 0) {
            op->kind = NS_CSS_TFN_SKEW;
            double aa = 0, bb = 0;
            if (nt >= 1) parse_angle_any(targs[0], &aa);
            if (nt >= 2) parse_angle_any(targs[1], &bb);
            if (strcmp(fn_lc, "skewx") == 0) { op->a = aa; op->b = 0; }
            else if (strcmp(fn_lc, "skewy") == 0) { op->a = 0; op->b = aa; }
            else { op->a = aa; op->b = bb; }
            accept = TRUE;
        } else if (strcmp(fn_lc, "matrix") == 0 && nt == 6) {
            op->kind = NS_CSS_TFN_MATRIX;
            op->a = g_ascii_strtod(targs[0], NULL);
            op->b = g_ascii_strtod(targs[1], NULL);
            op->c = g_ascii_strtod(targs[2], NULL);
            op->d = g_ascii_strtod(targs[3], NULL);
            op->e = g_ascii_strtod(targs[4], NULL);
            op->f = g_ascii_strtod(targs[5], NULL);
            accept = TRUE;
        } else if (strcmp(fn_lc, "matrix3d") == 0 && nt == 16) {
            op->kind = NS_CSS_TFN_MATRIX3D;
            for (int k = 0; k < 16; k++)
                op->m3d[k] = g_ascii_strtod(targs[k], NULL);
            accept = TRUE;
        } else if ((strcmp(fn_lc, "translate3d") == 0 && nt >= 2)) {
            op->kind = NS_CSS_TFN_TRANSLATE;
            op->a = 0; op->b = 0; op->c = 0;
            op->a_is_percent = FALSE; op->b_is_percent = FALSE;
            parse_translate_len(targs[0], op, 0);
            parse_translate_len(targs[1], op, 1);
            if (nt >= 3) parse_translate_len(targs[2], op, 2);
            accept = TRUE;
        } else if (strcmp(fn_lc, "scale3d") == 0 && nt >= 2) {
            op->kind = NS_CSS_TFN_SCALE;
            op->a = 0; op->b = 0; op->c = 1;
            parse_scale_number(targs[0], &op->a);
            parse_scale_number(targs[1], &op->b);
            if (nt >= 3) parse_scale_number(targs[2], &op->c);
            accept = TRUE;
        }
        if (accept) tf.n_ops++;
        for (int k = 0; k < 16; k++) g_free(targs[k]);
        g_free(args);
        g_free(fn_lc);
    }
    if (tf.n_ops == 0) return NULL;
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_TRANSFORM;
    v->u.transform = tf;
    return v;
}

static gboolean
parse_origin_axis(const char *tok, gboolean is_y,
                  double *out, gboolean *is_percent)
{
    if (!tok || !*tok) return FALSE;
    char *lc = ascii_lower(tok, strlen(tok));
    gboolean ok = TRUE;
    if (strcmp(lc, "center") == 0)      { *out = 50; *is_percent = TRUE; }
    else if (!is_y && strcmp(lc, "left")  == 0)  { *out = 0;   *is_percent = TRUE; }
    else if (!is_y && strcmp(lc, "right") == 0)  { *out = 100; *is_percent = TRUE; }
    else if ( is_y && strcmp(lc, "top")   == 0)  { *out = 0;   *is_percent = TRUE; }
    else if ( is_y && strcmp(lc, "bottom") == 0) { *out = 100; *is_percent = TRUE; }
    else ok = parse_transform_len(tok, out, is_percent);
    g_free(lc);
    return ok;
}

static ns_css_value *
parse_transform_origin(const char *text)
{
    if (!text || !*text) return NULL;
    char *edge_canon = css_ws_token_count(text) >= 3 &&
                       position_canonical_ex(text, TRUE, FALSE)
        ? position_canonical_ex(text, TRUE, FALSE) : NULL;
    if (edge_canon) {
        char *xs = NULL, *ys = NULL;
        position_split(edge_canon, &xs, &ys);
        g_free(edge_canon);
        ns_css_transform tf;
        memset(&tf, 0, sizeof(tf));
        tf.n_ops = 1;
        ns_css_transform_op *op = &tf.ops[0];
        op->kind = NS_CSS_TFN_TRANSLATE;
        op->a = 50; op->b = 50; op->c = 0;
        op->a_is_percent = TRUE; op->b_is_percent = TRUE;
        if (xs) parse_origin_axis(xs, FALSE, &op->a, &op->a_is_percent);
        if (ys) parse_origin_axis(ys, TRUE, &op->b, &op->b_is_percent);
        g_free(xs);
        g_free(ys);
        ns_css_value *v = g_new0(ns_css_value, 1);
        v->kind = NS_CSS_V_TRANSFORM;
        v->u.transform = tf;
        return v;
    }
    char *toks[4] = {0};
    int nt = split_ws_limit(text, toks, 3);
    char *a = nt >= 1 ? toks[0] : NULL;
    char *b = nt >= 2 ? toks[1] : NULL;
    char *zc = nt >= 3 ? toks[2] : NULL;
    ns_css_transform tf;
    memset(&tf, 0, sizeof(tf));
    tf.n_ops = 1;
    ns_css_transform_op *op = &tf.ops[0];
    op->kind = NS_CSS_TFN_TRANSLATE;
    op->a = 50; op->b = 50; op->c = 0;
    op->a_is_percent = TRUE; op->b_is_percent = TRUE;
    gboolean swap = FALSE;
    if (a) {
        char *alc = ascii_lower(a, strlen(a));
        if (strcmp(alc, "top") == 0 || strcmp(alc, "bottom") == 0) swap = TRUE;
        g_free(alc);
    }
    if (swap) {
        if (a) parse_origin_axis(a, TRUE,  &op->b, &op->b_is_percent);
        if (b) parse_origin_axis(b, FALSE, &op->a, &op->a_is_percent);
    } else {
        if (a) parse_origin_axis(a, FALSE, &op->a, &op->a_is_percent);
        if (b) parse_origin_axis(b, TRUE,  &op->b, &op->b_is_percent);
        else if (a) {
            char *alc = ascii_lower(a, strlen(a));
            if (strcmp(alc, "left") == 0 || strcmp(alc, "right") == 0) {
                op->b = 50; op->b_is_percent = TRUE;
            }
            g_free(alc);
        }
    }
    if (zc) {
        gboolean zpct = FALSE;
        parse_transform_len(zc, &op->c, &zpct);
        if (zpct) op->c = 0;
    }
    for (int i = 0; i < nt; i++) g_free(toks[i]);
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_TRANSFORM;
    v->u.transform = tf;
    return v;
}

static ns_css_value *
transform_value_one_op(const ns_css_transform_op *op)
{
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_TRANSFORM;
    v->u.transform.n_ops = 1;
    v->u.transform.ops[0] = *op;
    return v;
}

static ns_css_value *
parse_translate_prop(const char *text)
{
    while (*text && is_ws(*text)) text++;
    if (!*text || g_ascii_strcasecmp(text, "none") == 0) return NULL;
    char *toks[4] = {0};
    int nt = split_ws_limit(text, toks, 3);
    if (nt == 0) return NULL;
    ns_css_transform_op op;
    memset(&op, 0, sizeof(op));
    op.kind = NS_CSS_TFN_TRANSLATE;
    gboolean ok = parse_translate_len(toks[0], &op, 0);
    if (ok && nt >= 2) ok = parse_translate_len(toks[1], &op, 1);
    if (ok && nt >= 3) ok = parse_translate_len(toks[2], &op, 2);
    for (int i = 0; i < nt; i++) g_free(toks[i]);
    if (!ok) return NULL;
    return transform_value_one_op(&op);
}

static ns_css_value *
parse_rotate_prop(const char *text)
{
    while (*text && is_ws(*text)) text++;
    if (!*text || g_ascii_strcasecmp(text, "none") == 0) return NULL;
    char *toks[5] = {0};
    int nt = split_ws_limit(text, toks, 4);
    ns_css_value *v = NULL;
    ns_css_transform_op op;
    memset(&op, 0, sizeof(op));
    if (nt == 1) {
        op.kind = NS_CSS_TFN_ROTATE;
        if (parse_angle_any(toks[0], &op.a)) v = transform_value_one_op(&op);
    } else if (nt == 2) {
        op.kind = NS_CSS_TFN_ROTATE3D;
        char *axis = ascii_lower(toks[0], strlen(toks[0]));
        gboolean ok = TRUE;
        if      (strcmp(axis, "x") == 0) op.a = 1;
        else if (strcmp(axis, "y") == 0) op.b = 1;
        else if (strcmp(axis, "z") == 0) op.c = 1;
        else ok = FALSE;
        g_free(axis);
        if (ok && parse_angle_any(toks[1], &op.d)) {
            if (op.c == 1 && op.a == 0 && op.b == 0) {
                op.kind = NS_CSS_TFN_ROTATE;
                op.a = op.d;
                op.b = 0; op.c = 0; op.d = 0;
            }
            v = transform_value_one_op(&op);
        }
    } else if (nt == 4) {
        op.kind = NS_CSS_TFN_ROTATE3D;
        op.a = g_ascii_strtod(toks[0], NULL);
        op.b = g_ascii_strtod(toks[1], NULL);
        op.c = g_ascii_strtod(toks[2], NULL);
        if (parse_angle_any(toks[3], &op.d)) v = transform_value_one_op(&op);
    }
    for (int i = 0; i < nt; i++) g_free(toks[i]);
    return v;
}

static gboolean
parse_scale_number(const char *s, double *out)
{
    if (!s) return FALSE;
    while (*s && is_ws(*s)) s++;
    if (!*s) return FALSE;
    char *end = NULL;
    double v = g_ascii_strtod(s, &end);
    if (end && end != s) {
        const char *p = end;
        while (*p && is_ws(*p)) p++;
        if (*p == '\0') { *out = v; return TRUE; }
        if (*p == '%' && p[1] == '\0') { *out = v / 100.0; return TRUE; }
    }
    double px = 0, pct = 0;
    if (resolve_to_px_pct(s, strlen(s), &px, &pct)) {
        *out = px + pct / 100.0;
        return TRUE;
    }
    ns_css_value *cv = parse_calc(s);
    if (!cv) {
        char *w = g_strdup_printf("calc(%s)", s);
        cv = parse_calc(w);
        g_free(w);
    }
    if (cv && cv->kind == NS_CSS_V_LENGTH) {
        double val = cv->u.length.unit == NS_CSS_UNIT_PERCENT
                   ? cv->u.length.v / 100.0 : cv->u.length.v;
        ns_css_value_free(cv);
        *out = isnan(val) ? 0.0 : val;
        return TRUE;
    }
    if (cv) ns_css_value_free(cv);
    return FALSE;
}

static ns_css_value *
parse_scale_prop(const char *text)
{
    while (*text && is_ws(*text)) text++;
    if (!*text || g_ascii_strcasecmp(text, "none") == 0) return NULL;
    char *toks[4] = {0};
    int nt = split_ws_limit(text, toks, 3);
    if (nt == 0) return NULL;
    ns_css_transform_op op;
    memset(&op, 0, sizeof(op));
    op.kind = NS_CSS_TFN_SCALE;
    gboolean ok = parse_scale_number(toks[0], &op.a);
    op.b = op.a;
    op.c = 1;
    if (ok && nt >= 2) ok = parse_scale_number(toks[1], &op.b);
    if (ok && nt >= 3) ok = parse_scale_number(toks[2], &op.c);
    for (int i = 0; i < nt; i++) g_free(toks[i]);
    if (!ok) return NULL;
    return transform_value_one_op(&op);
}

static void
append_scale_number(GString *s, double n)
{
    if (isnan(n)) {
        g_string_append_c(s, '0');
        return;
    }
    if (!isfinite(n)) {
        g_string_append(s, n < 0 ? "calc(-infinity)" : "calc(infinity)");
        return;
    }
    char *t = ns_css_number_str(n);
    g_string_append(s, t);
    g_free(t);
}

static gboolean
translate_axis_is_mixed(const ns_css_transform_op *op, int axis)
{
    double pct = axis == 0 ? op->a_pct : axis == 1 ? op->b_pct : 0;
    return pct != 0 || op->em[axis] != 0 || op->rem[axis] != 0;
}

static void
append_translate_length(GString *s, const ns_css_transform_op *op, int axis)
{
    double v = axis == 0 ? op->a : axis == 1 ? op->b : op->c;
    gboolean is_percent = axis == 0 ? op->a_is_percent
                        : axis == 1 && op->b_is_percent;
    if (is_percent || !translate_axis_is_mixed(op, axis)) {
        char *t = ns_css_number_str(v);
        g_string_append(s, t);
        g_free(t);
        g_string_append(s, is_percent ? "%" : "px");
        return;
    }
    const double parts[4] = {
        axis == 0 ? op->a_pct : axis == 1 ? op->b_pct : 0,
        v, op->em[axis], op->rem[axis],
    };
    static const char *const units[4] = { "%", "px", "em", "rem" };
    gboolean first = TRUE;
    g_string_append(s, "calc(");
    for (int k = 0; k < 4; k++) {
        if (parts[k] == 0) continue;
        if (!first) g_string_append(s, parts[k] < 0 ? " - " : " + ");
        char *t = ns_css_number_str(first ? parts[k] : fabs(parts[k]));
        g_string_append(s, t);
        g_free(t);
        g_string_append(s, units[k]);
        first = FALSE;
    }
    g_string_append_c(s, ')');
}

char *
ns_css_individual_transform_serialize(const ns_css_value *v, int prop)
{
    if (!v) return NULL;
    if (v->kind == NS_CSS_V_KEYWORD)
        return g_strdup(v->u.keyword);
    if (v->kind != NS_CSS_V_TRANSFORM || v->u.transform.n_ops < 1)
        return NULL;
    const ns_css_transform_op *op = &v->u.transform.ops[0];
    GString *s = g_string_new(NULL);
    if (prop == NS_CSS_SCALE) {
        gboolean ab_same = (op->a == op->b) || (isnan(op->a) && isnan(op->b));
        append_scale_number(s, op->a);
        if (op->c != 1) {
            g_string_append_c(s, ' ');
            append_scale_number(s, op->b);
            g_string_append_c(s, ' ');
            append_scale_number(s, op->c);
        } else if (!ab_same) {
            g_string_append_c(s, ' ');
            append_scale_number(s, op->b);
        }
    } else if (prop == NS_CSS_ROTATE) {
        if (op->kind == NS_CSS_TFN_ROTATE3D) {
            const char *axis = NULL;
            if (op->a == 1 && op->b == 0 && op->c == 0) axis = "x";
            else if (op->a == 0 && op->b == 1 && op->c == 0) axis = "y";
            else if (op->a == 0 && op->b == 0 && op->c == 1) axis = NULL;
            if (axis) {
                g_string_append(s, axis);
                g_string_append_c(s, ' ');
            } else if (!(op->a == 0 && op->b == 0 && op->c == 1)) {
                append_scale_number(s, op->a);
                g_string_append_c(s, ' ');
                append_scale_number(s, op->b);
                g_string_append_c(s, ' ');
                append_scale_number(s, op->c);
                g_string_append_c(s, ' ');
            }
            append_scale_number(s, op->d);
            g_string_append(s, "deg");
        } else {
            append_scale_number(s, op->a);
            g_string_append(s, "deg");
        }
    } else if (prop == NS_CSS_TRANSLATE) {
        append_translate_length(s, op, 0);
        gboolean need_c = op->c != 0 || translate_axis_is_mixed(op, 2);
        gboolean need_b = need_c || op->b != 0 || op->b_is_percent ||
                          translate_axis_is_mixed(op, 1);
        if (need_b) {
            g_string_append_c(s, ' ');
            append_translate_length(s, op, 1);
        }
        if (need_c) {
            g_string_append_c(s, ' ');
            append_translate_length(s, op, 2);
        }
    } else {
        g_string_free(s, TRUE);
        return NULL;
    }
    return g_string_free(s, FALSE);
}

gboolean
ns_css_transform_is_3d(const ns_css_transform *tf)
{
    if (!tf) return FALSE;
    for (int i = 0; i < tf->n_ops; i++) {
        const ns_css_transform_op *op = &tf->ops[i];
        switch (op->kind) {
        case NS_CSS_TFN_TRANSLATE:
            if (op->c != 0 || translate_axis_is_mixed(op, 2)) return TRUE;
            break;
        case NS_CSS_TFN_SCALE:
            if (op->c != 0 && op->c != 1) return TRUE;
            break;
        case NS_CSS_TFN_ROTATE3D:
            if (fabs(op->d) > 1e-12 && (op->a != 0 || op->b != 0)) return TRUE;
            break;
        case NS_CSS_TFN_MATRIX3D:
        case NS_CSS_TFN_PERSPECTIVE:
            return TRUE;
        default:
            break;
        }
    }
    return FALSE;
}

void
ns_css_style_effective_transform(const ns_style *st,
                                 const ns_css_transform *transform_override,
                                 ns_css_transform *out)
{
    memset(out, 0, sizeof(*out));
    static const ns_css_prop independent[3] = {
        NS_CSS_TRANSLATE, NS_CSS_ROTATE, NS_CSS_SCALE,
    };
    for (int i = 0; i < 3; i++) {
        const ns_css_value *v = st ? st->values[independent[i]] : NULL;
        if (v && v->kind == NS_CSS_V_TRANSFORM && v->u.transform.n_ops > 0 &&
            out->n_ops < NS_CSS_TRANSFORM_OPS_MAX)
            out->ops[out->n_ops++] = v->u.transform.ops[0];
    }
    const ns_css_transform *tf = transform_override;
    if (!tf && st && st->values[NS_CSS_TRANSFORM] &&
        st->values[NS_CSS_TRANSFORM]->kind == NS_CSS_V_TRANSFORM)
        tf = &st->values[NS_CSS_TRANSFORM]->u.transform;
    if (tf)
        for (int i = 0; i < tf->n_ops && out->n_ops < NS_CSS_TRANSFORM_OPS_MAX; i++)
            out->ops[out->n_ops++] = tf->ops[i];
}

void
ns_css_transform_to_mat4(const ns_css_transform *tf,
                         double bw, double bh, ns_mat4 *out)
{
    ns_mat4_identity(out);
    if (!tf) return;
    for (int i = 0; i < tf->n_ops; i++) {
        ns_css_transform_op sane = tf->ops[i];
        double dflt = sane.kind == NS_CSS_TFN_SCALE ? 1.0 : 0.0;
        double *fields[] = { &sane.a, &sane.b, &sane.c, &sane.d,
                             &sane.e, &sane.f, &sane.a_pct, &sane.b_pct,
                             &sane.em[0], &sane.em[1], &sane.em[2],
                             &sane.rem[0], &sane.rem[1], &sane.rem[2] };
        for (gsize k = 0; k < G_N_ELEMENTS(fields); k++)
            if (!isfinite(*fields[k])) *fields[k] = dflt;
        const ns_css_transform_op *op = &sane;
        switch (op->kind) {
        case NS_CSS_TFN_TRANSLATE: {
            double dx = (op->a_is_percent ? op->a / 100.0 * bw : op->a) +
                        op->a_pct / 100.0 * bw +
                        (op->em[0] + op->rem[0]) * 16.0;
            double dy = (op->b_is_percent ? op->b / 100.0 * bh : op->b) +
                        op->b_pct / 100.0 * bh +
                        (op->em[1] + op->rem[1]) * 16.0;
            double dz = op->c + (op->em[2] + op->rem[2]) * 16.0;
            ns_mat4_translate(out, dx, dy, dz);
            break;
        }
        case NS_CSS_TFN_ROTATE:
            ns_mat4_rotate_axis(out, 0, 0, 1, op->a);
            break;
        case NS_CSS_TFN_ROTATE3D:
            ns_mat4_rotate_axis(out, op->a, op->b, op->c, op->d);
            break;
        case NS_CSS_TFN_SCALE:
            ns_mat4_scale(out, op->a, op->b, op->c == 0 ? 1 : op->c);
            break;
        case NS_CSS_TFN_SKEW:
            ns_mat4_skew(out, op->a, op->b);
            break;
        case NS_CSS_TFN_MATRIX:
            ns_mat4_affine2d(out, op->a, op->b, op->c, op->d, op->e, op->f);
            break;
        case NS_CSS_TFN_MATRIX3D: {
            ns_mat4 t;
            for (int row = 0; row < 4; row++)
                for (int col = 0; col < 4; col++)
                    t.m[row * 4 + col] = op->m3d[col * 4 + row];
            ns_mat4_multiply(out, &t, out);
            break;
        }
        case NS_CSS_TFN_PERSPECTIVE:
            ns_mat4_perspective(out, op->a);
            break;
        }
    }
}

static ns_css_timing
parse_timing_keyword(const char *kw)
{
    ns_css_timing t = { .kind = NS_CSS_TIMING_EASE };
    if (!kw) return t;
    if (g_ascii_strcasecmp(kw, "linear") == 0)        t.kind = NS_CSS_TIMING_LINEAR;
    else if (g_ascii_strcasecmp(kw, "ease") == 0)     t.kind = NS_CSS_TIMING_EASE;
    else if (g_ascii_strcasecmp(kw, "ease-in") == 0)  t.kind = NS_CSS_TIMING_EASE_IN;
    else if (g_ascii_strcasecmp(kw, "ease-out") == 0) t.kind = NS_CSS_TIMING_EASE_OUT;
    else if (g_ascii_strcasecmp(kw, "ease-in-out") == 0) t.kind = NS_CSS_TIMING_EASE_IN_OUT;
    else if (g_ascii_strcasecmp(kw, "step-start") == 0) {
        t.kind = NS_CSS_TIMING_STEPS; t.steps = 1; t.step_pos = NS_CSS_STEP_JUMP_START;
    } else if (g_ascii_strcasecmp(kw, "step-end") == 0) {
        t.kind = NS_CSS_TIMING_STEPS; t.steps = 1; t.step_pos = NS_CSS_STEP_JUMP_END;
    }
    return t;
}

static gboolean
timing_keyword_matches(const char *kw)
{
    return g_ascii_strcasecmp(kw, "linear") == 0 ||
           g_ascii_strcasecmp(kw, "ease") == 0 ||
           g_ascii_strcasecmp(kw, "ease-in") == 0 ||
           g_ascii_strcasecmp(kw, "ease-out") == 0 ||
           g_ascii_strcasecmp(kw, "ease-in-out") == 0 ||
           g_ascii_strcasecmp(kw, "step-start") == 0 ||
           g_ascii_strcasecmp(kw, "step-end") == 0;
}

static gboolean
parse_time_ms(const char *tok, double *out_ms)
{
    if (!tok) return FALSE;
    char *end = NULL;
    double v = g_ascii_strtod(tok, &end);
    if (end == tok) return FALSE;
    if (g_ascii_strcasecmp(end, "ms") == 0)      *out_ms = v;
    else if (g_ascii_strcasecmp(end, "s") == 0)  *out_ms = v * 1000.0;
    else return FALSE;
    return TRUE;
}

static gboolean css_time_seconds(const char *s, const char *e, double *out);
static gboolean css_starts_math_fn(const char *s, const char *e);
static char *css_time_text(double ms);
static char *anim_string_decode(const char *tok);
static gboolean list_style_split(const char *text, char **out_type,
                                 char **out_position, char **out_image);
static char *css_inline_value_canonical(const char *prop, char *value);
static char *anim_ident_decode(const char *tok);
static int prop_id(const char *name);
static ns_css_value *parse_anim_value(const char *text, gboolean is_animation);
static const char *anim_target_text(const ns_css_anim_entry *e);
static char *anim_entry_longhand_text(const ns_css_anim_entry *e, ns_css_prop lh);
static gboolean anim_range_shorthand_expand(const char *text, char **out_start, char **out_end);
static gboolean anim_range_item_canonical(const char *item, gboolean is_end, char **out);
typedef enum { TVT_INVALID, TVT_NUMBER, TVT_TIME } ns_tval_type;
static ns_tval_type css_time_sum(const char *s, const char *e);

static int
anim_list_split(const char *text, char *items[], int max)
{
    int n = 0;
    if (!text) return 0;
    const char *end = text + strlen(text);
    const char *p = text;
    while (p <= end && n < max) {
        char term = 0;
        const char *seg = css_scan_until(p, end, ",", &term);
        items[n++] = css_trim_dup_range(p, seg);
        if (term != ',') break;
        p = seg + 1;
    }
    return n;
}

static gboolean timing_item_parse(const char *item, ns_css_timing *out);

gboolean
ns_css_timing_parse(const char *text, ns_css_timing *out)
{
    if (!text || !out) return FALSE;
    char *t = g_strstrip(g_strdup(text));
    gboolean ok = timing_item_parse(t, out);
    g_free(t);
    return ok;
}

static gboolean
timing_item_parse(const char *item, ns_css_timing *out)
{
    if (!item || !*item) return FALSE;
    if (timing_keyword_matches(item)) {
        *out = parse_timing_keyword(item);
        return TRUE;
    }
    if (g_ascii_strncasecmp(item, "linear(", 7) == 0 && item[strlen(item) - 1] == ')') {
        *out = (ns_css_timing){ .kind = NS_CSS_TIMING_LINEAR };
        return TRUE;
    }
    gboolean is_steps = g_ascii_strncasecmp(item, "steps(", 6) == 0;
    gboolean is_cubic = g_ascii_strncasecmp(item, "cubic-bezier(", 13) == 0;
    if ((!is_steps && !is_cubic) || item[strlen(item) - 1] != ')') return FALSE;
    char *body = g_strndup(item + (is_steps ? 6 : 13), strlen(item) - (is_steps ? 7 : 14));
    char **parts = g_strsplit(body, ",", -1);
    guint np = g_strv_length(parts);
    gboolean ok = FALSE;
    if (is_steps && (np == 1 || np == 2)) {
        char *e = NULL;
        long n = strtol(g_strstrip(parts[0]), &e, 10);
        if (e != parts[0] && *e == '\0' && n >= 1) {
            ns_css_step_pos pos = NS_CSS_STEP_JUMP_END;
            ok = TRUE;
            gboolean jump_kw = FALSE;
            if (np == 2) {
                const char *k = g_strstrip(parts[1]);
                jump_kw = g_ascii_strncasecmp(k, "jump-", 5) == 0;
                if (g_ascii_strcasecmp(k, "jump-start") == 0 ||
                    g_ascii_strcasecmp(k, "start") == 0) pos = NS_CSS_STEP_JUMP_START;
                else if (g_ascii_strcasecmp(k, "jump-end") == 0 ||
                         g_ascii_strcasecmp(k, "end") == 0) pos = NS_CSS_STEP_JUMP_END;
                else if (g_ascii_strcasecmp(k, "jump-none") == 0) pos = NS_CSS_STEP_JUMP_NONE;
                else if (g_ascii_strcasecmp(k, "jump-both") == 0) pos = NS_CSS_STEP_JUMP_BOTH;
                else ok = FALSE;
            }
            if (ok && pos == NS_CSS_STEP_JUMP_NONE && n < 2) ok = FALSE;
            if (ok) *out = (ns_css_timing){ .kind = NS_CSS_TIMING_STEPS,
                                            .steps = (int)n, .step_pos = pos,
                                            .jump_keyword = jump_kw };
        }
    } else if (is_cubic && np == 4) {
        double cb[4];
        ok = TRUE;
        for (int i = 0; i < 4 && ok; i++) {
            char *e = NULL;
            cb[i] = g_ascii_strtod(g_strstrip(parts[i]), &e);
            if (e == parts[i] || *e != '\0') ok = FALSE;
        }
        if (ok && (cb[0] < 0 || cb[0] > 1 || cb[2] < 0 || cb[2] > 1)) ok = FALSE;
        if (ok) {
            *out = (ns_css_timing){ .kind = NS_CSS_TIMING_CUBIC };
            memcpy(out->cb, cb, sizeof cb);
        }
    }
    g_strfreev(parts);
    g_free(body);
    return ok;
}

static gboolean
css_wide_keyword_or_default(const char *item)
{
    static const char *const words[] = { "initial", "inherit", "unset", "revert",
                                         "revert-layer", "default" };
    for (gsize i = 0; i < G_N_ELEMENTS(words); i++)
        if (g_ascii_strcasecmp(item, words[i]) == 0) return TRUE;
    return FALSE;
}

static gboolean
anim_longhand_item_valid(ns_css_prop prop, const char *item)
{
    ns_css_timing tm;
    char *e = NULL;
    double num;
    switch (prop) {
    case NS_CSS_ANIMATION_NAME:
        if (g_ascii_strcasecmp(item, "none") == 0) return TRUE;
        if (item[0] == '"' || item[0] == '\'') return strlen(item) >= 3 &&
            item[strlen(item) - 1] == item[0];
        {
            char *ident = anim_ident_decode(item);
            gboolean ok = ident && *ident && !css_wide_keyword_or_default(ident) &&
                          !g_ascii_isdigit((guchar)item[0]) &&
                          !(item[0] == '-' && g_ascii_isdigit((guchar)item[1]));
            g_free(ident);
            return ok;
        }
    case NS_CSS_ANIMATION_TIMING_FUNCTION:
    case NS_CSS_TRANSITION_TIMING_FUNCTION:
        return timing_item_parse(item, &tm);
    case NS_CSS_ANIMATION_ITERATION_COUNT:
        if (g_ascii_strcasecmp(item, "infinite") == 0) return TRUE;
        num = g_ascii_strtod(item, &e);
        return e != item && *e == '\0' && num >= 0;
    case NS_CSS_ANIMATION_DIRECTION:
        return g_ascii_strcasecmp(item, "normal") == 0 ||
               g_ascii_strcasecmp(item, "reverse") == 0 ||
               g_ascii_strcasecmp(item, "alternate") == 0 ||
               g_ascii_strcasecmp(item, "alternate-reverse") == 0;
    case NS_CSS_ANIMATION_FILL_MODE:
        return g_ascii_strcasecmp(item, "none") == 0 ||
               g_ascii_strcasecmp(item, "forwards") == 0 ||
               g_ascii_strcasecmp(item, "backwards") == 0 ||
               g_ascii_strcasecmp(item, "both") == 0;
    case NS_CSS_TRANSITION_PROPERTY:
        return g_ascii_strcasecmp(item, "none") == 0 ||
               g_ascii_strcasecmp(item, "all") == 0 ||
               (content_ident_valid(item) && !css_wide_keyword_or_default(item));
    case NS_CSS_TRANSITION_BEHAVIOR:
        return g_ascii_strcasecmp(item, "normal") == 0 ||
               g_ascii_strcasecmp(item, "allow-discrete") == 0;
    case NS_CSS_ANIMATION_PLAY_STATE:
        return g_ascii_strcasecmp(item, "running") == 0 ||
               g_ascii_strcasecmp(item, "paused") == 0;
    case NS_CSS_ANIMATION_COMPOSITION:
        return g_ascii_strcasecmp(item, "replace") == 0 ||
               g_ascii_strcasecmp(item, "add") == 0 ||
               g_ascii_strcasecmp(item, "accumulate") == 0;
    case NS_CSS_ANIMATION_TIMELINE:
        return ns_css_timeline_parse(item, NULL);
    case NS_CSS_ANIMATION_RANGE_START:
    case NS_CSS_ANIMATION_RANGE_END:
        return anim_range_item_canonical(item, prop == NS_CSS_ANIMATION_RANGE_END,
                                         NULL);
    default:
        return FALSE;
    }
}

static const char *const kTimelineRangeNames[] = {
    "cover", "contain", "entry", "exit", "entry-crossing", "exit-crossing",
};

static gboolean
anim_range_is_name(const char *tok)
{
    for (gsize i = 0; i < G_N_ELEMENTS(kTimelineRangeNames); i++)
        if (g_ascii_strcasecmp(tok, kTimelineRangeNames[i]) == 0) return TRUE;
    return FALSE;
}

static char *
anim_range_lp_canonical(const char *tok)
{
    if (!tok || !*tok) return NULL;
    if (css_starts_math_fn(tok, tok + strlen(tok))) {
        char *m = ns_css_math_canonical(tok);
        if (!m) {
            gsize len = strlen(tok);
            if (len < 3 || tok[len - 1] != ')' || strstr(tok, "s)") || strstr(tok, "deg"))
                return NULL;
            return g_strdup(tok);
        }
        static const char *const bad_units[] = { "s", "ms", "deg", "rad", "turn", "hz" };
        if (math_text_has_unit(m, bad_units, G_N_ELEMENTS(bad_units))) {
            g_free(m);
            return NULL;
        }
        return m;
    }
    double v;
    ns_css_unit u;
    if (!parse_length(tok, &v, &u)) return NULL;
    if (u == NS_CSS_UNIT_NUMBER) {
        if (v != 0) return NULL;
        return g_strdup("0px");
    }
    char *unit_start = NULL;
    g_ascii_strtod(tok, &unit_start);
    char *num = ns_css_number_str(v);
    char *unit = g_ascii_strdown(unit_start, -1);
    char *r = g_strconcat(num, unit, NULL);
    g_free(num);
    g_free(unit);
    return r;
}

static gboolean
anim_range_item_canonical(const char *item, gboolean is_end, char **out)
{
    char *toks[4] = { 0 };
    int n = split_ws_limit(item, toks, 4);
    gboolean ok = FALSE;
    char *result = NULL;
    if (n == 1 && g_ascii_strcasecmp(toks[0], "normal") == 0) {
        ok = TRUE;
        result = g_strdup("normal");
    } else if (n == 1 && anim_range_is_name(toks[0])) {
        ok = TRUE;
        result = g_ascii_strdown(toks[0], -1);
    } else if (n == 1) {
        result = anim_range_lp_canonical(toks[0]);
        ok = result != NULL;
    } else if (n == 2 && anim_range_is_name(toks[0])) {
        char *lp = anim_range_lp_canonical(toks[1]);
        if (lp) {
            ok = TRUE;
            const char *dflt = is_end ? "100%" : "0%";
            char *name = g_ascii_strdown(toks[0], -1);
            result = strcmp(lp, dflt) == 0 ? g_strdup(name)
                                           : g_strconcat(name, " ", lp, NULL);
            g_free(name);
            g_free(lp);
        }
    }
    for (int i = 0; i < n; i++) g_free(toks[i]);
    if (out) *out = ok ? result : NULL;
    else g_free(result);
    return ok;
}

static const char *const kScrollAxisNames[] = { "block", "inline", "x", "y" };
static const char *const kScrollerNames[] = { "nearest", "root", "self" };

static int
keyword_index(const char *tok, const char *const *names, int n)
{
    for (int i = 0; tok && i < n; i++)
        if (g_ascii_strcasecmp(tok, names[i]) == 0) return i;
    return -1;
}

gboolean
ns_css_scroll_axis_parse(const char *item, ns_css_scroll_axis *out)
{
    int i = keyword_index(item, kScrollAxisNames, G_N_ELEMENTS(kScrollAxisNames));
    if (i < 0) return FALSE;
    if (out) *out = (ns_css_scroll_axis)i;
    return TRUE;
}

static gboolean
timeline_dashed_ident(const char *item)
{
    return item[0] == '-' && item[1] == '-' && content_ident_valid(item);
}

static gboolean
scroll_timeline_name_item_valid(const char *item)
{
    return g_ascii_strcasecmp(item, "none") == 0 || timeline_dashed_ident(item);
}

static gboolean
scroll_notation_token(const char *tok, ns_css_timeline *t, guint *seen)
{
    int scroller = keyword_index(tok, kScrollerNames, G_N_ELEMENTS(kScrollerNames));
    if (!(*seen & 1) && ns_css_scroll_axis_parse(tok, &t->axis)) {
        *seen |= 1;
        return TRUE;
    }
    if ((*seen & 2) || scroller < 0) return FALSE;
    t->scroller = (ns_css_scroller)scroller;
    *seen |= 2;
    return TRUE;
}

static gboolean
scroll_notation_parse(const char *item, gsize len, ns_css_timeline *t)
{
    char *args = g_strndup(item + 7, len - 8);
    char *toks[3] = { 0 };
    int n = split_ws_limit(args, toks, 3);
    guint seen = 0;
    gboolean ok = n <= 2;
    for (int i = 0; i < n; i++) {
        if (ok) ok = scroll_notation_token(toks[i], t, &seen);
        g_free(toks[i]);
    }
    g_free(args);
    return ok;
}

static gboolean
timeline_function_parse(const char *item, ns_css_timeline *t)
{
    gsize len = strlen(item);
    if (len < 2 || item[len - 1] != ')') return FALSE;
    if (g_ascii_strncasecmp(item, "view(", 5) == 0) {
        t->kind = NS_CSS_TIMELINE_VIEW;
        return TRUE;
    }
    if (g_ascii_strncasecmp(item, "scroll(", 7) != 0) return FALSE;
    t->kind = NS_CSS_TIMELINE_SCROLL;
    return scroll_notation_parse(item, len, t);
}

gboolean
ns_css_timeline_parse(const char *item, ns_css_timeline *out)
{
    ns_css_timeline t = { 0 };
    gboolean ok = TRUE;
    if (!item || !*item) return FALSE;
    if (g_ascii_strcasecmp(item, "none") == 0) {
        t.kind = NS_CSS_TIMELINE_NONE;
    } else if (timeline_dashed_ident(item)) {
        t.kind = NS_CSS_TIMELINE_NAMED;
    } else if (g_ascii_strcasecmp(item, "auto") != 0) {
        ok = timeline_function_parse(item, &t);
    }
    if (ok && out) *out = t;
    return ok;
}

static char *
timeline_scroll_serialize(const ns_css_timeline *t)
{
    GString *out = g_string_new("scroll(");
    gboolean scroller = t->scroller != NS_CSS_SCROLLER_NEAREST;
    if (scroller) g_string_append(out, kScrollerNames[t->scroller]);
    if (t->axis != NS_CSS_SCROLL_AXIS_BLOCK) {
        if (scroller) g_string_append_c(out, ' ');
        g_string_append(out, kScrollAxisNames[t->axis]);
    }
    g_string_append_c(out, ')');
    return g_string_free(out, FALSE);
}

static char *
anim_timeline_item_canonical(const char *item)
{
    ns_css_timeline t;
    if (!ns_css_timeline_parse(item, &t)) return NULL;
    if (t.kind == NS_CSS_TIMELINE_SCROLL) return timeline_scroll_serialize(&t);
    if (t.kind == NS_CSS_TIMELINE_NAMED) return g_strdup(item);
    return g_ascii_strdown(item, -1);
}

static gboolean
anim_item_has_canonical(ns_css_prop prop)
{
    return prop == NS_CSS_ANIMATION_RANGE_START ||
           prop == NS_CSS_ANIMATION_RANGE_END ||
           prop == NS_CSS_ANIMATION_TIMELINE;
}

static char *
anim_item_canonical(ns_css_prop prop, const char *item)
{
    char *c = NULL;
    if (prop == NS_CSS_ANIMATION_TIMELINE) return anim_timeline_item_canonical(item);
    anim_range_item_canonical(item, prop == NS_CSS_ANIMATION_RANGE_END, &c);
    return c;
}

static ns_css_value *
keyword_value_take(GString *canon, gboolean ok)
{
    if (!ok) {
        g_string_free(canon, TRUE);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_KEYWORD;
    v->u.keyword = g_string_free(canon, FALSE);
    return v;
}

static ns_css_value *
parse_scroll_timeline_longhand(ns_css_prop prop, const char *t)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(t, items, (int)G_N_ELEMENTS(items));
    gboolean names = prop != NS_CSS_SCROLL_TIMELINE_AXIS;
    gboolean ok = n > 0;
    GString *canon = g_string_new(NULL);
    for (int i = 0; i < n; i++) {
        ns_css_scroll_axis axis = NS_CSS_SCROLL_AXIS_BLOCK;
        if (ok) ok = names ? scroll_timeline_name_item_valid(items[i])
                           : ns_css_scroll_axis_parse(items[i], &axis);
        if (i) g_string_append(canon, ", ");
        if (names && g_ascii_strcasecmp(items[i], "none") != 0)
            g_string_append(canon, items[i]);
        else
            g_string_append(canon, names ? "none" : kScrollAxisNames[axis]);
        g_free(items[i]);
    }
    return keyword_value_take(canon, ok);
}

static const char *const kTimelineScopeKeywords[] = { "none", "all" };

static ns_css_value *
parse_timeline_scope(const char *t)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(t, items, (int)G_N_ELEMENTS(items));
    int keyword = n == 1 ? keyword_index(items[0], kTimelineScopeKeywords,
                                         G_N_ELEMENTS(kTimelineScopeKeywords))
                         : -1;
    gboolean ok = n > 0;
    GString *canon = g_string_new(NULL);
    for (int i = 0; i < n; i++) {
        if (ok) ok = keyword >= 0 || timeline_dashed_ident(items[i]);
        if (i) g_string_append(canon, ", ");
        g_string_append(canon, keyword >= 0 ? kTimelineScopeKeywords[keyword]
                                            : items[i]);
        g_free(items[i]);
    }
    return keyword_value_take(canon, ok);
}

static int
style_list_items(const ns_style *s, ns_css_prop prop, char *items[], int max)
{
    const ns_css_value *v = s ? s->values[prop] : NULL;
    if (!v || v->kind != NS_CSS_V_KEYWORD || !v->u.keyword) return 0;
    return anim_list_split(v->u.keyword, items, max);
}

int
ns_css_timeline_name_index(const ns_style *s, ns_css_prop prop, const char *name)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    const ns_css_value *v = s && name ? s->values[prop] : NULL;
    if (!v || v->kind != NS_CSS_V_KEYWORD || !v->u.keyword ||
        !strstr(v->u.keyword, name))
        return -1;
    int n = style_list_items(s, prop, items, (int)G_N_ELEMENTS(items));
    int found = -1;
    for (int i = 0; i < n; i++) {
        if (found < 0 && strcmp(items[i], name) == 0) found = i;
        g_free(items[i]);
    }
    return found;
}

char *
ns_css_timeline_name_at(const ns_style *s, int index)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = style_list_items(s, NS_CSS_ANIMATION_TIMELINE, items,
                             (int)G_N_ELEMENTS(items));
    const char *item = n > 0 && index >= 0 ? items[index % n] : NULL;
    char *name = item && timeline_dashed_ident(item) ? g_strdup(item) : NULL;
    for (int i = 0; i < n; i++) g_free(items[i]);
    return name;
}

ns_css_scroll_axis
ns_css_timeline_axis_at(const ns_style *s, int index)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = style_list_items(s, NS_CSS_SCROLL_TIMELINE_AXIS, items,
                             (int)G_N_ELEMENTS(items));
    ns_css_scroll_axis axis = NS_CSS_SCROLL_AXIS_BLOCK;
    if (n > 0 && index >= 0) ns_css_scroll_axis_parse(items[index % n], &axis);
    for (int i = 0; i < n; i++) g_free(items[i]);
    return axis;
}

static ns_css_value *
parse_animation_duration(const char *t)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(t, items, (int)G_N_ELEMENTS(items));
    gboolean ok = n > 0;
    GString *canon = g_string_new(NULL);
    for (int i = 0; i < n; i++) {
        if (ok) {
            if (i) g_string_append(canon, ", ");
            char *spec = NULL;
            if (g_ascii_strcasecmp(items[i], "auto") == 0) {
                g_string_append(canon, "auto");
            } else if ((spec = ns_css_time_specified(items[i]))) {
                g_string_append(canon, spec);
                g_free(spec);
            } else if (css_time_sum(items[i], items[i] + strlen(items[i])) == TVT_TIME) {
                g_string_append(canon, items[i]);
            } else {
                ok = FALSE;
            }
        }
        g_free(items[i]);
    }
    if (!ok) {
        g_string_free(canon, TRUE);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_KEYWORD;
    v->u.keyword = g_string_free(canon, FALSE);
    return v;
}

char *
ns_css_ident_serialize(const char *name)
{
    if (!name) return g_strdup("");
    GString *out = g_string_new(NULL);
    for (const char *p = name; *p; p++) {
        guchar c = (guchar)*p;
        gboolean first = p == name;
        if (c == '\0') {
            g_string_append(out, "\xef\xbf\xbd");
        } else if (c <= 0x1f || c == 0x7f) {
            g_string_append_printf(out, "\\%x ", c);
        } else if (first && g_ascii_isdigit(c)) {
            g_string_append_printf(out, "\\%x ", c);
        } else if (first && c == '-' && g_ascii_isdigit((guchar)p[1])) {
            g_string_append_c(out, '-');
            p++;
            g_string_append_printf(out, "\\%x ", (guchar)*p);
        } else if (first && c == '-' && !p[1]) {
            g_string_append(out, "\\-");
        } else if (c >= 0x80 || c == '-' || c == '_' || g_ascii_isalnum(c)) {
            g_string_append_c(out, (char)c);
        } else {
            g_string_append_c(out, '\\');
            g_string_append_c(out, (char)c);
        }
    }
    return g_string_free(out, FALSE);
}

static ns_css_value *
parse_anim_longhand(ns_css_prop prop, const char *t)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(t, items, (int)G_N_ELEMENTS(items));
    gboolean ok = n > 0;
    gboolean lower = prop != NS_CSS_ANIMATION_NAME && prop != NS_CSS_ANIMATION_TIMELINE;
    gboolean special = anim_item_has_canonical(prop);
    GString *canon = g_string_new(NULL);
    for (int i = 0; i < n; i++) {
        if (!*items[i] || !anim_longhand_item_valid(prop, items[i])) ok = FALSE;
        if (ok && n > 1 && prop == NS_CSS_TRANSITION_PROPERTY &&
            g_ascii_strcasecmp(items[i], "none") == 0) ok = FALSE;
        if (ok) {
            if (i) g_string_append(canon, ", ");
            if (special) {
                char *c = anim_item_canonical(prop, items[i]);
                g_string_append(canon, c ? c : items[i]);
                g_free(c);
            } else if (prop == NS_CSS_ANIMATION_NAME) {
                if (g_ascii_strcasecmp(items[i], "none") == 0) g_string_append(canon, "none");
                else if (items[i][0] == '"' || items[i][0] == '\'') {
                    char *inner = anim_string_decode(items[i]);
                    if (css_wide_keyword_or_default(inner) ||
                        g_ascii_strcasecmp(inner, "none") == 0) {
                        g_string_append_c(canon, '"');
                        g_string_append(canon, inner);
                        g_string_append_c(canon, '"');
                    } else {
                        char *ident = ns_css_ident_serialize(inner);
                        g_string_append(canon, ident);
                        g_free(ident);
                    }
                    g_free(inner);
                } else {
                    char *ident = anim_ident_decode(items[i]);
                    char *ser = ns_css_ident_serialize(ident ? ident : items[i]);
                    g_string_append(canon, ser);
                    g_free(ser);
                    g_free(ident);
                }
            } else if (lower) {
                char *l = g_ascii_strdown(items[i], -1);
                g_string_append(canon, l);
                g_free(l);
            } else {
                g_string_append(canon, items[i]);
            }
        }
        g_free(items[i]);
    }
    if (!ok) {
        g_string_free(canon, TRUE);
        return NULL;
    }
    ns_css_value *v = g_new0(ns_css_value, 1);
    v->kind = NS_CSS_V_KEYWORD;
    v->u.keyword = g_string_free(canon, FALSE);
    return v;
}

static void
anim_entry_init(ns_css_anim_entry *e, gboolean is_animation)
{
    memset(e, 0, sizeof *e);
    e->target = is_animation ? NS_CSS_ANIM_TARGET_ALL : NS_CSS_ANIM_TARGET_ALL;
    e->timing = (ns_css_timing){ .kind = NS_CSS_TIMING_EASE };
    e->iterations = 1;
}

static void
anim_entry_set_target(ns_css_anim_entry *e, const char *tok, gboolean is_animation)
{
    g_free(e->name);
    e->name = NULL;
    if (is_animation) {
        e->target = NS_CSS_ANIM_TARGET_ALL;
        if (g_ascii_strcasecmp(tok, "none") != 0) {
            if ((tok[0] == '"' || tok[0] == '\'') && strlen(tok) >= 2)
                e->name = anim_string_decode(tok);
            else {
                e->name = anim_ident_decode(tok);
                if (!e->name) e->name = g_strdup(tok);
            }
        }
        return;
    }
    if (g_ascii_strcasecmp(tok, "none") == 0) e->target = NS_CSS_ANIM_TARGET_NONE;
    else if (g_ascii_strcasecmp(tok, "all") == 0) e->target = NS_CSS_ANIM_TARGET_ALL;
    else if (g_ascii_strcasecmp(tok, "opacity") == 0) e->target = NS_CSS_ANIM_TARGET_OPACITY;
    else if (g_ascii_strcasecmp(tok, "transform") == 0) e->target = NS_CSS_ANIM_TARGET_TRANSFORM;
    else if (g_ascii_strcasecmp(tok, "color") == 0) e->target = NS_CSS_ANIM_TARGET_COLOR;
    else if (g_ascii_strcasecmp(tok, "background-color") == 0 ||
             g_ascii_strcasecmp(tok, "background") == 0)
        e->target = NS_CSS_ANIM_TARGET_BG_COLOR;
    else {
        e->target = NS_CSS_ANIM_TARGET_OTHER;
        e->name = ascii_lower(tok, strlen(tok));
    }
}

static void
anim_apply_longhand(ns_css_anim_list *out, const ns_css_value *v, ns_css_prop prop)
{
    if (!v || v->kind != NS_CSS_V_KEYWORD || !v->u.keyword || out->n == 0) return;
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(v->u.keyword, items, (int)G_N_ELEMENTS(items));
    if (n == 0) return;
    for (int i = 0; i < out->n; i++) {
        ns_css_anim_entry *e = &out->entries[i];
        const char *item = items[i % n];
        double sec;
        switch (prop) {
        case NS_CSS_ANIMATION_DURATION:
        case NS_CSS_TRANSITION_DURATION:
            if (g_ascii_strcasecmp(item, "auto") == 0) {
                e->duration_ms = 0;
                e->duration_auto = TRUE;
            } else if (css_time_seconds(item, item + strlen(item), &sec) && isfinite(sec)) {
                e->duration_ms = MAX(sec, 0.0) * 1000.0;
                e->duration_auto = FALSE;
            }
            break;
        case NS_CSS_ANIMATION_DELAY:
        case NS_CSS_TRANSITION_DELAY:
            if (css_time_seconds(item, item + strlen(item), &sec) && isfinite(sec))
                e->delay_ms = sec * 1000.0;
            break;
        case NS_CSS_ANIMATION_TIMING_FUNCTION:
        case NS_CSS_TRANSITION_TIMING_FUNCTION:
            timing_item_parse(item, &e->timing);
            break;
        case NS_CSS_ANIMATION_ITERATION_COUNT:
            if (g_ascii_strcasecmp(item, "infinite") == 0) {
                e->iterations = INFINITY;
            } else {
                double num = g_ascii_strtod(item, NULL);
                e->iterations = num < 0 ? 0 : num;
            }
            break;
        case NS_CSS_ANIMATION_DIRECTION:
            if (g_ascii_strcasecmp(item, "reverse") == 0) e->direction = NS_CSS_ANIM_DIR_REVERSE;
            else if (g_ascii_strcasecmp(item, "alternate") == 0) e->direction = NS_CSS_ANIM_DIR_ALTERNATE;
            else if (g_ascii_strcasecmp(item, "alternate-reverse") == 0)
                e->direction = NS_CSS_ANIM_DIR_ALTERNATE_REVERSE;
            else e->direction = NS_CSS_ANIM_DIR_NORMAL;
            break;
        case NS_CSS_ANIMATION_FILL_MODE:
            if (g_ascii_strcasecmp(item, "forwards") == 0) e->fill = NS_CSS_ANIM_FILL_FORWARDS;
            else if (g_ascii_strcasecmp(item, "backwards") == 0) e->fill = NS_CSS_ANIM_FILL_BACKWARDS;
            else if (g_ascii_strcasecmp(item, "both") == 0) e->fill = NS_CSS_ANIM_FILL_BOTH;
            else e->fill = NS_CSS_ANIM_FILL_NONE;
            break;
        case NS_CSS_ANIMATION_PLAY_STATE:
            e->paused = g_ascii_strcasecmp(item, "paused") == 0;
            break;
        case NS_CSS_TRANSITION_BEHAVIOR:
            e->allow_discrete = g_ascii_strcasecmp(item, "allow-discrete") == 0;
            break;
        default:
            break;
        }
    }
    for (int i = 0; i < n; i++) g_free(items[i]);
}

static void
anim_apply_timelines(ns_css_anim_list *out, const ns_css_value *v,
                     gboolean duration_unset)
{
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    if (!v || v->kind != NS_CSS_V_KEYWORD || !v->u.keyword) return;
    int n = anim_list_split(v->u.keyword, items, (int)G_N_ELEMENTS(items));
    for (int i = 0; i < out->n && n > 0; i++) {
        ns_css_anim_entry *e = &out->entries[i];
        ns_css_timeline_parse(items[i % n], &e->timeline);
        e->duration_auto |= duration_unset &&
                            e->timeline.kind != NS_CSS_TIMELINE_AUTO;
    }
    for (int i = 0; i < n; i++) g_free(items[i]);
}

void
ns_css_anim_list_clear(ns_css_anim_list *list)
{
    if (!list) return;
    for (int i = 0; i < list->n; i++) g_free(list->entries[i].name);
    list->n = 0;
}

static int
anim_longhand_count(const ns_css_value *v)
{
    if (!v || v->kind != NS_CSS_V_KEYWORD || !v->u.keyword) return 0;
    char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
    int n = anim_list_split(v->u.keyword, items, (int)G_N_ELEMENTS(items));
    for (int i = 0; i < n; i++) g_free(items[i]);
    return n;
}

static void
anim_build_list(const ns_style *s, gboolean is_animation, int n,
                ns_css_anim_list *out)
{
    memset(out, 0, sizeof *out);
    if (n > NS_CSS_ANIM_ENTRIES_MAX) n = NS_CSS_ANIM_ENTRIES_MAX;
    for (int i = 0; i < n; i++) anim_entry_init(&out->entries[i], is_animation);
    out->n = n;
    if (n == 0) return;
    const ns_css_value *names =
        s->values[is_animation ? NS_CSS_ANIMATION_NAME : NS_CSS_TRANSITION_PROPERTY];
    if (names && names->kind == NS_CSS_V_KEYWORD && names->u.keyword) {
        char *items[NS_CSS_ANIM_ENTRIES_MAX * 4];
        int k = anim_list_split(names->u.keyword, items, (int)G_N_ELEMENTS(items));
        for (int i = 0; i < n && k > 0; i++)
            anim_entry_set_target(&out->entries[i], items[i % k], is_animation);
        for (int i = 0; i < k; i++) g_free(items[i]);
    } else if (is_animation) {
        for (int i = 0; i < n; i++) out->entries[i].name = NULL;
    }
    if (is_animation) {
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_DURATION], NS_CSS_ANIMATION_DURATION);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_DELAY], NS_CSS_ANIMATION_DELAY);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_TIMING_FUNCTION],
                            NS_CSS_ANIMATION_TIMING_FUNCTION);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_ITERATION_COUNT],
                            NS_CSS_ANIMATION_ITERATION_COUNT);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_DIRECTION], NS_CSS_ANIMATION_DIRECTION);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_FILL_MODE], NS_CSS_ANIMATION_FILL_MODE);
        anim_apply_longhand(out, s->values[NS_CSS_ANIMATION_PLAY_STATE], NS_CSS_ANIMATION_PLAY_STATE);
        anim_apply_timelines(out, s->values[NS_CSS_ANIMATION_TIMELINE],
                             !s->values[NS_CSS_ANIMATION_DURATION]);
    } else {
        anim_apply_longhand(out, s->values[NS_CSS_TRANSITION_DURATION], NS_CSS_TRANSITION_DURATION);
        anim_apply_longhand(out, s->values[NS_CSS_TRANSITION_DELAY], NS_CSS_TRANSITION_DELAY);
        anim_apply_longhand(out, s->values[NS_CSS_TRANSITION_TIMING_FUNCTION],
                            NS_CSS_TRANSITION_TIMING_FUNCTION);
        anim_apply_longhand(out, s->values[NS_CSS_TRANSITION_BEHAVIOR], NS_CSS_TRANSITION_BEHAVIOR);
    }
}

static const ns_css_prop *
anim_longhand_props(gboolean is_animation, gsize *n)
{
    static const ns_css_prop anim[] = {
        NS_CSS_ANIMATION_NAME, NS_CSS_ANIMATION_DURATION, NS_CSS_ANIMATION_DELAY,
        NS_CSS_ANIMATION_TIMING_FUNCTION, NS_CSS_ANIMATION_ITERATION_COUNT,
        NS_CSS_ANIMATION_DIRECTION, NS_CSS_ANIMATION_FILL_MODE,
        NS_CSS_ANIMATION_PLAY_STATE,
    };
    static const ns_css_prop trans[] = {
        NS_CSS_TRANSITION_PROPERTY, NS_CSS_TRANSITION_DURATION,
        NS_CSS_TRANSITION_DELAY, NS_CSS_TRANSITION_TIMING_FUNCTION,
        NS_CSS_TRANSITION_BEHAVIOR,
    };
    *n = is_animation ? G_N_ELEMENTS(anim) : G_N_ELEMENTS(trans);
    return is_animation ? anim : trans;
}

gboolean
ns_css_style_may_animate(const ns_style *s)
{
    if (!s) return FALSE;
    if (s->animation_hint) return s->animation_hint == 2;
    gboolean may = s->values[NS_CSS_ANIMATION_NAME] != NULL;
    gsize count;
    const ns_css_prop *lh = anim_longhand_props(FALSE, &count);
    for (gsize i = 0; !may && i < count; i++)
        if (s->values[lh[i]]) may = TRUE;
    ((ns_style *)s)->animation_hint = may ? 2 : 1;
    return may;
}

void
ns_css_anim_effective(const ns_style *s, gboolean is_animation, ns_css_anim_list *out)
{
    memset(out, 0, sizeof *out);
    if (!s) return;
    int n;
    if (is_animation) {
        n = anim_longhand_count(s->values[NS_CSS_ANIMATION_NAME]);
    } else {
        n = anim_longhand_count(s->values[NS_CSS_TRANSITION_PROPERTY]);
        if (!s->values[NS_CSS_TRANSITION_PROPERTY]) {
            gsize count;
            const ns_css_prop *lh = anim_longhand_props(FALSE, &count);
            for (gsize i = 0; i < count; i++)
                n = MAX(n, anim_longhand_count(s->values[lh[i]]));
        }
    }
    anim_build_list(s, is_animation, n, out);
}

void
ns_css_anim_lists(const ns_style *s, gboolean is_animation, ns_css_anim_list *out,
                  gboolean *out_mismatch)
{
    memset(out, 0, sizeof *out);
    if (out_mismatch) *out_mismatch = FALSE;
    if (!s) return;
    gsize count;
    const ns_css_prop *lh = anim_longhand_props(is_animation, &count);
    int n = 0;
    for (gsize i = 0; i < count; i++)
        n = MAX(n, anim_longhand_count(s->values[lh[i]]));
    for (gsize i = 0; i < count; i++) {
        int c = anim_longhand_count(s->values[lh[i]]);
        if (c > 0 && c != n && out_mismatch) *out_mismatch = TRUE;
    }
    anim_build_list(s, is_animation, n, out);
}

static void
anim_append_part(GString *out, char *part)
{
    if (out->len > 0 && out->str[out->len - 1] != ' ' && out->str[out->len - 1] != ',')
        g_string_append_c(out, ' ');
    g_string_append(out, part);
    g_free(part);
}

char *
ns_css_anim_shorthand_serialize(const ns_css_anim_list *list, gboolean is_animation)
{
    GString *out = g_string_new(NULL);
    if (!list || list->n == 0) return g_string_free(out, FALSE);
    for (int i = 0; i < list->n; i++) {
        const ns_css_anim_entry *e = &list->entries[i];
        if (i) g_string_append(out, ", ");
        GString *entry = g_string_new(NULL);
        if (is_animation) {
            if (!e->duration_auto || e->delay_ms != 0)
                anim_append_part(entry, anim_entry_longhand_text(e, NS_CSS_ANIMATION_DURATION));
            if (e->timing.kind != NS_CSS_TIMING_EASE)
                anim_append_part(entry, ns_css_timing_serialize(&e->timing));
            if (e->delay_ms != 0)
                anim_append_part(entry, css_time_text(e->delay_ms));
            if (e->iterations != 1)
                anim_append_part(entry, anim_entry_longhand_text(e, NS_CSS_ANIMATION_ITERATION_COUNT));
            if (e->direction != NS_CSS_ANIM_DIR_NORMAL)
                anim_append_part(entry, anim_entry_longhand_text(e, NS_CSS_ANIMATION_DIRECTION));
            if (e->fill != NS_CSS_ANIM_FILL_NONE)
                anim_append_part(entry, anim_entry_longhand_text(e, NS_CSS_ANIMATION_FILL_MODE));
            if (e->paused)
                anim_append_part(entry, g_strdup("paused"));
            if (e->name)
                anim_append_part(entry, ns_css_ident_serialize(e->name));
            if (entry->len == 0) g_string_append(entry, "none");
        } else {
            if (e->target != NS_CSS_ANIM_TARGET_ALL)
                anim_append_part(entry, g_strdup(anim_target_text(e)));
            if (e->duration_ms != 0 || e->delay_ms != 0)
                anim_append_part(entry, css_time_text(e->duration_ms));
            if (e->timing.kind != NS_CSS_TIMING_EASE)
                anim_append_part(entry, ns_css_timing_serialize(&e->timing));
            if (e->delay_ms != 0)
                anim_append_part(entry, css_time_text(e->delay_ms));
            if (e->allow_discrete)
                anim_append_part(entry, g_strdup("allow-discrete"));
            if (entry->len == 0) g_string_append(entry, "all");
        }
        g_string_append(out, entry->str);
        g_string_free(entry, TRUE);
    }
    return g_string_free(out, FALSE);
}

char *
ns_css_animation_shorthand_canonical(const char *text, gboolean is_animation)
{
    ns_css_value *v = parse_anim_value(text, is_animation);
    if (!v) return NULL;
    char *r = ns_css_anim_shorthand_serialize(&v->u.anim, is_animation);
    ns_css_value_free(v);
    return r;
}

