typedef struct {
    GHashTable *keys;
    GPtrArray  *attrs;
    gboolean    whole;
} incr_inv_set;

static void
incr_inv_set_free(gpointer data)
{
    incr_inv_set *inv = data;
    g_hash_table_destroy(inv->keys);
    g_ptr_array_free(inv->attrs, TRUE);
    g_free(inv);
}

static incr_inv_set *
incr_inv_get(char prefix, const char *name)
{
    if (!g_inv_sets)
        g_inv_sets = g_hash_table_new_full(g_str_hash, g_str_equal, g_free,
                                           incr_inv_set_free);
    char *key = g_strdup_printf("%c%s", prefix, name);
    incr_inv_set *inv = g_hash_table_lookup(g_inv_sets, key);
    if (inv) {
        g_free(key);
        return inv;
    }
    inv = g_new0(incr_inv_set, 1);
    inv->keys = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
    inv->attrs = g_ptr_array_new_with_free_func(g_free);
    g_hash_table_insert(g_inv_sets, key, inv);
    return inv;
}

static void
incr_inv_add_subject(incr_inv_set *inv, const ns_css_simple *subject)
{
    if (inv->whole) return;
    if (subject->id && *subject->id) {
        g_hash_table_add(inv->keys, g_strconcat("#", subject->id, NULL));
    } else if (subject->classes && subject->classes->len > 0 &&
               g_ptr_array_index(subject->classes, 0)) {
        g_hash_table_add(inv->keys, g_strconcat(".",
            (const char *)g_ptr_array_index(subject->classes, 0), NULL));
    } else if (subject->attrs && subject->attrs->len > 0 &&
               g_array_index(subject->attrs, ns_css_attr_pred, 0).name) {
        g_ptr_array_add(inv->attrs, g_ascii_strdown(
            g_array_index(subject->attrs, ns_css_attr_pred, 0).name, -1));
    } else if (subject->type && *subject->type &&
               strcmp(subject->type, "*") != 0) {
        char *t = g_ascii_strdown(subject->type, -1);
        g_hash_table_add(inv->keys, g_strconcat("%", t, NULL));
        g_free(t);
    } else {
        inv->whole = TRUE;
    }
}

static void
incr_inv_note_key(char kind, const char *name, const ns_css_simple *subject)
{
    incr_inv_set *inv = incr_inv_get(kind, name);
    if (subject) incr_inv_add_subject(inv, subject);
    else inv->whole = TRUE;
}

static void
incr_inv_note_compound(const ns_css_simple *c, const ns_css_simple *subject)
{
    if (c->id && *c->id) incr_inv_note_key('#', c->id, subject);
    for (guint i = 0; c->classes && i < c->classes->len; i++) {
        const char *cls = g_ptr_array_index(c->classes, i);
        if (cls && *cls) incr_inv_note_key('.', cls, subject);
    }
    for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
        const ns_css_attr_pred *a =
            &g_array_index(c->attrs, ns_css_attr_pred, i);
        if (!a->name) continue;
        char *low = g_ascii_strdown(a->name, -1);
        incr_inv_note_key('[', low, subject);
        g_free(low);
    }
}
static gboolean       g_class_keys_loose;
static gboolean       g_id_keys_loose;
static GPtrArray     *g_has_anchors;
static GPtrArray     *g_has_subject_anchors;
static gboolean       g_has_cq_loose;
static gboolean       g_struct_loose;
static gboolean       g_sib_loose;
static guint64        g_struct_sig;
static gboolean       g_struct_ready;
typedef struct {
    GHashTable *keys;
    GHashTable *attrs;
    gboolean    loose;
    guint64     relevant_serial;
    gboolean    relevant;
} incr_has_args;

typedef struct {
    gboolean    active;
    gboolean    all;
    guint64     serial;
    GHashTable *keys;
    GHashTable *attrs;
} incr_has_mutation;

typedef enum {
    INCR_HAS_REGION,
    INCR_HAS_SUBTREE,
    INCR_HAS_DESCENDANTS,
    INCR_HAS_SELF,
} incr_has_reach;

typedef struct {
    char *type;
    char *id;
    GPtrArray *classes;
    GPtrArray *attrs;
    const incr_has_args *args;
    gboolean pending;
    incr_has_reach reach;
    incr_inv_set *inv;
} incr_has_anchor;

static GPtrArray        *g_has_args_all;
static incr_has_args    *g_has_args_cur;
static gboolean          g_has_args_gateable;
static incr_has_mutation g_has_mut;

static void incr_has_invalidate_anchors(ns_node *n);

static void
incr_has_args_free(gpointer data)
{
    incr_has_args *a = data;
    g_hash_table_destroy(a->keys);
    g_hash_table_destroy(a->attrs);
    g_free(a);
}

static incr_has_args *
incr_has_args_new(void)
{
    incr_has_args *a = g_new0(incr_has_args, 1);
    a->keys = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
    a->attrs = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
    if (!g_has_args_all)
        g_has_args_all = g_ptr_array_new_with_free_func(incr_has_args_free);
    g_ptr_array_add(g_has_args_all, a);
    return a;
}

static gboolean
incr_has_sets_intersect(GHashTable *a, GHashTable *b)
{
    if (g_hash_table_size(a) > g_hash_table_size(b)) {
        GHashTable *t = a;
        a = b;
        b = t;
    }
    GHashTableIter it;
    gpointer key;
    g_hash_table_iter_init(&it, a);
    while (g_hash_table_iter_next(&it, &key, NULL))
        if (g_hash_table_contains(b, key)) return TRUE;
    return FALSE;
}

static gboolean
incr_has_args_relevant(const incr_has_args *args)
{
    if (!g_has_mut.active || g_has_mut.all || !args || args->loose)
        return TRUE;
    incr_has_args *cached = (incr_has_args *)args;
    if (cached->relevant_serial != g_has_mut.serial) {
        cached->relevant_serial = g_has_mut.serial;
        cached->relevant =
            incr_has_sets_intersect(args->keys, g_has_mut.keys) ||
            incr_has_sets_intersect(args->attrs, g_has_mut.attrs);
    }
    return cached->relevant;
}

static void
incr_has_mut_add_key(char prefix, const char *name, gsize len, gboolean lower)
{
    char *key = g_malloc(len + 2);
    key[0] = prefix;
    for (gsize i = 0; i < len; i++)
        key[i + 1] = lower ? g_ascii_tolower(name[i]) : name[i];
    key[len + 1] = '\0';
    g_hash_table_add(g_has_mut.keys, key);
}

static void
incr_has_mut_add_classes(const char *cls)
{
    for (const char *p = cls; p && *p; ) {
        while (*p && g_ascii_isspace((guchar)*p)) p++;
        const char *tok = p;
        while (*p && !g_ascii_isspace((guchar)*p)) p++;
        if (p > tok) incr_has_mut_add_key('.', tok, (gsize)(p - tok), FALSE);
    }
}

static void
incr_has_mut_add_node(const ns_node *n)
{
    if (!n || n->kind != NS_NODE_ELEMENT) return;
    if (n->name) incr_has_mut_add_key('%', n->name, strlen(n->name), TRUE);
    for (const ns_attr *a = n->attrs; a; a = a->next) {
        if (!a->name) continue;
        g_hash_table_add(g_has_mut.attrs, g_ascii_strdown(a->name, -1));
        if (strcmp(a->name, "id") == 0 && a->value && *a->value)
            incr_has_mut_add_key('#', a->value, strlen(a->value), FALSE);
        else if (strcmp(a->name, "class") == 0)
            incr_has_mut_add_classes(a->value);
    }
}

static void
incr_has_mut_add_subtree(const ns_node *n, guint *budget)
{
    if (!n || g_has_mut.all) return;
    if (*budget == 0) {
        g_has_mut.all = TRUE;
        return;
    }
    (*budget)--;
    incr_has_mut_add_node(n);
    for (const ns_node *c = n->first_child; c; c = c->next_sibling)
        incr_has_mut_add_subtree(c, budget);
}

static gboolean
incr_has_mut_begin(void)
{
    if (g_has_mut.active || !g_has_args_gateable) return FALSE;
    if (!g_has_mut.keys) {
        g_has_mut.keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                               g_free, NULL);
        g_has_mut.attrs = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                g_free, NULL);
    }
    g_has_mut.active = TRUE;
    g_has_mut.all = FALSE;
    g_has_mut.serial++;
    return TRUE;
}

static void
incr_has_mut_end(gboolean began)
{
    if (!began) return;
    g_has_mut.active = FALSE;
    g_hash_table_remove_all(g_has_mut.keys);
    g_hash_table_remove_all(g_has_mut.attrs);
}

static void
incr_has_mut_add_nodes(ns_node *const *nodes, guint n, gboolean following,
                       guint *budget)
{
    for (guint i = 0; i < n; i++)
        for (const ns_node *c = nodes[i]; c;
             c = following ? c->next_sibling : NULL)
            incr_has_mut_add_subtree(c, budget);
}

static gboolean
incr_has_mut_begin_nodes(ns_node *const *nodes, guint n, gboolean following)
{
    if (!incr_has_mut_begin()) return FALSE;
    guint budget = 4096;
    incr_has_mut_add_nodes(nodes, n, following, &budget);
    return TRUE;
}

static gboolean
incr_has_mut_begin_replaced(ns_node *added, ns_node *const *removed,
                            guint n_removed)
{
    if (!incr_has_mut_begin()) return FALSE;
    guint budget = 4096;
    incr_has_mut_add_nodes(&added, 1, TRUE, &budget);
    incr_has_mut_add_nodes(removed, n_removed, FALSE, &budget);
    return TRUE;
}

static gboolean
incr_has_mut_begin_attr(const ns_node *target, const char *name,
                        const char *old_value)
{
    if (!incr_has_mut_begin()) return FALSE;
    incr_has_mut_add_node(target);
    if (!name) {
        g_has_mut.all = TRUE;
        return TRUE;
    }
    g_hash_table_add(g_has_mut.attrs, g_ascii_strdown(name, -1));
    if (old_value && *old_value && g_ascii_strcasecmp(name, "class") == 0)
        incr_has_mut_add_classes(old_value);
    if (old_value && *old_value && g_ascii_strcasecmp(name, "id") == 0)
        incr_has_mut_add_key('#', old_value, strlen(old_value), FALSE);
    return TRUE;
}

static void
incr_mark_has_region(ns_node *anchor)
{
    if (!anchor) return;
    if (!g_incr_dirty)
        g_incr_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    for (ns_node *n = anchor; n; n = n->next_sibling)
        if (n->kind == NS_NODE_ELEMENT)
            g_hash_table_add(g_incr_dirty, n);
}

static GHashTable    *g_has_subject_docs;
static __thread gboolean g_css_compute_thread;

void
ns_css_forget_node(const ns_node *node)
{
    if (g_css_focus_node == node) g_css_focus_node = NULL;
    if (g_css_focus_visible_node == node) g_css_focus_visible_node = NULL;
    if (g_css_hover_node == node) g_css_hover_node = NULL;
    if (g_css_active_node == node) g_css_active_node = NULL;
    if (g_css_fullscreen_node == node) g_css_fullscreen_node = NULL;
    if (!g_css_compute_thread) return;
    GHashTable *node_sets[] = {
        g_incr_dirty, g_incr_self_dirty, g_incr_exclude, g_incr_inv_pending,
        g_has_subject_docs, g_incr_env_nodes,
    };
    for (gsize i = 0; i < G_N_ELEMENTS(node_sets); i++)
        if (node_sets[i]) g_hash_table_remove(node_sets[i], node);
}

static void
incr_defer_loose_has_subjects(ns_node *changed)
{
    if (!g_has_subject_anchors || g_has_subject_anchors->len == 0) return;
    gboolean any = FALSE;
    for (guint i = 0; i < g_has_subject_anchors->len; i++) {
        incr_has_anchor *a = g_ptr_array_index(g_has_subject_anchors, i);
        if (incr_has_args_relevant(a->args)) {
            a->pending = TRUE;
            any = TRUE;
        }
    }
    if (!any) return;
    ns_node *doc = changed;
    while (doc->parent) doc = doc->parent;
    if (doc->kind != NS_NODE_DOCUMENT) return;
    if (!g_has_subject_docs)
        g_has_subject_docs = g_hash_table_new(g_direct_hash, g_direct_equal);
    g_hash_table_add(g_has_subject_docs, doc);
}

static void
incr_mark_has_subjects(ns_node *changed)
{
    if (!changed || !g_incr_eligible || g_has_cq_loose) return;
    if (!g_incr_dirty)
        g_incr_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    incr_defer_loose_has_subjects(changed);
    if (!g_has_anchors || g_has_anchors->len == 0)
        return;
    for (ns_node *a = changed; a; a = a->parent) {
        if (a->kind == NS_NODE_ELEMENT) incr_has_invalidate_anchors(a);
        guint scanned = 0;
        for (ns_node *s = a->prev_sibling; s; s = s->prev_sibling) {
            if (s->kind != NS_NODE_ELEMENT) continue;
            if (++scanned > 256) {
                if (a->parent)
                    g_hash_table_add(g_incr_dirty, a->parent);
                break;
            }
            incr_has_invalidate_anchors(s);
        }
    }
}

void
ns_css_set_render_zoom(double zoom)
{
    g_incr_zoom = zoom > 0 ? zoom : 1.0;
}

void
ns_css_mark_restyle_dirty(ns_node *parent)
{
    if (!parent) return;
    if (!g_incr_dirty)
        g_incr_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    g_hash_table_add(g_incr_dirty, parent);
    incr_mark_has_subjects(parent);
}

static gboolean incr_pc_is_structural(ns_css_pseudo k)
{
    switch (k) {
    case NS_CSS_PC_FIRST_CHILD: case NS_CSS_PC_LAST_CHILD:
    case NS_CSS_PC_ONLY_CHILD:  case NS_CSS_PC_ONLY_OF_TYPE:
    case NS_CSS_PC_FIRST_OF_TYPE: case NS_CSS_PC_LAST_OF_TYPE:
    case NS_CSS_PC_EMPTY:
    case NS_CSS_PC_NTH_CHILD:   case NS_CSS_PC_NTH_LAST_CHILD:
    case NS_CSS_PC_NTH_OF_TYPE: case NS_CSS_PC_NTH_LAST_OF_TYPE:
        return TRUE;
    default:
        return FALSE;
    }
}

static gboolean incr_selector_has_structural(const ns_css_selector *sel, int d);

static gboolean
incr_simple_has_structural(const ns_css_simple *c, int d)
{
    if (!c) return FALSE;
    if (d > 6) return TRUE;
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            if (incr_pc_is_structural(p->kind)) return TRUE;
            if (p->of_group)
                for (guint gi = 0; gi < p->of_group->len; gi++)
                    if (incr_selector_has_structural(
                            g_ptr_array_index(p->of_group, gi), d + 1))
                        return TRUE;
        }
    GPtrArray *gls[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (int g = 0; g < 3; g++) {
        if (!gls[g]) continue;
        for (guint gi = 0; gi < gls[g]->len; gi++) {
            const GPtrArray *grp = g_ptr_array_index(gls[g], gi);
            for (guint si = 0; grp && si < grp->len; si++)
                if (incr_selector_has_structural(
                        g_ptr_array_index(grp, si), d + 1))
                    return TRUE;
        }
    }
    return FALSE;
}

static gboolean
incr_selector_has_structural(const ns_css_selector *sel, int d)
{
    if (!sel || !sel->compounds) return FALSE;
    if (d > 6) return TRUE;
    for (guint i = 0; i < sel->compounds->len; i++)
        if (incr_simple_has_structural(g_ptr_array_index(sel->compounds, i), d))
            return TRUE;
    return FALSE;
}

static gboolean
incr_add_compound_keys(GHashTable *keys, const ns_css_simple *c)
{
    gboolean any = FALSE;
    if (!c) return FALSE;
    if (c->id && *c->id) {
        g_hash_table_add(keys, g_strconcat("#", c->id, NULL));
        any = TRUE;
    }
    if (c->classes)
        for (guint i = 0; i < c->classes->len; i++) {
            const char *cls = g_ptr_array_index(c->classes, i);
            if (cls && *cls) {
                g_hash_table_add(keys, g_strconcat(".", cls, NULL));
                any = TRUE;
            }
        }
    if (c->type && *c->type && strcmp(c->type, "*") != 0) {
        char *t = g_ascii_strdown(c->type, -1);
        g_hash_table_add(keys, g_strconcat("%", t, NULL));
        g_free(t);
        any = TRUE;
    }
    return any;
}

static void
incr_attr_dep_free(gpointer data)
{
    ns_attr_pred_clear(data);
    g_free(data);
}

static void
incr_own_attr_deps_from(GPtrArray *attrs, guint first)
{
    if (!attrs) return;
    for (guint i = first; i < attrs->len; i++) {
        const ns_css_attr_pred *source = g_ptr_array_index(attrs, i);
        ns_css_attr_pred *copy = g_new0(ns_css_attr_pred, 1);
        *copy = *source;
        copy->name = g_strdup(source->name);
        copy->value = g_strdup(source->value);
        attrs->pdata[i] = copy;
    }
}

static void
incr_own_attr_deps(GPtrArray *attrs)
{
    incr_own_attr_deps_from(attrs, 0);
}

static gboolean
incr_add_positive_compound_deps(GHashTable *keys, GPtrArray *attrs,
                                const ns_css_simple *c, int depth);

static const char *
incr_state_pseudo_attr(ns_css_pseudo k)
{
    switch (k) {
    case NS_CSS_PC_DISABLED:
    case NS_CSS_PC_ENABLED:       return "disabled";
    case NS_CSS_PC_CHECKED:       return "data-nd-checked";
    case NS_CSS_PC_REQUIRED:
    case NS_CSS_PC_OPTIONAL:      return "required";
    case NS_CSS_PC_READ_ONLY:
    case NS_CSS_PC_READ_WRITE:    return "readonly";
    case NS_CSS_PC_LINK:
    case NS_CSS_PC_VISITED:
    case NS_CSS_PC_ANY_LINK:
    case NS_CSS_PC_HOVER:
    case NS_CSS_PC_ACTIVE:
    case NS_CSS_PC_FOCUS:
    case NS_CSS_PC_FOCUS_VISIBLE:
    case NS_CSS_PC_FOCUS_WITHIN:
    case NS_CSS_PC_TARGET:
    case NS_CSS_PC_TARGET_WITHIN:
    case NS_CSS_PC_FIRST_CHILD:
    case NS_CSS_PC_LAST_CHILD:
    case NS_CSS_PC_ONLY_CHILD:
    case NS_CSS_PC_ONLY_OF_TYPE:
    case NS_CSS_PC_FIRST_OF_TYPE:
    case NS_CSS_PC_LAST_OF_TYPE:
    case NS_CSS_PC_EMPTY:
    case NS_CSS_PC_NTH_CHILD:
    case NS_CSS_PC_NTH_LAST_CHILD:
    case NS_CSS_PC_NTH_OF_TYPE:
    case NS_CSS_PC_NTH_LAST_OF_TYPE:
    case NS_CSS_PC_ROOT:
    case NS_CSS_PC_SCOPE:
    case NS_CSS_PC_DEFINED:       return "";
    default:                      return NULL;
    }
}

static void incr_collect_sib_left_at(const ns_css_simple *c, int depth);

static void
incr_collect_sib_selectors(const GPtrArray *selectors, int depth)
{
    for (guint si = 0; selectors && si < selectors->len; si++) {
        const ns_css_selector *sel = g_ptr_array_index(selectors, si);
        for (guint ci = 0; sel && sel->compounds &&
                           ci < sel->compounds->len; ci++)
            incr_collect_sib_left_at(g_ptr_array_index(sel->compounds, ci),
                                     depth + 1);
    }
}

static void
incr_collect_sib_groups(const GPtrArray *groups, int depth)
{
    for (guint gi = 0; groups && gi < groups->len; gi++)
        incr_collect_sib_selectors(g_ptr_array_index(groups, gi), depth);
}

static void
incr_collect_sib_left(const ns_css_simple *c)
{
    incr_collect_sib_left_at(c, 0);
}

static void
incr_collect_sib_left_at(const ns_css_simple *c, int depth)
{
    if (!c) return;
    if (depth > 6 || c->has_groups) {
        g_sib_loose = TRUE;
        return;
    }
    gboolean handled = incr_add_compound_keys(g_sib_keys, c);
    if (c->attrs)
        for (guint i = 0; i < c->attrs->len; i++) {
            const ns_css_attr_pred *a =
                &g_array_index(c->attrs, ns_css_attr_pred, i);
            if (a->name && *a->name) {
                char *low = g_ascii_strdown(a->name, -1);
                g_hash_table_add(g_sib_attrs, g_strdup(low));
                if (a->op != NS_CSS_ATTR_PRESENT)
                    g_hash_table_add(g_sib_value_attrs, low);
                else
                    g_free(low);
                handled = TRUE;
            }
        }
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            const char *attr = incr_state_pseudo_attr(p->kind);
            if (attr == NULL) { g_sib_loose = TRUE; }
            else if (*attr) {
                g_hash_table_add(g_sib_attrs, g_strdup(attr));
                g_hash_table_add(g_sib_value_attrs, g_strdup(attr));
            }
            if (p->of_group) incr_collect_sib_selectors(p->of_group, depth);
            handled = TRUE;
        }
    incr_collect_sib_groups(c->matches_any, depth);
    incr_collect_sib_groups(c->matches_none, depth);
    (void)handled;
}

static void incr_collect_attr_keys_selector(const ns_css_selector *sel, int depth);

static void
incr_collect_attr_keys_simple(const ns_css_simple *c, int depth)
{
    if (!c || depth > 6) return;
    if (c->attrs)
        for (guint i = 0; i < c->attrs->len; i++) {
            const ns_css_attr_pred *a =
                &g_array_index(c->attrs, ns_css_attr_pred, i);
            if (a->name && *a->name)
                g_hash_table_add(g_attr_keys, g_ascii_strdown(a->name, -1));
        }
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            const char *attr = incr_state_pseudo_attr(p->kind);
            if (attr && *attr)
                g_hash_table_add(g_attr_keys, g_strdup(attr));
            if (p->kind == NS_CSS_PC_LANG) {
                g_hash_table_add(g_attr_keys, g_strdup("lang"));
                g_hash_table_add(g_attr_keys, g_strdup("xml:lang"));
            } else if (p->kind == NS_CSS_PC_DIR) {
                g_hash_table_add(g_attr_keys, g_strdup("dir"));
            } else if (p->kind == NS_CSS_PC_OPEN) {
                g_hash_table_add(g_attr_keys, g_strdup("open"));
            } else if (p->kind == NS_CSS_PC_POPOVER_OPEN) {
                g_hash_table_add(g_attr_keys, g_strdup("data-nd-popover-open"));
            } else if (p->kind == NS_CSS_PC_MODAL) {
                g_hash_table_add(g_attr_keys, g_strdup("data-nd-modal"));
            }
            if (p->of_group)
                for (guint gi = 0; gi < p->of_group->len; gi++)
                    incr_collect_attr_keys_selector(
                        g_ptr_array_index(p->of_group, gi), depth + 1);
        }
    GPtrArray *groups[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (guint i = 0; i < G_N_ELEMENTS(groups); i++)
        if (groups[i])
            for (guint gi = 0; gi < groups[i]->len; gi++) {
                const GPtrArray *group = g_ptr_array_index(groups[i], gi);
                for (guint si = 0; group && si < group->len; si++)
                    incr_collect_attr_keys_selector(
                        g_ptr_array_index(group, si), depth + 1);
            }
}

static void
incr_collect_attr_keys_selector(const ns_css_selector *sel, int depth)
{
    if (!sel || !sel->compounds || depth > 6) return;
    for (guint i = 0; i < sel->compounds->len; i++)
        incr_collect_attr_keys_simple(g_ptr_array_index(sel->compounds, i),
                                      depth);
}

static gboolean
incr_compound_position_dependent(const ns_css_simple *c)
{
    if (incr_simple_has_structural(c, 0)) return TRUE;
    GPtrArray *gls[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (int g = 0; g < 3; g++)
        for (guint gi = 0; gls[g] && gi < gls[g]->len; gi++) {
            const GPtrArray *grp = g_ptr_array_index(gls[g], gi);
            for (guint si = 0; grp && si < grp->len; si++) {
                const ns_css_selector *nested = g_ptr_array_index(grp, si);
                for (guint ci = 1; nested && nested->combinators &&
                                   ci < nested->combinators->len; ci++) {
                    ns_css_comb cb =
                        g_array_index(nested->combinators, ns_css_comb, ci);
                    if (cb == NS_CSS_COMB_ADJACENT || cb == NS_CSS_COMB_SIBLING)
                        return TRUE;
                }
            }
        }
    return FALSE;
}

static gboolean
incr_simple_has_subject_key(const ns_css_simple *c)
{
    return (c->id && *c->id) ||
           (c->classes && c->classes->len > 0 &&
            g_ptr_array_index(c->classes, 0)) ||
           (c->attrs && c->attrs->len > 0 &&
            g_array_index(c->attrs, ns_css_attr_pred, 0).name) ||
           (c->type && *c->type && strcmp(c->type, "*") != 0);
}

static gboolean
incr_note_struct_flood_compound(const ns_css_simple *c)
{
    if (!g_struct_flood_keys) {
        g_struct_flood_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                    g_free, NULL);
        g_struct_flood_attrs = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                     g_free, NULL);
    }
    GPtrArray *preds = g_ptr_array_new();
    gboolean keyed = incr_add_positive_compound_deps(g_struct_flood_keys,
                                                     preds, c, 0);
    for (guint i = 0; i < preds->len; i++) {
        const ns_css_attr_pred *a = g_ptr_array_index(preds, i);
        if (a->name)
            g_hash_table_add(g_struct_flood_attrs,
                             g_ascii_strdown(a->name, -1));
    }
    g_ptr_array_free(preds, TRUE);
    return keyed;
}

static gboolean
incr_note_struct_flood(const ns_css_selector *sel)
{
    guint n = sel->compounds->len;
    for (guint ci = 0; ci + 1 < n; ci++) {
        ns_css_comb right = NS_CSS_COMB_NONE;
        if (sel->combinators && ci + 1 < sel->combinators->len)
            right = g_array_index(sel->combinators, ns_css_comb, ci + 1);
        ns_css_comb left = NS_CSS_COMB_NONE;
        if (sel->combinators && ci < sel->combinators->len)
            left = g_array_index(sel->combinators, ns_css_comb, ci);
        const ns_css_simple *c = g_ptr_array_index(sel->compounds, ci);
        gboolean dependent = incr_compound_position_dependent(c) ||
            left == NS_CSS_COMB_ADJACENT || left == NS_CSS_COMB_SIBLING;
        if (dependent && (right == NS_CSS_COMB_DESCENDANT ||
                          right == NS_CSS_COMB_CHILD) &&
            !incr_note_struct_flood_compound(c))
            return FALSE;
    }
    return TRUE;
}

static void
incr_note_struct_descendants(const ns_css_selector *sel)
{
    guint n = sel->compounds->len;
    if (n < 2) return;
    gboolean dependent_ancestor = FALSE;
    for (guint ci = 0; ci + 1 < n; ci++) {
        ns_css_comb right = NS_CSS_COMB_NONE;
        if (sel->combinators && ci + 1 < sel->combinators->len)
            right = g_array_index(sel->combinators, ns_css_comb, ci + 1);
        ns_css_comb left = NS_CSS_COMB_NONE;
        if (sel->combinators && ci < sel->combinators->len)
            left = g_array_index(sel->combinators, ns_css_comb, ci);
        gboolean dependent =
            incr_compound_position_dependent(g_ptr_array_index(sel->compounds, ci)) ||
            left == NS_CSS_COMB_ADJACENT || left == NS_CSS_COMB_SIBLING;
        if (dependent && (right == NS_CSS_COMB_DESCENDANT ||
                          right == NS_CSS_COMB_CHILD))
            dependent_ancestor = TRUE;
        if (dependent_ancestor) break;
    }
    if (!dependent_ancestor) return;
    if (!g_struct_desc_inv) {
        incr_inv_set *inv = g_new0(incr_inv_set, 1);
        inv->keys = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
        inv->attrs = g_ptr_array_new_with_free_func(g_free);
        g_struct_desc_inv = inv;
    }
    const ns_css_simple *subject = g_ptr_array_index(sel->compounds, n - 1);
    if (incr_simple_has_subject_key(subject) ||
        !incr_note_struct_flood(sel))
        incr_inv_add_subject(g_struct_desc_inv, subject);
}

static gboolean
incr_simple_uses_empty(const ns_css_simple *c, int depth)
{
    if (!c) return FALSE;
    if (depth > 6) return TRUE;
    for (guint i = 0; c->pseudos && i < c->pseudos->len; i++)
        if (g_array_index(c->pseudos, ns_css_pseudo_pred, i).kind ==
            NS_CSS_PC_EMPTY)
            return TRUE;
    GPtrArray *groups[2] = { c->matches_any, c->matches_none };
    for (guint g = 0; g < G_N_ELEMENTS(groups); g++)
        for (guint gi = 0; groups[g] && gi < groups[g]->len; gi++) {
            const GPtrArray *group = g_ptr_array_index(groups[g], gi);
            for (guint si = 0; group && si < group->len; si++) {
                const ns_css_selector *sel = g_ptr_array_index(group, si);
                for (guint ci = 0; sel && sel->compounds &&
                                   ci < sel->compounds->len; ci++)
                    if (incr_simple_uses_empty(
                            g_ptr_array_index(sel->compounds, ci), depth + 1))
                        return TRUE;
            }
        }
    return FALSE;
}

static void
incr_note_empty_sib(const ns_css_simple *c)
{
    if (!g_empty_sib_keys) {
        g_empty_sib_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                 g_free, NULL);
        g_empty_sib_attrs = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                  g_free, NULL);
    }
    GPtrArray *preds = g_ptr_array_new();
    if (!incr_add_positive_compound_deps(g_empty_sib_keys, preds, c, 0))
        g_empty_sib_loose = TRUE;
    for (guint i = 0; i < preds->len; i++) {
        const ns_css_attr_pred *a = g_ptr_array_index(preds, i);
        if (a->name)
            g_hash_table_add(g_empty_sib_attrs, g_ascii_strdown(a->name, -1));
    }
    g_ptr_array_free(preds, TRUE);
}

static void
incr_collect_struct_keys(const ns_css_stylesheet *sh)
{
    if (!sh || !sh->rules) return;
    for (guint ri = 0; ri < sh->rules->len; ri++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, ri);
        if (!r || !r->selectors) continue;
        for (guint si = 0; si < r->selectors->len; si++) {
            const ns_css_selector *sel = g_ptr_array_index(r->selectors, si);
            if (!sel || !sel->compounds) continue;
            incr_collect_attr_keys_selector(sel, 0);
            incr_note_struct_descendants(sel);
            guint nc = sel->compounds->len;
            for (guint ci = 0; ci < nc; ci++) {
                const ns_css_simple *c = g_ptr_array_index(sel->compounds, ci);
                ns_css_comb left = NS_CSS_COMB_NONE;
                if (sel->combinators && ci < sel->combinators->len)
                    left = g_array_index(sel->combinators, ns_css_comb, ci);
                ns_css_comb right = NS_CSS_COMB_NONE;
                if (sel->combinators && ci + 1 < sel->combinators->len)
                    right = g_array_index(sel->combinators, ns_css_comb, ci + 1);
                if (right == NS_CSS_COMB_ADJACENT ||
                    right == NS_CSS_COMB_SIBLING) {
                    incr_collect_sib_left(c);
                    if (incr_simple_uses_empty(c, 0)) incr_note_empty_sib(c);
                }
                gboolean sib_subject = (left == NS_CSS_COMB_ADJACENT ||
                                        left == NS_CSS_COMB_SIBLING);
                if (!incr_simple_has_structural(c, 0) && !sib_subject)
                    continue;
                if (incr_add_positive_compound_deps(
                        g_struct_keys, g_struct_attrs, c, 0))
                    continue;
                gboolean sib_ctx = TRUE, found = FALSE;
                for (int j = (int)ci - 1; j >= 0; j--) {
                    ns_css_comb cb = NS_CSS_COMB_NONE;
                    if (sel->combinators &&
                        (guint)(j + 1) < sel->combinators->len)
                        cb = g_array_index(sel->combinators, ns_css_comb, j + 1);
                    const ns_css_simple *jc =
                        g_ptr_array_index(sel->compounds, j);
                    if (sib_ctx && (cb == NS_CSS_COMB_ADJACENT ||
                                    cb == NS_CSS_COMB_SIBLING)) {
                        if (incr_add_positive_compound_deps(
                                g_struct_keys, g_struct_attrs, jc, 0)) {
                            found = TRUE; break;
                        }
                    } else {
                        sib_ctx = FALSE;
                        if (incr_add_positive_compound_deps(
                                g_struct_anc_keys, g_struct_anc_attrs, jc, 0)) {
                            found = TRUE; break;
                        }
                    }
                }
                if (!found) g_struct_loose = TRUE;
            }
        }
    }
}

static void incr_collect_name_keys_selector(const ns_css_selector *sel,
                                            int depth);

static void
incr_collect_name_keys_group(const GPtrArray *group, int depth)
{
    for (guint i = 0; group && i < group->len; i++)
        incr_collect_name_keys_selector(g_ptr_array_index(group, i), depth);
}

static void
incr_collect_name_keys_simple(const ns_css_simple *c, int depth,
                              gboolean desc)
{
    if (!c) return;
    if (depth > 6) {
        g_class_keys_loose = TRUE;
        g_id_keys_loose = TRUE;
        g_desc_keys_loose = TRUE;
        return;
    }
    if (c->id && *c->id) {
        g_hash_table_add(g_id_keys, g_ascii_strdown(c->id, -1));
        if (desc) g_hash_table_add(g_desc_id_keys, g_ascii_strdown(c->id, -1));
    }
    for (guint i = 0; c->classes && i < c->classes->len; i++) {
        const char *cls = g_ptr_array_index(c->classes, i);
        if (!cls || !*cls) continue;
        g_hash_table_add(g_class_keys, g_ascii_strdown(cls, -1));
        if (desc) g_hash_table_add(g_desc_class_keys, g_ascii_strdown(cls, -1));
    }
    for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
        const ns_css_attr_pred *a =
            &g_array_index(c->attrs, ns_css_attr_pred, i);
        if (!a->name) continue;
        if (desc)
            g_hash_table_add(g_desc_attr_keys, g_ascii_strdown(a->name, -1));
        if (g_ascii_strcasecmp(a->name, "class") == 0)
            g_class_keys_loose = TRUE;
        else if (g_ascii_strcasecmp(a->name, "id") == 0)
            g_id_keys_loose = TRUE;
    }
    for (guint i = 0; c->pseudos && i < c->pseudos->len; i++) {
        const ns_css_pseudo_pred *pc =
            &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
        if (pc->kind == NS_CSS_PC_TARGET || pc->kind == NS_CSS_PC_TARGET_WITHIN)
            g_id_keys_loose = TRUE;
        if (pc->of_group) incr_collect_name_keys_group(pc->of_group, depth + 1);
    }
    GPtrArray *groups[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (guint g = 0; g < G_N_ELEMENTS(groups); g++)
        for (guint gi = 0; groups[g] && gi < groups[g]->len; gi++)
            incr_collect_name_keys_group(g_ptr_array_index(groups[g], gi),
                                         depth + 1);
}

static void incr_inv_note_selector(const ns_css_selector *sel,
                                   const ns_css_simple *subject, int depth);

static void
incr_inv_note_nested(const ns_css_simple *c, const ns_css_simple *subject,
                     int depth)
{
    if (depth > 6) {
        g_desc_keys_loose = TRUE;
        return;
    }
    GPtrArray *groups[3] = { c->matches_any, c->matches_none, c->has_groups };
    for (int g = 0; g < 3; g++)
        for (guint gi = 0; groups[g] && gi < groups[g]->len; gi++) {
            const GPtrArray *group = g_ptr_array_index(groups[g], gi);
            for (guint si = 0; group && si < group->len; si++)
                incr_inv_note_selector(g_ptr_array_index(group, si),
                                       g == 2 ? NULL : subject, depth + 1);
        }
    for (guint i = 0; c->pseudos && i < c->pseudos->len; i++) {
        const ns_css_pseudo_pred *pc =
            &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
        for (guint gi = 0; pc->of_group && gi < pc->of_group->len; gi++)
            incr_inv_note_selector(g_ptr_array_index(pc->of_group, gi),
                                   subject, depth + 1);
    }
}

static void
incr_inv_note_selector(const ns_css_selector *sel, const ns_css_simple *subject,
                       int depth)
{
    for (guint i = 0; sel && sel->compounds && i < sel->compounds->len; i++) {
        const ns_css_simple *c = g_ptr_array_index(sel->compounds, i);
        incr_inv_note_compound(c, subject);
        incr_inv_note_nested(c, subject, depth);
    }
}

static void
incr_collect_name_keys_selector(const ns_css_selector *sel, int depth)
{
    if (!sel || !sel->compounds || sel->compounds->len == 0) return;
    guint last = sel->compounds->len - 1;
    const ns_css_simple *subject = g_ptr_array_index(sel->compounds, last);
    gboolean ancestor_chain = depth == 0;
    for (guint i = last; i-- > 0; ) {
        ns_css_comb comb = NS_CSS_COMB_DESCENDANT;
        if (sel->combinators && i + 1 < sel->combinators->len)
            comb = g_array_index(sel->combinators, ns_css_comb, i + 1);
        if (comb != NS_CSS_COMB_DESCENDANT && comb != NS_CSS_COMB_CHILD)
            ancestor_chain = FALSE;
        if (depth == 0) {
            const ns_css_simple *c = g_ptr_array_index(sel->compounds, i);
            incr_inv_note_compound(c, ancestor_chain ? subject : NULL);
            incr_inv_note_nested(c, ancestor_chain ? subject : NULL, 1);
        }
    }
    if (depth == 0)
        incr_inv_note_nested(subject, subject, 1);
    for (guint i = 0; i <= last; i++)
        incr_collect_name_keys_simple(g_ptr_array_index(sel->compounds, i),
                                      depth, depth > 0 || i < last);
}

static void
incr_collect_name_keys(const ns_css_stylesheet *sh)
{
    for (guint ri = 0; sh && sh->rules && ri < sh->rules->len; ri++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, ri);
        if (!r) continue;
        incr_collect_name_keys_group(r->selectors, 0);
        for (guint si = 0; r->scopes && si < r->scopes->len; si++) {
            const ns_css_scope *scope = g_ptr_array_index(r->scopes, si);
            incr_collect_name_keys_group(scope->roots, 1);
            incr_collect_name_keys_group(scope->limits, 1);
            const GPtrArray *scope_groups[2] = { scope->roots, scope->limits };
            for (int sg = 0; sg < 2; sg++)
                for (guint k = 0; scope_groups[sg] && k < scope_groups[sg]->len; k++)
                    incr_inv_note_selector(g_ptr_array_index(scope_groups[sg], k),
                                           NULL, 1);
        }
    }
}

static gboolean
incr_name_in_keys(const char *name, gsize len, GHashTable *keys)
{
    char stack[64];
    char *low = len < sizeof stack ? stack : g_malloc(len + 1);
    for (gsize i = 0; i < len; i++) low[i] = g_ascii_tolower(name[i]);
    low[len] = '\0';
    gboolean hit = g_hash_table_contains(keys, low);
    if (low != stack) g_free(low);
    return hit;
}

static gboolean
incr_class_tokens_in_keys(const char *value)
{
    for (const char *p = value; p && *p; ) {
        while (*p && g_ascii_isspace((guchar)*p)) p++;
        const char *tok = p;
        while (*p && !g_ascii_isspace((guchar)*p)) p++;
        if (p > tok && incr_name_in_keys(tok, (gsize)(p - tok), g_class_keys))
            return TRUE;
    }
    return FALSE;
}

static gboolean
incr_id_in_keys(const char *value)
{
    return value && incr_name_in_keys(value, strlen(value), g_id_keys);
}

static gboolean
incr_name_change_unused(const ns_node *target, const char *name,
                        const char *old_value)
{
    if (!g_struct_ready || !name) return FALSE;
    if (g_ascii_strcasecmp(name, "class") == 0)
        return g_class_keys && !g_class_keys_loose &&
               !incr_class_tokens_in_keys(old_value) &&
               !incr_class_tokens_in_keys(ns_element_get_attr(target, "class"));
    if (g_ascii_strcasecmp(name, "id") == 0)
        return g_id_keys && !g_id_keys_loose &&
               !incr_id_in_keys(old_value) &&
               !incr_id_in_keys(ns_element_id_attr(target));
    return FALSE;
}

static gboolean
incr_sheet_newly_seen(GHashTable *seen, const ns_css_stylesheet *sh)
{
    if (!sh) return FALSE;
    if (g_hash_table_contains(seen, &sh->serial)) return FALSE;
    g_hash_table_add(seen, g_memdup2(&sh->serial, sizeof sh->serial));
    return TRUE;
}

static GHashTable *g_struct_serials;
static GHashTable *g_has_serials;

static gboolean
incr_struct_keys_extend(const ns_css_stylesheet *ua,
                        const ns_css_stylesheet *const *author, gsize n)
{
    if (!g_struct_ready || !g_struct_serials ||
        g_hash_table_size(g_struct_serials) > 2 * (n + 1) + 64)
        return FALSE;
    guint attrs_mark = g_struct_attrs->len;
    guint anc_mark = g_struct_anc_attrs->len;
    if (incr_sheet_newly_seen(g_struct_serials, ua)) {
        incr_collect_struct_keys(ua);
        incr_collect_name_keys(ua);
    }
    for (gsize i = 0; i < n; i++) {
        if (!incr_sheet_newly_seen(g_struct_serials, author[i])) continue;
        incr_collect_struct_keys(author[i]);
        incr_collect_name_keys(author[i]);
    }
    incr_own_attr_deps_from(g_struct_attrs, attrs_mark);
    incr_own_attr_deps_from(g_struct_anc_attrs, anc_mark);
    return TRUE;
}

static gboolean
incr_ensure_struct_keys(const ns_css_stylesheet *ua,
                        const ns_css_stylesheet *const *author, gsize n,
                        guint64 sig)
{
    if (g_struct_ready && g_struct_sig == sig) return TRUE;
    if (incr_struct_keys_extend(ua, author, n)) {
        g_struct_sig = sig;
        return TRUE;
    }
    if (g_struct_serials) g_hash_table_remove_all(g_struct_serials);
    else g_struct_serials = g_hash_table_new_full(g_int64_hash, g_int64_equal,
                                                  g_free, NULL);
    incr_sheet_newly_seen(g_struct_serials, ua);
    for (gsize i = 0; i < n; i++)
        incr_sheet_newly_seen(g_struct_serials, author[i]);
    if (g_struct_keys) g_hash_table_remove_all(g_struct_keys);
    else g_struct_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                               g_free, NULL);
    if (g_struct_anc_keys) g_hash_table_remove_all(g_struct_anc_keys);
    else g_struct_anc_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                   g_free, NULL);
    if (g_struct_attrs) g_ptr_array_set_size(g_struct_attrs, 0);
    else g_struct_attrs = g_ptr_array_new_with_free_func(incr_attr_dep_free);
    if (g_struct_anc_attrs) g_ptr_array_set_size(g_struct_anc_attrs, 0);
    else g_struct_anc_attrs =
        g_ptr_array_new_with_free_func(incr_attr_dep_free);
    if (g_sib_keys) g_hash_table_remove_all(g_sib_keys);
    else g_sib_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                            g_free, NULL);
    if (g_sib_attrs) g_hash_table_remove_all(g_sib_attrs);
    else g_sib_attrs = g_hash_table_new_full(g_str_hash, g_str_equal,
                                             g_free, NULL);
    if (g_sib_value_attrs) g_hash_table_remove_all(g_sib_value_attrs);
    else g_sib_value_attrs = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                   g_free, NULL);
    if (g_attr_keys) g_hash_table_remove_all(g_attr_keys);
    else g_attr_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                             g_free, NULL);
    if (g_class_keys) g_hash_table_remove_all(g_class_keys);
    else g_class_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                              g_free, NULL);
    if (g_id_keys) g_hash_table_remove_all(g_id_keys);
    else g_id_keys = g_hash_table_new_full(g_str_hash, g_str_equal,
                                           g_free, NULL);
    GHashTable **desc_sets[] = {
        &g_desc_class_keys, &g_desc_id_keys, &g_desc_attr_keys,
    };
    for (gsize i = 0; i < G_N_ELEMENTS(desc_sets); i++) {
        if (*desc_sets[i]) g_hash_table_remove_all(*desc_sets[i]);
        else *desc_sets[i] = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                   g_free, NULL);
    }
    g_desc_keys_loose = FALSE;
    g_clear_pointer(&g_struct_desc_inv, incr_inv_set_free);
    g_clear_pointer(&g_struct_flood_keys, g_hash_table_destroy);
    g_clear_pointer(&g_struct_flood_attrs, g_hash_table_destroy);
    g_clear_pointer(&g_empty_sib_keys, g_hash_table_destroy);
    g_clear_pointer(&g_empty_sib_attrs, g_hash_table_destroy);
    g_empty_sib_loose = FALSE;
    if (g_incr_inv_pending) g_hash_table_remove_all(g_incr_inv_pending);
    if (g_inv_sets) g_hash_table_remove_all(g_inv_sets);
    else g_inv_sets = g_hash_table_new_full(g_str_hash, g_str_equal, g_free,
                                            incr_inv_set_free);
    g_class_keys_loose = FALSE;
    g_id_keys_loose = FALSE;
    g_struct_loose = FALSE;
    g_sib_loose = FALSE;
    incr_collect_struct_keys(ua);
    incr_collect_name_keys(ua);
    for (gsize i = 0; i < n; i++) {
        incr_collect_struct_keys(author[i]);
        incr_collect_name_keys(author[i]);
    }
    incr_own_attr_deps(g_struct_attrs);
    incr_own_attr_deps(g_struct_anc_attrs);
    g_struct_sig = sig;
    g_struct_ready = TRUE;
    return FALSE;
}

static gboolean
incr_keyset_contains(GHashTable *keyset, char prefix, const char *name,
                     gsize len, gboolean lower)
{
    char stack[128];
    char *key = len + 2 <= sizeof stack ? stack : g_malloc(len + 2);
    key[0] = prefix;
    for (gsize i = 0; i < len; i++)
        key[i + 1] = lower ? g_ascii_tolower(name[i]) : name[i];
    key[len + 1] = '\0';
    gboolean hit = g_hash_table_contains(keyset, key);
    if (key != stack) g_free(key);
    return hit;
}

static gboolean
incr_class_list_matches_keys(const char *cls, GHashTable *keyset)
{
    for (const char *p = cls; p && *p; ) {
        while (*p && g_ascii_isspace((guchar)*p)) p++;
        const char *tok = p;
        while (*p && !g_ascii_isspace((guchar)*p)) p++;
        if (p > tok && incr_keyset_contains(keyset, '.', tok,
                                            (gsize)(p - tok), FALSE))
            return TRUE;
    }
    return FALSE;
}

static gboolean
incr_node_matches_keys(const ns_node *n, GHashTable *keyset)
{
    if (!n || n->kind != NS_NODE_ELEMENT || !keyset ||
        g_hash_table_size(keyset) == 0)
        return FALSE;
    if (n->name && incr_keyset_contains(keyset, '%', n->name,
                                        strlen(n->name), TRUE))
        return TRUE;
    const char *id = ns_element_id_attr(n);
    if (id && *id && incr_keyset_contains(keyset, '#', id, strlen(id), FALSE))
        return TRUE;
    return incr_class_list_matches_keys(ns_element_get_attr(n, "class"),
                                        keyset);
}

static gboolean
incr_attr_pred_matches(const ns_node *n, const ns_css_attr_pred *wanted)
{
    const char *value = ns_element_get_attr(n, wanted->name);
    if (wanted->op == NS_CSS_ATTR_PRESENT) return value != NULL;
    if (!value || !wanted->value) return FALSE;
    gsize value_len = strlen(value);
    gsize wanted_len = strlen(wanted->value);
    gboolean html_doc = !(n->flags & NS_NODE_XML_DOC) &&
                        !(n->flags & (NS_NODE_FOREIGN_NS | NS_NODE_SVG_NS));
    gboolean ci = wanted->case_insensitive ||
        (!wanted->case_sensitive && html_doc &&
         wanted->html_ci);
    switch (wanted->op) {
    case NS_CSS_ATTR_EQ:
        return ci ? g_ascii_strcasecmp(value, wanted->value) == 0
                  : strcmp(value, wanted->value) == 0;
    case NS_CSS_ATTR_PREFIX:
        return wanted_len > 0 && value_len >= wanted_len &&
               (ci ? g_ascii_strncasecmp(value, wanted->value,
                                         wanted_len) == 0
                   : strncmp(value, wanted->value, wanted_len) == 0);
    case NS_CSS_ATTR_SUFFIX:
        return wanted_len > 0 && value_len >= wanted_len &&
               (ci ? g_ascii_strcasecmp(value + value_len - wanted_len,
                                        wanted->value) == 0
                   : strcmp(value + value_len - wanted_len,
                            wanted->value) == 0);
    case NS_CSS_ATTR_SUBSTR:
        if (wanted_len == 0) return FALSE;
        if (!ci) return strstr(value, wanted->value) != NULL;
        for (gsize i = 0; i + wanted_len <= value_len; i++)
            if (g_ascii_strncasecmp(value + i, wanted->value,
                                    wanted_len) == 0)
                return TRUE;
        return FALSE;
    case NS_CSS_ATTR_WORD: {
        const char *p = value;
        while (*p) {
            while (*p && is_ws(*p)) p++;
            const char *token = p;
            while (*p && !is_ws(*p)) p++;
            if ((gsize)(p - token) == wanted_len &&
                (ci ? g_ascii_strncasecmp(token, wanted->value,
                                          wanted_len) == 0
                    : strncmp(token, wanted->value, wanted_len) == 0))
                return TRUE;
        }
        return FALSE;
    }
    case NS_CSS_ATTR_HYPHEN:
        return value_len >= wanted_len &&
               (ci ? g_ascii_strncasecmp(value, wanted->value,
                                         wanted_len) == 0
                   : strncmp(value, wanted->value, wanted_len) == 0) &&
               (value_len == wanted_len || value[wanted_len] == '-');
    case NS_CSS_ATTR_PRESENT:
        return TRUE;
    }
    return FALSE;
}

static gboolean
incr_node_matches_attr_preds(const ns_node *n, const GPtrArray *preds)
{
    if (!n || n->kind != NS_NODE_ELEMENT || !preds) return FALSE;
    for (guint i = 0; i < preds->len; i++) {
        const ns_css_attr_pred *wanted = g_ptr_array_index(preds, i);
        if (!wanted || !wanted->name) continue;
        if (incr_attr_pred_matches(n, wanted)) return TRUE;
    }
    return FALSE;
}

static void
incr_has_anchor_free(gpointer data)
{
    incr_has_anchor *a = data;
    if (a->inv) incr_inv_set_free(a->inv);
    g_free(a->type);
    g_free(a->id);
    g_ptr_array_free(a->classes, TRUE);
    g_ptr_array_free(a->attrs, TRUE);
    g_free(a);
}

static gboolean
incr_has_anchor_matches(const ns_node *n, const incr_has_anchor *a)
{
    if (a->type && (!n->name || g_ascii_strcasecmp(n->name, a->type) != 0))
        return FALSE;
    if (a->id) {
        const char *id = ns_element_id_attr(n);
        if (!id || strcmp(id, a->id) != 0) return FALSE;
    }
    for (guint i = 0; i < a->classes->len; i++) {
        const char *cls = g_ptr_array_index(a->classes, i);
        if (!ns_node_has_class(n, cls, strlen(cls))) return FALSE;
    }
    for (guint i = 0; i < a->attrs->len; i++)
        if (!incr_attr_pred_matches(n, g_ptr_array_index(a->attrs, i)))
            return FALSE;
    return TRUE;
}

static void
incr_mark_subject_candidates(GPtrArray *nodes, const incr_has_anchor *a)
{
    for (guint i = 0; nodes && i < nodes->len; i++) {
        ns_node *n = g_ptr_array_index(nodes, i);
        if (n && n->kind == NS_NODE_ELEMENT && incr_has_anchor_matches(n, a))
            g_hash_table_add(g_incr_dirty, n);
    }
}

static void
incr_mark_loose_has_subjects(ns_node *doc)
{
    if (!g_has_subject_docs || !g_hash_table_remove(g_has_subject_docs, doc))
        return;
    if (!g_has_subject_anchors || g_has_subject_anchors->len == 0) return;
    if (!g_incr_dirty)
        g_incr_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    for (guint i = 0; i < g_has_subject_anchors->len; i++) {
        incr_has_anchor *a = g_ptr_array_index(g_has_subject_anchors, i);
        if (!a->pending) continue;
        a->pending = FALSE;
        if (a->classes->len > 0) {
            if (!doc->class_index) ns_doc_class_index_build(doc);
            incr_mark_subject_candidates(
                ns_doc_class_index_lookup(doc,
                                          g_ptr_array_index(a->classes, 0)),
                a);
        } else if (a->id) {
            ns_node *n = ns_node_find_by_id(doc, a->id);
            if (n && incr_has_anchor_matches(n, a))
                g_hash_table_add(g_incr_dirty, n);
        } else if (a->type) {
            if (!doc->tag_index) ns_doc_tag_index_build(doc);
            incr_mark_subject_candidates(ns_doc_tag_index_lookup(doc, a->type),
                                         a);
        }
    }
}

static GHashTable *g_has_anchor_index;
static GPtrArray  *g_has_anchor_unkeyed;
static guint64     g_has_anchor_gen;
static guint64     g_has_anchor_index_gen;

static void
incr_has_anchor_index_ensure(void)
{
    if (g_has_anchor_index && g_has_anchor_index_gen == g_has_anchor_gen)
        return;
    if (!g_has_anchor_index)
        g_has_anchor_index = g_hash_table_new_full(
            g_str_hash, g_str_equal, g_free,
            (GDestroyNotify)g_ptr_array_unref);
    else
        g_hash_table_remove_all(g_has_anchor_index);
    if (!g_has_anchor_unkeyed) g_has_anchor_unkeyed = g_ptr_array_new();
    g_ptr_array_set_size(g_has_anchor_unkeyed, 0);
    for (guint i = 0; g_has_anchors && i < g_has_anchors->len; i++) {
        incr_has_anchor *a = g_ptr_array_index(g_has_anchors, i);
        char *key = a->classes->len > 0
            ? g_strconcat(".", (char *)g_ptr_array_index(a->classes, 0), NULL)
            : a->id ? g_strconcat("#", a->id, NULL)
            : a->type ? g_strconcat("%", a->type, NULL) : NULL;
        if (!key) {
            g_ptr_array_add(g_has_anchor_unkeyed, a);
            continue;
        }
        GPtrArray *list = g_hash_table_lookup(g_has_anchor_index, key);
        if (list) {
            g_free(key);
        } else {
            list = g_ptr_array_new();
            g_hash_table_insert(g_has_anchor_index, key, list);
        }
        g_ptr_array_add(list, a);
    }
    g_has_anchor_index_gen = g_has_anchor_gen;
}

static void
incr_has_mark_self(ns_node *n, incr_inv_set *inv)
{
    if (!g_incr_self_dirty)
        g_incr_self_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    g_hash_table_add(g_incr_self_dirty, n);
    if (!inv) return;
    if (!g_incr_inv_pending)
        g_incr_inv_pending = g_hash_table_new_full(
            g_direct_hash, g_direct_equal, NULL,
            (GDestroyNotify)g_ptr_array_unref);
    GPtrArray *pending = g_hash_table_lookup(g_incr_inv_pending, n);
    if (!pending) {
        pending = g_ptr_array_new();
        g_hash_table_insert(g_incr_inv_pending, n, pending);
    }
    for (guint i = 0; i < pending->len; i++)
        if (g_ptr_array_index(pending, i) == inv) return;
    g_ptr_array_add(pending, inv);
}

static gboolean
incr_has_apply_list(ns_node *n, const GPtrArray *list)
{
    for (guint i = 0; list && i < list->len; i++) {
        const incr_has_anchor *a = g_ptr_array_index(list, i);
        if (!incr_has_args_relevant(a->args) || !incr_has_anchor_matches(n, a))
            continue;
        switch (a->reach) {
        case INCR_HAS_SELF:
            incr_has_mark_self(n, NULL);
            break;
        case INCR_HAS_DESCENDANTS:
            incr_has_mark_self(n, a->inv);
            break;
        case INCR_HAS_SUBTREE:
            g_hash_table_add(g_incr_dirty, n);
            break;
        case INCR_HAS_REGION:
            incr_mark_has_region(n);
            return TRUE;
        }
    }
    return FALSE;
}

static gboolean
incr_has_apply_key(ns_node *n, char prefix, const char *name, gsize len,
                   gboolean lower)
{
    char stack[128];
    char *key = len + 2 <= sizeof stack ? stack : g_malloc(len + 2);
    key[0] = prefix;
    for (gsize i = 0; i < len; i++)
        key[i + 1] = lower ? g_ascii_tolower(name[i]) : name[i];
    key[len + 1] = '\0';
    const GPtrArray *list = g_hash_table_lookup(g_has_anchor_index, key);
    if (key != stack) g_free(key);
    return list && incr_has_apply_list(n, list);
}

static const char *
class_token_next(const char *p, const char **tok, gsize *len)
{
    while (*p && g_ascii_isspace((guchar)*p)) p++;
    *tok = p;
    while (*p && !g_ascii_isspace((guchar)*p)) p++;
    *len = (gsize)(p - *tok);
    return p;
}

static gboolean
incr_has_apply_name_and_id(ns_node *n)
{
    if (n->name &&
        incr_has_apply_key(n, '%', n->name, strlen(n->name), TRUE))
        return TRUE;
    const char *id = ns_element_id_attr(n);
    return id && *id && incr_has_apply_key(n, '#', id, strlen(id), FALSE);
}

static void
incr_has_apply_classes(ns_node *n)
{
    for (const char *p = ns_element_get_attr(n, "class"); p && *p; ) {
        const char *tok;
        gsize len;
        p = class_token_next(p, &tok, &len);
        if (len && incr_has_apply_key(n, '.', tok, len, FALSE)) return;
    }
}

static void
incr_has_invalidate_anchors(ns_node *n)
{
    if (!n || n->kind != NS_NODE_ELEMENT || !g_has_anchors ||
        g_has_anchors->len == 0)
        return;
    incr_has_anchor_index_ensure();
    if (incr_has_apply_list(n, g_has_anchor_unkeyed)) return;
    if (incr_has_apply_name_and_id(n)) return;
    incr_has_apply_classes(n);
}

static gboolean
incr_childlist_needs_flood(const ns_node *parent)
{
    if (g_struct_loose) return TRUE;
    if (g_incr_dirty && g_hash_table_contains(g_incr_dirty, parent))
        return TRUE;
    if (incr_node_matches_keys(parent, g_struct_keys) ||
        incr_node_matches_attr_preds(parent, g_struct_attrs))
        return TRUE;
    for (const ns_node *c = parent->first_child; c; c = c->next_sibling) {
        if (c->kind == NS_NODE_ELEMENT &&
            (incr_node_matches_keys(c, g_struct_keys) ||
             incr_node_matches_attr_preds(c, g_struct_attrs)))
            return TRUE;
    }
    for (const ns_node *a = parent; a; a = a->parent)
        if (incr_node_matches_keys(a, g_struct_anc_keys) ||
            incr_node_matches_attr_preds(a, g_struct_anc_attrs))
            return TRUE;
    return FALSE;
}

static void incr_mark_self_dirty(ns_node *target, GPtrArray *queue);

static gboolean
incr_node_hits_key_sets(const ns_node *n, GHashTable *keys, GHashTable *attrs)
{
    if (!keys) return FALSE;
    if (incr_node_matches_keys(n, keys)) return TRUE;
    if (g_hash_table_size(attrs) == 0) return FALSE;
    for (const ns_attr *a = n->attrs; a; a = a->next) {
        if (!a->name) continue;
        char *low = g_ascii_strdown(a->name, -1);
        gboolean hit = g_hash_table_contains(attrs, low);
        g_free(low);
        if (hit) return TRUE;
    }
    return FALSE;
}

static gboolean
incr_node_hits_struct_flood(const ns_node *n)
{
    return incr_node_hits_key_sets(n, g_struct_flood_keys,
                                   g_struct_flood_attrs);
}

static gboolean incr_mark_following_siblings(ns_node *from);

static void
incr_mark_empty_dependents(ns_node *parent)
{
    if (!parent->next_sibling || parent->kind != NS_NODE_ELEMENT) return;
    if (!g_empty_sib_loose &&
        !incr_node_hits_key_sets(parent, g_empty_sib_keys, g_empty_sib_attrs))
        return;
    if (!incr_mark_following_siblings(parent->next_sibling))
        ns_css_mark_restyle_dirty(parent->parent ? parent->parent : parent);
}

static gboolean
incr_mark_children_positions(ns_node *parent, ns_node *added)
{
    const incr_inv_set *desc = g_struct_desc_inv;
    if (g_struct_loose || (desc && desc->whole) ||
        (g_incr_dirty && g_hash_table_contains(g_incr_dirty, parent)))
        return FALSE;
    GPtrArray *queue = g_ptr_array_new();
    if (desc) g_ptr_array_add(queue, (gpointer)desc);
    incr_mark_self_dirty(parent, NULL);
    for (ns_node *c = parent->first_child; c; c = c->next_sibling) {
        if (c->kind != NS_NODE_ELEMENT || c == added) continue;
        if (incr_node_hits_struct_flood(c))
            ns_css_mark_restyle_dirty(c);
        else
            incr_mark_self_dirty(c, queue);
    }
    g_ptr_array_free(queue, TRUE);
    if (added) ns_css_mark_restyle_dirty(added);
    return TRUE;
}

static void
incr_mark_childlist(ns_node *parent, ns_node *added)
{
    if (!g_struct_ready) {
        ns_css_mark_restyle_dirty(parent);
        return;
    }
    incr_mark_empty_dependents(parent);
    if (incr_childlist_needs_flood(parent)) {
        if (!incr_mark_children_positions(parent, added))
            ns_css_mark_restyle_dirty(parent);
    } else if (added)
        ns_css_mark_restyle_dirty(added);
    else
        incr_mark_has_subjects(parent);
}

void
ns_css_mark_childlist_dirty(ns_node *parent, ns_node *added)
{
    ns_css_mark_childlist_replaced(parent, added, NULL, 0);
}

static gboolean
incr_node_connected(const ns_node *n)
{
    const ns_node *root = ns_node_root(n);
    return root && root->kind == NS_NODE_DOCUMENT &&
           !(root->flags & NS_NODE_FRAGMENT);
}

void
ns_css_mark_childlist_replaced(ns_node *parent, ns_node *added,
                               ns_node *const *removed, guint n_removed)
{
    if (!parent || !incr_node_connected(parent)) return;
    gboolean gated = added &&
                     incr_has_mut_begin_replaced(added, removed, n_removed);
    incr_mark_childlist(parent, added);
    incr_has_mut_end(gated);
}

void
ns_css_mark_childlist_removed(ns_node *parent, ns_node *const *removed,
                              guint n_removed, ns_node *next_sibling,
                              ns_node *previous_sibling)
{
    if (!parent || !incr_node_connected(parent)) return;
    gboolean gated = n_removed > 0 &&
                     incr_has_mut_begin_nodes(removed, n_removed, FALSE);
    incr_mark_childlist(parent, NULL);
    ns_node *gap = next_sibling ? next_sibling : previous_sibling;
    if (gap && gap->parent == parent) incr_mark_has_subjects(gap);
    incr_has_mut_end(gated);
}

static gboolean
incr_mark_following_siblings(ns_node *from)
{
    int marked = 0;
    for (ns_node *s = from; s; s = s->next_sibling)
        if (s->kind == NS_NODE_ELEMENT) {
            if (++marked > 256) return FALSE;
            ns_css_mark_restyle_dirty(s);
        }
    return TRUE;
}

static gboolean
class_list_has_token(const char *list, const char *tok, gsize len)
{
    for (const char *q = list; q && *q; ) {
        const char *other_tok;
        gsize other_len;
        q = class_token_next(q, &other_tok, &other_len);
        if (other_len == len && memcmp(other_tok, tok, len) == 0) return TRUE;
    }
    return FALSE;
}

static gboolean
incr_class_tokens_added_hit(const char *list, const char *other,
                            GHashTable *keys)
{
    for (const char *p = list; p && *p; ) {
        const char *tok;
        gsize len;
        p = class_token_next(p, &tok, &len);
        if (len && !class_list_has_token(other, tok, len) &&
            incr_keyset_contains(keys, '.', tok, len, FALSE))
            return TRUE;
    }
    return FALSE;
}

static gboolean
incr_attr_key_change_is_sib(const ns_node *target, const char *name,
                            const char *old_value)
{
    if (!target || !name || !g_sib_keys) return FALSE;
    if (g_ascii_strcasecmp(name, "id") == 0) {
        const char *value = ns_element_id_attr(target);
        char *new_key = value && *value ? g_strconcat("#", value, NULL) : NULL;
        char *old_key = old_value && *old_value ?
            g_strconcat("#", old_value, NULL) : NULL;
        gboolean hit = (new_key && g_hash_table_contains(g_sib_keys, new_key)) ||
                       (old_key && g_hash_table_contains(g_sib_keys, old_key));
        g_free(new_key);
        g_free(old_key);
        return hit;
    }
    if (g_ascii_strcasecmp(name, "class") != 0) return FALSE;
    const char *value = ns_element_get_attr(target, "class");
    return incr_class_tokens_added_hit(value, old_value, g_sib_keys) ||
           incr_class_tokens_added_hit(old_value, value, g_sib_keys);
}

static gboolean
incr_queue_inv(GPtrArray *queue, char prefix, const char *name, gsize len)
{
    if (!g_inv_sets) return FALSE;
    char *key = g_strdup_printf("%c%.*s", prefix, (int)len, name);
    incr_inv_set *inv = g_hash_table_lookup(g_inv_sets, key);
    g_free(key);
    if (!inv || inv->whole) return FALSE;
    g_ptr_array_add(queue, inv);
    return TRUE;
}

static gboolean
incr_queue_class_tokens(GPtrArray *queue, const char *list, const char *other)
{
    for (const char *p = list; p && *p; ) {
        const char *tok;
        gsize len;
        p = class_token_next(p, &tok, &len);
        if (!len || class_list_has_token(other, tok, len) ||
            !incr_name_in_keys(tok, len, g_desc_class_keys))
            continue;
        if (!incr_queue_inv(queue, '.', tok, len)) return FALSE;
    }
    return TRUE;
}

static gboolean
incr_queue_class_change(GPtrArray *queue, const char *old_value,
                        const char *new_value)
{
    return incr_queue_class_tokens(queue, old_value, new_value) &&
           incr_queue_class_tokens(queue, new_value, old_value);
}

static gboolean
attr_disables_descendants(const ns_node *target, const char *name)
{
    return g_ascii_strcasecmp(name, "disabled") == 0 &&
           (ns_node_is_element_named(target, "fieldset") ||
            ns_node_is_element_named(target, "optgroup"));
}

static gboolean
attr_restyles_subtree(const ns_node *target, const char *name)
{
    static const char *const subtree_attrs[] = {
        "lang", "xml:lang", "dir", "slot", "inert", "open", "popover",
        "part", "exportparts",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(subtree_attrs); i++)
        if (g_ascii_strcasecmp(name, subtree_attrs[i]) == 0) return TRUE;
    return attr_disables_descendants(target, name);
}

static gboolean
incr_attr_queue_ready(const char *name)
{
    return g_struct_ready && !g_desc_keys_loose && name && g_desc_attr_keys;
}

static gboolean
incr_queue_attr_key(GPtrArray *queue, const char *name)
{
    gsize name_len = strlen(name);
    if (!incr_name_in_keys(name, name_len, g_desc_attr_keys)) return TRUE;
    char *low = g_ascii_strdown(name, -1);
    gboolean queued = incr_queue_inv(queue, '[', low, name_len);
    g_free(low);
    return queued;
}

static gboolean
incr_queue_id_change(GPtrArray *queue, const char *old_id, const char *new_id)
{
    const char *ids[2] = { old_id, new_id };
    for (int i = 0; i < 2; i++) {
        if (!ids[i] || !*ids[i]) continue;
        if (!incr_name_in_keys(ids[i], strlen(ids[i]), g_desc_id_keys))
            continue;
        if (!incr_queue_inv(queue, '#', ids[i], strlen(ids[i])))
            return FALSE;
    }
    return TRUE;
}

static gboolean
incr_queue_attr_change(GPtrArray *queue, const ns_node *target,
                       const char *name, const char *old_value)
{
    if (!incr_attr_queue_ready(name) || attr_restyles_subtree(target, name))
        return FALSE;
    if (g_ascii_strcasecmp(name, "style") == 0) return TRUE;
    if (is_presentational_attr_name(name)) return FALSE;
    if (!incr_queue_attr_key(queue, name)) return FALSE;
    if (g_ascii_strcasecmp(name, "class") == 0)
        return incr_queue_class_change(queue, old_value,
                                       ns_element_get_attr(target, "class"));
    if (g_ascii_strcasecmp(name, "id") == 0)
        return incr_queue_id_change(queue, old_value,
                                    ns_element_id_attr(target));
    return TRUE;
}

static void
incr_add_self_dirty(ns_node *target)
{
    if (!g_incr_self_dirty)
        g_incr_self_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    g_hash_table_add(g_incr_self_dirty, target);
}

static void
incr_mark_self_dirty(ns_node *target, GPtrArray *queue)
{
    incr_add_self_dirty(target);
    if (queue && queue->len > 0) {
        if (!g_incr_inv_pending)
            g_incr_inv_pending = g_hash_table_new_full(
                g_direct_hash, g_direct_equal, NULL,
                (GDestroyNotify)g_ptr_array_unref);
        GPtrArray *pending = g_hash_table_lookup(g_incr_inv_pending, target);
        if (!pending) {
            pending = g_ptr_array_new();
            g_hash_table_insert(g_incr_inv_pending, target, pending);
        }
        for (guint i = 0; i < queue->len; i++)
            g_ptr_array_add(pending, g_ptr_array_index(queue, i));
    }
    incr_mark_has_subjects(target);
}

static gboolean
incr_node_hits_inv(const ns_node *n)
{
    for (guint i = 0; i < g_inv_active->len; i++) {
        const incr_inv_set *inv = g_ptr_array_index(g_inv_active, i);
        if (incr_node_matches_keys(n, inv->keys)) return TRUE;
        for (guint a = 0; a < inv->attrs->len; a++)
            if (ns_element_get_attr(n, g_ptr_array_index(inv->attrs, a)))
                return TRUE;
    }
    return FALSE;
}

static void incr_mark_attr_change(ns_node *target, const char *name,
                                  const char *old_value);

void
ns_css_mark_attr_dirty(ns_node *target, const char *name, const char *old_value)
{
    if (!target) return;
    if (name && old_value &&
        g_strcmp0(ns_element_get_attr(target, name), old_value) == 0)
        return;
    if (target->flags & NS_NODE_STYLE_USES_ATTR)
        ns_css_mark_restyle_dirty(target);
    if (!ns_css_attr_may_affect_style(target, name)) return;
    if (incr_name_change_unused(target, name, old_value)) return;
    gboolean gated = incr_has_mut_begin_attr(target, name, old_value);
    incr_mark_attr_change(target, name, old_value);
    incr_has_mut_end(gated);
}

static gboolean
incr_style_attr_untested(const char *name)
{
    return name && g_ascii_strcasecmp(name, "style") == 0 && g_attr_keys &&
           !g_hash_table_contains(g_attr_keys, "style");
}

static gboolean
incr_style_attr_restyles_self(const char *name)
{
    return name && g_ascii_strcasecmp(name, "style") == 0 &&
           !g_desc_keys_loose &&
           !(g_desc_attr_keys &&
             g_hash_table_contains(g_desc_attr_keys, "style"));
}

static gboolean
incr_attr_change_hits_siblings(ns_node *target, const char *name,
                               const char *old_value)
{
    if (g_sib_loose || incr_attr_key_change_is_sib(target, name, old_value))
        return TRUE;
    if (!name || !g_sib_attrs) return FALSE;
    char *low = g_ascii_strdown(name, -1);
    gboolean sib = FALSE;
    if (g_hash_table_contains(g_sib_attrs, low)) {
        gboolean value_sensitive = g_sib_value_attrs &&
            g_hash_table_contains(g_sib_value_attrs, low);
        gboolean was_present = old_value != NULL;
        gboolean is_present = ns_element_get_attr(target, name) != NULL;
        sib = value_sensitive || was_present != is_present;
    }
    g_free(low);
    return sib;
}

static void
incr_mark_sibling_change(ns_node *target)
{
    ns_css_mark_restyle_dirty(target);
    if (target->next_sibling &&
        !incr_mark_following_siblings(target->next_sibling))
        ns_css_mark_restyle_dirty(target->parent ? target->parent : target);
}

static void
incr_mark_queued_attr_change(ns_node *target, const char *name,
                             const char *old_value)
{
    GPtrArray *queue = g_ptr_array_new();
    if (incr_queue_attr_change(queue, target, name, old_value))
        incr_mark_self_dirty(target, queue);
    else
        ns_css_mark_restyle_dirty(target);
    g_ptr_array_free(queue, TRUE);
}

static void
incr_mark_attr_change(ns_node *target, const char *name, const char *old_value)
{
    if (!g_struct_ready) {
        ns_css_mark_restyle_dirty(target->parent ? target->parent : target);
        return;
    }
    if (incr_style_attr_untested(name)) {
        incr_add_self_dirty(target);
        return;
    }
    if (incr_style_attr_restyles_self(name)) {
        incr_mark_self_dirty(target, NULL);
        return;
    }
    if (incr_attr_change_hits_siblings(target, name, old_value))
        incr_mark_sibling_change(target);
    else
        incr_mark_queued_attr_change(target, name, old_value);
}

gboolean
ns_css_attr_may_affect_style(const ns_node *target, const char *name)
{
    if (!name || !*name || !g_struct_ready || !g_attr_keys) return TRUE;
    if (is_presentational_attr_name(name)) return TRUE;
    if (g_ascii_strcasecmp(name, "rel") == 0 &&
        ns_node_is_element_named(target, "link"))
        return TRUE;
    char *low = g_ascii_strdown(name, -1);
    gboolean affects = g_hash_table_contains(g_attr_keys, low);
    static const char *const intrinsic[] = {
        "class", "id", "style", "hidden", "lang", "xml:lang", "dir",
        "width", "height", "src", "srcset", "sizes", "href", "type",
        "value", "checked", "selected", "open", "disabled", "readonly",
        "required", "placeholder", "multiple", "size", "rows", "cols",
        "rowspan", "colspan", "span", "start", "reversed", "wrap",
        "contenteditable", "inert", "popover", "popovertarget", "slot",
        "name", "form", "list", "min", "max", "step", "media",
    };
    for (guint i = 0; !affects && i < G_N_ELEMENTS(intrinsic); i++)
        affects = strcmp(low, intrinsic[i]) == 0;
    g_free(low);
    return affects;
}

static gboolean
incr_add_positive_subject_deps(GHashTable *keys, GPtrArray *attrs,
                               const ns_css_selector *sel, int depth);

static gboolean
incr_add_positive_compound_deps(GHashTable *keys, GPtrArray *attrs,
                                const ns_css_simple *c, int depth)
{
    if (!c || depth > 6) return FALSE;
    if (c->id && *c->id) {
        g_hash_table_add(keys, g_strconcat("#", c->id, NULL));
        return TRUE;
    }
    if (c->classes && c->classes->len > 0) {
        const char *cls = g_ptr_array_index(c->classes, 0);
        if (cls && *cls) {
            g_hash_table_add(keys, g_strconcat(".", cls, NULL));
            return TRUE;
        }
    }
    if (c->attrs && c->attrs->len > 0) {
        g_ptr_array_add(attrs, &g_array_index(c->attrs, ns_css_attr_pred, 0));
        return TRUE;
    }
    if (c->type && *c->type && strcmp(c->type, "*") != 0) {
        char *type = g_ascii_strdown(c->type, -1);
        g_hash_table_add(keys, g_strconcat("%", type, NULL));
        g_free(type);
        return TRUE;
    }
    if (!c->matches_any) return FALSE;
    for (guint gi = 0; gi < c->matches_any->len; gi++) {
        const GPtrArray *group = g_ptr_array_index(c->matches_any, gi);
        if (!group || group->len == 0) continue;
        GHashTable *group_keys = g_hash_table_new_full(
            g_str_hash, g_str_equal, g_free, NULL);
        GPtrArray *group_attrs = g_ptr_array_new();
        gboolean complete = TRUE;
        for (guint si = 0; si < group->len; si++)
            if (!incr_add_positive_subject_deps(
                    group_keys, group_attrs,
                    g_ptr_array_index(group, si), depth + 1)) {
                complete = FALSE;
                break;
            }
        if (complete) {
            GHashTableIter it;
            gpointer key;
            g_hash_table_iter_init(&it, group_keys);
            while (g_hash_table_iter_next(&it, &key, NULL))
                g_hash_table_add(keys, g_strdup(key));
            for (guint ai = 0; ai < group_attrs->len; ai++)
                g_ptr_array_add(attrs, g_ptr_array_index(group_attrs, ai));
            g_hash_table_destroy(group_keys);
            g_ptr_array_free(group_attrs, TRUE);
            return TRUE;
        }
        g_hash_table_destroy(group_keys);
        g_ptr_array_free(group_attrs, TRUE);
    }
    return FALSE;
}

static gboolean
incr_add_positive_subject_deps(GHashTable *keys, GPtrArray *attrs,
                               const ns_css_selector *sel, int depth)
{
    if (!sel || !sel->compounds || sel->compounds->len == 0)
        return FALSE;
    const ns_css_simple *subject =
        g_ptr_array_index(sel->compounds, sel->compounds->len - 1);
    return incr_add_positive_compound_deps(keys, attrs, subject, depth);
}

static gboolean incr_selector_uses_has(const ns_css_selector *sel, int depth);

static gboolean
incr_simple_uses_has(const ns_css_simple *c, int depth)
{
    if (!c) return FALSE;
    if (depth > 6) return TRUE;
    if (c->has_groups && c->has_groups->len > 0) return TRUE;
    if (c->pseudos)
        for (guint i = 0; i < c->pseudos->len; i++) {
            const ns_css_pseudo_pred *p =
                &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
            if (p->of_group)
                for (guint gi = 0; gi < p->of_group->len; gi++)
                    if (incr_selector_uses_has(
                            g_ptr_array_index(p->of_group, gi), depth + 1))
                        return TRUE;
        }
    GPtrArray *groups[2] = { c->matches_any, c->matches_none };
    for (guint g = 0; g < G_N_ELEMENTS(groups); g++) {
        if (!groups[g]) continue;
        for (guint gi = 0; gi < groups[g]->len; gi++) {
            const GPtrArray *group = g_ptr_array_index(groups[g], gi);
            for (guint si = 0; group && si < group->len; si++)
                if (incr_selector_uses_has(
                        g_ptr_array_index(group, si), depth + 1))
                    return TRUE;
        }
    }
    return FALSE;
}

static gboolean
incr_selector_uses_has(const ns_css_selector *sel, int depth)
{
    if (!sel || !sel->compounds) return FALSE;
    for (guint i = 0; i < sel->compounds->len; i++)
        if (incr_simple_uses_has(
                g_ptr_array_index(sel->compounds, i), depth))
            return TRUE;
    return FALSE;
}

typedef struct incr_has_ctx {
    const ns_css_selector *sel;
    guint idx;
    const struct incr_has_ctx *outer;
} incr_has_ctx;

static void
incr_has_anchor_copy_keys(incr_has_anchor *a, const ns_css_simple *c)
{
    for (guint i = 0; c->classes && i < c->classes->len; i++) {
        const char *cls = g_ptr_array_index(c->classes, i);
        if (cls && *cls) g_ptr_array_add(a->classes, g_strdup(cls));
    }
    for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
        const ns_css_attr_pred *src =
            &g_array_index(c->attrs, ns_css_attr_pred, i);
        if (!src->name) continue;
        ns_css_attr_pred *copy = g_new0(ns_css_attr_pred, 1);
        *copy = *src;
        copy->name = g_strdup(src->name);
        copy->value = g_strdup(src->value);
        g_ptr_array_add(a->attrs, copy);
    }
}

static const ns_css_selector *g_has_anchor_ctx_sel;
static guint                  g_has_anchor_ctx_idx;

static void
incr_has_anchor_set_reach(incr_has_anchor *a)
{
    a->reach = INCR_HAS_REGION;
    const ns_css_selector *sel = g_has_anchor_ctx_sel;
    if (!sel || !sel->compounds) return;
    guint last = sel->compounds->len - 1;
    guint idx = g_has_anchor_ctx_idx;
    if (idx == last) {
        a->reach = INCR_HAS_SELF;
        return;
    }
    for (guint i = idx + 1; i <= last; i++) {
        ns_css_comb comb = NS_CSS_COMB_DESCENDANT;
        if (sel->combinators && i < sel->combinators->len)
            comb = g_array_index(sel->combinators, ns_css_comb, i);
        if (comb != NS_CSS_COMB_DESCENDANT && comb != NS_CSS_COMB_CHILD)
            return;
    }
    a->inv = g_new0(incr_inv_set, 1);
    a->inv->keys = g_hash_table_new_full(g_str_hash, g_str_equal, g_free,
                                         NULL);
    a->inv->attrs = g_ptr_array_new_with_free_func(g_free);
    incr_inv_add_subject(a->inv, g_ptr_array_index(sel->compounds, last));
    a->reach = a->inv->whole ? INCR_HAS_SUBTREE : INCR_HAS_DESCENDANTS;
}

static incr_has_anchor *
incr_has_anchor_from_compound(const ns_css_simple *c)
{
    incr_has_anchor *a = g_new0(incr_has_anchor, 1);
    a->classes = g_ptr_array_new_with_free_func(g_free);
    a->attrs = g_ptr_array_new_with_free_func(incr_attr_dep_free);
    a->args = g_has_args_cur;
    incr_has_anchor_set_reach(a);
    if (c->type && *c->type && strcmp(c->type, "*") != 0)
        a->type = g_ascii_strdown(c->type, -1);
    if (c->id && *c->id) a->id = g_strdup(c->id);
    incr_has_anchor_copy_keys(a, c);
    if (a->type || a->id || a->classes->len > 0 || a->attrs->len > 0)
        return a;
    incr_has_anchor_free(a);
    return NULL;
}

static gboolean incr_add_has_anchor_compound(const ns_css_simple *c,
                                             int depth);

static gboolean
incr_add_has_anchor_group(const GPtrArray *group, int depth)
{
    guint mark = g_has_anchors->len;
    for (guint si = 0; si < group->len; si++) {
        const ns_css_selector *alt = g_ptr_array_index(group, si);
        if (!alt || !alt->compounds || alt->compounds->len == 0 ||
            !incr_add_has_anchor_compound(
                g_ptr_array_index(alt->compounds, alt->compounds->len - 1),
                depth + 1)) {
            g_ptr_array_set_size(g_has_anchors, mark);
            g_has_anchor_gen++;
            return FALSE;
        }
    }
    return TRUE;
}

static gboolean
incr_add_has_anchor_compound(const ns_css_simple *c, int depth)
{
    if (!c || depth > 6) return FALSE;
    incr_has_anchor *a = incr_has_anchor_from_compound(c);
    if (a) {
        g_ptr_array_add(g_has_anchors, a);
        g_has_anchor_gen++;
        return TRUE;
    }
    for (guint gi = 0; c->matches_any && gi < c->matches_any->len; gi++) {
        const GPtrArray *group = g_ptr_array_index(c->matches_any, gi);
        if (group && group->len > 0 && incr_add_has_anchor_group(group, depth))
            return TRUE;
    }
    return FALSE;
}

static gboolean
incr_add_has_anchor_deps(const incr_has_ctx *at, int depth)
{
    for (const incr_has_ctx *cx = at; cx; cx = cx->outer) {
        for (guint i = cx->idx + 1; i-- > 0; ) {
            g_has_anchor_ctx_sel = cx->outer ? NULL : cx->sel;
            g_has_anchor_ctx_idx = i;
            gboolean added = incr_add_has_anchor_compound(
                g_ptr_array_index(cx->sel->compounds, i), depth);
            g_has_anchor_ctx_sel = NULL;
            if (added) return TRUE;
        }
        if (cx->idx + 1 != cx->sel->compounds->len) return FALSE;
    }
    return FALSE;
}

static gboolean incr_collect_has_anchors_selector(const ns_css_selector *sel,
                                                  const incr_has_ctx *outer,
                                                  int depth);

static gboolean
incr_add_has_subject_anchor(const incr_has_ctx *at)
{
    const incr_has_ctx *top = at;
    while (top->outer) top = top->outer;
    if (!top->sel || !top->sel->compounds || top->sel->compounds->len == 0)
        return FALSE;
    const ns_css_simple *subject =
        g_ptr_array_index(top->sel->compounds, top->sel->compounds->len - 1);
    if (!subject || (!subject->id && !subject->type &&
                     (!subject->classes || subject->classes->len == 0)))
        return FALSE;
    incr_has_anchor *a = incr_has_anchor_from_compound(subject);
    if (!a) return FALSE;
    if (!a->id && !a->type && a->classes->len == 0) {
        incr_has_anchor_free(a);
        return FALSE;
    }
    if (!g_has_subject_anchors)
        g_has_subject_anchors =
            g_ptr_array_new_with_free_func(incr_has_anchor_free);
    g_ptr_array_add(g_has_subject_anchors, a);
    return TRUE;
}

static void
incr_has_arg_note_compound(incr_has_args *args, const ns_css_simple *c)
{
    gboolean keyed = incr_add_compound_keys(args->keys, c);
    for (guint i = 0; c->attrs && i < c->attrs->len; i++) {
        const ns_css_attr_pred *a =
            &g_array_index(c->attrs, ns_css_attr_pred, i);
        if (!a->name) continue;
        g_hash_table_add(args->attrs, g_ascii_strdown(a->name, -1));
        keyed = TRUE;
    }
    if (!keyed || incr_simple_has_structural(c, 0) ||
        (c->has_groups && c->has_groups->len > 0))
        args->loose = TRUE;
}

static void
incr_has_arg_note_selector(incr_has_args *args, const ns_css_selector *sel)
{
    if (!sel || !sel->compounds || sel->compounds->len == 0) {
        args->loose = TRUE;
        return;
    }
    for (guint i = 0; sel->combinators && i < sel->combinators->len; i++) {
        ns_css_comb comb = g_array_index(sel->combinators, ns_css_comb, i);
        if (comb == NS_CSS_COMB_ADJACENT || comb == NS_CSS_COMB_SIBLING)
            args->loose = TRUE;
    }
    for (guint i = 0; i < sel->compounds->len; i++)
        incr_has_arg_note_compound(args, g_ptr_array_index(sel->compounds, i));
}

static void
incr_note_has_groups(const incr_has_ctx *at, int depth, const ns_css_simple *c)
{
    incr_has_args *args = incr_has_args_new();
    for (guint gi = 0; gi < c->has_groups->len; gi++) {
        const GPtrArray *group = g_ptr_array_index(c->has_groups, gi);
        for (guint si = 0; group && si < group->len; si++)
            incr_has_arg_note_selector(args, g_ptr_array_index(group, si));
    }
    if (!args->loose) g_has_args_gateable = TRUE;
    incr_has_args *outer_args = g_has_args_cur;
    g_has_args_cur = args;
    if (!incr_add_has_anchor_deps(at, depth) &&
        !incr_add_has_subject_anchor(at))
        g_has_cq_loose = TRUE;
    g_has_args_cur = outer_args;
}

static gboolean
incr_collect_has_anchors_list(const GPtrArray *sels, const incr_has_ctx *at,
                              int depth)
{
    gboolean found = FALSE;
    for (guint i = 0; sels && i < sels->len; i++)
        found |= incr_collect_has_anchors_selector(
            g_ptr_array_index(sels, i), at, depth + 1);
    return found;
}

static gboolean
incr_collect_has_anchors_pseudos(const ns_css_simple *c,
                                 const incr_has_ctx *at, int depth)
{
    gboolean found = FALSE;
    for (guint i = 0; c->pseudos && i < c->pseudos->len; i++) {
        const ns_css_pseudo_pred *p =
            &g_array_index(c->pseudos, ns_css_pseudo_pred, i);
        found |= incr_collect_has_anchors_list(p->of_group, at, depth);
    }
    return found;
}

static gboolean
incr_collect_has_anchors_matches(const ns_css_simple *c,
                                 const incr_has_ctx *at, int depth)
{
    GPtrArray *groups[2] = { c->matches_any, c->matches_none };
    gboolean found = FALSE;
    for (guint g = 0; g < G_N_ELEMENTS(groups); g++)
        for (guint gi = 0; groups[g] && gi < groups[g]->len; gi++)
            found |= incr_collect_has_anchors_list(
                g_ptr_array_index(groups[g], gi), at, depth);
    return found;
}

static gboolean
incr_collect_has_anchors_simple(const incr_has_ctx *at, int depth)
{
    const ns_css_simple *c = g_ptr_array_index(at->sel->compounds, at->idx);
    if (!c || depth > 6) return FALSE;
    gboolean found = FALSE;
    if (c->has_groups && c->has_groups->len > 0) {
        found = TRUE;
        incr_note_has_groups(at, depth, c);
    }
    found |= incr_collect_has_anchors_pseudos(c, at, depth);
    found |= incr_collect_has_anchors_matches(c, at, depth);
    return found;
}

static gboolean
incr_collect_has_anchors_selector(const ns_css_selector *sel,
                                  const incr_has_ctx *outer, int depth)
{
    if (!sel || !sel->compounds || depth > 6) return FALSE;
    gboolean found = FALSE;
    for (guint i = 0; i < sel->compounds->len; i++) {
        incr_has_ctx at = { sel, i, outer };
        found |= incr_collect_has_anchors_simple(&at, depth);
    }
    return found;
}

static void
incr_collect_has_cq_keys(const ns_css_stylesheet *sh)
{
    if (!sh || !sh->rules) return;
    for (guint ri = 0; ri < sh->rules->len; ri++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, ri);
        if (!r || !r->selectors) continue;
        for (guint si = 0; si < r->selectors->len; si++) {
            const ns_css_selector *sel = g_ptr_array_index(r->selectors, si);
            if (!sel || !sel->compounds || sel->compounds->len == 0) continue;
            if (!incr_selector_uses_has(sel, 0)) continue;
            if (!incr_collect_has_anchors_selector(sel, NULL, 0))
                g_has_cq_loose = TRUE;
        }
    }
}

static guint64
incr_sheet_sig(const ns_css_stylesheet *ua,
               const ns_css_stylesheet *const *author, gsize n)
{
    guint64 h = 1469598103934665603ULL;
    guint64 vals[3] = { ua ? ua->serial : 0, (guint64)n,
                        ns_css_registered_property_serial() };
    for (int i = 0; i < 3; i++) { h ^= vals[i]; h *= 1099511628211ULL; }
    for (gsize i = 0; i < n; i++) {
        h ^= author[i] ? author[i]->serial : 0;
        h *= 1099511628211ULL;
    }
    return h;
}

static GHashTable *g_style_share;
static GByteArray *g_share_scratch;
static guint64 g_style_share_next_id;

typedef struct {
    guint32  hash;
    guint32  len;
    guint8  *data;
} share_key_t;

static guint
share_key_hash(gconstpointer p)
{
    return ((const share_key_t *)p)->hash;
}

static gboolean
share_key_equal(gconstpointer a, gconstpointer b)
{
    const share_key_t *x = a, *y = b;
    return x->hash == y->hash && x->len == y->len &&
           memcmp(x->data, y->data, x->len) == 0;
}

static void
share_key_free(gpointer p)
{
    share_key_t *k = p;
    g_free(k->data);
    g_free(k);
}

static guint32
share_key_djb2(const guint8 *d, guint32 n)
{
    guint64 h = 1469598103934665603ULL;
    guint32 i = 0;
    for (; i + 8 <= n; i += 8) {
        guint64 w;
        memcpy(&w, d + i, 8);
        h = (h ^ w) * 1099511628211ULL;
    }
    for (; i < n; i++)
        h = (h ^ d[i]) * 1099511628211ULL;
    return (guint32)(h ^ (h >> 32));
}

typedef struct {
    ns_css_pseudo_element pe;
    GArray *m;
    GArray *v;
    GArray *p;
} ns_pe_gather;

static ns_var_map *
ns_style_vars_clone(ns_var_map *vars)
{
    return ns_var_map_ref(vars);
}

static ns_style *
ns_style_clone_shared(const ns_style *s)
{
    if (!s) return NULL;
    ns_style *c = ns_style_alloc();
    c->share_id = s->share_id;
    c->display  = s->display;
    c->explicit_inherit = s->explicit_inherit;
    c->env_dependent = s->env_dependent;
    c->currentcolor_bits = s->currentcolor_bits;
    c->inherited_bits = s->inherited_bits;
    for (int i = 0; i < NS_CSS_PROP_COUNT; i++) {
        c->values[i] = s->values[i];
        if (c->values[i]) c->values[i]->ref++;
    }
    c->before       = ns_style_clone_shared(s->before);
    c->after        = ns_style_clone_shared(s->after);
    c->first_letter = ns_style_clone_shared(s->first_letter);
    c->first_line   = ns_style_clone_shared(s->first_line);
    c->placeholder  = ns_style_clone_shared(s->placeholder);
    c->selection    = ns_style_clone_shared(s->selection);
    c->marker       = ns_style_clone_shared(s->marker);
    c->backdrop     = ns_style_clone_shared(s->backdrop);
    c->file_selector_button = ns_style_clone_shared(
        s->file_selector_button);
    c->hidden_before = ns_style_clone_shared(s->hidden_before);
    c->hidden_after  = ns_style_clone_shared(s->hidden_after);
    c->vars = ns_style_vars_clone(s->vars);
    return c;
}

#define SHARE_KEY_MATCH_BYTES \
    (sizeof(int) * 9 + sizeof(((match_entry *)0)->important) + \
     sizeof(((match_entry *)0)->inline_style) + \
     sizeof(((match_entry *)0)->rule) + sizeof(((match_entry *)0)->value) + \
     sizeof(((match_entry *)0)->prop))
#define SHARE_KEY_VAR_BYTES \
    (sizeof(int) * 9 + sizeof(((var_match *)0)->important) + \
     sizeof(((var_match *)0)->inline_style) + \
     sizeof(((var_match *)0)->rule) + sizeof(((var_match *)0)->name) + \
     sizeof(((var_match *)0)->text))
#define SHARE_KEY_PENDING_BYTES \
    (sizeof(int) * 9 + sizeof(((pending_match *)0)->inline_style) + \
     sizeof(((pending_match *)0)->rule) + sizeof(((pending_match *)0)->pd))

static inline guint8 *
share_key_put_raw(guint8 *p, const void *src, gsize n)
{
    memcpy(p, src, n);
    return p + n;
}

static guint8 *
share_key_put_matches(guint8 *p, const GArray *arr)
{
    guint n = arr ? arr->len : 0;
    p = share_key_put_raw(p, &n, sizeof n);
    for (guint i = 0; i < n; i++) {
        const match_entry *e = &g_array_index((GArray *)arr, match_entry, i);
        p = share_key_put_raw(p, &e->origin, sizeof(int) * 9);
        p = share_key_put_raw(p, &e->important, sizeof e->important);
        p = share_key_put_raw(p, &e->inline_style, sizeof e->inline_style);
        p = share_key_put_raw(p, &e->rule, sizeof e->rule);
        p = share_key_put_raw(p, &e->value, sizeof e->value);
        p = share_key_put_raw(p, &e->prop, sizeof e->prop);
    }
    return p;
}

static guint8 *
share_key_put_vars(guint8 *p, const GArray *arr)
{
    guint n = arr ? arr->len : 0;
    p = share_key_put_raw(p, &n, sizeof n);
    for (guint i = 0; i < n; i++) {
        const var_match *e = &g_array_index((GArray *)arr, var_match, i);
        p = share_key_put_raw(p, &e->origin, sizeof(int) * 9);
        p = share_key_put_raw(p, &e->important, sizeof e->important);
        p = share_key_put_raw(p, &e->inline_style, sizeof e->inline_style);
        p = share_key_put_raw(p, &e->rule, sizeof e->rule);
        p = share_key_put_raw(p, &e->name, sizeof e->name);
        p = share_key_put_raw(p, &e->text, sizeof e->text);
    }
    return p;
}

static guint8 *
share_key_put_pending(guint8 *p, const GArray *arr)
{
    guint n = arr ? arr->len : 0;
    p = share_key_put_raw(p, &n, sizeof n);
    for (guint i = 0; i < n; i++) {
        const pending_match *e = &g_array_index((GArray *)arr, pending_match, i);
        p = share_key_put_raw(p, &e->origin, sizeof(int) * 9);
        p = share_key_put_raw(p, &e->inline_style, sizeof e->inline_style);
        p = share_key_put_raw(p, &e->rule, sizeof e->rule);
        p = share_key_put_raw(p, &e->pd, sizeof e->pd);
    }
    return p;
}

static gboolean
container_relative_unit(ns_css_unit unit)
{
    return unit == NS_CSS_UNIT_CQW || unit == NS_CSS_UNIT_CQH ||
           unit == NS_CSS_UNIT_CQMIN || unit == NS_CSS_UNIT_CQMAX;
}

static gboolean
share_matches_need_container(const GArray *matches)
{
    if (!matches) return FALSE;
    for (guint i = 0; i < matches->len; i++) {
        const match_entry *e = &g_array_index((GArray *)matches,
                                               match_entry, i);
        if (e->prop == NS_CSS_FONT_SIZE && e->value &&
            e->value->kind == NS_CSS_V_LENGTH &&
            container_relative_unit(e->value->u.length.unit))
            return TRUE;
    }
    return FALSE;
}

static gboolean
share_vars_need_container(const GArray *matches)
{
    if (!matches) return FALSE;
    for (guint i = 0; i < matches->len; i++) {
        const var_match *e = &g_array_index((GArray *)matches, var_match, i);
        if (ns_css_text_has_container_units(e->text, -1)) return TRUE;
    }
    return FALSE;
}

static gboolean
share_pending_need_container(const GArray *matches)
{
    if (!matches) return FALSE;
    for (guint i = 0; i < matches->len; i++) {
        const pending_match *e = &g_array_index((GArray *)matches,
                                                 pending_match, i);
        if (e->pd && ns_css_text_has_container_units(e->pd->raw_vtext, -1))
            return TRUE;
    }
    return FALSE;
}

static gboolean
share_key_needs_container(const GArray *matches,
                          const GArray *var_matches,
                          const GArray *pending_matches,
                          const ns_pe_gather *pe_g, int n_pe)
{
    if (share_matches_need_container(matches) ||
        share_vars_need_container(var_matches) ||
        share_pending_need_container(pending_matches))
        return TRUE;
    for (int i = 0; i < n_pe; i++)
        if (share_matches_need_container(pe_g[i].m) ||
            share_vars_need_container(pe_g[i].v) ||
            share_pending_need_container(pe_g[i].p))
            return TRUE;
    return FALSE;
}

static gsize
share_key_arrays_bytes(const GArray *matches, const GArray *var_matches,
                       const GArray *pending_matches)
{
    return sizeof(guint) * 3 +
           (matches ? matches->len : 0) * SHARE_KEY_MATCH_BYTES +
           (var_matches ? var_matches->len : 0) * SHARE_KEY_VAR_BYTES +
           (pending_matches ? pending_matches->len : 0) *
               SHARE_KEY_PENDING_BYTES;
}

static void
style_share_key(GByteArray *b,
                const ns_style *parent_style, double root_px,
                const GArray *matches, const GArray *var_matches,
                const GArray *pending_matches,
                const ns_pe_gather *pe_g, int n_pe)
{
    guint cq_len = g_cq_stack && g_cq_stack->len > 0 &&
        share_key_needs_container(matches, var_matches, pending_matches,
                                  pe_g, n_pe)
        ? g_cq_stack->len : 0;

    gsize need = sizeof(guint64) + sizeof(double) + sizeof(guint) +
                 cq_len * sizeof(ns_cq_container) +
                 share_key_arrays_bytes(matches, var_matches, pending_matches);
    for (int i = 0; i < n_pe; i++)
        need += sizeof(guint) +
                share_key_arrays_bytes(pe_g[i].m, pe_g[i].v, pe_g[i].p);
    if (b->len < need) g_byte_array_set_size(b, (guint)need);

    guint8 *p = b->data;
    guint64 parent_id = parent_style ? parent_style->share_id : 0;
    p = share_key_put_raw(p, &parent_id, sizeof parent_id);
    p = share_key_put_raw(p, &root_px, sizeof root_px);
    p = share_key_put_raw(p, &cq_len, sizeof cq_len);
    if (cq_len)
        p = share_key_put_raw(p, g_cq_stack->data,
                              cq_len * sizeof(ns_cq_container));
    p = share_key_put_matches(p, matches);
    p = share_key_put_vars(p, var_matches);
    p = share_key_put_pending(p, pending_matches);
    for (int i = 0; i < n_pe; i++) {
        guint pe = (guint)pe_g[i].pe;
        p = share_key_put_raw(p, &pe, sizeof pe);
        p = share_key_put_matches(p, pe_g[i].m);
        p = share_key_put_vars(p, pe_g[i].v);
        p = share_key_put_pending(p, pe_g[i].p);
    }
    b->len = (guint)(p - b->data);
}

static gboolean
element_cannot_be_unboxed(const ns_node *el)
{
    if (el->kind != NS_NODE_ELEMENT || !el->name) return FALSE;
    if (el->flags & NS_NODE_SVG_NS)
        return strcmp(el->name, "svg") == 0 && el->parent &&
               !(el->parent->flags & NS_NODE_SVG_NS);
    if (el->flags & NS_NODE_FOREIGN_NS) return FALSE;
    static const char *const unusual[] = {
        "audio", "br", "canvas", "embed", "frame", "frameset", "iframe",
        "img", "input", "meter", "object", "progress", "select",
        "textarea", "video", "wbr",
    };
    for (gsize i = 0; i < G_N_ELEMENTS(unusual); i++)
        if (g_ascii_strcasecmp(el->name, unusual[i]) == 0) return TRUE;
    return FALSE;
}

static gboolean
display_contents_to_none(const ns_node *el, ns_style *s)
{
    if (s->display.box != NS_DISPLAY_BOX_CONTENTS ||
        !element_cannot_be_unboxed(el))
        return FALSE;
    ns_css_value_free(s->values[NS_CSS_DISPLAY]);
    s->values[NS_CSS_DISPLAY] = keyword_value_dup("none");
    s->display = ns_css_display_from_keyword("none");
    return TRUE;
}

static void
button_inline_to_inline_block(const ns_node *el, ns_style *s)
{
    const ns_css_value *v = s->values[NS_CSS_DISPLAY];
    if (s->display.box != NS_DISPLAY_BOX_NORMAL ||
        s->display.outer != NS_DISPLAY_OUTER_INLINE ||
        s->display.inner != NS_DISPLAY_INNER_FLOW ||
        !v || v->kind != NS_CSS_V_KEYWORD || !v->u.keyword ||
        (strcmp(v->u.keyword, "inline") != 0 &&
         strcmp(v->u.keyword, "inline flow") != 0) ||
        !ns_node_is_element_named(el, "button"))
        return;
    s->display = ns_css_display_from_keyword("inline-block");
}

static void
strip_native_widget_decorations(const ns_node *el, ns_style *s)
{
    if (!ns_node_is_element_named(el, "input")) return;
    const char *type = ns_element_get_attr(el, "type");
    if (!type || (g_ascii_strcasecmp(type, "checkbox") != 0 &&
                  g_ascii_strcasecmp(type, "radio") != 0))
        return;
    const ns_css_value *ap = s->values[NS_CSS_APPEARANCE];
    if (ap && ap->kind == NS_CSS_V_KEYWORD && ap->u.keyword &&
        strcmp(ap->u.keyword, "none") == 0)
        return;
    static const ns_css_prop stripped[] = {
        NS_CSS_BACKGROUND_COLOR, NS_CSS_BACKGROUND_IMAGE,
        NS_CSS_BORDER_TOP_WIDTH, NS_CSS_BORDER_RIGHT_WIDTH,
        NS_CSS_BORDER_BOTTOM_WIDTH, NS_CSS_BORDER_LEFT_WIDTH,
        NS_CSS_BORDER_TOP_STYLE, NS_CSS_BORDER_RIGHT_STYLE,
        NS_CSS_BORDER_BOTTOM_STYLE, NS_CSS_BORDER_LEFT_STYLE,
        NS_CSS_BORDER_TOP_COLOR, NS_CSS_BORDER_RIGHT_COLOR,
        NS_CSS_BORDER_BOTTOM_COLOR, NS_CSS_BORDER_LEFT_COLOR,
        NS_CSS_BORDER_TOP_LEFT_RADIUS, NS_CSS_BORDER_TOP_RIGHT_RADIUS,
        NS_CSS_BORDER_BOTTOM_RIGHT_RADIUS, NS_CSS_BORDER_BOTTOM_LEFT_RADIUS,
        NS_CSS_PADDING_TOP, NS_CSS_PADDING_RIGHT,
        NS_CSS_PADDING_BOTTOM, NS_CSS_PADDING_LEFT,
        NS_CSS_BOX_SHADOW,
    };
    for (gsize i = 0; i < G_N_ELEMENTS(stripped); i++) {
        if (s->values[stripped[i]]) {
            ns_css_value_free(s->values[stripped[i]]);
            s->values[stripped[i]] = NULL;
        }
    }
}

static double
frame_edge_px(const ns_style *s, ns_css_prop prop)
{
    const ns_css_value *v = s->values[prop];
    if (!v || v->kind != NS_CSS_V_LENGTH || v->u.length.unit != NS_CSS_UNIT_PX)
        return 0;
    return v->u.length.v;
}

static double
frame_border_px(const ns_style *s, ns_css_prop width_prop,
                ns_css_prop style_prop)
{
    const ns_css_value *st = s->values[style_prop];
    if (!st || (st->kind == NS_CSS_V_KEYWORD && st->u.keyword &&
                (strcmp(st->u.keyword, "none") == 0 ||
                 strcmp(st->u.keyword, "hidden") == 0)))
        return 0;
    return frame_edge_px(s, width_prop);
}

static gboolean
frame_viewport_from_style(const ns_style *s, double *w, double *h)
{
    if (!s) return FALSE;
    const ns_css_value *wv = s->values[NS_CSS_WIDTH];
    const ns_css_value *hv = s->values[NS_CSS_HEIGHT];
    if (!wv || wv->kind != NS_CSS_V_LENGTH ||
        wv->u.length.unit != NS_CSS_UNIT_PX ||
        !hv || hv->kind != NS_CSS_V_LENGTH ||
        hv->u.length.unit != NS_CSS_UNIT_PX)
        return FALSE;
    double fw = wv->u.length.v, fh = hv->u.length.v;
    if (ns_css_keyword_is(s->values[NS_CSS_BOX_SIZING], "border-box")) {
        fw -= frame_edge_px(s, NS_CSS_PADDING_LEFT) +
              frame_edge_px(s, NS_CSS_PADDING_RIGHT) +
              frame_border_px(s, NS_CSS_BORDER_LEFT_WIDTH,
                              NS_CSS_BORDER_LEFT_STYLE) +
              frame_border_px(s, NS_CSS_BORDER_RIGHT_WIDTH,
                              NS_CSS_BORDER_RIGHT_STYLE);
        fh -= frame_edge_px(s, NS_CSS_PADDING_TOP) +
              frame_edge_px(s, NS_CSS_PADDING_BOTTOM) +
              frame_border_px(s, NS_CSS_BORDER_TOP_WIDTH,
                              NS_CSS_BORDER_TOP_STYLE) +
              frame_border_px(s, NS_CSS_BORDER_BOTTOM_WIDTH,
                              NS_CSS_BORDER_BOTTOM_STYLE);
    }
    if (fw <= 0 || fh <= 0) return FALSE;
    *w = fw;
    *h = fh;
    return TRUE;
}

static __thread GHashTable *g_doc_sheets;

static GHashTable *
doc_sheets_new(const ns_css_stylesheet *const *sheets,
               const ns_node *const *docs, gsize n)
{
    if (!docs) return NULL;
    GHashTable *map = g_hash_table_new_full(g_direct_hash, g_direct_equal,
                                            NULL,
                                            (GDestroyNotify)g_ptr_array_unref);
    for (gsize i = 0; i < n; i++) {
        GPtrArray *own = g_hash_table_lookup(map, docs[i]);
        if (!own) {
            own = g_ptr_array_new();
            g_hash_table_insert(map, (gpointer)docs[i], own);
        }
        g_ptr_array_add(own, (gpointer)sheets[i]);
    }
    return map;
}

static GPtrArray *
host_scoped_sheets(const ns_node *node, const ns_css_stylesheet *const *author,
                   gsize n_author)
{
    if (!g_doc_sheets || node->kind != NS_NODE_ELEMENT) return NULL;
    const GPtrArray *own = g_hash_table_lookup(g_doc_sheets, node);
    if (!own || own->len == 0) return NULL;
    GPtrArray *all = g_ptr_array_sized_new((guint)n_author + own->len);
    for (gsize i = 0; i < n_author; i++)
        g_ptr_array_add(all, (gpointer)author[i]);
    for (guint i = 0; i < own->len; i++)
        g_ptr_array_add(all, g_ptr_array_index(own, i));
    return all;
}

static void
doc_own_sheets(const ns_node *node, const ns_css_stylesheet *const **author,
               gsize *n_author)
{
    if (!g_doc_sheets || node->kind != NS_NODE_DOCUMENT) return;
    const GPtrArray *own = g_hash_table_lookup(g_doc_sheets, node);
    *author = own ? (const ns_css_stylesheet *const *)own->pdata : NULL;
    *n_author = own ? own->len : 0;
}

static GHashTable *g_incr_walk_needed;

static void
incr_walk_needed_add_chain(gpointer key, gpointer value, gpointer user)
{
    (void)value; (void)user;
    for (ns_node *n = key; n; n = n->parent)
        if (!g_hash_table_insert(g_incr_walk_needed, n, n)) break;
}

static void
incr_walk_needed_build(void)
{
    if (!g_incr_walk_needed)
        g_incr_walk_needed = g_hash_table_new(g_direct_hash, g_direct_equal);
    GHashTable *sources[4] = {
        g_incr_dirty, g_incr_self_dirty, g_incr_exclude, g_incr_inv_pending,
    };
    for (gsize i = 0; i < G_N_ELEMENTS(sources); i++)
        if (sources[i])
            g_hash_table_foreach(sources[i], incr_walk_needed_add_chain, NULL);
}

static gboolean
incr_copy_clean_subtree(ns_node *node, GHashTable *out)
{
    ns_style *s = g_hash_table_lookup(g_incr_prev_styles, node);
    if (!s) return FALSE;
    s->ref++;
    g_hash_table_insert(out, node, s);
    g_incr_reused++;
    for (ns_node *c = node->first_child; c; c = c->next_sibling) {
        if (c->kind == NS_NODE_DOCUMENT) return FALSE;
        if (c->kind == NS_NODE_ELEMENT && !incr_copy_clean_subtree(c, out))
            return FALSE;
    }
    return TRUE;
}

enum {
    STYLE_READS_CONTAINER    = 1 << 0,
    STYLE_READS_FONT_METRICS = 1 << 1,
};

static void
incr_note_env_dependent(ns_node *node, guint8 reads)
{
    if (reads) {
        if (!g_incr_env_nodes)
            g_incr_env_nodes = g_hash_table_new(g_direct_hash, g_direct_equal);
        g_hash_table_insert(g_incr_env_nodes, node, GUINT_TO_POINTER(reads));
    } else if (g_incr_env_nodes && g_hash_table_size(g_incr_env_nodes) > 0) {
        g_hash_table_remove(g_incr_env_nodes, node);
    }
}

static void
incr_mark_env_dependents(guint changed)
{
    if (!changed || !g_incr_env_nodes ||
        g_hash_table_size(g_incr_env_nodes) == 0)
        return;
    if (!g_incr_self_dirty)
        g_incr_self_dirty = g_hash_table_new(g_direct_hash, g_direct_equal);
    GHashTableIter it;
    gpointer node, reads;
    g_hash_table_iter_init(&it, g_incr_env_nodes);
    while (g_hash_table_iter_next(&it, &node, &reads))
        if (GPOINTER_TO_UINT(reads) & changed)
            g_hash_table_add(g_incr_self_dirty, node);
}

static void
cascade_walk(ns_node *node,
             const ns_css_stylesheet *ua,
             const ns_css_stylesheet *const *author, gsize n_author,
             const ns_style *parent_style,
             const ns_style *layout_parent,
             double *root_px,
             GHashTable *layer_ranks,
             GHashTable *out,
             gboolean under_dirty,
             gboolean parent_changed)
{
    static int depth;
    if (depth >= NS_CSS_MAX_CASCADE_DEPTH) return;
    if (node->kind == NS_NODE_ELEMENT && g_incr_pass_active && !under_dirty &&
        !parent_changed && g_incr_walk_needed && *root_px > 0 &&
        (!g_inv_active || g_inv_active->len == 0) &&
        !g_hash_table_contains(g_incr_walk_needed, node) &&
        incr_copy_clean_subtree(node, out))
        return;
    depth++;
    double frame_vw = 0, frame_vh = 0;
    gboolean frame_viewport = FALSE;
    if (node->kind == NS_NODE_DOCUMENT && node->parent && g_frame_viewport_cb) {
        double fw = 0, fh = 0;
        if (!frame_viewport_from_style(parent_style, &fw, &fh))
            g_frame_viewport_cb(node->parent, &fw, &fh);
        if (fw > 0 && fh > 0 &&
            (fabs(fw - g_viewport_w) > 0.01 ||
             fabs(fh - g_viewport_h) > 0.01)) {
            frame_vw = g_viewport_w;
            frame_vh = g_viewport_h;
            g_viewport_w = fw;
            g_viewport_h = fh;
            frame_viewport = TRUE;
        }
    }
    doc_own_sheets(node, &author, &n_author);
    GPtrArray *host_sheets = host_scoped_sheets(node, author, n_author);
    if (host_sheets) {
        author = (const ns_css_stylesheet *const *)host_sheets->pdata;
        n_author = host_sheets->len;
    }
    const ns_style *child_parent_style = parent_style;
    const ns_style *child_layout_parent = layout_parent;
    gboolean nd_recurse_dirty = under_dirty;
    gboolean child_parent_changed = node->kind != NS_NODE_ELEMENT &&
                                    parent_changed;
    if (node->kind == NS_NODE_ELEMENT) {
        gboolean nd_node_dirty = under_dirty ||
            (g_incr_dirty && g_hash_table_contains(g_incr_dirty, node));
        gboolean nd_self_only = !nd_node_dirty &&
            (parent_changed ||
             (g_incr_exclude && g_hash_table_contains(g_incr_exclude, node)) ||
             (g_incr_self_dirty &&
              g_hash_table_contains(g_incr_self_dirty, node)) ||
             (g_inv_active && g_inv_active->len > 0 &&
              incr_node_hits_inv(node)));
        if (nd_self_only) nd_node_dirty = TRUE;
        ns_style *nd_prev =
            (g_incr_pass_active && !nd_node_dirty && g_incr_prev_styles)
            ? g_hash_table_lookup(g_incr_prev_styles, node) : NULL;
        ns_style *s;
        if (nd_prev) {
            s = nd_prev;
            s->ref++;
            g_incr_reused++;
        } else {
        s = ns_style_alloc();
        g_incr_recomputed++;
        if (g_incr_changed) g_ptr_array_add(g_incr_changed, node);
        nd_node_dirty = TRUE;
        guint container_reads_before = g_container_reads;
        guint font_metric_reads_before = g_font_metric_reads;
        static GArray *sc_matches, *sc_var, *sc_pending;
        static GPtrArray *sc_owned;
        static GArray *sc_pe_m[9], *sc_pe_v[9], *sc_pe_p[9];
        if (!sc_matches) {
            sc_matches  = g_array_new(FALSE, FALSE, sizeof(match_entry));
            sc_var      = g_array_new(FALSE, FALSE, sizeof(var_match));
            sc_pending  = g_array_new(FALSE, FALSE, sizeof(pending_match));
            sc_owned    = g_ptr_array_new_with_free_func(
                              (GDestroyNotify)ns_css_value_free);
        }
        GArray *matches = sc_matches;
        GArray *var_matches = sc_var;
        GArray *pending_matches = sc_pending;
        GPtrArray *owned_values = sc_owned;
        g_array_set_size(matches, 0);
        g_array_set_size(var_matches, 0);
        g_array_set_size(pending_matches, 0);
        g_ptr_array_set_size(owned_values, 0);
        guint pe_mask = ua ? ua->pseudo_mask : 0;
        for (gsize i = 0; i < n_author; i++)
            if (author[i]) pe_mask |= author[i]->pseudo_mask;
        ns_pe_gather pe_g[9];
        int n_pe = 0;
        gather_dest dests[10];
        dests[0].pe = NS_CSS_PE_NONE;
        dests[0].out = matches;
        dests[0].var_out = var_matches;
        dests[0].pending_out = pending_matches;
        for (int pi = 0; pe_mask && pi < 9; pi++) {
            ns_css_pseudo_element pe = (pi == 0) ? NS_CSS_PE_BEFORE :
                                       (pi == 1) ? NS_CSS_PE_AFTER :
                                       (pi == 2) ? NS_CSS_PE_FIRST_LETTER :
                                       (pi == 3) ? NS_CSS_PE_FIRST_LINE :
                                       (pi == 4) ? NS_CSS_PE_SELECTION :
                                       (pi == 5) ? NS_CSS_PE_MARKER :
                                       (pi == 6) ? NS_CSS_PE_BACKDROP :
                                       (pi == 7) ? NS_CSS_PE_PLACEHOLDER :
                                                   NS_CSS_PE_FILE_SELECTOR_BUTTON;
            if (!(pe_mask & (1u << pe))) continue;
            ns_pe_gather *pg = &pe_g[n_pe];
            pg->pe = pe;
            if (!sc_pe_m[n_pe]) {
                sc_pe_m[n_pe] = g_array_new(FALSE, FALSE, sizeof(match_entry));
                sc_pe_v[n_pe] = g_array_new(FALSE, FALSE, sizeof(var_match));
                sc_pe_p[n_pe] = g_array_new(FALSE, FALSE, sizeof(pending_match));
            }
            pg->m = sc_pe_m[n_pe];
            pg->v = sc_pe_v[n_pe];
            pg->p = sc_pe_p[n_pe];
            g_array_set_size(pg->m, 0);
            g_array_set_size(pg->v, 0);
            g_array_set_size(pg->p, 0);
            dests[n_pe + 1].pe = pe;
            dests[n_pe + 1].out = pg->m;
            dests[n_pe + 1].var_out = pg->v;
            dests[n_pe + 1].pending_out = pg->p;
            n_pe++;
        }
        g_ancestor_filter_subject = node;
        gather_matches_multi(ua, NS_CSS_ORIGIN_UA, 0, node, dests,
                             (guint)n_pe + 1,
                             layer_ranks);
        for (gsize i = 0; i < n_author; i++)
            gather_matches_multi(author[i], NS_CSS_ORIGIN_AUTHOR,
                                 (int)(i + 1), node, dests,
                                 (guint)n_pe + 1, layer_ranks);

        char *pres_css = presentational_hints_css(node);
        const ns_css_stylesheet *pres_sheet = NULL;
        if (pres_css) {
            pres_sheet = ns_css_cached_decl_sheet(pres_css);
            g_free(pres_css);
        }
        if (pres_sheet) {
            for (guint ri = 0; ri < pres_sheet->rules->len; ri++) {
                ns_css_rule *r = g_ptr_array_index(pres_sheet->rules, ri);
                for (guint di = 0; di < r->decls->len; di++) {
                    ns_css_decl *d = &g_array_index(r->decls, ns_css_decl, di);
                    match_entry e = {
                        .origin = NS_CSS_ORIGIN_PRESENTATIONAL,
                        .spec_a = 0, .spec_b = 0, .spec_c = 0,
                        .layer_order = NS_CSS_LAYER_NONE,
                        .source_order = INT_MIN,
                        .decl_order = css_decl_slot(di),
                        .important = d->important,
                        .rule = r,
                        .value = d->value,
                        .prop  = d->prop,
                    };
                    g_array_append_val(matches, e);
                }
                if (r->vars) {
                    GHashTableIter it; gpointer k, v; int di_v = 0;
                    g_hash_table_iter_init(&it, r->vars);
                    while (g_hash_table_iter_next(&it, &k, &v)) {
                        var_match vm = {
                            .origin = NS_CSS_ORIGIN_PRESENTATIONAL,
                            .spec_a = 0, .spec_b = 0, .spec_c = 0,
                            .sheet_index = 0,
                            .layer_order = NS_CSS_LAYER_NONE,
                            .source_order = INT_MIN,
                            .decl_order = di_v++,
                            .important = r->var_important &&
                                g_hash_table_contains(r->var_important, k),
                            .rule = r,
                            .name = (const char *)k,
                            .text = (const char *)v,
                        };
                        g_array_append_val(var_matches, vm);
                    }
                }
                if (r->pending) {
                    for (guint pi = 0; pi < r->pending->len; pi++) {
                        ns_css_pending_decl *pd =
                            &g_array_index(r->pending, ns_css_pending_decl, pi);
                        pending_match pm = {
                            .origin = NS_CSS_ORIGIN_PRESENTATIONAL,
                            .spec_a = 0, .spec_b = 0, .spec_c = 0,
                            .sheet_index = 0,
                            .layer_order = NS_CSS_LAYER_NONE,
                            .source_order = INT_MIN,
                            .decl_order_base = css_pending_decl_slot(pd),
                            .rule = r,
                            .pd = pd,
                        };
                        g_array_append_val(pending_matches, pm);
                    }
                }
            }
        }

        const char *inline_css = ns_element_get_attr(node, "style");
        const ns_css_stylesheet *inline_sheet = NULL;
        if (inline_css && *inline_css)
            inline_sheet = ns_css_cached_decl_sheet(inline_css);
        if (inline_sheet) {
            for (guint ri = 0; ri < inline_sheet->rules->len; ri++) {
                ns_css_rule *r = g_ptr_array_index(inline_sheet->rules, ri);
                for (guint di = 0; di < r->decls->len; di++) {
                    ns_css_decl *d = &g_array_index(r->decls, ns_css_decl, di);
                    match_entry e = {
                        .origin = NS_CSS_ORIGIN_AUTHOR,
                        .spec_a = 1000, .spec_b = 0, .spec_c = 0,
                        .layer_order = NS_CSS_LAYER_NONE,
                        .source_order = INT_MAX,
                        .decl_order = css_decl_slot(di),
                        .important = d->important,
                        .inline_style = TRUE,
                        .rule = r,
                        .value = d->value,
                        .prop  = d->prop,
                    };
                    g_array_append_val(matches, e);
                }
                if (r->vars) {
                    GHashTableIter it; gpointer k, v; int di_v = 0;
                    g_hash_table_iter_init(&it, r->vars);
                    while (g_hash_table_iter_next(&it, &k, &v)) {
                        var_match vm = {
                            .origin = NS_CSS_ORIGIN_AUTHOR,
                            .spec_a = 1000, .spec_b = 0, .spec_c = 0,
                            .sheet_index = 0,
                            .layer_order = NS_CSS_LAYER_NONE,
                            .source_order = INT_MAX,
                            .decl_order = di_v++,
                            .important = r->var_important &&
                                g_hash_table_contains(r->var_important, k),
                            .inline_style = TRUE,
                            .rule = r,
                            .name = (const char *)k,
                            .text = (const char *)v,
                        };
                        g_array_append_val(var_matches, vm);
                    }
                }
                if (r->pending) {
                    for (guint pi = 0; pi < r->pending->len; pi++) {
                        ns_css_pending_decl *pd =
                            &g_array_index(r->pending, ns_css_pending_decl, pi);
                        pending_match pm = {
                            .origin = NS_CSS_ORIGIN_AUTHOR,
                            .spec_a = 1000, .spec_b = 0, .spec_c = 0,
                            .sheet_index = 0,
                            .layer_order = NS_CSS_LAYER_NONE,
                            .source_order = INT_MAX,
                            .decl_order_base = css_pending_decl_slot(pd),
                            .inline_style = TRUE,
                            .rule = r,
                            .pd = pd,
                        };
                        g_array_append_val(pending_matches, pm);
                    }
                }
            }
        }

        share_key_t probe;
        gboolean have_key = FALSE;
        const ns_style *shared = NULL;
        if (g_style_share) {
            style_share_key(g_share_scratch, parent_style, *root_px, matches,
                            var_matches, pending_matches, pe_g, n_pe);
            probe.data = g_share_scratch->data;
            probe.len  = g_share_scratch->len;
            probe.hash = share_key_djb2(probe.data, probe.len);
            have_key = TRUE;
            shared = g_hash_table_lookup(g_style_share, &probe);
            gboolean uses_attr = pending_uses_attr(pending_matches);
            for (int i = 0; i < n_pe && !uses_attr; i++)
                uses_attr = pending_uses_attr(pe_g[i].p);
            if (uses_attr) {
                have_key = FALSE;
                shared = NULL;
                node->flags |= NS_NODE_STYLE_USES_ATTR;
            }
        }
        if (shared) {
            ns_style_free(s);
            s = ns_style_clone_shared(shared);
            display_contents_to_none(node, s);
            button_inline_to_inline_block(node, s);
            g_array_set_size(matches, 0);
            g_array_set_size(var_matches, 0);
            g_array_set_size(pending_matches, 0);
            g_ptr_array_set_size(owned_values, 0);
        } else {
            s->share_id = ++g_style_share_next_id;
            s->vars = build_vars_for_element(parent_style, var_matches);
            resolve_pending_into_matches(pending_matches, s->vars,
                                         matches, owned_values, node,
                                         *root_px);

            cascade_for(matches, s, parent_style, layout_parent,
                    node->parent &&
                        node->parent->kind == NS_NODE_DOCUMENT, *root_px);
            compute_registered_vars(s, parent_style, *root_px);
            strip_native_widget_decorations(node, s);
            if (display_contents_to_none(node, s)) have_key = FALSE;
            button_inline_to_inline_block(node, s);
            g_array_set_size(matches, 0);
            g_array_set_size(var_matches, 0);
            g_array_set_size(pending_matches, 0);
            g_ptr_array_set_size(owned_values, 0);

            for (int gi = 0; gi < n_pe; gi++) {
                ns_css_pseudo_element pe = pe_g[gi].pe;
                GArray *pm = pe_g[gi].m;
                GArray *pe_vars = pe_g[gi].v;
                GArray *pe_pending = pe_g[gi].p;
                if (pm->len == 0 && pe_pending->len == 0) continue;
                GPtrArray *pe_owned =
                    g_ptr_array_new_with_free_func(
                        (GDestroyNotify)ns_css_value_free);
                ns_style *ps = ns_style_alloc();
                ps->vars = build_vars_for_element(s, pe_vars);
                resolve_pending_into_matches(pe_pending, ps->vars, pm, pe_owned,
                                             node, *root_px);
                cascade_for(pm, ps, s,
                            pe == NS_CSS_PE_BEFORE || pe == NS_CSS_PE_AFTER
                                ? s : NULL,
                            FALSE, *root_px);
                compute_registered_vars(ps, s, *root_px);
                gboolean keep = TRUE;
                if (pe == NS_CSS_PE_BEFORE || pe == NS_CSS_PE_AFTER)
                    keep = ps->values[NS_CSS_CONTENT] != NULL;
                if (keep && (pe == NS_CSS_PE_BEFORE || pe == NS_CSS_PE_AFTER) &&
                    ns_display_is_none(ns_css_display_of(ps))) {
                    if (pe == NS_CSS_PE_BEFORE) s->hidden_before = ps;
                    else                        s->hidden_after  = ps;
                } else if (keep) {
                    if (pe == NS_CSS_PE_BEFORE)            s->before       = ps;
                    else if (pe == NS_CSS_PE_AFTER)        s->after        = ps;
                    else if (pe == NS_CSS_PE_FIRST_LETTER) s->first_letter = ps;
                    else if (pe == NS_CSS_PE_FIRST_LINE)   s->first_line   = ps;
                    else if (pe == NS_CSS_PE_SELECTION)    s->selection    = ps;
                    else if (pe == NS_CSS_PE_MARKER)       s->marker       = ps;
                    else if (pe == NS_CSS_PE_BACKDROP)     s->backdrop     = ps;
                    else if (pe == NS_CSS_PE_PLACEHOLDER)  s->placeholder  = ps;
                    else s->file_selector_button = ps;
                } else {
                    ns_style_free(ps);
                }
                g_ptr_array_free(pe_owned, TRUE);
            }
            if (have_key) {
                share_key_t *k = g_new(share_key_t, 1);
                k->len  = probe.len;
                k->hash = probe.hash;
                k->data = g_memdup2(probe.data, probe.len);
                g_hash_table_insert(g_style_share, k, s);
            }
        }
        if (g_container_reads != container_reads_before)
            s->env_dependent |= STYLE_READS_CONTAINER;
        if (g_font_metric_reads != font_metric_reads_before)
            s->env_dependent |= STYLE_READS_FONT_METRICS;
        incr_note_env_dependent(node, s->env_dependent);
        }
        g_hash_table_insert(out, node, s);
        if (s->explicit_inherit && g_cascade_parent_node) {
            if (!g_explicit_inherit_parents)
                g_explicit_inherit_parents =
                    g_hash_table_new(g_direct_hash, g_direct_equal);
            g_hash_table_add(g_explicit_inherit_parents, g_cascade_parent_node);
        }
        child_parent_style = s;
        child_layout_parent = ns_display_is_contents(ns_css_display_of(s))
            ? layout_parent : s;
        if (*root_px <= 0 &&
            s->values[NS_CSS_FONT_SIZE] &&
            s->values[NS_CSS_FONT_SIZE]->kind == NS_CSS_V_LENGTH &&
            s->values[NS_CSS_FONT_SIZE]->u.length.unit == NS_CSS_UNIT_PX)
            *root_px = s->values[NS_CSS_FONT_SIZE]->u.length.v;
        nd_recurse_dirty = nd_node_dirty;
        if (nd_self_only && g_incr_pass_active && g_incr_prev_styles) {
            const ns_style *prev = g_hash_table_lookup(g_incr_prev_styles,
                                                       node);
            if (prev) {
                nd_recurse_dirty = FALSE;
                child_parent_changed =
                    ns_display_is_contents(ns_css_display_of(s)) ||
                    !incr_styles_equal_for_children(node, prev, s);
            }
        }
    }
    gboolean pushed = FALSE;
    if (g_cq_map && g_cq_stack) {
        ns_cq_container *info = g_hash_table_lookup(g_cq_map, node);
        if (info) {
            g_array_append_val(g_cq_stack, *info);
            pushed = TRUE;
        }
    }
    gboolean filter_element = g_ancestor_filter_active &&
                              node->kind == NS_NODE_ELEMENT && node->first_child;
    guint8 *outer_filter = NULL;
    if (g_ancestor_filter_active && node->kind == NS_NODE_DOCUMENT &&
        node->parent) {
        outer_filter = g_memdup2(g_ancestor_filter, sizeof g_ancestor_filter);
        memset(g_ancestor_filter, 0, sizeof g_ancestor_filter);
    }
    if (filter_element) css_ancestor_filter_update(node, 1);
    guint inv_mark = g_inv_active ? g_inv_active->len : 0;
    GPtrArray *inv_pending = g_incr_inv_pending && !nd_recurse_dirty
        ? g_hash_table_lookup(g_incr_inv_pending, node) : NULL;
    if (inv_pending) {
        if (!g_inv_active) g_inv_active = g_ptr_array_new();
        for (guint i = 0; i < inv_pending->len; i++)
            g_ptr_array_add(g_inv_active, g_ptr_array_index(inv_pending, i));
    }
    ns_node *outer_parent_node = g_cascade_parent_node;
    if (node->kind == NS_NODE_ELEMENT) g_cascade_parent_node = node;
    for (ns_node *c = node->first_child; c; c = c->next_sibling)
        cascade_walk(c, ua, author, n_author, child_parent_style,
                     child_layout_parent, root_px,
                     layer_ranks, out, nd_recurse_dirty,
                     child_parent_changed);
    g_cascade_parent_node = outer_parent_node;
    if (g_inv_active) g_ptr_array_set_size(g_inv_active, inv_mark);
    if (filter_element) css_ancestor_filter_update(node, -1);
    if (outer_filter) {
        memcpy(g_ancestor_filter, outer_filter, sizeof g_ancestor_filter);
        g_free(outer_filter);
    }
    if (pushed) g_array_set_size(g_cq_stack, g_cq_stack->len - 1);
    if (frame_viewport) {
        g_viewport_w = frame_vw;
        g_viewport_h = frame_vh;
    }
    if (host_sheets) g_ptr_array_free(host_sheets, TRUE);
    depth--;
}

static void
append_text_children(const ns_node *n, GString *out, int depth)
{
    if (depth >= 512) return;
    for (const ns_node *c = n->first_child; c; c = c->next_sibling) {
        if (c->kind == NS_NODE_TEXT && c->text)
            g_string_append(out, c->text);
        else if (c->kind == NS_NODE_ELEMENT)
            append_text_children(c, out, depth + 1);
    }
}

static int g_host_scope_counter;

static char *
shadow_root_host_scope_id(ns_node *root)
{
    if (!root || !root->parent) return NULL;
    ns_node *host = root->parent;
    const char *existing = ns_element_get_attr(host, NS_HOST_SCOPE_ATTR);
    if (existing) return g_strdup(existing);
    char buf[32];
    g_snprintf(buf, sizeof buf, "%d", ++g_host_scope_counter);
    ns_element_set_attr(host, NS_HOST_SCOPE_ATTR, buf);
    return g_strdup(buf);
}

static char *
style_host_scope_id(ns_node *style_el)
{
    for (ns_node *a = style_el; a && a->kind != NS_NODE_DOCUMENT; a = a->parent)
        if (a->kind == NS_NODE_ELEMENT &&
            ns_element_has_shadow_marker(a))
            return shadow_root_host_scope_id(a);
    return NULL;
}

static char *
style_iframe_scope_id(ns_node *style_el)
{
    ns_node *root = NULL;
    for (ns_node *a = style_el; a; a = a->parent) {
        if (a->kind == NS_NODE_ELEMENT && a->parent &&
            a->parent->kind == NS_NODE_DOCUMENT && a->parent->parent) {
            root = a;
            break;
        }
    }
    if (!root) return NULL;
    const char *existing = ns_element_get_attr(root, NS_HOST_SCOPE_ATTR);
    if (existing) return g_strdup(existing);
    char buf[32];
    g_snprintf(buf, sizeof buf, "%d", ++g_host_scope_counter);
    ns_element_set_attr(root, NS_HOST_SCOPE_ATTR, buf);
    return g_strdup(buf);
}

static char *
rewrite_host_selectors(const char *css, const char *host_id)
{
    GString *out = g_string_new(NULL);
    char marker[96];
    g_snprintf(marker, sizeof marker, "[" NS_HOST_SCOPE_ATTR "=\"%s\"]", host_id);
    for (const char *p = css; *p; ) {
        if (p[0] == ':' && g_ascii_strncasecmp(p, "::slotted(", 10) == 0) {
            const char *inner = p + 10;
            const char *q = inner;
            int depth = 1;
            while (*q && depth) {
                if (*q == '(') depth++;
                else if (*q == ')') { depth--; if (!depth) break; }
                q++;
            }
            g_string_append(out, marker);
            g_string_append(out, " > ");
            g_string_append_len(out, inner, (gssize)(q - inner));
            p = (*q == ')') ? q + 1 : q;
            continue;
        }
        if (p[0] == ':' && g_ascii_strncasecmp(p, ":host", 5) == 0) {
            const char *after = p + 5;
            if (g_ascii_strncasecmp(after, "-context(", 9) == 0) {
                const char *q = after + 9;
                int depth = 1;
                while (*q && depth) {
                    if (*q == '(') depth++;
                    else if (*q == ')') depth--;
                    q++;
                }
                g_string_append(out, marker);
                p = q;
                continue;
            }
            if (*after == '(') {
                const char *inner = after + 1;
                const char *q = inner;
                int depth = 1;
                while (*q && depth) {
                    if (*q == '(') depth++;
                    else if (*q == ')') { depth--; if (!depth) break; }
                    q++;
                }
                g_string_append(out, marker);
                g_string_append_len(out, inner, (gssize)(q - inner));
                p = (*q == ')') ? q + 1 : q;
                continue;
            }
            if (!is_ident(*after) && *after != '-') {
                g_string_append(out, marker);
                p = after;
                continue;
            }
        }
        g_string_append_c(out, *p);
        p++;
    }
    return g_string_free(out, FALSE);
}

static gsize
selector_first_compound_len(const char *s)
{
    gsize i = 0;
    int depth = 0;
    while (s[i]) {
        char c = s[i];
        if (c == '(' || c == '[') depth++;
        else if (c == ')' || c == ']') { if (depth) depth--; }
        else if (!depth && (is_ws(c) || c == '>' || c == '+' || c == '~' ||
                            c == ','))
            break;
        i++;
    }
    return i;
}

static gboolean
selector_first_compound_targets_root(const char *s, gsize clen)
{
    if (clen >= 4 && g_ascii_strncasecmp(s, "html", 4) == 0 &&
        (clen == 4 || !is_ident(s[4])))
        return TRUE;
    if (clen >= 5 && g_ascii_strncasecmp(s, ":root", 5) == 0 &&
        (clen == 5 || !is_ident(s[5])))
        return TRUE;
    return FALSE;
}

static gsize
selector_compound_simple_len(const char *s, gsize clen)
{
    static const char *const legacy[] = {
        "before", "after", "first-line", "first-letter", NULL
    };
    int depth = 0;
    for (gsize i = 0; i < clen; i++) {
        char c = s[i];
        if (c == '(' || c == '[') depth++;
        else if (c == ')' || c == ']') { if (depth) depth--; }
        else if (!depth && c == ':') {
            if (i + 1 < clen && s[i + 1] == ':') return i;
            for (int k = 0; legacy[k]; k++) {
                gsize n = strlen(legacy[k]);
                if (i + 1 + n <= clen &&
                    g_ascii_strncasecmp(s + i + 1, legacy[k], n) == 0 &&
                    (i + 1 + n == clen || !is_ident(s[i + 1 + n])))
                    return i;
            }
        }
    }
    return clen;
}

static gboolean
selector_first_compound_may_be_root(const char *s, gsize clen)
{
    if (!clen) return FALSE;
    if (s[0] == '*') return TRUE;
    return s[0] == '.' || s[0] == '#' || s[0] == '[' || s[0] == ':';
}

static void
scope_one_selector(GString *out, const char *sel, gsize len,
                   const char *marker, const char *host_id,
                   gboolean frame_scope)
{
    while (len && is_ws(*sel)) { sel++; len--; }
    while (len && is_ws(sel[len - 1])) len--;
    if (!len) return;
    char *s = g_strndup(sel, len);
    gsize clen = selector_first_compound_len(s);
    gsize simple = selector_compound_simple_len(s, clen);
    if (strstr(s, ":host") || strstr(s, "::slotted")) {
        char *r = rewrite_host_selectors(s, host_id);
        g_string_append(out, r);
        g_free(r);
    } else if (selector_first_compound_targets_root(s, clen)) {
        g_string_append_len(out, s, (gssize)simple);
        g_string_append(out, marker);
        g_string_append(out, s + simple);
    } else {
        g_string_append(out, marker);
        g_string_append_c(out, ' ');
        g_string_append(out, s);
        if (frame_scope && selector_first_compound_may_be_root(s, clen)) {
            g_string_append(out, ", ");
            g_string_append_len(out, s, (gssize)simple);
            g_string_append(out, marker);
            g_string_append(out, s + simple);
        }
    }
    g_free(s);
}

static void
scope_rule_list(GString *out, const char *p, const char *end,
                const char *marker, const char *host_id, int depth,
                gboolean frame_scope)
{
    if (depth >= NS_CSS_MAX_AT_NESTING) {
        g_string_append_len(out, p, (gssize)(end - p));
        return;
    }
    while (p < end) {
        while (p < end && is_ws(*p)) p++;
        if (p >= end) break;
        if (p + 1 < end && p[0] == '/' && p[1] == '*') {
            p += 2;
            while (p + 1 < end && !(p[0] == '*' && p[1] == '/')) p++;
            if (p + 1 < end) p += 2;
            continue;
        }
        if (*p == '}') { p++; continue; }
        if (*p == '@') {
            const char *prelude = p;
            char term = 0;
            const char *seg = css_scan_segment(p, end, &term);
            if (term == '{') {
                gboolean group =
                    g_ascii_strncasecmp(prelude, "@media", 6) == 0 ||
                    g_ascii_strncasecmp(prelude, "@supports", 9) == 0 ||
                    g_ascii_strncasecmp(prelude, "@container", 10) == 0 ||
                    g_ascii_strncasecmp(prelude, "@layer", 6) == 0 ||
                    g_ascii_strncasecmp(prelude, "@scope", 6) == 0;
                const char *be = css_skip_to_block_end(seg, end);
                if (group) {
                    g_string_append_len(out, prelude, (gssize)(seg - prelude));
                    g_string_append_c(out, '{');
                    const char *body_s = seg + 1;
                    scope_rule_list(out, body_s, css_block_body_end(body_s, be),
                                    marker, host_id, depth + 1, frame_scope);
                    g_string_append_c(out, '}');
                } else {
                    g_string_append_len(out, prelude, (gssize)(be - prelude));
                }
                p = be;
            } else {
                g_string_append_len(out, prelude, (gssize)(seg - prelude));
                if (term == ';' && seg < end) { g_string_append_c(out, ';'); p = seg + 1; }
                else p = seg;
            }
            continue;
        }
        char term = 0;
        const char *seg = css_scan_segment(p, end, &term);
        if (term != '{') { p = (seg < end) ? seg + 1 : end; continue; }
        const char *be = css_skip_to_block_end(seg, end);
        const char *selend = seg;
        const char *q = p, *segstart = p;
        char quote = 0;
        int paren = 0, bracket = 0;
        gboolean first = TRUE;
        for (; q <= selend; q++) {
            if (q == selend || (!quote && !paren && !bracket && *q == ',')) {
                if (!first) g_string_append(out, ", ");
                first = FALSE;
                scope_one_selector(out, segstart, (gsize)(q - segstart),
                                   marker, host_id, frame_scope);
                segstart = q + 1;
                if (q == selend) break;
            } else if (quote) {
                if (*q == '\\' && q + 1 < selend) q++;
                else if (*q == quote) quote = 0;
            } else if (*q == '\\' && q + 1 < selend) q++;
            else if (*q == '"' || *q == '\'') quote = *q;
            else if (*q == '(') paren++;
            else if (*q == ')') { if (paren) paren--; }
            else if (*q == '[') bracket++;
            else if (*q == ']') { if (bracket) bracket--; }
        }
        g_string_append_c(out, '{');
        const char *body_s = seg + 1;
        const char *body_e = css_block_body_end(body_s, be);
        g_string_append_len(out, body_s, (gssize)(body_e - body_s));
        g_string_append_c(out, '}');
        p = be;
    }
}

static char *
scope_shadow_css(const char *flat_css, const char *host_id, gboolean frame_scope)
{
    GString *out = g_string_new(NULL);
    char marker[96];
    g_snprintf(marker, sizeof marker, "[" NS_HOST_SCOPE_ATTR "=\"%s\"]", host_id);
    scope_rule_list(out, flat_css, flat_css + strlen(flat_css), marker, host_id, 0,
                    frame_scope);
    return g_string_free(out, FALSE);
}

#define NS_SCOPED_CSS_CACHE_MAX 4096

static GHashTable *g_scoped_css_cache;

static char *
scoped_css_cached(const char *css, gsize len, const char *host_id,
                  gboolean frame_scope)
{
    GString *key = g_string_sized_new(len + strlen(host_id) + 3);
    g_string_append_c(key, frame_scope ? 'f' : 's');
    g_string_append(key, host_id);
    g_string_append_c(key, '\n');
    g_string_append_len(key, css, (gssize)len);
    const char *hit = g_scoped_css_cache
        ? g_hash_table_lookup(g_scoped_css_cache, key->str) : NULL;
    if (hit) {
        g_string_free(key, TRUE);
        return g_strdup(hit);
    }
    char *flat = css_flatten_nesting(css, (gssize)len);
    char *scoped = scope_shadow_css(flat, host_id, frame_scope);
    g_free(flat);
    if (!g_scoped_css_cache)
        g_scoped_css_cache = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                   g_free, g_free);
    if (g_hash_table_size(g_scoped_css_cache) >= NS_SCOPED_CSS_CACHE_MAX)
        g_hash_table_remove_all(g_scoped_css_cache);
    g_hash_table_insert(g_scoped_css_cache, g_string_free(key, FALSE),
                        g_strdup(scoped));
    return scoped;
}

static char *
style_element_final_css(ns_node *style)
{
    if (!ns_node_is_element_named(style, "style")) return NULL;
    const char *media = ns_element_get_attr(style, "media");
    if (media && *media && !ns_css_media_query_matches(media)) return NULL;
    GString *buf = g_string_new(NULL);
    append_text_children(style, buf, 0);
    if (buf->len == 0) {
        g_string_free(buf, TRUE);
        return NULL;
    }
    gboolean frame_scope = FALSE;
    char *host_id = style_host_scope_id(style);
    if (!host_id) {
        host_id = style_iframe_scope_id(style);
        frame_scope = host_id != NULL;
    }
    if (host_id) {
        char *rewritten = scoped_css_cached(buf->str, buf->len, host_id,
                                            frame_scope);
        g_free(host_id);
        g_string_free(buf, TRUE);
        return rewritten;
    }
    return g_string_free(buf, FALSE);
}

char *
ns_css_style_element_text(ns_node *style)
{
    return style_element_final_css(style);
}

char *
ns_css_shadow_adopted_css(ns_node *root)
{
    const char *css = ns_element_get_attr(root, NS_ADOPTED_CSS_ATTR);
    if (!css || !*css) return NULL;
    char *host_id = shadow_root_host_scope_id(root);
    if (!host_id) return NULL;
    char *scoped = scoped_css_cached(css, strlen(css), host_id, FALSE);
    g_free(host_id);
    return scoped;
}

typedef struct {
    char *css;
    ns_css_stylesheet *sheet;
    double vw;
    double vh;
} ns_style_el_cached;

typedef struct {
    ns_css_stylesheet *sheet;
    guint64 stamp;
} ns_merged_style_cached;

typedef struct {
    double      vw;
    double      vh;
    const char *base;
    gsize       len;
    guint64     digest;
    guint       hash;
} ns_merged_style_key;

typedef struct {
    GBytes *bytes;
    ns_css_stylesheet *sheet;
} ns_import_sheet_cached;

static GHashTable *g_style_el_cache;
static GHashTable *g_merged_style_cache;
static GHashTable *g_link_sheet_cache;
static GHashTable *g_sheet_cache_used;
static guint g_sheet_cache_clock;
static GHashTable *g_import_sheet_cache;
static guint64 g_merged_style_cache_clock;

static void
ns_style_el_cached_free(gpointer data)
{
    ns_style_el_cached *e = data;
    if (!e) return;
    g_free(e->css);
    if (e->sheet) {
        e->sheet->cached = FALSE;
        ns_css_stylesheet_free(e->sheet);
    }
    g_free(e);
}

static guint
ns_merged_style_key_hash(gconstpointer p)
{
    return ((const ns_merged_style_key *)p)->hash;
}

static gboolean
ns_merged_style_key_equal(gconstpointer pa, gconstpointer pb)
{
    const ns_merged_style_key *a = pa, *b = pb;
    return a->hash == b->hash && a->len == b->len &&
           a->vw == b->vw && a->vh == b->vh &&
           a->digest == b->digest && g_strcmp0(a->base, b->base) == 0;
}

static void
ns_merged_style_key_free(gpointer data)
{
    ns_merged_style_key *k = data;
    g_free((char *)k->base);
    g_free(k);
}

static guint64 g_merged_style_pass_start;

static void
ns_merged_style_cache_trim(guint64 keep_after)
{
    if (!g_merged_style_cache ||
        g_hash_table_size(g_merged_style_cache) <= 64)
        return;
    while (g_hash_table_size(g_merged_style_cache) > 48) {
        GHashTableIter it;
        gpointer key, value, victim = NULL;
        guint64 oldest = G_MAXUINT64;
        g_hash_table_iter_init(&it, g_merged_style_cache);
        while (g_hash_table_iter_next(&it, &key, &value)) {
            ns_merged_style_cached *entry = value;
            if (entry->stamp > keep_after) continue;
            if (entry->stamp < oldest) {
                oldest = entry->stamp;
                victim = key;
            }
        }
        if (!victim) break;
        g_hash_table_remove(g_merged_style_cache, victim);
    }
}

static int g_css_relayout_depth;

void
ns_css_relayout_enter(void)
{
    g_css_relayout_depth++;
}

void
ns_css_relayout_leave(void)
{
    if (g_css_relayout_depth > 0) g_css_relayout_depth--;
}

static guint g_stylesheet_cache_generation;

guint
ns_css_stylesheet_cache_generation(void)
{
    return g_stylesheet_cache_generation;
}

void
ns_css_stylesheet_cache_drop(void)
{
    g_stylesheet_cache_generation++;
    if (g_style_el_cache) g_hash_table_remove_all(g_style_el_cache);
    if (g_merged_style_cache) g_hash_table_remove_all(g_merged_style_cache);
    if (g_link_sheet_cache) g_hash_table_remove_all(g_link_sheet_cache);
    if (g_import_sheet_cache) g_hash_table_remove_all(g_import_sheet_cache);
}

static void
sheet_cache_note_used(const char *key)
{
    if (!g_sheet_cache_used)
        g_sheet_cache_used = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                   g_free, NULL);
    g_hash_table_replace(g_sheet_cache_used, g_strdup(key),
                         GUINT_TO_POINTER(g_sheet_cache_clock + 1));
}

static void
sheet_cache_evict_unused(GHashTable *cache)
{
    if (!cache || g_hash_table_size(cache) <= 256) return;
    guint oldest = g_sheet_cache_clock > 512 ? g_sheet_cache_clock - 512 : 0;
    GHashTableIter iter;
    gpointer key;
    g_hash_table_iter_init(&iter, cache);
    while (g_hash_table_iter_next(&iter, &key, NULL)) {
        guint used = g_sheet_cache_used
            ? GPOINTER_TO_UINT(g_hash_table_lookup(g_sheet_cache_used, key))
            : 0;
        if (used <= oldest) {
            if (g_sheet_cache_used) g_hash_table_remove(g_sheet_cache_used, key);
            g_hash_table_iter_remove(&iter);
        }
    }
}

void
ns_css_style_element_cache_begin(void)
{
    if (g_css_relayout_depth > 1) return;
    if (g_style_el_cache && g_hash_table_size(g_style_el_cache) > 2048)
        g_hash_table_remove_all(g_style_el_cache);
    ns_merged_style_cache_trim(g_merged_style_pass_start);
    g_merged_style_pass_start = g_merged_style_cache_clock;
    g_sheet_cache_clock++;
    sheet_cache_evict_unused(g_link_sheet_cache);
    sheet_cache_evict_unused(g_import_sheet_cache);
}

static void
ns_merged_style_cached_free(gpointer data)
{
    ns_merged_style_cached *entry = data;
    if (!entry) return;
    if (entry->sheet) {
        entry->sheet->cached = FALSE;
        ns_css_stylesheet_free(entry->sheet);
    }
    g_free(entry);
}

static void
ns_cached_stylesheet_free(gpointer data)
{
    ns_css_stylesheet *sheet = data;
    if (!sheet) return;
    sheet->cached = FALSE;
    ns_css_stylesheet_free(sheet);
}

static void
ns_import_sheet_cached_free(gpointer data)
{
    ns_import_sheet_cached *e = data;
    if (!e) return;
    g_bytes_unref(e->bytes);
    ns_cached_stylesheet_free(e->sheet);
    g_free(e);
}

void
ns_css_style_element_cache_end(void)
{
    if (g_css_relayout_depth > 1) return;
    ns_merged_style_cache_trim(g_merged_style_pass_start);
}

ns_css_stylesheet *
ns_css_merged_styles_cached_digest(guint64 digest, gsize len,
                                   const char *base_url,
                                   ns_css_text_builder build, gpointer data)
{
    if (len == 0 || !build) return NULL;
    if (!g_merged_style_cache)
        g_merged_style_cache =
            g_hash_table_new_full(ns_merged_style_key_hash,
                                  ns_merged_style_key_equal,
                                  ns_merged_style_key_free,
                                  ns_merged_style_cached_free);
    ns_merged_style_key probe = {
        .vw = rint(ns_css_media_viewport_current_w()),
        .vh = rint(ns_css_media_viewport_current_h()),
        .base = base_url,
        .len = len,
        .digest = digest,
    };
    probe.hash = (guint)(digest ^ (digest >> 32)) ^
                 (base_url ? g_str_hash(base_url) * 31u : 0) ^
                 (guint)probe.vw * 7919u ^ (guint)probe.vh * 104729u;
    ns_merged_style_cached *hit =
        g_hash_table_lookup(g_merged_style_cache, &probe);
    if (hit) {
        hit->stamp = ++g_merged_style_cache_clock;
        return hit->sheet;
    }
    GString *text = g_string_sized_new(len + 1);
    build(text, data);
    ns_css_stylesheet *sh = ns_css_stylesheet_parse(text->str,
                                                    (gssize)text->len);
    g_string_free(text, TRUE);
    if (!sh) return NULL;
    sh->cached = TRUE;
    ns_merged_style_cached *entry = g_new0(ns_merged_style_cached, 1);
    entry->sheet = sh;
    entry->stamp = ++g_merged_style_cache_clock;
    ns_merged_style_key *key = g_new(ns_merged_style_key, 1);
    *key = probe;
    key->base = g_strdup(base_url);
    g_hash_table_replace(g_merged_style_cache, key, entry);
    return sh;
}

ns_css_stylesheet *
ns_css_stylesheet_parse_url_cached(const char *url, const char *css, gssize len)
{
    if (!css) return NULL;
    if (!url || !*url) return ns_css_stylesheet_parse(css, len);
    if (!g_link_sheet_cache)
        g_link_sheet_cache =
            g_hash_table_new_full(g_str_hash, g_str_equal,
                                  g_free, ns_cached_stylesheet_free);
    char *key = g_strdup_printf("%.0fx%.0f|%s",
                                ns_css_media_viewport_current_w(),
                                ns_css_media_viewport_current_h(), url);
    sheet_cache_note_used(key);
    ns_css_stylesheet *hit = g_hash_table_lookup(g_link_sheet_cache, key);
    if (hit) {
        g_free(key);
        return hit;
    }
    ns_css_stylesheet *sh = ns_css_stylesheet_parse(css, len);
    if (!sh) {
        g_free(key);
        return NULL;
    }
    sh->cached = TRUE;
    g_hash_table_replace(g_link_sheet_cache, key, sh);
    return sh;
}

static ns_css_stylesheet *
ns_css_stylesheet_parse_in_layer(GBytes *bytes, const char *layer_name)
{
    gsize len = 0;
    const char *data = g_bytes_get_data(bytes, &len);
    ns_css_stylesheet *sh = ns_css_stylesheet_parse(data, (gssize)len);
    if (sh && layer_name)
        ns_css_stylesheet_force_layer(sh, layer_name);
    return sh;
}

ns_css_stylesheet *
ns_css_stylesheet_parse_import_cached(const char *url, const char *layer_name,
                                      GBytes *bytes)
{
    if (!bytes) return NULL;
    if (!url || !*url) return ns_css_stylesheet_parse_in_layer(bytes, layer_name);
    if (!g_import_sheet_cache)
        g_import_sheet_cache =
            g_hash_table_new_full(g_str_hash, g_str_equal,
                                  g_free, ns_import_sheet_cached_free);
    char *key = g_strdup_printf("%.0fx%.0f|%c%zu:%s|%s",
                                ns_css_media_viewport_current_w(),
                                ns_css_media_viewport_current_h(),
                                layer_name ? 'L' : '-',
                                layer_name ? strlen(layer_name) : (gsize)0,
                                layer_name ? layer_name : "", url);
    sheet_cache_note_used(key);
    ns_import_sheet_cached *hit = g_hash_table_lookup(g_import_sheet_cache, key);
    if (hit && (hit->bytes == bytes || g_bytes_equal(hit->bytes, bytes))) {
        g_free(key);
        return hit->sheet;
    }
    ns_css_stylesheet *sh = ns_css_stylesheet_parse_in_layer(bytes, layer_name);
    if (!sh) {
        g_free(key);
        return NULL;
    }
    sh->cached = TRUE;
    ns_import_sheet_cached *entry = g_new0(ns_import_sheet_cached, 1);
    entry->bytes = g_bytes_ref(bytes);
    entry->sheet = sh;
    g_hash_table_replace(g_import_sheet_cache, key, entry);
    return sh;
}

ns_css_stylesheet *
ns_css_stylesheet_from_style_element_cached(ns_node *style)
{
    char *css = style_element_final_css(style);
    if (!css) return NULL;
    if (!g_style_el_cache)
        g_style_el_cache = g_hash_table_new_full(g_direct_hash, g_direct_equal,
                                                 NULL, ns_style_el_cached_free);
    ns_style_el_cached *e = g_hash_table_lookup(g_style_el_cache, style);
    if (e && strcmp(e->css, css) == 0 &&
        e->vw == ns_css_media_viewport_current_w() &&
        e->vh == ns_css_media_viewport_current_h()) {
        g_free(css);
        return e->sheet;
    }
    ns_css_stylesheet *sh = ns_css_stylesheet_parse(css, -1);
    if (!sh) {
        g_free(css);
        return NULL;
    }
    sh->cached = TRUE;
    ns_style_el_cached *ne = g_new0(ns_style_el_cached, 1);
    ne->css = css;
    ne->sheet = sh;
    ne->vw = ns_css_media_viewport_current_w();
    ne->vh = ns_css_media_viewport_current_h();
    g_hash_table_replace(g_style_el_cache, style, ne);
    return sh;
}

typedef struct {
    GHashTable *keys;
    GPtrArray  *attrs;
    gboolean    whole;
} incr_sheet_deps;

static GHashTable *g_sheet_deps;
static GArray     *g_incr_prev_serials;
static guint64     g_incr_prev_ua_serial;
static guint64     g_incr_prev_reg_serial;

static void
incr_sheet_deps_free(gpointer data)
{
    incr_sheet_deps *d = data;
    g_hash_table_destroy(d->keys);
    g_ptr_array_free(d->attrs, TRUE);
    g_free(d);
}

static gboolean
incr_sheet_rule_is_global(const ns_css_rule *r)
{
    return r->layer_name || r->container_condition || r->container_query;
}

static gboolean
incr_sheet_is_global(const ns_css_stylesheet *sh)
{
    return (sh->layer_names && sh->layer_names->len > 0) ||
           (sh->layers && g_hash_table_size(sh->layers) > 0) ||
           (sh->property_rules && sh->property_rules->len > 0) ||
           (sh->imports && sh->imports->len > 0) ||
           sh->page_rule || sh->has_container_rules;
}

static void
incr_sheet_deps_add_selector(incr_sheet_deps *d, const ns_css_selector *sel)
{
    GPtrArray *preds = g_ptr_array_new();
    if (!incr_add_positive_subject_deps(d->keys, preds, sel, 0))
        d->whole = TRUE;
    for (guint i = 0; i < preds->len; i++) {
        const ns_css_attr_pred *a = g_ptr_array_index(preds, i);
        if (a->name) g_ptr_array_add(d->attrs, g_ascii_strdown(a->name, -1));
    }
    g_ptr_array_free(preds, TRUE);
}

static incr_sheet_deps *
incr_sheet_deps_build(const ns_css_stylesheet *sh)
{
    incr_sheet_deps *d = g_new0(incr_sheet_deps, 1);
    d->keys = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
    d->attrs = g_ptr_array_new_with_free_func(g_free);
    d->whole = incr_sheet_is_global(sh);
    for (guint i = 0; !d->whole && sh->rules && i < sh->rules->len; i++) {
        const ns_css_rule *r = g_ptr_array_index(sh->rules, i);
        if (incr_sheet_rule_is_global(r)) {
            d->whole = TRUE;
            break;
        }
        for (guint si = 0; !d->whole && r->selectors &&
                           si < r->selectors->len; si++)
            incr_sheet_deps_add_selector(d,
                g_ptr_array_index(r->selectors, si));
    }
    return d;
}

static const incr_sheet_deps *
incr_sheet_deps_for(const ns_css_stylesheet *sh)
{
    if (!g_sheet_deps)
        g_sheet_deps = g_hash_table_new_full(g_int64_hash, g_int64_equal,
                                             g_free, incr_sheet_deps_free);
    incr_sheet_deps *d = g_hash_table_lookup(g_sheet_deps, &sh->serial);
    if (d) return d;
    d = incr_sheet_deps_build(sh);
    g_hash_table_insert(g_sheet_deps, g_memdup2(&sh->serial, sizeof sh->serial),
                        d);
    return d;
}

static GArray *
incr_serials_of(const ns_css_stylesheet *const *author, gsize n)
{
    GArray *serials = g_array_sized_new(FALSE, FALSE, sizeof(guint64),
                                        (guint)n);
    for (gsize i = 0; i < n; i++) {
        guint64 serial = author[i] ? author[i]->serial : 0;
        g_array_append_val(serials, serial);
    }
    return serials;
}

static gboolean
incr_node_has_attr_named(const ns_node *n, const char *name)
{
    for (const ns_attr *a = n->attrs; a; a = a->next)
        if (a->name && g_ascii_strcasecmp(a->name, name) == 0) return TRUE;
    return FALSE;
}

static gboolean
incr_node_hits_sheet_deps(const ns_node *n, GPtrArray *deps)
{
    for (guint i = 0; i < deps->len; i++) {
        const incr_sheet_deps *d = g_ptr_array_index(deps, i);
        if (incr_node_matches_keys(n, d->keys)) return TRUE;
        for (guint a = 0; a < d->attrs->len; a++)
            if (incr_node_has_attr_named(n, g_ptr_array_index(d->attrs, a)))
                return TRUE;
    }
    return FALSE;
}

static gboolean
incr_mark_sheet_deps_walk(ns_node *n, GPtrArray *deps, guint *marked,
                          int depth)
{
    if (depth >= NS_CSS_MAX_CASCADE_DEPTH) return TRUE;
    if (n->kind == NS_NODE_DOCUMENT && (n->flags & NS_NODE_QUIRKS))
        return FALSE;
    if (n->kind == NS_NODE_ELEMENT && incr_node_hits_sheet_deps(n, deps)) {
        incr_add_self_dirty(n);
        (*marked)++;
    }
    for (ns_node *c = n->first_child; c; c = c->next_sibling)
        if (!incr_mark_sheet_deps_walk(c, deps, marked, depth + 1))
            return FALSE;
    return TRUE;
}

static void
incr_sheet_deps_prune(const GArray *live)
{
    if (!g_sheet_deps) return;
    GHashTable *keep = g_hash_table_new(g_int64_hash, g_int64_equal);
    for (guint i = 0; i < live->len; i++)
        g_hash_table_add(keep, &g_array_index(live, guint64, i));
    GHashTableIter it;
    gpointer key;
    g_hash_table_iter_init(&it, g_sheet_deps);
    while (g_hash_table_iter_next(&it, &key, NULL))
        if (!g_hash_table_contains(keep, key))
            g_hash_table_iter_remove(&it);
    g_hash_table_destroy(keep);
}

static gboolean
incr_collect_changed_sheet_deps(const ns_css_stylesheet *const *author,
                                const GArray *prev, const GArray *now,
                                GPtrArray *deps)
{
    guint shorter = MIN(prev->len, now->len);
    guint head = 0;
    while (head < shorter && g_array_index(prev, guint64, head) ==
                             g_array_index(now, guint64, head))
        head++;
    guint tail = 0;
    while (tail < shorter - head &&
           g_array_index(prev, guint64, prev->len - 1 - tail) ==
           g_array_index(now, guint64, now->len - 1 - tail))
        tail++;
    for (guint i = head; i < now->len - tail; i++) {
        if (!author[i]) continue;
        const incr_sheet_deps *d = incr_sheet_deps_for(author[i]);
        if (d->whole) return FALSE;
        g_ptr_array_add(deps, (gpointer)d);
    }
    for (guint i = head; i < prev->len - tail; i++) {
        guint64 serial = g_array_index(prev, guint64, i);
        if (!serial) continue;
        const incr_sheet_deps *d =
            g_sheet_deps ? g_hash_table_lookup(g_sheet_deps, &serial) : NULL;
        if (!d || d->whole) return FALSE;
        g_ptr_array_add(deps, (gpointer)d);
    }
    return TRUE;
}

static gboolean
incr_apply_sheet_change(ns_node *doc, const ns_css_stylesheet *ua,
                        const ns_css_stylesheet *const *author, gsize n,
                        guint *marked)
{
    if (!g_incr_prev_serials || !ua ||
        ua->serial != g_incr_prev_ua_serial ||
        ns_css_registered_property_serial() != g_incr_prev_reg_serial)
        return FALSE;
    GArray *now = incr_serials_of(author, n);
    GPtrArray *deps = g_ptr_array_new();
    gboolean ok = incr_collect_changed_sheet_deps(author, g_incr_prev_serials,
                                                  now, deps) &&
                  incr_mark_sheet_deps_walk(doc, deps, marked, 0);
    g_ptr_array_free(deps, TRUE);
    g_array_free(now, TRUE);
    return ok;
}

static void
incr_remember_sheets(const ns_css_stylesheet *ua,
                     const ns_css_stylesheet *const *author, gsize n)
{
    if (g_incr_prev_serials) g_array_free(g_incr_prev_serials, TRUE);
    g_incr_prev_serials = incr_serials_of(author, n);
    g_incr_prev_ua_serial = ua ? ua->serial : 0;
    g_incr_prev_reg_serial = ns_css_registered_property_serial();
    for (gsize i = 0; i < n; i++)
        if (author[i]) (void)incr_sheet_deps_for(author[i]);
    incr_sheet_deps_prune(g_incr_prev_serials);
}

static void
incr_mark_newly_defined_walk(ns_node *n, int depth)
{
    if (depth >= NS_CSS_MAX_CASCADE_DEPTH) return;
    if (n->kind == NS_NODE_ELEMENT && n->name && strchr(n->name, '-')) {
        char *lower = g_ascii_strdown(n->name, -1);
        gboolean hit = g_hash_table_contains(g_defined_since_restyle, lower);
        g_free(lower);
        if (hit) {
            ns_css_mark_restyle_dirty(n);
            return;
        }
    }
    for (ns_node *c = n->first_child; c; c = c->next_sibling)
        incr_mark_newly_defined_walk(c, depth + 1);
}

static void
incr_mark_newly_defined(ns_node *doc)
{
    if (!g_defined_since_restyle ||
        g_hash_table_size(g_defined_since_restyle) == 0)
        return;
    if (g_incr_pass_active) incr_mark_newly_defined_walk(doc, 0);
    g_hash_table_remove_all(g_defined_since_restyle);
}

static gboolean
incr_prev_update_in_place(GHashTable *out)
{
    if (!g_incr_pass_active || !g_incr_prev_styles || !g_incr_changed)
        return FALSE;
    guint added = 0;
    for (guint i = 0; i < g_incr_changed->len; i++)
        if (!g_hash_table_lookup(g_incr_prev_styles,
                                 g_ptr_array_index(g_incr_changed, i)))
            added++;
    if (g_hash_table_size(g_incr_prev_styles) + added !=
        g_hash_table_size(out))
        return FALSE;
    GHashTable *before = g_hash_table_new_full(
        g_direct_hash, g_direct_equal, NULL, (GDestroyNotify)ns_style_free);
    for (guint i = 0; i < g_incr_changed->len; i++) {
        gpointer node = g_ptr_array_index(g_incr_changed, i);
        ns_style *now = g_hash_table_lookup(out, node);
        ns_style *old = g_hash_table_lookup(g_incr_prev_styles, node);
        if (!now || now == old) continue;
        if (old) {
            old->ref++;
            g_hash_table_replace(before, node, old);
        }
        now->ref++;
        g_hash_table_replace(g_incr_prev_styles, node, now);
    }
    if (g_incr_before_styles) g_hash_table_destroy(g_incr_before_styles);
    g_incr_before_styles = before;
    g_incr_before_partial = TRUE;
    return TRUE;
}

GHashTable *
ns_css_compute(ns_node *doc,
               const ns_css_stylesheet *const *author_sheets,
               const ns_node *const *sheet_docs,
               gsize n_sheets)
{
    GHashTable *out = g_hash_table_new_full(g_direct_hash, g_direct_equal,
                                            NULL, (GDestroyNotify)ns_style_free);

    g_css_compute_thread = TRUE;
    g_pragma_valid = FALSE;

    const ns_css_stylesheet *cached_ua = ua_sheet_for(doc);

    gboolean profile = g_getenv("NS_PROFILE") != NULL;
    gint64 t0 = profile ? g_get_monotonic_time() : 0;
    (void)ns_css_rule_index_ensure(cached_ua);
    for (gsize i = 0; i < n_sheets; i++)
        (void)ns_css_rule_index_ensure(author_sheets[i]);
    gint64 t_idx = profile ? g_get_monotonic_time() : 0;

    GHashTable *layer_ranks = g_hash_table_new_full(g_str_hash, g_str_equal,
                                                    g_free, NULL);
    css_layer_rank_add_sheet(layer_ranks, cached_ua);
    for (gsize i = 0; i < n_sheets; i++)
        css_layer_rank_add_sheet(layer_ranks, author_sheets[i]);
    css_layer_ranks_finalize(layer_ranks);

    g_registered_props = g_hash_table_new(g_str_hash, g_str_equal);
    css_collect_property_rules(g_registered_props, cached_ua);
    for (gsize i = 0; i < n_sheets; i++)
        css_collect_property_rules(g_registered_props, author_sheets[i]);
    if (g_js_registered_props) {
        GHashTableIter it;
        gpointer k, v;
        g_hash_table_iter_init(&it, g_js_registered_props);
        while (g_hash_table_iter_next(&it, &k, &v))
            g_hash_table_replace(g_registered_props, k, v);
    }

    double root_px = 0;
    if (g_decl_sheet_cache && g_hash_table_size(g_decl_sheet_cache) >= 8192)
        g_hash_table_remove_all(g_decl_sheet_cache);
    if (!g_cq_stack)
        g_cq_stack = g_array_new(FALSE, FALSE, sizeof(ns_cq_container));
    g_array_set_size(g_cq_stack, 0);
    if (!g_share_scratch)
        g_share_scratch = g_byte_array_sized_new(512);
    g_style_share = g_hash_table_new_full(share_key_hash, share_key_equal,
                                          share_key_free, NULL);
    g_var_build_cache = g_hash_table_new_full(
        g_bytes_hash, g_bytes_equal, (GDestroyNotify)g_bytes_unref,
        (GDestroyNotify)ns_var_map_unref);
    g_var_build_parents = g_ptr_array_new();
    g_reg_reset_cache = g_hash_table_new_full(
        g_direct_hash, g_direct_equal, reg_reset_key_free,
        (GDestroyNotify)g_hash_table_destroy);
    g_reg_compute_memo = g_hash_table_new_full(
        g_direct_hash, g_direct_equal, NULL,
        (GDestroyNotify)g_hash_table_destroy);
    g_var_adjust_cache = g_hash_table_new_full(
        g_direct_hash, g_direct_equal,
        (GDestroyNotify)ns_var_map_unref, (GDestroyNotify)ns_var_map_unref);
    g_has_memo = g_hash_table_new_full(has_memo_hash, has_memo_equal,
                                       g_free, NULL);
    pending_parse_cache_trim();
    g_element_keys_pass++;
    ns_css_selector_batch_begin();

    guint64 sig = incr_sheet_sig(cached_ua, author_sheets, n_sheets);
    gboolean has_reset = FALSE;
    if (sig != g_incr_has_sig) {
        gboolean extend = g_has_anchors && g_has_serials &&
            g_hash_table_size(g_has_serials) <= 2 * (n_sheets + 1) + 64;
        if (!extend) {
            has_reset = TRUE;
            g_has_anchor_gen++;
            if (g_has_anchors) g_ptr_array_set_size(g_has_anchors, 0);
            else g_has_anchors =
                g_ptr_array_new_with_free_func(incr_has_anchor_free);
            if (g_has_subject_anchors)
                g_ptr_array_set_size(g_has_subject_anchors, 0);
            if (g_has_serials) g_hash_table_remove_all(g_has_serials);
            else g_has_serials = g_hash_table_new_full(g_int64_hash,
                                                       g_int64_equal,
                                                       g_free, NULL);
            g_has_cq_loose = FALSE;
            if (g_has_args_all) g_ptr_array_set_size(g_has_args_all, 0);
            g_has_args_gateable = FALSE;
        }
        if (incr_sheet_newly_seen(g_has_serials, cached_ua))
            incr_collect_has_cq_keys(cached_ua);
        for (gsize i = 0; i < n_sheets; i++)
            if (incr_sheet_newly_seen(g_has_serials, author_sheets[i]))
                incr_collect_has_cq_keys(author_sheets[i]);
        g_incr_eligible = !g_has_cq_loose;
        g_incr_has_sig = sig;
    }
    gboolean incr_usable = g_getenv("NS_NO_INCR_RESTYLE") == NULL
        && g_incr_eligible
        && fabs(g_incr_zoom - 1.0) <= 0.001;
    gboolean incr_want = incr_usable;
    guint64 cq_sig = cq_map_signature(g_cq_map);
    gboolean struct_kept =
        incr_ensure_struct_keys(cached_ua, author_sheets, n_sheets, sig);
    guint64 font_gen = g_font_generation_cb ? g_font_generation_cb() : 0;
    guint env_changed =
        (g_incr_prev_cq_sig != cq_sig ? STYLE_READS_CONTAINER : 0) |
        (g_incr_prev_font_gen != font_gen ? STYLE_READS_FONT_METRICS : 0);
    g_incr_pass_active = incr_want
        && g_incr_prev_styles != NULL
        && g_incr_prev_doc == doc
        && g_css_focus_node == g_incr_prev_focus
        && g_css_hover_node == g_incr_prev_hover
        && g_css_active_node == g_incr_prev_active
        && g_css_fullscreen_node == g_incr_prev_fullscreen;
    guint sheet_marked = 0;
    if (g_incr_pass_active && g_incr_prev_sig != sig)
        g_incr_pass_active = struct_kept && !has_reset &&
            incr_apply_sheet_change(doc, cached_ua, author_sheets, n_sheets,
                                    &sheet_marked);
    if (g_incr_pass_active)
        incr_mark_env_dependents(env_changed);
    else if (g_incr_env_nodes)
        g_hash_table_remove_all(g_incr_env_nodes);
    g_incr_reused = 0;
    g_incr_recomputed = 0;
    incr_mark_newly_defined(doc);
    incr_mark_loose_has_subjects(doc);
    if (g_incr_walk_needed) g_hash_table_remove_all(g_incr_walk_needed);
    if (g_incr_pass_active) incr_walk_needed_build();
    else if (g_explicit_inherit_parents)
        g_hash_table_remove_all(g_explicit_inherit_parents);
    g_cascade_parent_node = NULL;
    if (!g_incr_changed) g_incr_changed = g_ptr_array_new();
    g_ptr_array_set_size(g_incr_changed, 0);

    memset(g_ancestor_filter, 0, sizeof g_ancestor_filter);
    g_ancestor_filter_active = TRUE;
    g_ancestor_filter_attrs = g_css_attr_ancestor_hashes;
    GHashTable *outer_doc_sheets = g_doc_sheets;
    g_doc_sheets = doc_sheets_new(author_sheets, sheet_docs, n_sheets);
    cascade_walk(doc, cached_ua, author_sheets, n_sheets, NULL, NULL,
                 &root_px, layer_ranks, out, FALSE, FALSE);
    g_clear_pointer(&g_doc_sheets, g_hash_table_destroy);
    g_doc_sheets = outer_doc_sheets;
    g_ancestor_filter_active = FALSE;
    g_ancestor_filter_subject = NULL;

    if (incr_want) {
        if (!incr_prev_update_in_place(out)) {
            GHashTable *new_prev = g_hash_table_new_full(
                g_direct_hash, g_direct_equal, NULL,
                (GDestroyNotify)ns_style_free);
            GHashTableIter pit; gpointer pk, pv;
            g_hash_table_iter_init(&pit, out);
            while (g_hash_table_iter_next(&pit, &pk, &pv)) {
                ((ns_style *)pv)->ref++;
                g_hash_table_insert(new_prev, pk, pv);
            }
            if (g_incr_before_styles)
                g_hash_table_destroy(g_incr_before_styles);
            g_incr_before_styles = g_incr_prev_styles;
            g_incr_before_partial = FALSE;
            g_incr_prev_styles = new_prev;
        }
        g_incr_prev_doc = doc;
        g_incr_prev_sig = sig;
        incr_remember_sheets(cached_ua, author_sheets, n_sheets);
        g_incr_prev_cq_sig = cq_sig;
        g_incr_prev_font_gen = font_gen;
        g_incr_prev_focus = g_css_focus_node;
        g_incr_prev_hover = g_css_hover_node;
        g_incr_prev_active = g_css_active_node;
        g_incr_prev_fullscreen = g_css_fullscreen_node;
        if (g_getenv("NS_PROFILE"))
            g_printerr("[incr] active=%d reused=%u recomputed=%u "
                       "sheet_marked=%u\n",
                       g_incr_pass_active, g_incr_reused, g_incr_recomputed,
                       sheet_marked);
    } else if (g_incr_prev_styles && !incr_usable) {
        g_hash_table_destroy(g_incr_prev_styles);
        g_incr_prev_styles = NULL;
        g_incr_prev_doc = NULL;
        if (g_incr_before_styles) g_hash_table_destroy(g_incr_before_styles);
        g_incr_before_styles = NULL;
        g_incr_before_partial = FALSE;
    }
    if (g_incr_dirty) g_hash_table_remove_all(g_incr_dirty);
    if (g_incr_self_dirty) g_hash_table_remove_all(g_incr_self_dirty);
    if (g_incr_inv_pending) g_hash_table_remove_all(g_incr_inv_pending);

    g_hash_table_destroy(g_has_memo);
    g_has_memo = NULL;
    ns_css_selector_batch_end();
    g_hash_table_destroy(g_style_share);
    g_style_share = NULL;
    g_hash_table_destroy(g_var_adjust_cache);
    g_var_adjust_cache = NULL;
    g_clear_pointer(&g_reg_reset_cache, g_hash_table_destroy);
    g_clear_pointer(&g_reg_compute_memo, g_hash_table_destroy);
    g_clear_pointer(&g_var_build_cache, g_hash_table_destroy);
    for (guint i = 0; g_var_build_parents && i < g_var_build_parents->len; i++)
        if (g_ptr_array_index(g_var_build_parents, i))
            ns_var_map_unref(g_ptr_array_index(g_var_build_parents, i));
    g_clear_pointer(&g_var_build_parents, g_ptr_array_unref);
    g_hash_table_destroy(layer_ranks);
    g_hash_table_destroy(g_registered_props);
    g_registered_props = NULL;
    gint64 t_cascade = profile ? g_get_monotonic_time() : 0;
    if (profile)
        g_printerr("[profile]   css.idx=%.1fms css.cascade=%.1fms\n",
                   (t_idx - t0) / 1000.0,
                   (t_cascade - t_idx) / 1000.0);
    return out;
}

void
ns_css_style_scale_font_size(ns_style *s, double factor)
{
    if (!s || !s->values[NS_CSS_FONT_SIZE] ||
        s->values[NS_CSS_FONT_SIZE]->kind != NS_CSS_V_LENGTH)
        return;
    ns_css_value_cow(s, NS_CSS_FONT_SIZE)->u.length.v *= factor;
}
